import sys

try:
    import os
    import re
    import gc
    import time
    import errno
    import signal
    import atexit
    import struct
    import itertools
    from copy import deepcopy

    # from ctypes import *  # for lint check
except ImportError:
    err = sys.exc_info()[1]
    sys.exit("[ERROR] failed to import essential package: %s" % err.args[0])

# handle backward compatibility between python 2 and 3
try:
    long  # pylint: disable=used-before-assignment
except:
    long = int

# python 2's xrange is equivalent to range in python 3
try:
    xrange  # pylint: disable=used-before-assignment
except:
    xrange = range

# enable JIT compiler #
try:
    if "JITCOMPILE" in os.environ:
        from numba import jit  # pylint: disable=import-error
    else:

        def jit(func):
            def decorated():
                func()

            return decorated

except:
    err = sys.exc_info()[1]
    sys.exit("[ERROR] failed to import numba package: %s" % err.args[0])


