class UtilMgr(object):
    """Manager for utilities"""

    r"""
    [ TIPS ]
    - vim replacement
        1.PROBLEM: replace all "type(???) is long" with "isinstance(???, (int, long))"
        1.SOLUTION: %s/type(\(.*\)) is long/isinstance(\1, (int, long)/g
        2.PROBLEM: replace all except:pass with except:SysMgr.printErr
        2.SOLUTION: %s/\(^\s*\)except:\n\1\s\+pass/\1except:\r\1    if "PRINTEXCEPT":\r\1        SysMgr.printErr("EXCEPT", True)/g
    """

    curTime = 0
    totalCnt = 0
    totalTime = 0
    progressCnt = 0
    progressStr = 0
    progressChar = {0: "|", 1: "/", 2: "-", 3: "\\"}
