            plist = []
            for palette_entry in palette:
                r"""
                rgb = [
                    int(rgb_value)
                    for rgb_value in re.findall("\d+", palette_entry)
                ]
                """
                color = "rgb%s" % palette_entry
                plist.append(color)
            return plist

