    @staticmethod
    def getAnrInfo():
        anrDir = "/data/anr"
        try:
            paths = sorted(
                [
                    os.path.join(anrDir, f)
                    for f in os.listdir(anrDir)
                    if os.path.isfile(os.path.join(anrDir, f))
                ],
                key=os.path.getmtime,
                reverse=True,
            )
        except SystemExit:
            sys.exit(0)
        except:
            SysMgr.printErr("failed to read ANR directory '%s'" % anrDir, True)
            return

        if not paths:
            SysMgr.printErr("no ANR trace found in '%s'" % anrDir)
            return

        for path in paths:
            SysMgr.printInfo("ANR trace: '%s'" % path)
            try:
                with open(path, "r") as f:
                    SysMgr.printPipe(f.read())
            except SystemExit:
                sys.exit(0)
            except:
                SysMgr.printErr("failed to read '%s'" % path, True)

