    @staticmethod
    def dumpHeap(target):
        if not target or target == "SET":
            SysMgr.printErr(
                "no valid input for dumpheap (format: package[@output_file])"
            )
            return
        parts = target.split("@", 1)
        pkg = parts[0]
        outFile = (
            parts[1]
            if len(parts) > 1
            else "/data/local/tmp/%s.hprof" % pkg.replace(".", "_")
        )
        cmd = ["am", "dumpheap", pkg, outFile]
        ret = SysMgr.executeCmdSync(cmd)
        if ret:
            SysMgr.printPipe("\n".join(ret))
        else:
            SysMgr.printPipe("saved heap dump to '%s'" % outFile)

