    @staticmethod
    def getSelinuxEnforce():
        # Try getenforce binary (most reliable on Android)
        ret = SysMgr.executeCmdSync(["getenforce"])
        if ret:
            SysMgr.printPipe(ret[0].strip())
            return
        # Fallback: read sysfs enforce node
        data = SysMgr.readFile("/sys/fs/selinux/enforce", verb=False)
        state = "Enforcing" if str(data or "").strip() == "1" else "Permissive"
        SysMgr.printPipe(state)

    @staticmethod
    def getWakeLockInfo():
        # Try kernel wakeup_sources first (requires debugfs/root access)
        for path in ("/sys/kernel/debug/wakeup_sources", "/proc/wakelocks"):
            data = SysMgr.readFile(path, verb=False)
            if not data:
                continue
            lines = data.splitlines()
            fmt = "%-40s  %6s  %12s  %12s  %4s"
            SysMgr.printPipe(
                fmt % ("WAKELOCK", "COUNT", "ACTIVE_MS", "TOTAL_MS", "ACT")
            )
            SysMgr.printPipe("-" * 80)
            found = 0
            for line in lines[1:]:
                parts = line.split("\t")
                if len(parts) < 7:
                    continue
                name = parts[0].strip()
                try:
                    active_count = int(parts[1])
                    active_since = int(parts[5])
                    total_time = int(parts[6])
                except (ValueError, IndexError):
                    continue
                is_active = "Yes" if active_since > 0 else "No"
                SysMgr.printPipe(
                    fmt
                    % (
                        name[:40],
                        active_count,
                        active_since,
                        total_time,
                        is_active,
                    )
                )
                found += 1
            if found == 0:
                SysMgr.printPipe("  (no wakelock entries)")
            return

        # Fall back: extract wake lock sections from 'dumpsys power'
        ret = SysMgr.executeCmdSync(["dumpsys", "power"])
        wl_keywords = (
            "Wake Locks:",
            "Kernel Wake Locks:",
            "Suspend Blockers:",
        )
        cur_section = []
        sections = []
        for line in ret:
            stripped = line.strip()
            is_header = any(stripped.startswith(k) for k in wl_keywords)
            if is_header:
                if cur_section:
                    sections.append("\n".join(cur_section))
                cur_section = [line.rstrip()]
            elif cur_section:
                if stripped and line[0] not in (" ", "\t"):
                    sections.append("\n".join(cur_section))
                    cur_section = []
                else:
                    cur_section.append(line.rstrip())
        if cur_section:
            sections.append("\n".join(cur_section))
        if sections:
            SysMgr.printPipe("\n\n".join(sections))
        else:
            SysMgr.printPipe("  (no wake lock info available)")

    @staticmethod
    def getBinderStats():
        stat_paths = [
            "/dev/binderfs/binder_logs/stats",
            "/proc/binder/stats",
        ]
        txn_paths = [
            "/dev/binderfs/binder_logs/transactions",
            "/proc/binder/transactions",
        ]

        stat_data = None
        for path in stat_paths:
            stat_data = SysMgr.readFile(path, verb=False)
            if stat_data:
                break

        txn_data = None
        for path in txn_paths:
            txn_data = SysMgr.readFile(path, verb=False)
            if txn_data:
                break

        if not stat_data:
            SysMgr.printWarn("binder stats not available (/proc/binder/stats)")
            return

        filter_str = SysMgr.filterGroup[0] if SysMgr.filterGroup else None
        filter_pid = None
        filter_name = None
        if filter_str:
            try:
                filter_pid = int(filter_str)
            except ValueError:
                filter_name = filter_str

        cur_pid = -1
        cur_name = ""
        buf = []
        in_global = True

        def _flush():
            if in_global:
                if buf:
                    SysMgr.printPipe("[GLOBAL STATS]")
                    SysMgr.printPipe("\n".join(buf))
            else:
                if filter_pid is None and filter_name is None:
                    match = True
                elif filter_pid is not None:
                    match = cur_pid == filter_pid
                else:
                    match = filter_name in cur_name
                if match:
                    SysMgr.printPipe("\n[PROC %d (%s)]" % (cur_pid, cur_name))
                    SysMgr.printPipe("\n".join(buf))

        for line in stat_data.splitlines():
            s = line.strip()
            if s.startswith("proc "):
                _flush()
                buf = []
                in_global = False
                try:
                    cur_pid = int(s.split()[1])
                except Exception:
                    cur_pid = -1
                cur_name = SysMgr.getComm(cur_pid) if cur_pid >= 0 else ""
            else:
                buf.append("  " + s)

        _flush()

        if txn_data:
            SysMgr.printPipe("\n[PENDING TRANSACTIONS]")
            SysMgr.printPipe(txn_data[:2000])

    @staticmethod
    def resetGfxStats():
        pkg_list = SysMgr.environList.get("RESETGFXSTATS", [])
        pkg = pkg_list[0] if pkg_list else None
        if not pkg or pkg == "SET":
            pkg = SysMgr.filterGroup[0] if SysMgr.filterGroup else None
        if not pkg:
            SysMgr.printErr(
                "no package specified for RESETGFXSTATS "
                "(use resetgfxstats:<pkg> or -g <pkg>)"
            )
            return
        cmd = ["dumpsys", "gfxinfo", pkg, "reset"]
        SysMgr.executeCmdSync(cmd)
        SysMgr.printPipe("[RESETGFXSTATS] %s: done" % pkg)

