    @staticmethod
    def toggleWifi(val):
        if not val or val == "SET":
            SysMgr.printErr(
                "no valid input for togglewifi (format: enable/disable)"
            )
            return
        state = "enable" if val in ("enable", "1", "on") else "disable"
        cmd = ["svc", "wifi", state]
        SysMgr.executeCmdSync(cmd)

    @staticmethod
    def toggleBt(val):
        if not val or val == "SET":
            SysMgr.printErr(
                "no valid input for togglebt (format: enable/disable)"
            )
            return
        state = "enable" if val in ("enable", "1", "on") else "disable"
        cmd = ["svc", "bluetooth", state]
        SysMgr.executeCmdSync(cmd)

    @staticmethod
    def handlePkg(act, pkg):
        users = AndroidMgr.getUserList()

        if act in ("enable", "disable"):
            subcmd = act
        else:
            SysMgr.printErr("no support action '%s' for package control" % act)
            return

        cmd = ["pm", subcmd]
        for uid, uv in users.items():
            userInfo = "%s(%s)<%s>" % (uv.get("name"), uid, uv.get("status"))
            ucmd = cmd + ["--user", uid, pkg]

            SysMgr.printInfo("%s '%s' for user %s" % (subcmd, pkg, userInfo))
            ret = SysMgr.executeCmdSync(ucmd)

    @staticmethod
    def getUserList():
        userList = {}
        pattern = (
            r"UserInfo\{(?P<user_id>\d+):(?P<name>[^:]+):"
            r"(?P<flag>\d+)\}\s+(?P<status>\w+)"
        )

        cmd = ["cmd", "user", "list"]
        ret = SysMgr.executeCmdSync(cmd)
        for u in ret:
            m = re.match(pattern, u.strip())
            if not m:
                continue

            d = m.groupdict()
            user = d.pop("user_id", None)
            if user:
                userList[user] = d

        return userList

    @staticmethod
    def getAppStat(i):
        appList = []
        for v in i.split("|"):
            appList += SysMgr.getTids(v, isThread=False, cmdline=True)
        for pid in appList:
            taskInfo = "%s(%s)" % (SysMgr.getCmdline(pid), pid)
            if not SysMgr.isAndroidApp(pid):
                SysMgr.printWarn(
                    "failed to check %s as an android app" % taskInfo, True
                )
                if not SysMgr.forceEnable:
                    continue

            SysMgr.printInfo("start getting stats of %s" % taskInfo)
            cmd = ["debuggerd", "-j", pid]
            ret = "\n".join(SysMgr.executeCmdSync(cmd))
            start = ret.find("Zygote loaded")
            if start < 0:
                SysMgr.printWarn("%s has no stat info" % taskInfo, True)
                continue
            SysMgr.printPipe("----- %s -----" % taskInfo)
            SysMgr.printPipe(ret[start:] + "\n\n")

    @staticmethod
    def useContent(i):
        items = i.split(":", 1)
        if len(items) == 1:
            SysMgr.printErr("no input value")
            return

        inputCmd, inputVal = items
        for v in inputVal.split("|"):
            if inputCmd == "listall":
                cmd = ["dumpsys", "package", "providers"]
            elif inputCmd == "listact":
                cmd = ["dumpsys", "activity", "providers"]
            elif inputCmd == "notify":
                cmd = [
                    "content",
                    "call",
                    "--uri",
                    v,
                    "--method",
                    "notifyChange",
                ]
            else:
                cmd = ["content", inputCmd, "--uri"] + v.split(" ")
            SysMgr.printPipe("\n".join(SysMgr.executeCmdSync(cmd)))

    @staticmethod
    def injectInputEvent(i):
        inputList = {
            "dragdrop": "draganddrop",
            "key": "keyevent",
            "keyset": "keycombination",
            "motion": "motionevent",
            "mouse": "mouse",
            "press": "press",
            "roll": "roll",
            "swipe": "swipe",
            "text": "text",
            "touch": "tap",
        }
        inputListSet = list(inputList.values())

        items = i.split(":", 1)
        if len(items) == 1:
            SysMgr.printErr("no input value")
            return

        inputCmd, inputVal = items
        for v in inputVal.split("|"):
            if inputCmd in inputList:
                inputCmd = inputList[inputCmd]
            elif inputCmd in inputListSet:
                pass
            elif not SysMgr.forceEnable:
                SysMgr.printErr("no support command '%s'" % inputCmd)
                return
            elif inputCmd == "keyevent":
                v = v.upper()
                if not v.startswith("KEYCODE_"):
                    v = "KEYCODE_" + v

            cmd = ["input", inputCmd] + v.split(" ")
            SysMgr.executeCmdSync(cmd)

    @staticmethod
    def injectCarKey(i):
        keyCodeMap = {
            "SOFT_LEFT": 1,
            "SOFT_RIGHT": 2,
            "HOME": 3,
            "BACK": 4,
            "CALL": 5,
            "ENDCALL": 6,
            "DPAD_UP": 19,
            "DPAD_DOWN": 20,
            "DPAD_LEFT": 21,
            "DPAD_RIGHT": 22,
            "DPAD_CENTER": 23,
            "VOLUME_UP": 24,
            "VOLUME_DOWN": 25,
            "POWER": 26,
            "ENTER": 66,
            "MUTE": 91,
            "MEDIA_PLAY_PAUSE": 85,
            "MEDIA_STOP": 86,
            "MEDIA_NEXT": 87,
            "MEDIA_PREVIOUS": 88,
            "MEDIA_PLAY": 126,
            "MEDIA_PAUSE": 127,
            "SLEEP": 223,
            "WAKEUP": 224,
        }
        items = i.split(":")
        keyName = items[0].upper()
        if keyName.startswith("KEYCODE_"):
            keyName = keyName[len("KEYCODE_") :]
        action = items[1].lower() if len(items) > 1 else "click"
        display = items[2] if len(items) > 2 else None

        if keyName in keyCodeMap:
            keyCode = keyCodeMap[keyName]
        elif keyName.isdigit():
            keyCode = int(keyName)
        else:
            SysMgr.printErr("unknown keycode '%s'" % keyName)
            return

        base = ["cmd", "car_service", "inject-key", str(keyCode)]

        def _run(act):
            cmd = base + [str(act)]
            if display is not None:
                cmd.append(display)
            SysMgr.executeCmdSync(cmd)

        if action in ("down", "0"):
            _run(0)
        elif action in ("up", "1"):
            _run(1)
        else:  # click (default)
            _run(0)
            _run(1)

    @staticmethod
    def getPkgInfo(pkg=None, item=None):
        title = {
            "activity": "Activity Resolver Table:",
            "dump": "*",
            "package": "Packages:",
            "permission": "Permissions:",
        }.get(item, None)
        if pkg and not title:
            SysMgr.printErr("no '%s' info of package in dumpsys")
            return

        cmd = ["dumpsys", "package"]
        if pkg:
            cmd += [pkg]
        ret = SysMgr.executeCmdSync(cmd)

        pkgLines = []
        started = title in ("*", None)
        for l in ret:
            if not l:
                continue
            elif started:
                if title not in ("*", None) and (l[0] != " " and l != title):
                    break
                else:
                    pkgLines.append(l)
            elif l.startswith(title):
                started = True
        return pkgLines

    @staticmethod
    def runVehicleCmd(cscmd=None, vhal=True):
        if cscmd:
            restr, inputMapList, mapData, color = UtilMgr.getParseMapAttr(
                reverse=True
            )
            if mapData:
                cscmdList = cscmd.split()
                for idx in range(len(cscmdList)):
                    if cscmdList[idx] in mapData:
                        cscmdList[idx] = mapData[cscmdList[idx]][0]
                cscmd = " ".join(cscmdList)

        if vhal:
            cmd = [
                "dumpsys",
                "android.hardware.automotive.vehicle.IVehicle/default",
            ]
        else:
            cmd = ["dumpsys", "activity", "service", "CarService"]
        if cscmd:
            cmd += cscmd.split()
        ret = SysMgr.executeCmdSync(cmd)

        restr, inputMapList, mapData, color = UtilMgr.getParseMapAttr()
        if mapData:
            ret = [
                UtilMgr.replaceLineFromMap(l, mapData, restr, color)
                for l in ret
            ]
            ret = [l for l in ret if l]

        SysMgr.printPipe("\n".join(ret))

    @staticmethod
    def runVHalCmd(cscmd=None):
        AndroidMgr.runVehicleCmd(cscmd, True)

    @staticmethod
    def runCarServiceCmd(cscmd=None):
        AndroidMgr.runVehicleCmd(cscmd, False)

    @staticmethod
    def applySettingsList(vals=None):
        if not vals:
            vals = SysMgr.environList.get("SETSETTINGS")
        if not vals or vals == ["SET"]:
            SysMgr.printErr("no value to be set")
            return

        if not isinstance(vals, list):
            vals = [vals]

        for v in vals:
            try:
                if v == "SET":
                    continue

                items = v.split(":", 2)
                if len(items) != 3:
                    SysMgr.printErr("failed to parse settings value '%s'" % v)
                    continue
                ns, name, value = items

                if ns not in ("system", "global", "secure"):
                    SysMgr.printErr(
                        "failed to get valid namespace for settings value '%s'"
                        % v
                    )
                    continue

                AndroidMgr.writeSetting(name, value, ns, False)
            except SystemExit:
                sys.exit(0)
            except:
                SysMgr.printErr(
                    "failed to apply settings value '%s'" % v, True
                )

        AndroidMgr.applySettingVars(default=False)

    @staticmethod
    def printSettingsList(retval=False):
        items = {}
        mergeList = {}
        cmd = ["settings", "list", "--user", "current"]

        for namespace in ("system", "secure", "global"):
            ret = SysMgr.executeCmdSync(cmd + [namespace])
            if ret:
                items[namespace] = ret
                for v in ret:
                    try:
                        mergeList.setdefault(
                            v.split("=", 1)[0], {}
                        ).setdefault(namespace)
                    except SystemExit:
                        sys.exit(0)
                    except:
                        pass

        if retval:
            return items

        for n, v in items.items():
            for vv in v:
                SysMgr.printPipe("[%s] %s" % (n, vv))

        for n, v in mergeList.items():
            if len(v) > 1:
                SysMgr.printWarn(
                    "'%s' exists in %s" % (n, list(v.keys())), True
                )

