    @staticmethod
    def writeErr(fd, log):
        if not LogMgr.lock(fd):
            # already held (reentrant) -> skip rather than interleave writes #
            return

        try:
            fd.write(log)
        except SystemExit:
            sys.exit(0)
        except:
            LogMgr.unlock(fd)
            return

        LogMgr.unlock(fd)

    @staticmethod
    def setAlarmTimer(timer=None, handler=None):
        if not timer:
            timer = SysMgr.getOption("R")
            if timer:
                if timer.isdigit():
                    timer = long(timer)
                else:
                    timer = UtilMgr.convUnit2Time(timer)
            else:
                return

        if not handler:
            handler = SysMgr.alarmHandler

        SysMgr.setSignal(signal.SIGALRM, handler)
        signal.alarm(timer)

