    @staticmethod
    def getFileAttr(path):
        try:
            SysMgr.loadLibcObj(exit=True)

            if not hasattr(SysMgr.libcObj, "lgetxattr"):
                SysMgr.printErr("no lgetxattr() in libc")
                sys.exit(-1)

            SysMgr.libcObj.lgetxattr.restype = c_size_t
            SysMgr.libcObj.lgetxattr.argtypes = [
                c_char_p,
                c_char_p,
                c_void_p,
                c_size_t,
            ]

            size = 256
            buf = (c_char * size)()
            ret = SysMgr.libcObj.lgetxattr(
                path.encode(), "security.selinux".encode(), buf, size
            )
            if not ret or c_long(ret).value < 0:
                return None
            else:
                return memoryview(buf[:ret]).tobytes().decode().rstrip("\x00")
        except SystemExit:
            sys.exit(0)
        except:
            SysMgr.printErr("failed to get security info of '%s'" % path, True)

    @staticmethod
    def getTotalUsage(pid):
        try:
            dobj = Debugger(pid, attach=False)
            dobj.initValues()
            dobj.getCpuUsage()

            cpu = dobj.prevCpuStat[0]
            rss = dobj.getMemUsage()
            proc = "%s(%s)" % (dobj.comm, dobj.pid)

            return [cpu, rss, proc]
        except SystemExit:
            sys.exit(0)
        except:
            SysMgr.printWarn(
                "failed to get usage info of the task having PID %s" % pid,
                True,
                True,
            )
            return [0, 0, "?"]

