        SysMgr.maxCpuSteal = 0
        SysMgr.prevMaxProcCpuUsage = 0
        SysMgr.maxProcCpuUsage = 0
        SysMgr.maxProcCpuComm = ""
        SysMgr.maxProcMemUsage = 0
        SysMgr.prevMaxProcMemUsage = 0
        SysMgr.maxProcMemComm = ""
        SysMgr.prevMaxProcBlkUsage = 0
        SysMgr.maxProcBlkUsage = 0
        SysMgr.maxProcBlkComm = ""
        SysMgr.prevMaxProcBlkRdUsage = 0
        SysMgr.maxProcBlkRdUsage = 0
        SysMgr.maxProcBlkRdComm = ""
        SysMgr.prevMaxBlkWrUsage = 0
        SysMgr.maxProcBlkWrUsage = 0
        SysMgr.maxProcBlkWrComm = ""
        SysMgr.maxGpuMemUsage = 0
        SysMgr.maxGpuUsage = 0
        SysMgr.maxInterval = 0
        SysMgr.maxLoad15m = 0
        SysMgr.maxLoad1m = 0
        SysMgr.maxLoad5m = 0
