    @staticmethod
    def isAndroidApp(target):
        if not SysMgr.isRoot():
            SysMgr.printWarn(
                "failed to check android process because of permission", True
            )
            return False

        pid = SysMgr.getTids(target, isThread=False)
        if len(pid) > 1:
            SysMgr.printWarn(
                "no support android app check for multiple processes [%s]"
                % SysMgr.getCommList(pid),
                True,
            )
            return False

        exe = SysMgr.getExeName(pid[0])
        return exe and "app_process" in exe.rsplit("/", 1)[1]

