        try:
            major, minor = dev.split(":", 1)
            if major in ("public", "private"):
                nums = minor.split(",")
                if len(nums) == 2:
                    major, minor = nums
            return major, minor
        except SystemExit:
            sys.exit(0)
        except:
            return 0, 0

