    @staticmethod
    def getPidFilter(name="common_pid", comm=True, force=True):
        if SysMgr.pidFilter and force:
            return SysMgr.pidFilter

        cmd = ""
        for cond in list(SysMgr.filterGroup):
            try:
                if comm:
                    cmd += """%scomm == "*%s*" || """ % (cmd, cond)

                if cond.isdigit():
                    cmd += "%s == %s || " % (name, long(cond))
                elif cond.startswith(">") or cond.endswith("<"):
                    cmd += "%s >= %s || " % (name, long(cond.strip("<>")))
                    continue
                elif cond.startswith("<") or cond.endswith(">"):
                    cmd += "%s <= %s || " % (name, long(cond.strip("<>")))
                    continue
            except SystemExit:
                sys.exit(0)
            except:
                pass

        if cmd != "":
            cmd = "(" + cmd[: cmd.rfind("||")] + ")"

        if force:
            SysMgr.pidFilter = cmd

        return cmd

    @staticmethod
    def isExceptTarget(tid, tdata, comm=None, plist=[]):
        if not SysMgr.filterGroup:
            return

        filters = SysMgr.filterGroup

        if not comm:
            comm = tdata[tid]["comm"]

        exceptComm = SysMgr.environList.get("EXCEPTCOMM")
        if exceptComm and UtilMgr.isValidStr(comm, exceptComm):
            return True

        exceptTid = SysMgr.environList.get("EXCEPTTID")
        if exceptTid and tid in exceptTid:
            return True

        if UtilMgr.isValidStr(comm, filters):
            return False

        for item in filters:
            if item in (tid, "") or SysMgr.isValidTid(tid, item):
                return False

        if SysMgr.groupProcEnable:
            tgid = tdata[tid]["tgid"]

            if str(tgid) in plist:
                return False

            for item in filters:
                try:
                    if tgid == item or SysMgr.isValidTid(tgid, item):
                        return False
                    elif tgid == "0" or tgid.startswith("-"):
                        continue
                    elif (
                        tgid == tdata[item]["tgid"]
                        or tgid == SysMgr.savedProcTree[item]
                    ):
                        return False
                except SystemExit:
                    sys.exit(0)
                except:
                    pass

        return True

    @staticmethod
    def getTraceItem(string):
        if SysMgr.tgidEnable:
            if not SysMgr.traceTgidFormat2Code:
                SysMgr.traceTgidFormat2Code = re.compile(
                    SysMgr.traceTgidFormat2
                )
            m = SysMgr.traceTgidFormat2Code.match(string)
            if m:
                return m
            else:
                if not SysMgr.traceTgidFormat1Code:
                    SysMgr.traceTgidFormat1Code = re.compile(
                        SysMgr.traceTgidFormat1
                    )
                return SysMgr.traceTgidFormat1Code.match(string)

        if not SysMgr.traceNoTgidFormatCode:
            SysMgr.traceNoTgidFormatCode = re.compile(SysMgr.traceNoTgidFormat)
        return SysMgr.traceNoTgidFormatCode.match(string)

    @staticmethod
    def isValidEnableOption(options):
        if not options:
            return False

        disableList = ""
        if disableList:
            if bool(set(options) & set(disableList)):
                return False

        optionList = "ABCDEFGHIKLMNOPQRSUTVWXYabcdefghijklmnopqrrstuvwxy"
        return not bool(set(options) - set(optionList))

    @staticmethod
    def checkValidOption(option):
        disableList = ""
        if not disableList:
            return True

        invalidList = set(option) & set(disableList)
        if bool(invalidList):
            SysMgr.printErr(
                "not permitted option [%s]" % ",".join(invalidList)
            )
            sys.exit(-1)

    @staticmethod
    def isValidOption(option):
        if not option:
            return False

        if option.isdigit():
            return True

        optionList = "ABCDEFGHIJKLMNOPQRSTUWXYZabcdefgijklmnopqrstuvwxy"
        return option in optionList

    @staticmethod
    def isValidTid(tid, cond):
        try:
            tid = long(tid)

            if cond in (tid, str(tid)):
                return True

            lval = cond.find(">")
            if lval == 0 and tid >= long(cond[1:]):
                return True
            elif lval == len(cond) - 1 and tid <= long(cond[:-1]):
                return True

            rval = cond.find("<")
            if rval == 0 and tid <= long(cond[1:]):
                return True
            elif rval == len(cond) - 1 and tid >= long(cond[:-1]):
                return True

            return False
        except SystemExit:
            sys.exit(0)
        except:
            return False

    @staticmethod
    def printBacktrace():
        traceback = SysMgr.getPkg("traceback")
        traceback.print_stack(file=SysMgr.stderr)

    @staticmethod
    def waitEvent(
        ignChldSig=True, exit=False, forceExit=False, block=True, timeout=0
    ):
        if ignChldSig:
            SysMgr.setSignal(signal.SIGCHLD, signal.SIG_IGN)

        if SysMgr.waitEnable and block:
            handle = signal.getsignal(signal.SIGINT)
            SysMgr.setSignal(signal.SIGINT, SysMgr.defaultHandler)

        try:
            if timeout:
                time.sleep(timeout)
                return False
            else:
                signal.pause()
        except SystemExit:
            if exit:
                sys.exit(0)
            elif forceExit:
                os._exit(0)
        except:
            pass

        if SysMgr.waitEnable and block:
            SysMgr.setSignal(signal.SIGINT, handle)

        return True

    @staticmethod
    def backupFile(origFile):
        if not origFile or not os.path.isfile(origFile):
            return None
        elif "NOBACKUP" in SysMgr.environList:
            return None

        try:
            newFile = "%s.old" % origFile

            if os.path.exists(newFile):
                os.remove(newFile)

            os.rename(origFile, newFile)
            os.chmod(newFile, 0o777)

            SysMgr.printInfo(
                "renamed '%s' to '%s' for backup" % (origFile, newFile)
            )

            return newFile
        except SystemExit:
            sys.exit(0)
        except:
            SysMgr.printErr(
                "failed to backup '%s' to '%s'" % (origFile, newFile), True
            )
            return None

    @staticmethod
    def convFullPath(path):
        return os.path.realpath(os.path.expanduser(path))

    @staticmethod
    def convRealPath(flist):
        if UtilMgr.isString(flist):
            flist = [flist]

        nlist = []
        for fpath in flist:
            fpath = fpath.strip()

            if fpath.startswith("^"):
                fpath = fpath[1:]
                exflag = True
            else:
                exflag = False

            items = UtilMgr.convPath(fpath, warn=False)
            for path in items:
                try:
                    rpath = os.path.realpath(path)
                    if not rpath.startswith("/"):
                        dirname = os.path.dirname(path)
                        rpath = os.path.join(dirname, rpath)
                        rpath = os.path.realpath(rpath)

                    if exflag:
                        rpath = "^" + rpath

                    nlist.append(rpath)
                except SystemExit:
                    sys.exit(0)
                except:
                    if os.path.exists(path):
                        if exflag:
                            path = "^" + path

                        nlist.append(path)
                    else:
                        SysMgr.printWarn(
                            "failed to convert '%s' to real path" % path,
                            reason=True,
                            always=True,
                        )

        return nlist

    @staticmethod
    def getErrReason():
        # pylint: disable=not-callable
        if not SysMgr.geterrnoFunc:
            ret = SysMgr.loadLibcObj()
            if not ret:
                SysMgr.geterrnoFunc = -1
                return "N/A"

            if hasattr(SysMgr.libcObj, "__errno_location"):
                fname = "__errno_location"
            elif hasattr(SysMgr.libcObj, "__errno"):
                fname = "__errno"
            else:
                SysMgr.geterrnoFunc = -1
                return "N/A"

            SysMgr.geterrnoFunc = getattr(SysMgr.libcObj, fname)
            SysMgr.geterrnoFunc.restype = POINTER(c_int)

        if SysMgr.geterrnoFunc == -1:
            return "N/A (no errno function)"

        try:
            num = SysMgr.geterrnoFunc()[0]
            if num == 0:
                return "N/A"
            elif num not in errno.errorcode:
                raise Exception("no errorno")
            code = errno.errorcode[num]
            return "%s (%s)" % (code, os.strerror(num))
        except SystemExit:
            sys.exit(0)
        except:
            SysMgr.printWarn("failed to get error reason", reason=True)
            return "N/A"

    @staticmethod
    def getProcTree():
        procTree = {}

        pids = SysMgr.getPidList()
        for pid in pids:
            try:
                long(pid)
            except SystemExit:
                sys.exit(0)
            except:
                continue

            procPath = "%s/%s" % (SysMgr.procPath, pid)
            taskPath = "%s/%s" % (procPath, "task")

            try:
                tids = os.listdir(taskPath)
            except SystemExit:
                sys.exit(0)
            except:
                SysMgr.printOpenWarn(taskPath)
                continue

            for tid in tids:
                try:
                    if tid == pid:
                        procTree[tid] = SysMgr.getTaskStr(pid, save=True)
                    else:
                        SysMgr.getComm(tid, save=True)

                        procTree[tid] = pid
                except SystemExit:
                    sys.exit(0)
                except:
                    continue

        return procTree

    @staticmethod
    def setSortValue(values):
        if SysMgr.checkMode(["printslab", "checkdup"]):
            SysMgr.sort = values
            return True

        value = cond = None
        if values:
            values = values.split(":")
            if len(values) == 1:
                value = values[0]
                cond = None
            elif len(values) > 1:
                value, cond = values[:2]

        if value == "c":
            SysMgr.printInfo("sorted by CPU")
        elif value == "N":
            SysMgr.printInfo("sorted by NAME")
        elif value == "m":
            SysMgr.printInfo("sorted by MEMORY")
        elif value == "b":
            SysMgr.printInfo("sorted by BLOCK")
            if SysMgr.checkDiskTopCond():
                SysMgr.blockEnable = True
            else:
                sys.exit(-1)
        elif value == "w":
            SysMgr.printInfo("sorted by CHILD")
            SysMgr.wfcEnable = True
        elif value == "p":
            SysMgr.printInfo("sorted by PID")
        elif value == "n":
            SysMgr.printInfo("sorted by NEW")
        elif value == "e":
            SysMgr.printInfo("sorted by EXECTIME")
            SysMgr.schedEnable = True
        elif value == "d":
            SysMgr.printInfo("sorted by DELAY")
            SysMgr.schedEnable = True
        elif value == "D":
            SysMgr.printInfo("sorted by D-Bus")
        elif value == "r":
            SysMgr.printInfo("sorted by RUNTIME")
        elif value == "o":
            SysMgr.printInfo("sorted by OOMSCORE")
            TaskAnalyzer.setLastField("oom")
        elif value == "P":
            SysMgr.printInfo("sorted by PRIORITY")
        elif value == "f":
            SysMgr.printInfo("sorted by FILE")
            SysMgr.fileTopEnable = True
        elif value == "s":
            SysMgr.printInfo("sorted by SWAP")
        elif value == "C":
            if not SysMgr.checkMode("ttop"):
                SysMgr.printErr(
                    "failed to sort by CONTEXTSWITCH because "
                    "it is supported on thread mode"
                )
                sys.exit(-1)
            SysMgr.printInfo("sorted by CONTEXTSWITCH")
        elif not value:
            value = None
        else:
            SysMgr.printErr("wrong option value '%s' for sort" % value)
            return False

        SysMgr.sort = value
        if cond and len(cond) > 1:
            if cond[0] == ">":
                SysMgr.sortCondOp = ">"
                cond = cond[1:]
            elif cond[0] == "<":
                SysMgr.sortCondOp = "<"
                cond = cond[1:]
        SysMgr.sortCond = cond

        return True

    @staticmethod
    def readAppArmorInfo():
        return SysMgr.readFile(
            "/sys/kernel/security/apparmor/profiles", verb=False
        )

    @staticmethod
    def readPageInfo():
        try:
            pageBlockOrder = 0
            pagePerBlock = 0
            freeTitle = False
            blockTitle = False
            freeInfo = {}
            blockInfo = {}

            lines = SysMgr.procReadlines("pagetypeinfo")

            for item in lines:
                if item == "\n":
                    continue
                elif not pageBlockOrder and item.startswith(
                    "Page block order:"
                ):
                    pageBlockOrder = long(item.split(":")[1])
                    continue
                elif not pagePerBlock and item.startswith("Pages per block:"):
                    pagePerBlock = long(item.split(":")[1])
                    continue
                elif not freeTitle and item.startswith("Free pages"):
                    freeTitle = True
                    continue
                elif not blockTitle and item.startswith("Number of blocks"):
                    blockTitle = UtilMgr.lstrip(
                        item, "Number of blocks "
                    ).split()[1:]
                    continue
                elif blockTitle:
                    item = item.rstrip().split(",")[:2]

                    node = item[0].split()[1]
                    values = item[1].split()
                    zone = values[1]
                    blocks = list(
                        map(lambda f: long(f.lstrip(">")), values[2:])
                    )

                    blockInfo.setdefault(node, {})
                    blockInfo[node].setdefault(zone, {})

                    for ztype, block in zip(blockTitle, blocks):
                        blockInfo[node][zone][ztype] = block
                else:
                    item = item.rstrip().split(",")[:3]

                    node = item[0].split()[1]
                    zone = item[1].split()[1]
                    values = item[2].split()
                    ztype = values[1]
                    pages = list(
                        map(lambda f: long(f.lstrip(">")), values[2:])
                    )

                    freeInfo.setdefault(node, {})
                    freeInfo[node].setdefault(zone, {})
                    freeInfo[node][zone][ztype] = pages
        except SystemExit:
            sys.exit(0)
        except:
            SysMgr.printWarn("failed to read page info", reason=True)

        return {
            "pageBlockOrder": pageBlockOrder,
            "pagePerBlock": pagePerBlock,
            "freeInfo": freeInfo,
            "blockInfo": blockInfo,
        }

    @staticmethod
    def readLockInfo():
        try:
            res = {}
            lines = SysMgr.procReadlines("locks")

            for item in lines:
                num, items = item.split(":", 1)
                reent = "*" if items.strip().startswith("-> ") else ""
                if reent:
                    items = items[3:]
                lclass, attr, op, pid, lfile, start, end = items.split()[:7]

                res.setdefault(pid, [])
                res[pid].append(
                    {
                        "class": lclass,
                        "attr": attr,
                        "op": op,
                        "file": lfile,
                        "start": start,
                        "end": end,
                        "reent": reent,
                    }
                )
        except SystemExit:
            sys.exit(0)
        except:
            SysMgr.printWarn("failed to read lock info", reason=True)

        return res

    @staticmethod
    def readBuddyInfo():
        try:
            res = {}
            lines = SysMgr.procReadlines("buddyinfo")

            for item in lines:
                node, items = item.split(",", 1)
                node = node.split()[1]
                items = UtilMgr.lstrip(items.strip(), "zone").strip().split()
                name = items.pop(0)
                orders = list(map(long, items))

                res.setdefault(node, {})
                res[node][name] = orders
        except SystemExit:
            sys.exit(0)
        except:
            SysMgr.printWarn("failed to read buddy info", reason=True)

        return res

    @staticmethod
    def readMemoryMap():
        try:
            res = {}
            lines = SysMgr.procReadlines("iomem")
            for idx, item in enumerate(lines):
                addrs, name = item.split(":", 1)
                start, end = UtilMgr.cleanItem(
                    addrs.rstrip().split("-"), False
                )
                startAddr = long(start, 16)
                size = long(end, 16) - startAddr + 1
                sizeUnit = "%s (%7s)" % (
                    UtilMgr.convNum(size),
                    UtilMgr.convSize2Unit(size),
                )

                if startAddr in res:
                    startAddr = idx

                res[startAddr] = {
                    "name": name.strip(),
                    "start": start,
                    "end": end,
                    "size": size,
                    "sizeUnit": sizeUnit,
                }
        except SystemExit:
            sys.exit(0)
        except:
            SysMgr.printWarn("failed to read memory map", reason=True)

        return res

    @staticmethod
    def readDmabufStats():
        if "DMABUF" not in SysMgr.environList:
            return {}

        dpath = "/sys/kernel/dmabuf/buffers"
        if not os.path.exists(dpath):
            return {}

        try:
            stats = {}

            for inode in os.listdir(dpath):
                stats[inode] = {}
                mpath = os.path.join(dpath, inode)
                for f in os.listdir(mpath):
                    fpath = os.path.join(mpath, f)
                    stats[inode][f] = SysMgr.readFile(fpath, verb=False)
        except SystemExit:
            sys.exit(0)
        except:
            SysMgr.printErr("failed to get dmabuf stats", True)

        return stats

    @staticmethod
    def readPsiStats():
        dpath = "/proc/pressure"
        if not os.path.exists(dpath):
            return {}

        try:
            stats = {}

            for item in os.listdir(dpath):
                fpath = os.path.join(dpath, item)
                if os.path.isdir(fpath):
                    continue

                values = SysMgr.readFile(fpath)
                if not values:
                    continue

                stats.setdefault(item, {})

                for line in values.split("\n"):
                    if not line.strip():
                        continue

                    target, avg10, avg60, avg300, total = line.split()[:5]

                    """
                    some: delay for at least one task
                    full: delay for all tasks simultaneously
                    ----------------------------------------
                    avg: average time for seconds in %
                    total: total time for seconds in us
                    """

                    stats[item][target] = {
                        "avg10": float(avg10.split("=")[1]),
                        "avg60": float(avg60.split("=")[1]),
                        "avg300": float(avg300.split("=")[1]),
                        "total": float(total.split("=")[1]),
                    }
        except SystemExit:
            sys.exit(0)
        except:
            SysMgr.printErr("failed to get PSI stats", True)

        return stats

    @staticmethod
    def readSchedFeatures():
        try:
            path = "/sys/kernel/debug/sched_features"
            fd = open(path, "r")
            return sorted(fd.readline().split())
        except SystemExit:
            sys.exit(0)
        except:
            SysMgr.printOpenWarn(path)
            return []

    @staticmethod
    def readProcData(tid, path, num=-1, verb=True):
        path = "%s/%s/%s" % (SysMgr.procPath, tid, path)

        try:
            f = open(path, "r")

            if num == -1:
                return f.readlines()

            val = f.readline().replace("\n", "")
            if num == 0:
                return val

            return val.split()[num - 1]
        except SystemExit:
            sys.exit(0)
        except:
            if verb:
                SysMgr.printOpenErr(path)
            return None

    @staticmethod
    def hasMainArg(dash=False):
        if len(sys.argv) <= 2:
            return False
        elif not dash and sys.argv[2].startswith("-"):
            return False
        else:
            return True

    @staticmethod
    def getMainArgs(union=True, token=",", path=False):
        args = SysMgr.getMainArg(path)
        if not isinstance(args, list):
            args = args.replace("\\" + token, SysMgr.magicStr)
            args = [
                t.replace(SysMgr.magicStr, token) for t in args.split(token)
            ]
        return UtilMgr.cleanItem(args, union)

    @staticmethod
    def getMainArg(path=False):
        if len(sys.argv) <= 2:
            return None
        elif not path:
            return sys.argv[2]
        else:
            return UtilMgr.convPath(sys.argv[2], retStr=True, separator=",")

    @staticmethod
    def checkEnv():
        def _checkMode():
            if len(sys.argv) == 1:
                return True

            cmd = sys.argv[1]

            if cmd in (
                "addr2sym",
                "ask",
                "bgtop",
                "chat",
                "cli",
                "comp",
                "convert",
                "convlog",
                "cputest",
                "ctop",
                "decomp",
                "dirdiff",
                "disktop",
                "drawreq",
                "elftree",
                "embed",
                "exec",
                "fserver",
                "helptest",
                "hserver",
                "iotest",
                "less",
                "list",
                "merge",
                "mkcache",
                "ntop",
                "ping",
                "print",
                "printboot",
                "printdir",
                "printdlt",
                "printext",
                "ps",
                "pstree",
                "rag",
                "readelf",
                "readdex",
                "readapk",
                "report",
                "req",
                "rtop",
                "scrcap",
                "scrrec",
                "send",
                "split",
                "strings",
                "sym2addr",
                "tail",
                "top",
                "topdiff",
                "topsum",
                "trtop",
                "ttop",
            ):
                return True
            elif SysMgr.isDarwin and cmd in (
                "dlttop",
                "ftop",
                "kill",
                "printdlt",
                "server",
            ):
                return True
            elif SysMgr.isLinux and cmd in (
                "attop",
                "bdtop",
                "tptop",
            ):
                return True
            elif SysMgr.isDrawMode() or SysMgr.isHelpMode():
                return True

            return False

        SysMgr.platform = sys.platform

        def _checkOS():
            if len(sys.argv) == 1:
                pass
            elif not _checkMode():
                SysMgr.colorEnable = False
                if sys.argv[1] in SysMgr.getCmdSet():
                    SysMgr.printErr(
                        "'%s' command is not supported on '%s' platform"
                        % (sys.argv[1], SysMgr.platform)
                    )
                else:
                    SysMgr.printErr("no command '%s'" % sys.argv[1])
                sys.exit(-1)

        if SysMgr.platform.startswith(("linux", "android")):
            SysMgr.isLinux = True

            try:
                os.environ["TERM"] = "xterm"

                if "REMOTERUN" in os.environ:
                    SysMgr.encodeEnable = False
                    SysMgr.remoteRun = True
                    SysMgr.colorEnable = False
                else:
                    SysMgr.colorEnable = True

                if "LANG" not in os.environ or "tty" in os.ttyname(
                    sys.stdout.fileno()
                ):
                    SysMgr.encodeEnable = False
            except SystemExit:
                sys.exit(0)
            except:
                pass

            SysMgr.absColorEnable = SysMgr.isTraceMode()

            if SysMgr.platform.startswith("android") or (
                "ANDROID_ROOT" in os.environ and "NO_ANDROID" not in os.environ
            ):
                SysMgr.isAndroid = True
                SysMgr.tmpPath = SysMgr.tmpAndroidPath
                SysMgr.libcPath = "libc"
                SysMgr.libcppPath = "libstdc++"
                if os.path.exists("/system/lib/libgccdemangle.so"):
                    SysMgr.libdemanglePath = "libgccdemangle"
                else:
                    SysMgr.libdemanglePath = "libbacktrace"
                SysMgr.cacheDirPath = "/data/log/guider"

                if "PATH" in os.environ:
                    os.environ["PATH"] += os.pathsep + os.pathsep.join(
                        [
                            "/odm/bin",
                            "/system/bin",
                            "/system/xbin",
                            "/system_ext/bin",
                            "/vendor/bin",
                            "/vendor/xbin",
                        ]
                    )

            elif (
                True
                and len(sys.argv) > 1
                and sys.argv[1]
                in (
                    "andcmd",
                    "attop",
                    "bugrec",
                    "bugrep",
                    "gfxtop",
                    "getprop",
                    "logand",
                    "mdtop",
                    "scrcap",
                    "scrrec",
                    "setprop",
                    "watchprop",
                )
                and (not SysMgr.findOption("f") and not SysMgr.isHelpMode())
            ):
                SysMgr.printErr(
                    "'%s' command is not supported on '%s' platform"
                    % (sys.argv[1], SysMgr.platform)
                )
                sys.exit(-1)

        elif SysMgr.platform.startswith("win"):
            SysMgr.isLinux = False
            SysMgr.isWindows = True

            _checkOS()

            SysMgr.setStopHandler()

            SysMgr.colorEnable = False

        elif SysMgr.platform.startswith("darwin"):
            SysMgr.isLinux = False
            SysMgr.isDarwin = True
            ConfigMgr.SIG_LIST = ConfigMgr.SIG_LIST_MACOS

            _checkOS()

            SysMgr.colorEnable = True

        elif SysMgr.platform.startswith("qnx"):
            SysMgr.isLinux = False
            SysMgr.isQnx = True

            _checkOS()

            SysMgr.colorEnable = True

        else:
            SysMgr.printErr("'%s' platform is not supported" % SysMgr.platform)
            sys.exit(-1)

        try:
            if not SysMgr.encodeEnable:
                pass
            elif "NO_ENCODE" in os.environ:
                SysMgr.encodeEnable = False
            else:
                lang = os.getenv("LANG")
                if not lang or "UTF" not in lang:
                    SysMgr.encodeEnable = False
        except SystemExit:
            sys.exit(0)
        except:
            pass

        if sys.version_info < (2, 6):
            SysMgr.printWarn(
                "some features may not work on python %d.%d"
                % (sys.version_info[0], sys.version_info[1]),
                True,
            )

    @staticmethod
    def onAlarmExit(signum, frame):
        SysMgr.updateTimer()

        sys.exit(0)

    @staticmethod
    def onAlarm(signum, frame):
        SysMgr.progressCnt += 1
        if SysMgr.repeatCnt <= SysMgr.progressCnt:
            SysMgr.printWarn("terminated by timer\n", True)
            sys.exit(0)

        SysMgr.updateTimer()

    @staticmethod
    def checkProgress():
        if SysMgr.inExit:
            return

        def _getPsiAvg10(path):
            try:
                with open(path) as _f:
                    for _line in _f:
                        if _line.startswith("some"):
                            return float(_line.split()[1].split("=")[1])
            except:
                pass
            return -1.0

        _psiCpuVal = _getPsiAvg10("/proc/pressure/cpu")
        _psiMemVal = _getPsiAvg10("/proc/pressure/memory")
        _psiIOVal = _getPsiAvg10("/proc/pressure/io")
        try:
            _la = SysMgr.loadavg
            _load1 = (
                float(_la[0])
                if isinstance(_la, (list, tuple))
                else float(str(_la).split()[0])
            )
        except:
            _load1 = -1.0
        try:
            _gpuLoad = SysMgr.jsonData.get("gpu", {}).get("load", -1)
        except:
            _gpuLoad = -1

        exitCond = (
            0 < SysMgr.deadlineUptime <= SysMgr.uptime
            or 0 < SysMgr.exitCondCpuMore <= SysMgr.cpuUsage
            or 0 < SysMgr.exitCondCpuLess >= SysMgr.cpuUsage
            or 0 < SysMgr.exitCondMemMore <= SysMgr.memAvail
            or 0 < SysMgr.exitCondMemLess >= SysMgr.memAvail
            or (
                SysMgr.exitCondFile
                and any(os.path.exists(f) for f in SysMgr.exitCondFile)
            )
            or (
                SysMgr.exitCondNoFile
                and any(not os.path.exists(f) for f in SysMgr.exitCondNoFile)
            )
            or (0 <= SysMgr.exitCondPsiCpu <= _psiCpuVal)
            or (0 <= SysMgr.exitCondPsiMem <= _psiMemVal)
            or (0 <= SysMgr.exitCondPsiIO <= _psiIOVal)
            or (0 <= SysMgr.exitCondLoad1m <= _load1)
            or (0 <= SysMgr.exitCondGpu <= _gpuLoad)
        )

        if exitCond:
            reason = "condition"
        elif SysMgr.countEnable and SysMgr.progressCnt >= SysMgr.repeatCnt > 0:
            reason = "timer"
        else:
            reason = None

        if reason:
            UtilMgr.deleteProgress()

            try:
                SysMgr.printWarn("terminated by %s\n" % reason, True)
                os.kill(SysMgr.pid, signal.SIGINT)
                # send SIGKILL only if already in reporting phase (i.e., second
                # checkProgress call during stopHandler) to avoid killing the
                # process mid-report when outPath is set #
                if SysMgr.inExit:
                    os.kill(SysMgr.pid, signal.SIGKILL)
            except SystemExit:
                sys.exit(0)
            except:
                SysMgr.printSigError(SysMgr.pid, "SIGINT")

        if not SysMgr.countEnable:
            return

        if SysMgr.repeatCnt > 1:
            UtilMgr.printProgress(SysMgr.progressCnt, SysMgr.repeatCnt)

        SysMgr.progressCnt += 1

    @staticmethod
    def getCmdSet():
        cmdSet = []
        for types in SysMgr.getCmdList().values():
            cmdSet += types.keys()
        return set(cmdSet)

    @staticmethod
    def getCmdString():
        cmdList = SysMgr.getCmdList()

        cmdbuf = ""
        for ctype, tvalue in sorted(cmdList.items()):
            prefix = ctype
            for cmd, cvalue in sorted(tvalue.items()):
                if prefix:
                    types = "[%s]" % prefix.upper()
                else:
                    types = " "

                cmdbuf = "%s%4s%-12s%4s%-15s%4s%-15s (%-s)\n" % (
                    cmdbuf,
                    " ",
                    types,
                    " ",
                    cmd,
                    " ",
                    "<%s>" % cvalue[0],
                    cvalue[1],
                )
                prefix = ""
            cmdbuf = "%s\n" % cmdbuf

        return cmdbuf[:-1]

