    @staticmethod
    def getUdsList(addrList):
        def _getStats(addrList):
            retList = []
            for item in addrList:
                if item in SysMgr.udsListCache:
                    retList.append(SysMgr.udsListCache[item])
            return retList

        if SysMgr.udsListCache:
            return _getStats(addrList)

        inodeIdx = ConfigMgr.UDS_ATTR.index("Inode")
        pathIdx = ConfigMgr.UDS_ATTR.index("Path")

        udsBuf = []
        udsPath = "%s/net/unix" % SysMgr.procPath

        SysMgr.nrUDSSock = 0

        try:
            with open(udsPath, "r") as fd:
                udsBuf = fd.read().split("\n")
        except SystemExit:
            sys.exit(0)
        except:
            SysMgr.printOpenWarn(udsPath)
            return udsBuf

        udsBuf.pop(0)

        for line in udsBuf:
            try:
                if not line:
                    continue

                SysMgr.nrUDSSock += 1

                uds = line.split()

                item = "UDS>%s" % uds[pathIdx]

                SysMgr.udsListCache[uds[inodeIdx]] = item
            except SystemExit:
                sys.exit(0)
            except:
                pass

        SysMgr.maxNrUDSSock = max(SysMgr.nrUDSSock, SysMgr.maxNrUDSSock)

        return _getStats(addrList)

    @staticmethod
    def getUdpList(addrList):
        def _getStats(addrList):
            retList = []
            for item in addrList:
                if item in SysMgr.udpListCache:
                    retList.append(SysMgr.udpListCache[item])
            return retList

        if SysMgr.udpListCache:
            return _getStats(addrList)

        inodeIdx = ConfigMgr.PROTOCOL_ATTR.index("inode")
        laddrIdx = ConfigMgr.PROTOCOL_ATTR.index("local_address")
        queueIdx = ConfigMgr.PROTOCOL_ATTR.index("tx_rx_queue")

        udpBuf = []
        udpFileList = [
            "%s/net/udp" % SysMgr.procPath,
            "%s/net/udp6" % SysMgr.procPath,
        ]

        SysMgr.nrUDPSock = 0
        SysMgr.nrUDPTxQ = 0
        SysMgr.nrUDPRxQ = 0

        for udpPath in udpFileList:
            try:
                with open(udpPath, "r") as fd:
                    udpBuf = fd.read().split("\n")
            except SystemExit:
                sys.exit(0)
            except:
                SysMgr.printOpenWarn(udpPath)
                continue

            udpBuf.pop(0)

            for line in udpBuf:
                try:
                    if not line:
                        continue

                    SysMgr.nrUDPSock += 1

                    udp = line.split()

                    lip, lport = udp[laddrIdx].split(":")
                    lip = SysMgr.convCIDR(lip)
                    item = "UDP>%s:%s" % (lip, long(lport, base=16))

                    rip, rport = udp[laddrIdx + 1].split(":")

                    try:
                        rport = long(rport, 16)
                        if long(rip, 16) > 0 and rport > 0:
                            rip = SysMgr.convCIDR(rip)
                            item = "%s->%s:%s" % (item, rip, rport)
                    except SystemExit:
                        sys.exit(0)
                    except:
                        pass

                    try:
                        if udp[queueIdx] == "00000000:00000000":
                            raise Exception()

                        _conv = lambda x: UtilMgr.convSize2Unit(x)

                        queue = []
                        tx, rx = udp[queueIdx].split(":")
                        if tx != "00000000":
                            tx = long(tx, 16)
                            SysMgr.nrUDPTxQ += tx
                            queue.append("tx:%s" % _conv(tx))
                        if rx != "00000000":
                            rx = long(rx, 16)
                            SysMgr.nrUDPRxQ += rx
                            queue.append("rx:%s" % _conv(rx))
                        if queue:
                            item += " [%s]" % ",".join(queue)
                    except SystemExit:
                        sys.exit(0)
                    except:
                        pass

                    SysMgr.udpListCache[udp[inodeIdx]] = item
                except SystemExit:
                    sys.exit(0)
                except:
                    SysMgr.printWarn(
                        "failed to parse UDP data '%s'" % line, reason=True
                    )

        SysMgr.maxNrUDPSock = max(SysMgr.nrUDPSock, SysMgr.maxNrUDPSock)
        SysMgr.maxNrUDPTxQ = max(SysMgr.nrUDPTxQ, SysMgr.maxNrUDPTxQ)
        SysMgr.maxNrUDPRxQ = max(SysMgr.nrUDPRxQ, SysMgr.maxNrUDPRxQ)

        return _getStats(addrList)

    @staticmethod
    def getTcpList(addrList, cache=True):
        def _getStats(addrList):
            items = []
            for item in addrList:
                if item in SysMgr.tcpListCache:
                    items.append(SysMgr.tcpListCache[item])
            return items

        if not cache:
            SysMgr.tcpListCache = {}

        if SysMgr.tcpListCache:
            return _getStats(addrList)

        stIdx = ConfigMgr.PROTOCOL_ATTR.index("st")
        inodeIdx = ConfigMgr.PROTOCOL_ATTR.index("inode")
        laddrIdx = ConfigMgr.PROTOCOL_ATTR.index("local_address")
        queueIdx = ConfigMgr.PROTOCOL_ATTR.index("tx_rx_queue")
        estIdx = ConfigMgr.TCP_STAT.index("ESTABLISHED")

        tcpBuf = []
        tcpFileList = [
            "%s/net/tcp" % SysMgr.procPath,
            "%s/net/tcp6" % SysMgr.procPath,
        ]

        SysMgr.nrTCPSock = 0
        SysMgr.nrTCPTxQ = 0
        SysMgr.nrTCPRxQ = 0
        SysMgr.nrTCPConn = 0

        for tcpPath in tcpFileList:
            try:
                with open(tcpPath, "r") as fd:
                    tcpBuf = fd.read().split("\n")
            except SystemExit:
                sys.exit(0)
            except:
                SysMgr.printOpenWarn(tcpPath)
                continue

            tcpBuf.pop(0)

            for line in tcpBuf:
                try:
                    if not line:
                        continue

                    SysMgr.nrTCPSock += 1

                    tcp = line.split()

                    lip, lport = tcp[laddrIdx].split(":")
                    lip = SysMgr.convCIDR(lip)
                    lport = long(lport, base=16)
                    item = "TCP>%s:%s" % (lip, lport)

                    rip, rport = tcp[laddrIdx + 1].split(":")

                    try:
                        rport = long(rport, 16)
                        if rport > 0 and long(rip, 16) > 0:
                            rip = SysMgr.convCIDR(rip)
                            item = "%s->%s:%s" % (item, rip, rport)
                    except SystemExit:
                        sys.exit(0)
                    except:
                        pass

                    try:
                        tcpStat = long(tcp[stIdx], 16)

                        if tcpStat == estIdx:
                            SysMgr.nrTCPConn += 1

                        stat = "/%s" % ConfigMgr.TCP_STAT[tcpStat]
                    except SystemExit:
                        sys.exit(0)
                    except:
                        stat = ""

                    item += stat

                    try:
                        if tcp[queueIdx] == "00000000:00000000":
                            raise Exception()

                        _conv = lambda x: UtilMgr.convSize2Unit(x)

                        queue = []
                        tx, rx = tcp[queueIdx].split(":")
                        if tx != "00000000":
                            tx = long(tx, 16)
                            SysMgr.nrTCPTxQ += tx
                            queue.append("tx:%s" % _conv(tx))
                        if rx != "00000000":
                            rx = long(rx, 16)
                            SysMgr.nrTCPRxQ += rx
                            queue.append("rx:%s" % _conv(rx))
                        if queue:
                            item += " [%s]" % ",".join(queue)
                    except SystemExit:
                        sys.exit(0)
                    except:
                        pass

                    SysMgr.tcpListCache[tcp[inodeIdx]] = item
                except SystemExit:
                    sys.exit(0)
                except:
                    SysMgr.printWarn(
                        "failed to parse TCP data '%s'" % line, reason=True
                    )

        SysMgr.maxNrTCPSock = max(SysMgr.nrTCPSock, SysMgr.maxNrTCPSock)
        SysMgr.maxNrTCPTxQ = max(SysMgr.nrTCPTxQ, SysMgr.maxNrTCPTxQ)
        SysMgr.maxNrTCPRxQ = max(SysMgr.nrTCPRxQ, SysMgr.maxNrTCPRxQ)

        return _getStats(addrList)

