    @staticmethod
    def reqHandler(signum, frame):
        def _sendErrMsg(connObj, msg):
            connObj.write('{"error": %s}' % msg)

        def _sendInfoMsg(connObj, msg):
            connObj.write('{"info": %s}' % msg)

        def _printErr(msg, reason=False):
            SysMgr.printErr(msg, reason=reason)
            _sendErrMsg(connObj, msg)

        def _printInfo(msg):
            SysMgr.printInfo(msg)
            _sendInfoMsg(connObj, msg)

        def _handleCmd(connObj, cmd, cliProc):
            SysMgr.updateEventStatus()

            cmdList = cmd.split("|")
            mainCmd = cmdList[0].lower().strip()
            cmdOpt = (
                [s.strip() for s in cmdList[1:]] if len(cmdList) > 1 else []
            )

            if mainCmd == "watch":
                SysMgr.printInfo("registered %s for event watch" % cliProc)
                SysMgr.eventSubList.append([cliProc, connObj])
                return
            elif SysMgr.isLimitMode(mainCmd):
                origProcessEnable = SysMgr.processEnable
                origTargetExe = SysMgr.environList.pop("TARGETEXE", None)
                origTargetCmd = SysMgr.environList.pop("TARGETCMD", None)

                upperOpts = list(map(str.upper, cmdOpt))
                SysMgr.processEnable = "PROCESS" in upperOpts
                for name in ("TARGETEXE", "TARGETCMD"):
                    if name in upperOpts:
                        SysMgr.environList[name] = ["SET"]

                try:
                    ret = SysMgr.applyLimitVars(
                        {mainCmd.upper(): [":".join(cmdOpt[:1])]}
                    )
                    if ret:
                        _printInfo(
                            "applied %s command for %s"
                            % (
                                cmd,
                                SysMgr.getCommList(
                                    ret,
                                    cmdline="TARGETCMD" in SysMgr.environList,
                                ),
                            )
                        )
                    else:
                        raise Exception("no task")
                except SystemExit:
                    sys.exit(0)
                except Exception:
                    _printErr("failed to execute %s command" % cmd)

                try:
                    connObj.close()
                except:
                    pass

                SysMgr.processEnable = origProcessEnable
                for flag, name in (
                    (origTargetExe, "TARGETEXE"),
                    (origTargetCmd, "TARGETCMD"),
                ):
                    if flag:
                        SysMgr.environList[name] = flag
                    else:
                        SysMgr.environList.pop(name, None)
                return

            nrMaxJob = UtilMgr.getEnvironNum("NRMAXJOB", False, 0, False)
            if nrMaxJob:
                nrJobs = len(SysMgr.getEventTaskList(json=True))
                if nrMaxJob <= nrJobs:
                    _printErr(
                        (
                            "failed to run a new job "
                            "because %s jobs are already running (MAX:%s)"
                        )
                        % (UtilMgr.convNum(nrJobs), UtilMgr.convNum(nrMaxJob))
                    )
                    return

            localServObj = SysMgr.localServObj
            eventCommandList = SysMgr.eventCommandList

            isSaveMode = mainCmd in ("save", "saveraw", "savemin")

            pid = SysMgr.createProcess()
            if pid > 0:
                connObj.close()

                SysMgr.addEventInfo(cmd, pid)

                if isSaveMode or mainCmd in (
                    "cpuprof",
                    "memprof",
                    "scrrec",
                    "scrcap",
                    "bugrec",
                    "bugrep",
                ):
                    with SysMgr._nrReportLock:
                        SysMgr.nrReport += 1

                return

            sys.argv = sys.argv[:2]
            optStr = " ".join(cmdOpt)
            if optStr:
                try:
                    SysMgr.updateEnvironVars(optStr)
                    if mainCmd not in ("run",):
                        SysMgr.parseAnalOption(optStr)
                except:
                    _printErr("failed to apply options '%s'" % optStr, True)
                    return

            SysMgr.setSignal(SysMgr.commSig, signal.SIG_IGN)
            SysMgr.setSignal(signal.SIGINT, SysMgr.termHandler)
            SysMgr.clearExitFunc()
            SysMgr.encodeEnable = False
            SysMgr.colorEnable = False
            SysMgr.printEnable = True
            SysMgr.streamEnable = True
            SysMgr.eventCommandList = eventCommandList
            SysMgr.progressEnable = False
            origOutPath = SysMgr.outPath
            if origOutPath:
                origOutPath = SysMgr.convFullPath(origOutPath)
            SysMgr.outPath = None
            if not SysMgr.getOption("i"):
                SysMgr.intervalEnable = 1
            keepTask = "BGTASK" in SysMgr.environList

            SysMgr.addEnvironVar("SERVERTASK")
            if not SysMgr.stdlog:
                SysMgr.stdlog = SysMgr.printFd

            def _monitorConn(connObj, mainCmd, keepTask):
                while 1:
                    try:
                        if keepTask:
                            return

                        selectObj = SysMgr.getPkg("select")
                        selectObj.select([connObj.socket], [], [])

                        if NetworkMgr.check(connObj.socket):
                            time.sleep(0.1)
                            continue

                        SysMgr.printInfo(
                            "disconnected from %s for '%s' command"
                            % (cliProc, cmd)
                        )

                        # kill tracked descendants BEFORE removing the
                        # output dir (previously done in the opposite
                        # order, unlinking the dir while children were
                        # still writing to it); killOpenFds catches any
                        # orphan left behind by a parent that was already
                        # reparented to init before this snapshot #
                        SysMgr.killChildren(descendants=True, wait=True)

                        if mainCmd in ("bugrec", "bugrep"):
                            if os.path.isdir(SysMgr.outPath):
                                SysMgr.removeDirs(
                                    SysMgr.outPath, killOpenFds=True
                                )

                        os.kill(os.getpid(), signal.SIGKILL)

                        return
                    except SystemExit:
                        sys.exit(0)
                    except:
                        SysMgr.printWarn(
                            "failed to monitor the socket for %s of %s"
                            % (cmd, cliProc),
                            True,
                            True,
                        )

            def _retJson(connObj, retDict, pretty=False):
                if connObj:
                    connObj.write(UtilMgr.convDict2Str(retDict, pretty=pretty))

            def _setOutput(connObj):
                if connObj:
                    SysMgr.printFd = connObj

            threadObj = SysMgr.getPkg("threading")
            tobj = threadObj.Thread(
                target=_monitorConn, args=[connObj, mainCmd, keepTask]
            )
            tobj.daemon = True
            tobj.start()

            def _printExecutedCmd():
                SysMgr.printInfo(
                    "executed '%s' command from %s" % (cmd, cliProc)
                )

            isDrawMode = mainCmd in SysMgr.getCmdList().get("visual", {})
            if not (
                mainCmd
                in (
                    "andcmd",
                    "bdmon",
                    "bdtop",
                    "bgkill",
                    "bpfblktop",
                    "bpfdroptop",
                    "bpfnetlat",
                    "bpfpktsnoop",
                    "bpfpkttop",
                    "bpfrunqtop",
                    "bpfstacktop",
                    "bpfsyscalltop",
                    "bpftcplat",
                    "bpftcplife",
                    "bpftcpretrans",
                    "bpfwaittop",
                    "bugrec",
                    "bugrep",
                    "cantop",
                    "cansnoop",
                    "control",
                    "cpuprof",
                    "cputest",
                    "dir",
                    "dirlist",
                    "disablepkglist",
                    "download",
                    "dump",
                    "dumpfile",
                    "enablepkglist",
                    "event",
                    "funcall",
                    "funcschema",
                    "getactlist",
                    "getappstat",
                    "getconf",
                    "getdumplist",
                    "getpeak",
                    "getpermlist",
                    "getpkg",
                    "getpkgattr",
                    "getpkginfo",
                    "getpkglist",
                    "getpkglistinfo",
                    "getprop",
                    "getsettings",
                    "gfxmon",
                    "gfxtop",
                    "iotest",
                    "jobs",
                    "kill",
                    "logcat",
                    "logmon",
                    "memmon",
                    "memprof",
                    "memtest",
                    "memtop",
                    "ntop",
                    "overlay",
                    "printboot",
                    "ps",
                    "pslist",
                    "remove",
                    "resmon",
                    "ressum",
                    "restop",
                    "restopsum",
                    "run",
                    "runpkglist",
                    "save",
                    "savemin",
                    "saveraw",
                    "scrcap",
                    "screeninfo",
                    "scrrec",
                    "setprop",
                    "setsettings",
                    "stoppkglist",
                    "sysdump",
                    "sysinfo",
                    "syslist",
                    "taskresmon",
                    "tkill",
                    "updateconf",
                )
                or isDrawMode
            ):
                errMsg = "no support '%s' command" % mainCmd
                _printErr(errMsg)
                sys.exit(-1)

            _printExecutedCmd()

            SysMgr.setComm("guider_" + mainCmd)

            if (
                mainCmd
                not in (
                    "dump",
                    "sysdump",
                    "funcall",
                    "funcschema",
                )
                and not isSaveMode
            ):
                SysMgr.clearProcBuffer()

            if keepTask:
                connObj.close()
                connObj = None
                SysMgr.closeStdFd(stderr=False)
                SysMgr.initStdFd(stdout=True, binary=True)
                connObj = sys.stdout

            if mainCmd in ("dump", "sysdump", "dumpfile"):
                if mainCmd == "dumpfile":
                    if not cmdOpt:
                        _printErr("no target file path")
                        sys.exit(-1)
                    targetFile = cmdOpt[0]
                else:
                    targetFile = "tmp"

                    SysMgr.printFd = MemoryFile(name="buf")
                    TaskAnalyzer.printIntervalUsage(
                        onlySummary=True, onlyTotal=(mainCmd == "sysdump")
                    )

                if not (
                    SysMgr.rssEnable or SysMgr.pssEnable or SysMgr.ussEnable
                ):
                    SysMgr.rssEnable = True

                SysMgr.jsonEnable = True
                if SysMgr.printFd:
                    SysMgr.printFd.seek(0)
                stats, memstat = TaskAnalyzer.getStatsFile(
                    targetFile, handle=SysMgr.printFd
                )

                _setOutput(connObj)

                _retJson(connObj, stats)

            elif isSaveMode:
                SysMgr.outPath = origOutPath

                cmdstr = mainCmd.upper()
                if cmdOpt:
                    cmdstr += ":" + "|".join(cmdOpt)

                # WARN: timers are not supported in this context #

                def _pathSender(connObj, cmd):
                    # pylint: disable=unsupported-membership-test
                    path = SysMgr.lastReportPath
                    if path and not os.path.exists(path):
                        # only adopt the pid-suffixed name if it actually exists #
                        suffix = "_%s." % SysMgr.pid
                        if suffix not in path:
                            name, ext = path.rsplit(".", 1)
                            candidate = name + suffix + ext
                            if os.path.exists(candidate):
                                path = candidate

                    pathDict = {
                        "cmd": cmd,
                        "path": path,
                        "size": UtilMgr.getFileSize(path, False),
                    }
                    _retJson(connObj, pathDict)

                SysMgr.addExitFunc(_pathSender, [connObj, cmd])

                try:
                    SysMgr.topInstance.handleEventCmd(
                        cmdstr, "CUSTOM", False, False
                    )
                except SystemExit:
                    pass
                except:
                    _printErr("failed to handle %s" % mainCmd, True)

            elif mainCmd == "run":
                if not "ALLOWRUN" in SysMgr.environList:
                    _printErr("remote run is not allowed")
                    sys.exit(-1)

                if not cmdOpt:
                    _printErr("no command")
                    sys.exit(-1)

                os.dup2(connObj.fileno, 1)

                pid = SysMgr.createProcess(cmdOpt)
                if pid < 0:
                    sys.exit(-1)

                SysMgr.setIgnoreSignal()
                os.wait()
                SysMgr.setNormalSignal()

                os._exit(-1)

            elif mainCmd in ("resmon", "taskresmon", "restop"):
                SysMgr.jsonEnable = mainCmd in ("resmon", "taskresmon")
                addOpt = ""

                _setOutput(connObj)

                if mainCmd == "taskresmon":
                    SysMgr.addEnvironVar("TASKSTREAM")
                    SysMgr.taskStreamEnable = True

                if (
                    mainCmd not in ("restop",)
                    and "ALLSTAT" not in SysMgr.environList
                ):
                    SysMgr.minStatEnable = True
                    addOpt += " -eM"

                if SysMgr.isTopMode():
                    return
                else:
                    main("top" + addOpt)
                    sys.exit(0)

            elif mainCmd in ("screeninfo", "overlay", "getsettings"):
                _setOutput(connObj)

                varName = mainCmd.upper()
                SysMgr.addEnvironVar(varName)
                AndroidMgr.doPerfetto()

            elif mainCmd in (
                "disablepkglist",
                "enablepkglist",
                "getactlist",
                "getappstat",
                "getdumplist",
                "getpermlist",
                "getpkgattr",
                "runpkglist",
                "stoppkglist",
                "setsettings",
            ):
                if not cmdOpt:
                    _printErr("no target package")
                    sys.exit(-1)

                _setOutput(connObj)

                varName = mainCmd.upper()
                SysMgr.addEnvironVar(varName, cmdOpt)
                AndroidMgr.doPerfetto()

            elif mainCmd in ("getprop", "setprop"):
                if not cmdOpt:
                    _printErr("no target property")
                    sys.exit(-1)

                _setOutput(connObj)

                if mainCmd == "getprop":
                    propList = AndroidMgr.getProp(retList=True)
                    if cmdOpt:
                        propList = list(
                            filter(
                                lambda x: UtilMgr.isValidStr(x, cmdOpt),
                                propList,
                            )
                        )
                    propList = {
                        parts[0].strip(" []"): (
                            parts[1].strip(" []") if len(parts) > 1 else ""
                        )
                        for v in propList
                        for parts in [v.split(":", 1)]
                    }
                    _retJson(connObj, propList, True)
                else:
                    for x in cmdOpt:
                        val = x.split(":", 1)
                        if len(val) != 2:
                            _printErr("%s is not in KEY:VAL format" % x)
                            continue
                        k, v = val
                        AndroidMgr.setProperty(k, v)
                        _printInfo("set '%s' to '%s'" % (k, v))

            elif mainCmd in ("ressum", "restopsum"):
                if not cmdOpt:
                    _printErr("no target file path")
                    sys.exit(-1)
                for f in cmdOpt:
                    if not os.path.exists(f):
                        _printErr("no '%s' file" % f)
                        sys.exit(-1)

                SysMgr.jsonEnable = mainCmd in ("ressum")

                _setOutput(connObj)

                TaskAnalyzer.doSumReport(cmdOpt)

            elif mainCmd in ("getconf"):
                SysMgr.jsonEnable = True

                confData = SysMgr.getConfigItem("threshold")

                _retJson(connObj, confData)

            elif mainCmd in ("getpeak"):
                SysMgr.jsonEnable = True

                peakList = SysMgr.getPeakList()

                _retJson(connObj, peakList)

            elif mainCmd in ("updateconf"):
                if not cmdOpt:
                    _printErr("no target file")
                    sys.exit(-1)

                SysMgr.jsonEnable = True

                path = cmdOpt[0]
                if not os.path.exists(path):
                    _printErr("wrong path '%s'" % path)
                    sys.exit(-1)

                SysMgr.updateThreshold(path)

                _printInfo("updated the configuration from '%s'" % path)

            elif mainCmd in ("andcmd",):
                _setOutput(connObj)
                # inject ANDCMD sub-command into sys.argv so checkAndCmd() can read it
                # (sys.argv is truncated to [:2] by TCP dispatch; ANDCMD value comes from -q)
                andcmd_val = SysMgr.environList.get("ANDCMD", "")
                if andcmd_val:
                    if isinstance(andcmd_val, list):
                        andcmd_val = andcmd_val[0] if andcmd_val else ""
                    if andcmd_val and len(sys.argv) < 3:
                        sys.argv.append(andcmd_val)
                    elif andcmd_val:
                        sys.argv[2] = andcmd_val
                try:
                    AndroidMgr.checkAndCmd()
                    AndroidMgr.doPerfetto(False)
                except SystemExit:
                    sys.exit(0)
                except:
                    _printErr("failed to run andcmd", True)
                    sys.exit(-1)

            elif mainCmd in ("bdmon", "bdtop"):
                SysMgr.jsonEnable = mainCmd == "bdmon"

                _setOutput(connObj)

                SysMgr.addEnvironVar(["FLUSH", "CONSUME"])
                targets = [
                    "binder/binder_transaction",
                    "binder/binder_transaction_received",
                ]
                cb = LogMgr.binderHandler
                parser = LogMgr.parseBinderData
                LogMgr.printTrace(False, targets=targets, cb=cb, parser=parser)

            elif mainCmd in (
                "bpfblktop",
                "bpfdroptop",
                "bpfnetlat",
                "bpfpktsnoop",
                "bpfpkttop",
                "bpfrunqtop",
                "bpfstacktop",
                "bpfsyscalltop",
                "bpftcplat",
                "bpftcplife",
                "bpftcpretrans",
                "bpfwaittop",
                "cantop",
                "cansnoop",
                "ntop",
            ):
                _setOutput(connObj)

                args = [mainCmd] + (cmdOpt if cmdOpt else [])

                # for bpfstacktop/bpfwaittop/bpfsyscalltop -qdrawflame:
                # set writable outdir so flame SVG lands in an accessible dir
                _hasDrawflame = any(
                    "drawflame" in (a or "").lower() for a in (cmdOpt or [])
                )
                _drawflame_cmds = {
                    "bpfstacktop",
                    "bpfwaittop",
                    "bpfsyscalltop",
                }
                _isDrawflame = mainCmd in _drawflame_cmds and _hasDrawflame
                if _isDrawflame:
                    _drawdir = origOutPath or "/data/local/tmp"
                    if not any(a.startswith("-o") for a in args[1:]):
                        args.extend(["-o", _drawdir])

                # for the 3 drawflame commands, the flag is checked in BPF
                # polling loops (<0.5s via _tcpStopSleep) → loop breaks,
                # drawFlameSample() + drawFile JSON sent. For the rest, this
                # thread still drains the socket so a leftover unread STOP
                # (or any other stray bytes) can't fool _monitorConn's
                # MSG_PEEK-based disconnect check into never firing.
                if _isDrawflame:
                    # store draw dir as class attr so BPF cmd can
                    # use it after main() resets SysMgr.outPath via init
                    BpfMgr._tcp_drawdir = _drawdir

                BpfMgr._tcp_stop = False
                _sock_ref = connObj.socket

                def _stop_watcher():
                    _sel = SysMgr.getPkg("select")

                    try:
                        while True:
                            rd, _, _ = _sel.select([_sock_ref], [], [], 1.0)
                            if rd:
                                data = _sock_ref.recv(connObj.recvSize)
                                if not data or b"STOP" in data:
                                    # set flag — BPF polling loop detects
                                    # it within 0.5s and breaks
                                    BpfMgr._tcp_stop = True
                                    break
                    except Exception:
                        # socket closed/error → stop BPF command immediately
                        BpfMgr._tcp_stop = True

                import threading as _thr

                _sw = _thr.Thread(target=_stop_watcher, daemon=True)
                _sw.start()

                main(args)
                sys.exit(0)

            elif mainCmd in ("cputest", "memtest", "iotest"):
                # redirect fd 1 to TCP socket so all child process output streams back #
                sys.stdout.flush()
                os.dup2(connObj.fileno, 1)
                # reopen Python stdout as line-buffered writer on new fd 1 #
                sys.stdout = open(1, "w", buffering=1, closefd=False)
                # set REMOTERUN: makes printWarn/printInfo write via print() -> stdout #
                os.environ["REMOTERUN"] = "1"

                # set printFd for printPipe callers (memtest, iotest) #
                _setOutput(connObj)

                args = [mainCmd] + (cmdOpt if cmdOpt else [])
                main(args)
                sys.exit(0)

            elif mainCmd in ("gfxmon", "gfxtop"):
                if not cmdOpt:
                    _printErr("no target info")
                    sys.exit(-1)

                # inject target into sys.argv so runGfxTop() can read it via hasMainArg()
                if len(sys.argv) < 3:
                    sys.argv.append(cmdOpt[0])
                else:
                    sys.argv[2] = cmdOpt[0]

                SysMgr.jsonEnable = mainCmd == "gfxmon"

                _setOutput(connObj)

                try:
                    SysMgr.topInstance.runGfxTop()
                except SystemExit:
                    sys.exit(0)
                except:
                    _printErr("failed to monitor gfx", True)
                    sys.exit(-1)

            elif mainCmd in ("remove", "download"):
                if not cmdOpt:
                    _printErr("no target file path")
                    sys.exit(-1)

                def _getPacket(fd):
                    while 1:
                        try:
                            packet = fd.read(connObj.sendSize)
                            if packet == b"":
                                raise Exception()
                            yield packet
                        except GeneratorExit:
                            return
                        except SystemExit:
                            sys.exit(0)
                        except:
                            yield None

                def _remove(d):
                    flist = UtilMgr.getFileList(
                        [d], sort=True, exceptDir=False
                    )
                    res = SysMgr.removeFiles(flist)
                    if res:
                        _printInfo("removed '%s'" % ",".join(res))
                    else:
                        _printErr("no removed file")

                def _download(d):
                    try:
                        fd = open(d, "rb")
                    except SystemExit:
                        sys.exit(0)
                    except:
                        _printErr("failed to open '%s'" % d, True)
                        sys.exit(-1)

                    for packet in _getPacket(fd):
                        if not packet:
                            break
                        if connObj:
                            connObj.write(packet)

                for d in cmdOpt:
                    if "NOLIMITPATH" in SysMgr.environList:
                        pass
                    elif not origOutPath:
                        _printErr("no output path in Guider")
                        sys.exit(-1)
                    elif d.startswith("/"):
                        normOutPath = origOutPath.rstrip("/") + "/"
                        if d != origOutPath and not d.startswith(normOutPath):
                            _printErr("'%s' is not in '%s'" % (d, origOutPath))
                            sys.exit(-1)
                    elif not os.path.exists(os.path.join(origOutPath, d)):
                        _printErr("'%s' is not in '%s'" % (d, origOutPath))
                        sys.exit(-1)
                    else:
                        d = os.path.join(origOutPath, d)

                    if mainCmd == "remove":
                        _remove(d)
                    elif mainCmd == "download":
                        _download(d)

            elif mainCmd in ("dir", "dirlist"):
                if cmdOpt:
                    cmdOpt = [cmdOpt[0]]
                else:
                    if not origOutPath:
                        _printErr("no target directory")
                        sys.exit(-1)
                    if not os.path.exists(origOutPath):
                        cmdOpt = [os.path.dirname(origOutPath)]
                    elif os.path.isdir(origOutPath):
                        cmdOpt = [origOutPath]
                    else:
                        cmdOpt = [os.path.dirname(origOutPath)]

                SysMgr.jsonEnable = mainCmd == "dirlist"

                _setOutput(connObj)

                SysMgr.showAll = True

                cmdOpt = UtilMgr.cleanItem(cmdOpt)
                if not cmdOpt:
                    _printErr("failed to get directory info")
                    sys.exit(-1)

                # get depth — prefer TCP 3rd arg (cmdList[2]) over SysMgr.depthLevel #
                maxLevel = -1
                if len(cmdList) >= 3:
                    try:
                        _tcpDepth = int(cmdList[2])
                        if _tcpDepth > 0:
                            maxLevel = _tcpDepth
                    except (ValueError, TypeError):
                        pass
                elif SysMgr.depthLevel:
                    maxLevel = SysMgr.depthLevel

                for d in cmdOpt:
                    SysMgr.printDirs(d, maxLevel)

            elif mainCmd in (
                "getpkg",
                "getpkginfo",
                "getpkglist",
                "getpkglistinfo",
            ):
                SysMgr.jsonEnable = mainCmd in ("getpkglist", "getpkglistinfo")

                _setOutput(connObj)

                SysMgr.showAll = True

                if "info" in mainCmd:
                    SysMgr.addEnvironVar("GETPKGLISTINFO")
                else:
                    SysMgr.addEnvironVar("GETPKGLIST")
                AndroidMgr.doPerfetto()

            elif mainCmd in ("sysinfo", "syslist"):
                SysMgr.jsonEnable = mainCmd == "syslist"

                _setOutput(connObj)

                SysMgr.doPrintInfo()

            elif mainCmd in ("ps", "pslist"):
                SysMgr.jsonEnable = mainCmd == "pslist"

                _setOutput(connObj)

                SysMgr.doPs()

            elif mainCmd == "printboot":
                # set output (jsonEnable/SORT are already applied from
                # the '-J'/'-q SORT:<key>' options via parseAnalOption) #
                _setOutput(connObj)

                AndroidMgr.doPrintBoot()

            elif mainCmd in ("memtop", "memmon"):
                if not cmdOpt:
                    _printErr("no target info")
                    sys.exit(-1)

                SysMgr.jsonEnable = mainCmd == "memmon"

                _setOutput(connObj)

                SysMgr.addEnvironVar("MEMTOP")
                AndroidMgr.doPerfetto()

            elif mainCmd in ("logcat", "logmon"):
                SysMgr.jsonEnable = mainCmd == "logmon"

                _setOutput(connObj)

                LogMgr.printAndLog(True)

            elif mainCmd == "jobs":
                SysMgr.jsonEnable = True

                _retJson(connObj, SysMgr.getEventTaskList())

            elif mainCmd in ("kill", "tkill", "bgkill"):
                if not "ALLOWRUN" in SysMgr.environList:
                    _printErr("remote %s is not allowed" % mainCmd)
                    sys.exit(-1)

                SysMgr.jsonEnable = True

                isThread = mainCmd == "tkill"

                targets = []
                sig = signal.SIGKILL

                for x in cmdOpt:
                    if x.upper().startswith("SIG"):
                        try:
                            x = SysMgr.getSigNum(x)
                            if x:
                                sig = x
                                continue
                        except SystemExit:
                            sys.exit(0)
                        except:
                            _printErr(
                                "failed to get signal from '%s'" % x, True
                            )
                    elif x.startswith("-"):
                        continue

                    targets.append(x)

                try:
                    if mainCmd == "bgkill":
                        argList = []
                        for (
                            event,
                            taskList,
                        ) in SysMgr.getEventTaskList().items():
                            if UtilMgr.isValidStr(event, targets):
                                argList += list(taskList)
                            else:
                                for tid in list(map(str, taskList)):
                                    if UtilMgr.isValidStr(tid, targets):
                                        argList.append(tid)
                    else:
                        argList = UtilMgr.cleanItem(
                            ("".join(targets)).split(",")
                        )
                except SystemExit:
                    sys.exit(0)
                except:
                    _printErr("failed to convert target list", True)

                targets = SysMgr.convTaskList(argList, isThread=isThread)
                if targets:
                    targetList = targets
                else:
                    targetList = argList

                ret = SysMgr.sendSignalProcs(
                    sig, targetList, isThread=isThread
                )

                _retJson(connObj, ret)

            elif mainCmd in ("control", "event"):
                if not cmdOpt:
                    _printErr("no %s value" % mainCmd)
                    sys.exit(-1)

                cliObj = NetworkMgr(
                    "client", localServObj.ip, localServObj.port, tcp=False
                )

                for ccmd in cmdOpt:
                    ccmd = ccmd.upper()
                    if ccmd.startswith("EVENT_CMD_"):
                        pass
                    elif ccmd.startswith("CMD_"):
                        ccmd = "EVENT_" + ccmd
                    else:
                        ccmd = "EVENT_CMD_" + ccmd

                    if mainCmd == "event":
                        ccmd = ccmd.replace("_CMD", "")

                    cliObj.send(ccmd)

                    _printInfo(
                        "sent '%s' command to server(%s:%s)"
                        % (ccmd, cliObj.ip, cliObj.port)
                    )

            elif (
                mainCmd
                in (
                    "cpuprof",
                    "memprof",
                    "scrrec",
                    "scrcap",
                    "bugrec",
                    "bugrep",
                )
                or isDrawMode
            ):
                selectObj = SysMgr.getPkg("select")

                SysMgr.addEnvironVar("MERGEENVLIST")

                SysMgr.addEnvironVar("TERMCHILD")

                SysMgr.addEnvironVar("FIXOUTFILE")

                if isDrawMode:
                    gcmd = mainCmd
                elif mainCmd == "cpuprof":
                    gcmd = "sperf"
                elif mainCmd == "memprof":
                    gcmd = "hprof"
                elif mainCmd in ("scrrec", "scrcap", "bugrec", "bugrep"):
                    gcmd = mainCmd
                else:
                    _printErr(
                        "failed to recognize '%s' command from %s"
                        % (mainCmd, cliProc)
                    )
                    sys.exit(-1)

                cmdSet = [gcmd] + cmdOpt + ["-J"]
                if gcmd == "hprof":
                    q_idx = next(
                        (
                            i
                            for i, x in enumerate(cmdSet)
                            if x.startswith("-q")
                        ),
                        None,
                    )
                    if q_idx is not None:
                        cmdSet[q_idx] = cmdSet[q_idx] + ",SERVERTASK"
                    else:
                        cmdSet.append("-qSERVERTASK")

                SysMgr.cleanupDirs()

                SysMgr.outPath = origOutPath
                SysMgr.setReportPath(origOutPath, mainCmd)
                baseReportPath = SysMgr.outPath

                try:
                    ret = SysMgr.launchGuider(
                        cmdSet,
                        pipe=True,
                        stderr=True,
                        stream=True,
                        logo=False,
                        log=False,
                        keepOut=True,
                    )
                    if not ret:
                        sys.exit(-1)
                except SystemExit:
                    sys.exit(0)
                except:
                    _printErr(
                        "failed to launch %s(%s)"
                        % (__module__, " ".join(cmdSet)),
                        reason=True,
                    )
                    sys.exit(-1)

                pid, pipe = ret

                # drawflame/drawflamediff write their JSON summary to a report
                # file instead of stdout (see printPipe's file-output branch),
                # so an empty stdout pipe from the child doesn't mean it
                # failed - the relay loop below falls back to reading that
                # file. It writes its own SVG at baseReportPath itself (see
                # Debugger.drawFlame() -> UtilMgr.getDrawOutputPath, which
                # reuses SysMgr.outPath), but the JSON *summary* naming this
                # SVG's path lands at a sibling file with the child's pid
                # spliced in before the extension (confirmed on-device) -
                # e.g. "..._drawflame_<ts>.out" (the SVG) alongside
                # "..._drawflame_<ts>_<pid>.out" (the JSON) - so it's this
                # pid-suffixed sibling we need to read, not baseReportPath.
                if isDrawMode:
                    _base, _ext = os.path.splitext(baseReportPath)
                    expectedReportPath = "%s_%s%s" % (_base, pid, _ext)
                else:
                    expectedReportPath = None

                pipeObj = os.fdopen(os.dup(pipe.fileno()), "r")
                SysMgr.setBlock(pipe.fileno(), False)

                try:
                    connObj.timeout(None)
                    connSock = connObj.socket
                except SystemExit:
                    sys.exit(0)
                except:
                    connSock = None

                def _sigHandler(signum=None, frame=None):
                    os.kill(pid, signum)
                    SysMgr.waitChild()
                    sys.exit(0)

                for sig in (
                    signal.SIGINT,
                    signal.SIGQUIT,
                    signal.SIGTERM,
                    signal.SIGCONT,
                    signal.SIGUSR1,
                    signal.SIGUSR2,
                ):
                    SysMgr.setSignal(sig, _sigHandler)

                try:
                    inputList = [pipeObj]
                    if connSock:
                        inputList.append(connSock)

                    while 1:
                        [rdList, _, _] = selectObj.select(inputList, [], [], 1)

                        for rd in rdList:
                            if rd == pipeObj:
                                res = pipeObj.read()
                                if res:
                                    connObj.write(res.encode())
                                    # For recording/streaming commands keep the connection
                                    # open so the client can send STOP later.
                                    # Close only when the child exits (EOF below).
                                    if mainCmd not in (
                                        "scrrec",
                                        "bugrec",
                                        "bugrep",
                                    ):
                                        connObj.close()
                                        raise ValueError()
                                elif mainCmd in (
                                    "scrcap",
                                    "bugrep",
                                    "scrrec",
                                    "bugrec",
                                ):
                                    connObj.close()
                                    raise ValueError()
                                else:
                                    # EOF with no data: grandchild exited without
                                    # output on stdout. For isDrawMode commands
                                    # (drawflame/drawflamediff) this doesn't mean
                                    # failure - their JSON summary went to the
                                    # report file instead of stdout, so relay
                                    # that file's content if it was produced.
                                    if expectedReportPath:
                                        # the stdout pipe closing (what got us
                                        # here) doesn't guarantee the child has
                                        # finished flushing/closing its other
                                        # fds (the report file) yet - wait for
                                        # it to fully exit first. A SIGCHLD
                                        # handler elsewhere may reap it first,
                                        # which is fine (it also proves the
                                        # child is gone) - either way is enough.
                                        try:
                                            os.waitpid(pid, 0)
                                        except SystemExit:
                                            raise
                                        except:
                                            pass
                                        if os.path.exists(expectedReportPath):
                                            try:
                                                with open(
                                                    expectedReportPath, "rb"
                                                ) as _reportFd:
                                                    connObj.write(
                                                        _reportFd.read()
                                                    )
                                            except SystemExit:
                                                raise
                                            except:
                                                pass
                                    connObj.close()
                                    raise ValueError()
                            elif rd == connSock:
                                if not NetworkMgr.check(connSock):
                                    time.sleep(0.1)
                                    continue

                                sig = connObj.recv()
                                try:
                                    os.kill(pid, signal.SIGINT)
                                except:
                                    _printErr(
                                        "failed to send SIGINT to %s"
                                        % SysMgr.getTaskStr(pid),
                                        True,
                                    )
                except ValueError:
                    pass
                except SystemExit:
                    sys.exit(0)
                except:
                    _printErr("failed to watch events from channels", True)
                    sys.exit(-1)

            elif mainCmd in ("funcall", "funcschema"):
                import time as _time

                json = SysMgr.getPkg("json")

                def _getSchema():
                    return {
                        "functions": [
                            {
                                "name": "get_system_stats",
                                "description": "Get current system-wide CPU/memory/network snapshot",
                                "parameters": {
                                    "type": "object",
                                    "properties": {},
                                    "required": [],
                                },
                            },
                            {
                                "name": "get_top_processes",
                                "description": "Return top N processes sorted by metric",
                                "parameters": {
                                    "type": "object",
                                    "properties": {
                                        "n": {
                                            "type": "integer",
                                            "description": "Number of processes (default 10)",
                                        },
                                        "sort": {
                                            "type": "string",
                                            "enum": [
                                                "cpu",
                                                "mem",
                                                "io",
                                                "pid",
                                            ],
                                            "default": "cpu",
                                        },
                                    },
                                },
                            },
                            {
                                "name": "get_process_info",
                                "description": "Return detailed stats for a single process by PID",
                                "parameters": {
                                    "type": "object",
                                    "properties": {
                                        "pid": {
                                            "type": "integer",
                                            "description": "Process ID",
                                        }
                                    },
                                    "required": ["pid"],
                                },
                            },
                            {
                                "name": "get_cgroup_stats",
                                "description": "Return cgroup I/O statistics",
                                "parameters": {
                                    "type": "object",
                                    "properties": {},
                                    "required": [],
                                },
                            },
                            {
                                "name": "get_memory_stats",
                                "description": "Return system memory and VM statistics",
                                "parameters": {
                                    "type": "object",
                                    "properties": {},
                                    "required": [],
                                },
                            },
                            {
                                "name": "find_anomalies",
                                "description": "Find processes exceeding CPU or memory thresholds",
                                "parameters": {
                                    "type": "object",
                                    "properties": {
                                        "cpu_thr": {
                                            "type": "number",
                                            "description": "CPU usage threshold in percent (default 80)",
                                        },
                                        "mem_thr": {
                                            "type": "number",
                                            "description": "Memory usage threshold in MB (default 80)",
                                        },
                                    },
                                },
                            },
                            {
                                "name": "kill_process",
                                "description": "Send a signal to a process (requires ALLOWRUN)",
                                "parameters": {
                                    "type": "object",
                                    "properties": {
                                        "pid": {
                                            "type": "integer",
                                            "description": "Process ID",
                                        },
                                        "sig": {
                                            "type": "integer",
                                            "description": "Signal number (default 15 = SIGTERM)",
                                        },
                                    },
                                    "required": ["pid"],
                                },
                            },
                        ]
                    }

                def _sysStats():
                    return SysMgr.sysSnapshot()

                def _topProcs(n, sort):
                    return SysMgr.topProcs(n, sort)

                def _procInfo(pid):
                    inst = SysMgr.topInstance
                    uptimeDiff = SysMgr.uptimeDiff or 0.01
                    val = inst.procData.get(pid)
                    if val is None:
                        return {"error": "pid %d not found" % pid}
                    try:
                        cpu_pct = round(
                            val.get("ttimeDiff", 0) * 100.0 / uptimeDiff, 1
                        )
                        return {
                            "pid": pid,
                            "comm": val.get("comm", ""),
                            "cpu_pct": cpu_pct,
                            "rss_mb": val.get("rss", 0) >> 20,
                            "io_read_mb": val.get("ioReadDiff", 0) >> 20,
                            "io_write_mb": val.get("ioWriteDiff", 0) >> 20,
                            "ppid": val.get("ppid", 0),
                            "nr_threads": val.get("nrthread", 0),
                        }
                    except SystemExit:
                        sys.exit(0)
                    except Exception as e:
                        return {"error": str(e)}

                def _cgroupStats():
                    inst = SysMgr.topInstance
                    result = {}
                    try:
                        for system, groups in inst.cgroupData.items():
                            result[system] = {}
                            for group, stats in groups.items():
                                result[system][group] = {}
                                for name, val in stats.items():
                                    if isinstance(val, list) and len(val) == 2:
                                        result[system][group][name] = {
                                            "read": val[0],
                                            "write": val[1],
                                        }
                                    else:
                                        result[system][group][name] = val
                    except SystemExit:
                        sys.exit(0)
                    except:
                        pass
                    return result

                def _memStats():
                    inst = SysMgr.topInstance
                    result = {}
                    try:
                        mem = SysMgr.getMemDict()
                        for k, v in mem.items():
                            result[k] = v
                    except SystemExit:
                        sys.exit(0)
                    except:
                        pass
                    try:
                        for k, v in inst.vmData.items():
                            result["vm_" + str(k)] = v
                    except SystemExit:
                        sys.exit(0)
                    except:
                        pass
                    return result

                def _findAnomalies(cpu_thr, mem_thr):
                    inst = SysMgr.topInstance
                    uptimeDiff = SysMgr.uptimeDiff or 0.01
                    result = []
                    try:
                        for pid, val in inst.procData.items():
                            cpu_pct = (
                                val.get("ttimeDiff", 0) * 100.0 / uptimeDiff
                            )
                            rss_mb = val.get("rss", 0) >> 20
                            if cpu_pct >= cpu_thr or rss_mb >= mem_thr:
                                result.append(
                                    {
                                        "pid": pid,
                                        "comm": val.get("comm", ""),
                                        "cpu_pct": round(cpu_pct, 1),
                                        "rss_mb": rss_mb,
                                    }
                                )
                    except SystemExit:
                        sys.exit(0)
                    except:
                        pass
                    return result

                def _killProc(pid, sig):
                    if "ALLOWRUN" not in SysMgr.environList:
                        raise RuntimeError(
                            "kill_process requires ALLOWRUN option"
                        )
                    os.kill(pid, sig)
                    return {"killed": pid, "sig": sig}

                _FUNCS = {
                    "get_system_stats": lambda a: _sysStats(),
                    "get_top_processes": lambda a: _topProcs(
                        int(a.get("n", 10)), str(a.get("sort", "cpu"))
                    ),
                    "get_process_info": lambda a: _procInfo(
                        int(a.get("pid", 0))
                    ),
                    "get_cgroup_stats": lambda a: _cgroupStats(),
                    "get_memory_stats": lambda a: _memStats(),
                    "find_anomalies": lambda a: _findAnomalies(
                        float(a.get("cpu_thr", 80.0)),
                        float(a.get("mem_thr", 80.0)),
                    ),
                    "kill_process": lambda a: _killProc(
                        int(a.get("pid", 0)), int(a.get("sig", 15))
                    ),
                }

                if mainCmd == "funcschema":
                    _retJson(connObj, _getSchema(), pretty=True)
                else:
                    try:
                        req = json.loads(cmdOpt[0] if cmdOpt else "{}")
                        name = req.get("name", "")
                        args = req.get("arguments", {})
                        if name not in _FUNCS:
                            _retJson(
                                connObj,
                                {"error": "unknown function: %s" % name},
                            )
                        elif not SysMgr.topInstance:
                            _retJson(
                                connObj,
                                {"error": "guider not in top/ctop mode"},
                            )
                        else:
                            t0 = _time.time()
                            res = _FUNCS[name](args)
                            _retJson(
                                connObj,
                                {
                                    "result": res,
                                    "elapsed_ms": int(
                                        (_time.time() - t0) * 1000
                                    ),
                                },
                                pretty=True,
                            )
                    except SystemExit:
                        sys.exit(0)
                    except Exception as e:
                        _retJson(connObj, {"error": str(e)})

            sys.exit(0)

        SysMgr.blockSignal(SysMgr.commSig, "block")

        while 1:
            if not SysMgr.requestQueue:
                break

            try:
                req = SysMgr.requestQueue.pop(0)
                connObj, cmd, cliProc = req
            except SystemExit:
                sys.exit(0)
            except:
                SysMgr.printErr("failed to pop a request command", True)
                continue

            try:
                connObj.send(b"ACK")

                _handleCmd(connObj, cmd, cliProc)
            except SystemExit:
                sys.exit(0)
            except:
                _printErr(
                    "failed to handle '%s' command from %s" % (cmd, cliProc),
                    True,
                )
                sys.exit(-1)

        SysMgr.blockSignal(SysMgr.commSig, "unblock")

    @staticmethod
    def exceptHandler(signum, frame):
        raise Exception("signal")

    @staticmethod
    def defaultHandler(signum, frame):
        return

    @staticmethod
    def chldHandler(signum, frame):
        try:
            os.waitpid(-1, os.WNOHANG)
        except:
            pass

    @staticmethod
    def fgHandler(signum, frame):
        SysMgr.bgStatus = False

        SysMgr.setSignal(signal.SIGTSTP, SysMgr.bgHandler)
        SysMgr.setSignal(signal.SIGTTIN, SysMgr.bgHandler)

    @staticmethod
    def bgHandler(signum, frame):
        SysMgr.bgStatus = True

        if signum == signal.SIGTSTP:
            os.kill(SysMgr.pid, signal.SIGSTOP)
        elif signum == signal.SIGTTIN:
            pass

        SysMgr.setSignal(signal.SIGTSTP, signal.SIG_IGN)
        SysMgr.setSignal(signal.SIGTTIN, signal.SIG_IGN)

    @staticmethod
    def winchHandler(signum, frame):
        SysMgr.getTty(update=True)

    @staticmethod
    def printDelayTime(pid=None, force=False):
        if not SysMgr.warnEnable and not force:
            return

        if not pid:
            pid = os.getpid()

        try:
            schedData = SysMgr.readFile(
                "%s/%s/schedstat" % (SysMgr.procPath, pid)
            )
            if not schedData:
                return

            execTime, waitTime, nrSlice = list(
                map(long, schedData.split()[:3])
            )
            execPer = (execTime / (execTime + waitTime)) * 100
            if execPer == 0:
                execPer = 100

            statData = SysMgr.readFile("%s/%s/stat" % (SysMgr.procPath, pid))
            statList = statData.split(") ", 1)[1].split()
            utimeIdx = ConfigMgr.PROCSTAT_ATTR_DICT["UTIME"]
            stimeIdx = ConfigMgr.PROCSTAT_ATTR_DICT["STIME"]
            utime = long(statList[utimeIdx - 2])
            stime = long(statList[stimeIdx - 2])
            ttime = utime + stime

            totalTime = ttime * (100 / execPer)
            dtime = long(totalTime - ttime)
            if not dtime:
                return

            dtime = UtilMgr.convNum(dtime / 100.0, True, 2)
            SysMgr.printWarn(
                "%s is delayed for %s sec totally"
                % (SysMgr.getTaskStr(pid), dtime),
                True,
            )
        except SystemExit:
            sys.exit(0)
        except:
            SysMgr.printWarn(
                "failed to get delay time for %s" % SysMgr.getTaskStr(pid),
                reason=True,
            )

    @staticmethod
    def stopHandler(signum=None, frame=None):
        if SysMgr.exitFlag:
            os._exit(0)

        if signum:
            SysMgr.setSignal(signum, signal.SIG_IGN)

        SysMgr.printDelayTime()

        if "KEEPTASK" in SysMgr.environList:
            SysMgr.clearChildList()

        SysMgr.runProfCmd("STOP")

        if SysMgr.jsonEnable:
            sys.exit(0)
        elif SysMgr.checkMode("filerec") and not SysMgr.intervalEnable:
            sys.exit(0)
        elif SysMgr.isFileMode() or SysMgr.isSystemMode():
            SysMgr.condExit = True
        elif SysMgr.isTopMode() or SysMgr.isTraceMode():
            if Debugger.dbgInstance:
                pass
            elif SysMgr.outPath and "NOSUMMARY" not in SysMgr.environList:
                SysMgr.inExit = True

                signal.alarm(0)
                SysMgr.setSignal(signal.SIGALRM, signal.SIG_IGN)

                SysMgr.printStat(r"start reporting... [ STOP(Ctrl+\) ]")

                if any(
                    [
                        item in SysMgr.environList
                        for item in (
                            "ANDROIDEVENT",
                            "DLTEVENT",
                            "JOURNALEVENT",
                            "KERNELEVENT",
                            "SYSLOGEVENT",
                            "TRACEEVENT",
                        )
                    ]
                ):
                    if signum:
                        SysMgr.setSignal(signum, SysMgr.exitHandler)

                    msgall = "MSGALL" in SysMgr.environList

                    current = SysMgr.getUptime()

                    logInfo = {
                        "DLTEVENT": {
                            "time": "mtime",
                            "diff": UtilMgr.getClockTime(dlt=True) - current,
                            "field": (
                                [
                                    "mtime",
                                    "ecuId",
                                    "apId",
                                    "ctxId",
                                    "message",
                                ]
                                if msgall
                                else []
                            ),
                        },
                        # kmsg / ftrace timestamps already share guider's
                        # own uptime clock, so no offset is needed #
                        "KERNELEVENT": {
                            "time": "uptime",
                            "diff": 0,
                            "field": [],
                        },
                        "TRACEEVENT": {
                            "time": "time",
                            "diff": 0,
                            "field": [],
                        },
                        # ANDROIDEVENT/JOURNALEVENT/SYSLOGEVENT carry
                        # wall-clock timestamps and need date parsing
                        # before they fit guider's uptime timeline;
                        # not implemented yet (see _convertToGraphSeconds
                        # for their DATETIME-mode equivalent) #
                    }

                    SysMgr.printStat(
                        "start gathering log events... [ STOP(Ctrl+c) ]"
                    )

                    warnedLogTypes = set()
                    for log in SysMgr.getLogEvents(
                        since=SysMgr.startTime, until=SysMgr.getUptime()
                    ):
                        try:
                            info = logInfo[log["type"]]
                            ltime = float(log[info["time"]])
                            uptime = ltime - info["diff"]

                            name = log["name"]
                            for f in info["field"]:
                                if f in log:
                                    name += ">%s" % log[f]

                            TaskAnalyzer.procEventData.append(
                                [uptime, name, uptime]
                            )
                        except SystemExit:
                            break
                        except:
                            logType = log.get("type", "UNKNOWN")
                            if logType in warnedLogTypes:
                                continue
                            warnedLogTypes.add(logType)
                            SysMgr.printWarn(
                                "failed to recognize a below log\n%s"
                                % UtilMgr.convDict2Str(log, pretty=True),
                                True,
                                True,
                            )

                    if signum:
                        SysMgr.setSignal(signum, signal.SIG_IGN)

                if SysMgr.pipeEnable:
                    SysMgr.reloadFileBuffer()

                current = True

                for n, v in SysMgr.hostList.items():
                    buf = v["buffer"]
                    if not buf:
                        continue

                    pid = SysMgr.createProcess()
                    if pid > 0:
                        continue

                    current = False
                    SysMgr.procBuffer = buf
                    SysMgr.addEnvironVar("NOHEADER")
                    SysMgr.fileSuffix = "%s_%s_%s" % (
                        v["hostname"],
                        n,
                        SysMgr.pid,
                    )
                    break

                SysMgr.printLogo(absolute=True, big=True)

                SysMgr.saveSysStats(True)

                if "NOINTSUMMARY" in SysMgr.environList:
                    if "PRINTEVENTHIST" in SysMgr.environList:
                        TaskAnalyzer.printEventInterval()
                    if "PRINTFILEHIST" in SysMgr.environList:
                        TaskAnalyzer.printFileInterval()
                    if "PRINTLMKLOG" in SysMgr.environList:
                        TaskAnalyzer.printLmkLog()
                    SysMgr.printProcBuffer()
                else:
                    TaskAnalyzer.printIntervalUsage(current=current)

                for cmd in SysMgr.environList.get("PRINTCMD", []):
                    if "#" in cmd:
                        title, cmd = cmd.split("#", 1)
                    else:
                        title = cmd

                    title = " " + title + " "
                    stars = "*" * long(
                        (long(SysMgr.lineLength) - len(title)) / 2
                    )
                    SysMgr.printPipe(
                        "\n\n\n\n%s%s%s\n\n" % (stars, title, stars)
                    )
                    SysMgr.printPipe(SysMgr.executeCmdSync(cmd))

                if os.path.exists(SysMgr.inputFile):
                    fsize = UtilMgr.getFileSizeStr(SysMgr.inputFile)

                    SysMgr.printInfo(
                        "saved the results based monitoring into "
                        "'%s'%s successfully" % (SysMgr.inputFile, fsize)
                    )

            SysMgr.releaseResource(signal.SIGINT)

            SysMgr.inExit = False

            if signum:
                SysMgr.setSignal(signum, SysMgr.stopHandler)

            if not SysMgr.termFlag:
                SysMgr.progressCnt = 0
                return

            """
            # enable for cProfile #
            sys.settrace
            sys.exit(0)
            """

            # remove stopHandler in exit list to prevent recursive calls #
            SysMgr.removeExitFunc(SysMgr.stopHandler)

            SysMgr.doExit()

            os._exit(0)
        elif not SysMgr.isLinux:
            sys.exit(0)
        else:
            SysMgr.writeEvent("EVENT_STOP", False)

            if signum:
                SysMgr.setSignal(signal.SIGINT, signal.SIG_DFL)

            SysMgr.stopRecording()

        SysMgr.recordStatus = False
        SysMgr.repeatCnt = 0

        SysMgr.printStat("ready to save and analyze... [ STOP(Ctrl+c) ]")

        if signum:
            SysMgr.setSignal(signum, SysMgr.stopHandler)

        if "ISMAIN" not in os.environ:
            sys.exit(0)

        raise Exception("stop signal")

    @staticmethod
    def closePrintFd():
        try:
            SysMgr.printFd.close()
        except SystemExit:
            sys.exit(0)
        except:
            pass
        finally:
            SysMgr.printFd = None

    @staticmethod
    def newHandler(signum=None, frame=None):
        if SysMgr.inExit:
            SysMgr.releaseResource()
            os._exit(0)

        SysMgr.condExit = False

        if SysMgr.isFileMode():
            SysMgr.printStat("saved file usage successfully")
        elif SysMgr.isSystemMode():
            pass
        elif SysMgr.isTopMode():
            if SysMgr.wssEnable:
                SysMgr.initWssEnable = True
                SysMgr.printInfo("initialize WSS")

            if not SysMgr.outPath:
                return

            if signum:
                SysMgr.setSignal(signum, signal.SIG_IGN)

            if SysMgr.pipeEnable:
                SysMgr.reloadFileBuffer()

            pid = SysMgr.createProcess()
            if pid > 0:
                SysMgr.clearProcBuffer()

                SysMgr.closePrintFd()

                if signum:
                    SysMgr.setSignal(signum, SysMgr.newHandler)

                return True

            SysMgr.setLowPriority(True)

            SysMgr.printLogo(absolute=True, big=True)

            SysMgr.saveSysStats(True)

            TaskAnalyzer.printIntervalUsage()

            fsize = UtilMgr.getFileSizeStr(SysMgr.inputFile)

            SysMgr.printInfo(
                "saved the results based monitoring into "
                "'%s'%s successfully" % (SysMgr.inputFile, fsize)
            )

            sys.exit(0)
        elif SysMgr.resetEnable:
            SysMgr.writeEvent("EVENT_START")
        else:
            SysMgr.writeEvent("EVENT_MARK")

    @staticmethod
    def alarmStopHandler(signum, frame):
        SysMgr.printWarn("terminated by timer\n", True)
        SysMgr.stopHandler(signum, frame)

    @staticmethod
    def alarmExitHandler(signum, frame):
        SysMgr.printWarn("terminated by timer\n", True)
        SysMgr.exitHandler(signum, frame)

    @staticmethod
    def quitHandler(signum, frame):
        sys.exit(0)

    @staticmethod
    def termHandler(signum, frame):
        SysMgr.doExit()

        os._exit(0)

    @staticmethod
    def printHandler(signum, frame):
        print(
            "%s is delivered at %.1f"
            % (ConfigMgr.SIG_LIST[signum], SysMgr.getUptime())
        )

    @staticmethod
    def exitHandler(signum, frame):
        if SysMgr.exitFlag or SysMgr.checkMode("report"):
            os._exit(0)

        SysMgr.setIgnoreSignal()
        signal.alarm(0)
        SysMgr.condExit = True

        SysMgr.printWarn("terminated by user\n")

        sys.exit(0)

    @staticmethod
    def faultHandler(signum, frame):
        """
        SysMgr.releaseResource()
        sys.stdout.write('terminated by SEGFAULT signal\n')
        """
        os._exit(0)

    @staticmethod
    def timerHandler(signum, frame):
        raise Exception("timer expired")

    @staticmethod
    def alarmHandler(signum, frame):
        if SysMgr.repeatCnt <= SysMgr.progressCnt and SysMgr.termFlag:
            UtilMgr.deleteProgress()
            # block further alarms before reporting #
            try:
                signal.alarm(0)
                signal.pthread_sigmask(signal.SIG_BLOCK, {signal.SIGALRM})
            except Exception:
                pass
            SysMgr.printWarn("terminated by timer\n", True)
            sys.exit(0)

        if not SysMgr.isRecordMode() and SysMgr.repeatCnt > 0:
            UtilMgr.printProgress(SysMgr.progressCnt, SysMgr.repeatCnt)

        SysMgr.progressCnt += 1
        progressCnt = SysMgr.progressCnt
        repeatInterval = SysMgr.repeatInterval
        repeatCnt = SysMgr.repeatCnt

        SysMgr.setSignal(signal.SIGALRM, SysMgr.defaultHandler)

        if SysMgr.pipeEnable:
            if repeatCnt == progressCnt:
                SysMgr.stopRecording()
            signal.alarm(repeatInterval)
        elif SysMgr.outputFile:
            if repeatCnt == 1 and SysMgr.termFlag:
                output = SysMgr.outputFile
            else:
                output = "%s_%s" % (SysMgr.outputFile, SysMgr.getRuntime())

            SysMgr.stopRecording()

            SysMgr.saveSysStats()

            try:
                rpath = "%s/trace" % SysMgr.getTracefsPath()
                if sys.version_info >= (3, 0, 0):
                    with open(rpath, "r", encoding="latin-1") as fr:
                        lines = fr.readlines()
                else:
                    with open(rpath, "r") as fr:
                        lines = fr.readlines()
            except SystemExit:
                sys.exit(0)
            except:
                SysMgr.printOpenErr(rpath)
                sys.exit(-1)

            try:
                SysMgr.saveTraceData(lines, output)
                SysMgr.clearInfoBuffer()
            except:
                sys.exit(-1)
        else:
            SysMgr.printWarn(
                "failed to save data because the path is not set", True
            )

        SysMgr.setSignal(signal.SIGALRM, SysMgr.alarmHandler)

    @staticmethod
    def isTermSignal(sig):
        return sig in (signal.SIGKILL, signal.SIGSEGV, signal.SIGABRT)

    @staticmethod
    def getCompressFlag():
        disabledOptions = SysMgr.getOption("d")
        if disabledOptions and "C" in disabledOptions:
            ret = False
        else:
            ret = True
        return ret

    @staticmethod
    def saveTraceData(lines, outputFile=None):
        if not outputFile:
            outputFile = SysMgr.outputFile
        outputFile = os.path.realpath(outputFile)

        SysMgr.backupFile(outputFile)

        if SysMgr.isRecordMode() and SysMgr.getCompressFlag():
            compressor = SysMgr.getPkg("gzip", False)
        else:
            compressor = None

        size = 0
        for line in lines:
            size += len(line)

        try:
            traceData = "\n".join(lines)
            magicPos = traceData.rfind(SysMgr.magicStr)
            if magicPos > 0:
                traceData = traceData[magicPos:]

            encodedInfoData = SysMgr.sysinfoBuffer.encode("latin-1")
            encodedTraceData = traceData.encode("latin-1")
            del traceData
            totalSize = len(encodedInfoData) + len(encodedTraceData)

            SysMgr.printInfo(
                "wait for writing data to '%s' [%s]"
                % (outputFile, UtilMgr.convSize2Unit(totalSize))
            )

            f = open(outputFile, "wb")
            os.chmod(outputFile, 0o666)
            if compressor:
                f = compressor.GzipFile(mode="wb", fileobj=f)

            if SysMgr.sysinfoBuffer:
                magicStr = "%s\n" % SysMgr.magicStr
                magicStr = magicStr.encode("latin-1")

                f.write(magicStr)

                f.write(encodedInfoData)

                f.write(magicStr)

            f.write(encodedTraceData)
            f.close()

            fsize = UtilMgr.getFileSizeStr(outputFile)

            SysMgr.printInfo(
                "finished saving trace data into '%s'%s successfully"
                % (outputFile, fsize)
            )
        except SystemExit:
            sys.exit(0)
        except:
            SysMgr.printErr(
                "failed to write trace data to '%s'" % outputFile, True
            )

    @staticmethod
    def runFileCmd(cmdList, path):
        for cmd in cmdList:
            if cmd.upper() == "EXIT":
                sys.exit(0)
            elif cmd.endswith("&"):
                cmd = cmd[:-1]
                wait = False
            else:
                wait = True

            if path:
                cmd = cmd.replace("PATH", path)

            SysMgr.createCmdProcess(cmd)
            if wait:
                os.wait()

    @staticmethod
    def runProfCmd(time, convList={}):
        if not SysMgr.isLinux:
            return
        elif not SysMgr.rcmdList:
            return

        for cmd in SysMgr.rcmdList[time.upper()]:
            if len(cmd) == 1:
                if cmd[0].endswith("&"):
                    command = cmd[0].rstrip("& ")
                    wait = False
                else:
                    command = cmd[0]
                    wait = True

                for name, value in convList.items():
                    command = command.replace(name, value)

                SysMgr.execBgCmd(command, mute=False, wait=wait)
                continue
            elif len(cmd) != 2:
                continue

            try:
                path, val = cmd

                with open(path, "w") as fd:
                    fd.write(val)
                    SysMgr.printInfo(
                        "applied command '%s' to %s successfully" % (val, path)
                    )
            except:
                SysMgr.printWarn(
                    "failed to apply command '%s' to %s" % (val, path)
                )

    @staticmethod
    def readFile(
        path,
        size=-1,
        tail=False,
        verb=True,
        byte=False,
        offset=0,
        block=True,
        strip=True,
        comp=False,
        fd=None,
    ):
        try:
            perm = "rb" if byte else "r"

            def _readFile(fd):
                if not block:
                    SysMgr.setBlock(fd, False)

                if tail:
                    pos = os.path.getsize(path) - size
                    if pos < 0:
                        pos = 0
                    fd.seek(pos)
                    return fd.read().strip()[-size:]
                else:
                    fd.seek(offset)
                    res = fd.read(size)
                    return res.strip() if strip else res

            if isinstance(path, MemoryFile):
                fd = path
                path = fd.name

            if fd:
                return _readFile(fd)

            fd = SysMgr.getCompFd(path, perm=perm, verb=verb) if comp else None
            if fd:
                pass
            elif sys.version_info >= (3, 0, 0):
                fd = open(path, perm, encoding=None if byte else "UTF-8")
            else:
                fd = open(path, perm)

            return _readFile(fd)
        except SystemExit:
            sys.exit(0)
        except:
            if verb:
                SysMgr.printErr("failed to read '%s'" % path, True)
            return None

    @staticmethod
    def writeFile(
        path,
        val,
        errval=True,
        byte=False,
        verb=True,
        reverse=True,
        append=False,
        truncate=False,
    ):
        try:
            perm = "a" if append else "w"
            perm = perm + "b" if byte else perm

            dirpath = os.path.dirname(path)
            if dirpath:
                SysMgr.mkdirs(dirpath)

            with open(path, perm) as fd:
                if truncate:
                    fd.truncate()

                if isinstance(val, list):
                    if not reverse:
                        fd.seek(0)
                        fd.write("\n".join(val))
                        return True
                    for item in val:
                        if not item:
                            continue
                        fd.seek(0)
                        fd.write(item)
                else:
                    fd.write(val)

            return True
        except SystemExit:
            sys.exit(0)
        except:
            if not verb:
                return False

            SysMgr.printErr(
                "failed to write '%s' to '%s'"
                % (
                    "%s" % val[: SysMgr.maxErrStrLen] if errval else "",
                    path,
                ),
                True,
            )
            return False

    @staticmethod
    def readTraceFile(path):
        if not SysMgr.getTraceEventPath():
            SysMgr.printWarn("failed to get tracefs/debugfs mount point", True)

        try:
            target = "%s/%s" % (SysMgr.traceEventPath, path)
            with open(target, "r") as fd:
                return fd.read()[:-1]
        except:
            SysMgr.printErr("failed to read data from %s\n" % target)
            return None

    @staticmethod
    def procReadline(path):
        target = "%s/%s" % (SysMgr.procPath, path)
        with open(target, "r") as fd:
            return fd.readline()

    @staticmethod
    def procReadlines(path):
        target = "%s/%s" % (SysMgr.procPath, path)
        with open(target, "r") as fd:
            return fd.readlines()

    @staticmethod
    def getDirSize(path):
        dirInfo = SysMgr.printDirs(path=path, retVal=True)
        if not dirInfo:
            return 0

        try:
            item = next(iter(dirInfo))
            curSize = dirInfo[item].get("_size_")
            if curSize is None:
                return 0
            return UtilMgr.convUnit2Size(curSize)
        except SystemExit:
            sys.exit(0)
        except:
            SysMgr.printErr("failed to get current dir info", True)
            return None

    @staticmethod
    def getDirEntries(targetDir, recurse=False):
        """Return [(fpath, fname, size, mtime), ...] for regular files under
        targetDir, for the free*()/LIMIT* family below.

        Flat (default): targetDir's own files only, sorted by filename -
        matches guider's own zero-padded/timestamped report naming, so
        "oldest first" falls out of a plain name sort.

        Recursive (RECURSEDIR): walks the whole subtree and sorts by real
        mtime instead, since arbitrary nested files have no naming
        convention to rely on. os.walk() doesn't follow symlinked
        directories, so this can't loop on a symlink cycle.
        """
        entries = []

        if not recurse:
            try:
                names = sorted(
                    filter(
                        lambda x: os.path.isfile(os.path.join(targetDir, x)),
                        os.listdir(targetDir),
                    )
                )
            except SystemExit:
                sys.exit(0)
            except:
                return entries

            for fname in names:
                fpath = os.path.join(targetDir, fname)
                entries.append(
                    (fpath, fname, UtilMgr.getFileSize(fpath, False), 0)
                )
            return entries

        try:
            for root, _dirs, files in os.walk(targetDir):
                for fname in files:
                    fpath = os.path.join(root, fname)
                    try:
                        st = os.stat(fpath)
                    except SystemExit:
                        sys.exit(0)
                    except:
                        continue
                    entries.append((fpath, fname, st.st_size, st.st_mtime))
        except SystemExit:
            sys.exit(0)
        except:
            return entries

        entries.sort(key=lambda e: e[3])
        return entries

    @staticmethod
    def freeReportDir():
        if not SysMgr.limitRepDirSize or not SysMgr.outPath:
            return 0

        if SysMgr.outPath == SysMgr.nullPath:
            targetDir = SysMgr.tmpPath
        elif os.path.isdir(SysMgr.outPath):
            targetDir = SysMgr.outPath
        else:
            targetDir = os.path.dirname(SysMgr.outPath)

        convSize = UtilMgr.convSize2Unit

        removeOthers = "REMOVENOREP" in SysMgr.environList
        removeDirs = SysMgr.environList.get("REMOVEREPDIR")
        removeExDirs = SysMgr.environList.get("REMOVEEXREPDIR")

        if removeDirs or removeExDirs:
            dlist = filter(
                lambda x: os.path.isdir(os.path.join(targetDir, x)),
                os.listdir(targetDir),
            )
            for d in dlist:
                if removeDirs and not UtilMgr.isValidStr(d, removeDirs):
                    continue
                elif removeExDirs and UtilMgr.isValidStr(d, removeExDirs):
                    continue
                SysMgr.removeDirs(d, False)

        # RECURSEDIR opts into managing the whole subtree (size accounting
        # AND deletion both recurse) instead of just targetDir's own files -
        # off by default since outPath can be a shared/parent directory
        # (e.g. "-o /data") where unrelated nested content would otherwise
        # push curSize over the limit forever, deleting every one of this
        # function's own past reports without ever actually freeing enough
        # space #
        recurse = "RECURSEDIR" in SysMgr.environList
        entries = SysMgr.getDirEntries(targetDir, recurse)

        # count only files this function can actually remove (report-named
        # files, or every file when REMOVENOREP is set) toward the size
        # limit #
        curSize = sum(
            size
            for _fpath, fname, size, _mtime in entries
            if removeOthers or re.match(SysMgr.reportFormat, fname)
        )
        if not curSize:
            return 0

        try:
            diff = SysMgr.limitRepDirSize - curSize
            if diff >= 0:
                return 0

            needSize = abs(diff)
            rmSize = 0
        except SystemExit:
            sys.exit(0)
        except:
            SysMgr.printErr("failed to get free-up size of target dir", True)
            return 0

        removeRepList = {}
        keepRepList = SysMgr.keepRepDirFileList
        for f in keepRepList:
            for _fpath, fname, _size, _mtime in entries:
                if UtilMgr.isValidStr(fname, [f]):
                    removeRepList[f] = removeRepList.get(f, 0) + 1
            removeRepList[f] = removeRepList.get(f, 0) - keepRepList[f]

        for fpath, fname, size, _mtime in entries:
            m = re.match(SysMgr.reportFormat, fname)
            if not m and not removeOthers:
                continue

            keepFile = False
            for f in list(removeRepList):
                if UtilMgr.isValidStr(fname, [f]):
                    removeRepList[f] -= 1
                    if removeRepList[f] < 0:
                        keepFile = True
            if keepFile:
                continue

            msg = "'%s' [%s] to free up space of the report directory" % (
                fpath,
                convSize(size),
            )

            try:
                os.remove(fpath)

                rmSize += size
                curSize -= size

                msg += " [%s]" % (convSize(curSize))
                SysMgr.printWarn("removed %s" % msg, True)
            except SystemExit:
                sys.exit(0)
            except:
                msg += " [%s]" % (convSize(curSize))
                SysMgr.printErr("failed to remove %s" % msg, True)

            if rmSize >= needSize:
                break

        if rmSize:
            # curSize is already tracked precisely through the loop above #
            SysMgr.printInfo(
                (
                    "removed files with a total size of [%s] "
                    "to free up space of the report directory [%s]"
                )
                % (
                    convSize(rmSize),
                    convSize(curSize),
                )
            )

        return rmSize

    @staticmethod
    def freeDirsCnt(candidate=[]):
        convSize = UtilMgr.convSize2Unit

        if not isinstance(candidate, list):
            candidate = [candidate]

        # RECURSEDIR makes both the file-count budget and the eviction set
        # cover the whole subtree instead of just targetDir's own files -
        # off by default, matching freeReportDir()/freeDirs(). A target can
        # also opt in individually via LIMITDIRCNT:<path>:<n>:RECURSE
        # (SysMgr.recurseDirSet), so two targets in the same run can differ #
        globalRecurse = "RECURSEDIR" in SysMgr.environList

        for targetDir, limitCnt in SysMgr.limitDirCntList.items():
            recurse = globalRecurse or targetDir in SysMgr.recurseDirSet
            try:
                entries = SysMgr.getDirEntries(targetDir, recurse)
                if not entries:
                    continue
            except SystemExit:
                sys.exit(0)
            except:
                SysMgr.printWarn(
                    "failed to check file count of '%s'" % targetDir,
                    True,
                    True,
                )
                continue

            nrCandNew = 0
            for cand in candidate:
                # SysMgr.outPath (cleanupDirs()'s caller) can still be None
                # here - e.g. no "-o" given yet - and os.path.isdir(None)
                # raises TypeError, which used to abort this whole function
                # (and everything cleanupDirs() calls after it) with a
                # misleading "failed to get lock to free files" warning,
                # silently skipping LIMITDIRCNT enforcement entirely #
                if not cand:
                    continue
                if not os.path.isdir(cand):
                    cand = os.path.dirname(cand)
                if cand in SysMgr.limitDirCntList:
                    nrCandNew += 1

            try:
                diff = limitCnt - len(entries) - nrCandNew
                if diff >= 0:
                    continue
            except SystemExit:
                sys.exit(0)
            except:
                SysMgr.printErr(
                    "failed to get count limit for '%s'" % targetDir, True
                )
                continue

            # for the log message only - eviction below is decided by file
            # count, not by curSize #
            curSize = sum(size for _fpath, _fname, size, _mtime in entries)

            entries = entries[: abs(diff)]

            rmCnt = 0

            for fpath, _fname, size, _mtime in entries:
                msg = "'%s' [%s] to keep the file count (%s) for '%s'" % (
                    fpath,
                    convSize(size),
                    limitCnt,
                    targetDir,
                )

                try:
                    os.remove(fpath)

                    rmCnt += 1
                    curSize -= size

                    msg += " [%s]" % (convSize(curSize))
                    SysMgr.printWarn("removed %s" % msg, True)
                except SystemExit:
                    sys.exit(0)
                except:
                    msg += " [%s]" % (convSize(curSize))
                    SysMgr.printErr("failed to remove %s" % msg, True)

            if rmCnt:
                SysMgr.printInfo(
                    (
                        "removed a total of %s files "
                        "to keep the file count for '%s' [%s]"
                    )
                    % (
                        UtilMgr.convNum(rmCnt),
                        targetDir,
                        convSize(curSize),
                    )
                )

    @staticmethod
    def freeDirs():
        convSize = UtilMgr.convSize2Unit

        # RECURSEDIR opts into managing the whole subtree (size accounting
        # AND deletion both recurse) instead of just targetDir's own files -
        # off by default, since subdirectories are otherwise never touched
        # by the deletion loop below, so counting their size would make
        # this think it's over quota forever because of content it can
        # never free, and it would keep deleting unrelated top-level files
        # for no benefit (same class of bug as freeReportDir()). A target
        # can also opt in individually via LIMITDIR:<path>:<size>:RECURSE
        # (SysMgr.recurseDirSet), so two targets in the same run can differ #
        globalRecurse = "RECURSEDIR" in SysMgr.environList

        for targetDir, limitSize in SysMgr.limitDirList.items():
            recurse = globalRecurse or targetDir in SysMgr.recurseDirSet
            try:
                entries = SysMgr.getDirEntries(targetDir, recurse)
            except SystemExit:
                sys.exit(0)
            except:
                SysMgr.printWarn(
                    "failed to check size of '%s'" % targetDir, True, True
                )
                continue

            curSize = sum(size for _fpath, _fname, size, _mtime in entries)
            if not curSize:
                continue

            try:
                diff = limitSize - curSize
                if diff >= 0:
                    continue

                needSize = abs(diff)
                rmSize = 0
            except SystemExit:
                sys.exit(0)
            except:
                SysMgr.printErr(
                    "failed to get free-up size for '%s'" % targetDir, True
                )
                continue

            for fpath, _fname, size, _mtime in entries:
                msg = "'%s' [%s] to free up space for a directory '%s'" % (
                    fpath,
                    convSize(size),
                    targetDir,
                )

                try:
                    os.remove(fpath)

                    rmSize += size
                    curSize -= size

                    msg += "  [%s]" % convSize(curSize)
                    SysMgr.printWarn("removed %s" % msg, True)
                except SystemExit:
                    sys.exit(0)
                except:
                    msg += "  [%s]" % convSize(curSize)
                    SysMgr.printErr("failed to remove %s" % msg, True)

                if rmSize >= needSize:
                    break

            if rmSize:
                # curSize is already tracked precisely through the loop above #
                SysMgr.printInfo(
                    (
                        "removed files in a directory with a total size of [%s] "
                        "to free up space for '%s' [%s]"
                    )
                    % (
                        convSize(rmSize),
                        targetDir,
                        convSize(curSize),
                    )
                )

    @staticmethod
    def checkTracePoint(path):
        try:
            tp = "%s/%s" % (SysMgr.getTraceEventPath(), path)
            return os.path.isdir(tp)
        except SystemExit:
            sys.exit(0)
        except:
            SysMgr.printWarn(
                "failed to check tracepoint %s" % path, reason=True
            )

    @staticmethod
    def writeTraceCmd(path, val, append=False):
        if "SHOWCMD" in SysMgr.environList:
            SysMgr.printWarn("write '%s' to '%s'" % (path, val), True)

        if append:
            perm = "a+"
        else:
            perm = "w"

        if SysMgr.cmdEnable:
            if not SysMgr.cmdFd:
                try:
                    SysMgr.cmdFd = open(SysMgr.cmdEnable, perm)

                    # TODO: check debugfs and tracefs #
                    SysMgr.cmdFd.write(
                        "mount -t debugfs nodev %s 2>%s\n"
                        % (SysMgr.debugfsPath, SysMgr.nullPath)
                    )

                    SysMgr.cmdFd.write(
                        'echo "\n[Info] start recording... '
                        '[ STOP(Ctrl+c) ]\n"\n'
                    )
                except SystemExit:
                    sys.exit(0)
                except:
                    SysMgr.printOpenErr(SysMgr.cmdEnable)
                    return -1

            if SysMgr.cmdFd:
                try:
                    cmd = 'echo "%s" > %s/%s 2>%s\n' % (
                        str(val),
                        SysMgr.traceEventPath,
                        path,
                        SysMgr.nullPath,
                    )
                    SysMgr.cmdFd.write(cmd)
                    SysMgr.cmdFd.flush()
                except SystemExit:
                    sys.exit(0)
                except:
                    SysMgr.printErr("failed to write command", True)
                    return -1

        try:
            target = "%s/%s" % (SysMgr.getTraceEventPath(), path)
            if append:
                fd = os.open(target, os.O_RDWR | os.O_CREAT | os.O_APPEND)
            else:
                fd = open(target, perm)
        except SystemExit:
            sys.exit(0)
        except:
            fpos = path.rfind("/")
            try:
                if path[fpos + 1 :] == "enable":
                    epath = path[:fpos]
                else:
                    epath = path[fpos + 1 :]
            except:
                epath = path

            try:
                SysMgr.sysInstance.cmdList[epath] = False
            except:
                pass

            SysMgr.printWarn("failed to use %s event" % epath, reason=True)
            return -1

        try:
            if append:
                os.write(fd, bytes(UtilMgr.encodeStr(val)))
                try:
                    os.close(fd)
                except:
                    pass
            elif val:
                fd.write(val)
                try:
                    fd.close()
                except:
                    pass

            if path.endswith("/enable"):
                if not SysMgr.sysInstance:
                    SysMgr(onlyInstance=True)

                if val == "1":
                    SysMgr.sysInstance.cmdList[
                        path[: path.rfind("/enable")]
                    ] = True
                elif val == "0":
                    SysMgr.sysInstance.cmdList[
                        path[: path.rfind("/enable")]
                    ] = False
        except SystemExit:
            sys.exit(0)
        except:
            SysMgr.printWarn(
                "failed to apply command '%s' to %s" % (val, path), True, True
            )
            return -2

        return 0

    @staticmethod
    def doPrint(
        newline=True, clear=False, flush=True, addLine=False, pager=True
    ):
        if not SysMgr.bufferString and not SysMgr.bufferList:
            return

        output = SysMgr.getPrintBuf()

        if addLine:
            output += "\n"

        SysMgr.printPipe(output, newline=newline, flush=flush, pager=pager)

        if clear:
            SysMgr.clearPrint()

    @staticmethod
    def printConsole(string):
        string = "\n".join(
            [nline[: SysMgr.ttyCols - 1] for nline in string.split("\n")]
        )

        try:
            print(string.rstrip())
        except SystemExit:
            sys.exit(0)
        except:
            return

    @staticmethod
    def addPrint(string, newline=1, force=False):
        if not SysMgr.printEnable:
            return

        if not force and SysMgr.checkCutCond(newline):
            return False

        isList = "STRPRINTBUF" not in SysMgr.environList

        if isList:
            SysMgr.bufferList.append(string)
        else:
            try:
                SysMgr.bufferString += string
            except SystemExit:
                sys.exit(0)
            except:
                SysMgr.bufferString = "%s%s" % (SysMgr.bufferString, string)

        SysMgr.bufferRows += newline

        if (
            SysMgr.terminalOver
            or not SysMgr.outPath
            or not SysMgr.streamEnable
        ):
            return True

        SysMgr.printConsole(string)

        return True

    @staticmethod
    def hasPrintBuf():
        return SysMgr.bufferString or SysMgr.bufferList

    @staticmethod
    def getPrintBuf(retStr=True, sort=False, char=""):
        isList = "STRPRINTBUF" not in SysMgr.environList
        if isList:
            if sort:
                SysMgr.bufferList.sort()

            if retStr:
                return char.join(SysMgr.bufferList)
            else:
                return SysMgr.bufferList
        else:
            return SysMgr.bufferString

    @staticmethod
    def delPrint(newline=1):
        try:
            isList = "STRPRINTBUF" not in SysMgr.environList
            if isList:
                SysMgr.bufferList.pop(-(abs(newline)))
            else:
                target = SysMgr.bufferString
                start = target.rfind("\n")
                pos = newline

                while start >= 0 and pos > 1:
                    start = target.rfind("\n", start - 1)
                    pos -= 1

                SysMgr.bufferString = target[: start + 1]

            SysMgr.bufferRows -= newline
        except:
            pass

    @staticmethod
    def clearPrint():
        del SysMgr.bufferString
        SysMgr.bufferList = []
        SysMgr.bufferString = ""
        SysMgr.bufferRows = 0
        SysMgr.terminalOver = False

    @staticmethod
    def isPosixOS():
        return SysMgr.isLinux or SysMgr.isDarwin or SysMgr.isQnx

    @staticmethod
    def clearScreen():
        if not SysMgr.printEnable or SysMgr.pipeForPager:
            return

        if SysMgr.isPosixOS() and "REMOTERUN" not in os.environ:
            sys.stdout.write("\x1b[2J\x1b[H")
        elif SysMgr.platform.startswith("win"):
            os.system("cls")

    @staticmethod
    def printLogo(absolute=False, big=False, onlyFile=False, pager=True):
        if not SysMgr.logoEnable:
            return

        if "ISMAIN" not in os.environ:
            print("\nPowered by %s" % ConfigMgr.logo)
            return

        # skip logo when JSON mode is active to keep stdout clean #
        if SysMgr.jsonEnable or SysMgr.findOption("J"):
            return

        if not SysMgr.printEnable or SysMgr.remoteRun:
            return

        SysMgr.convExtAscii(ConfigMgr.logo)

        if not SysMgr.outPath:
            if SysMgr.streamEnable:
                if not absolute:
                    return
            elif onlyFile:
                return

        if big:
            logo = UtilMgr.convColor(ConfigMgr.logo, "GREEN")
            if pager:
                SysMgr.printPipe(logo)
            else:
                print(logo)
        else:
            title = "/ G.u.i.d.e.r \tver.%s_%s /" % (__version__, __revision__)
            SysMgr.printPipe(
                " %s\n%s\n%s"
                % (underLine[: len(title)], title, oneLine[: len(title)])
            )

        if onlyFile:
            SysMgr.printPipe("\n\n")

    @staticmethod
    def parseInfoData(lines):
        jsonData = {}

        oneLinePart = oneLine[:10]
        twoLinePart = twoLine[:10]
        cleanItem = UtilMgr.cleanItem

        for l in lines:
            try:
                l = l.strip()

                m = re.match(r"\s*\[(?P<context>.+) Info\]", l)
                if not m:
                    continue

                d = m.groupdict()
                context = d["context"].replace(" ", "")
                jsonSubData = jsonData[context] = {}
                prev = prev2 = None
                menu = []

                for idx, item in enumerate(l.split("\n")[1:]):
                    if item in (oneLine, twoLine):
                        continue
                    elif item.startswith(oneLinePart):
                        continue
                    elif item.startswith(twoLinePart):
                        continue

                    if context in (
                        "SystemGeneral",
                        "SystemOS",
                        "SystemCPU",
                        "SystemCPUCache",
                    ):
                        if idx < 3:
                            continue

                        ret = item.lstrip().split(None, 1)
                        if item.startswith("                     "):
                            if prev:
                                jsonSubData[prev] += item.lstrip().rstrip(" |")
                        else:
                            key, val = ret
                            key = key.strip()
                            jsonSubData[key] = val.strip(" |")
                            prev = key

                    elif context in (
                        "Buddy",
                        "FreePage",
                    ):
                        items = item.split("|")
                        if len(items) == 6:
                            isFree = True
                        else:
                            isFree = False

                        node = items[0].strip()
                        if node == "NODE":
                            menu = items[3 if isFree else 2].split()
                            continue

                        if not node:
                            node = prev
                        else:
                            prev = node

                        if isFree:
                            mtype = items[2].strip()
                            zoneIdx = 1
                            valIdx = 3
                            totalIdx = 4
                        else:
                            zoneIdx = 1
                            valIdx = 2
                            totalIdx = 3

                        zone = items[zoneIdx].strip()
                        if isFree:
                            if not zone:
                                zone = prev2
                            else:
                                prev2 = zone

                        values = [
                            items[valIdx][idx * 10 : idx * 10 + 10]
                            for idx in range(long(len(items[valIdx]) / 10))
                        ]
                        total = items[totalIdx].strip()

                        jsonSubData.setdefault(node, {})

                        if isFree:
                            jsonSubData[node].setdefault(zone, {})
                            jsonSubData[node][zone][mtype] = {"total": total}
                            jsonSubTarget = jsonSubData[node][zone][mtype]
                        else:
                            jsonSubData[node][zone] = {"total": total}
                            jsonSubTarget = jsonSubData[node][zone]

                        for i, v in zip(menu, values):
                            v = v.strip()
                            if not v:
                                continue
                            jsonSubTarget[i] = v

                    elif context in (
                        "SchedFactor",
                        "VM",
                        "Peak",
                        "Threshold",
                        "KSM",
                    ):
                        if idx < 3:
                            continue

                        ret = item.lstrip().split("|")[:2]
                        if len(ret) == 1:
                            if prev:
                                jsonSubData[prev] += ret[0]
                        else:
                            key, val = ret
                            key = key.strip()
                            val = val.strip(" |")
                            if not key or not val:
                                continue
                            jsonSubData[key] = val
                            prev = key

                    elif context in ("SchedFeature"):
                        if idx < 3:
                            continue

                        ret = cleanItem(item.lstrip().split("|"), False)
                        new = []
                        for i in item.split("|"):
                            new.append(i.strip())
                        ret = new
                        name = ret[0]
                        if not name:
                            if prev:
                                jsonSubData[prev] += cleanItem(ret[1:], False)
                        else:
                            jsonSubData[name] = cleanItem(ret[1:], False)
                            prev = name

                    elif context in ("SystemGPU", "HugePage"):
                        if idx < 3:
                            continue

                        ret = cleanItem(item.lstrip().split("|", 2), False)
                        if len(ret) == 2:
                            name = prev
                            stat, val = ret
                        else:
                            name, stat, val = ret
                        jsonSubData.setdefault(name, {})
                        jsonSubData[name][stat] = val.strip(" |")
                        prev = name

                    elif context in ("AppArmor", "SystemUSB", "MemoryMap"):
                        if idx < 1:
                            continue

                        if not isinstance(jsonSubData, list):
                            jsonSubData = jsonData[context] = []

                        if context == "AppArmor":
                            jsonSubData += UtilMgr.cleanItem(
                                item.split("|"), False
                            )
                        elif context == "MemoryMap":
                            if idx < 2:
                                continue
                            jsonSubData.append(
                                UtilMgr.cleanItem(item.split("|"), False)
                            )
                        else:
                            jsonSubData.append(item.rstrip(" |"))

                    elif context in ("SystemMemory"):
                        items = item.split()
                        items = UtilMgr.removeItems(items, "]")
                        name = items[1].strip(" ]")
                        if name == "DESC":
                            menu = items[5:-1]
                        elif name in ("TOTAL", "FREE", "AVAIL"):
                            mem, swap = items[2:4]
                            jsonSubData["mem" + name] = mem
                            jsonSubData["swap" + name] = swap
                        elif name == "LAST" and menu:
                            for n, stat in enumerate(items[5:-1]):
                                jsonSubData["mem" + menu[n]] = stat

                    elif context in ("SystemStorage"):
                        items = item.split()
                        name = items[0].strip()
                        if name == "DEV":
                            menu = items[1:-1]
                        elif name.startswith("/"):
                            jsonSubData[name] = {}
                            prev = name
                        elif name == "TOTAL" and menu:
                            jsonSubData[name] = {}
                            for n, item in enumerate(items[1:7]):
                                jsonSubData[name][menu[n]] = item
                        elif menu:
                            if item.startswith("                        "):
                                jsonSubData[prev][menu[8]] += item.lstrip()
                            else:
                                for n, item in enumerate(items[:8]):
                                    jsonSubData[prev][menu[n]] = item
                                jsonSubData[prev][menu[8]] = " ".join(
                                    items[8:]
                                )

                    elif context in ("SystemBlock"):
                        items = item.split()
                        name = items[0].strip()
                        if name == "DEV":
                            menu = items
                        elif menu:
                            jsonSubData[name] = {}
                            for n, item in enumerate(items[1:8]):
                                jsonSubData[name][menu[n]] = item
                            jsonSubData[name][menu[8]] = " ".join(
                                items[8:]
                            ).rstrip(" |")

                    elif context in ("SystemNetwork"):
                        items = item.split()
                        items = UtilMgr.removeItems(items, "|")
                        name = items[0].strip()
                        if name == "Network":
                            continue
                        elif name == "Dev":
                            menu = items
                        elif menu:
                            if len(items) >= len(menu):
                                jsonSubData[name] = {}
                                prev = name
                                continue

                            for n, item in enumerate(items[1:]):
                                bound = "recv" if n < 5 else "tran"
                                jsonSubData[prev].setdefault(bound, {})
                                jsonSubData[prev][bound][menu[n + 2]] = item

                    elif context in ("SystemGPUMemory"):
                        items = item.split("|")
                        name = items[0].strip()
                        if name == "Process":
                            menu = cleanItem(items, False)
                        elif menu:
                            jsonSubData[name] = {}
                            for n, item in enumerate(items[1:]):
                                item = item.strip()
                                if not item:
                                    continue
                                jsonSubData[name][menu[n + 1]] = item

                    elif context in ("SystemSwap"):
                        items = item.strip(" |").split(None, 5)
                        if len(items) > 5:
                            name = items[5]
                        else:
                            name = items[0]

                        if name in ("Type", "None", "Path(Stat)"):
                            continue

                        if name.startswith("-"):
                            if prev not in jsonSubData:
                                continue
                            items = item.split(":", 1)
                            iname = items[0].strip(" -")
                            ival = items[1].strip()
                            jsonSubData[prev][iname] = ival
                        else:
                            jsonSubData[name] = {
                                "size": items[1],
                                "used": items[2].rstrip("("),
                                "usedPer": items[3].rstrip(")"),
                                "type": items[0],
                            }

                            if len(items) > 4:
                                jsonSubData[name]["prio"] = items[4]
                                jsonSubData[name]["path"] = items[5]

                            prev = name

                    elif context in ("TaskLimit"):
                        if item.startswith("Limit"):
                            continue
                        items = item.strip(" |").rsplit(None, 3)

                        jsonSubData[items[0]] = {
                            "soft": items[1],
                            "hard": items[2],
                            "unit": items[3],
                        }

                    else:
                        pass
            except SystemExit:
                sys.exit(0)
            except:
                SysMgr.printWarn(
                    "failed to convert below system info in JSON format\n%s\n"
                    % l,
                    True,
                    True,
                )

        if "CONVUNIT2SIZE" in SysMgr.environList:

            def _convValues(d):
                result = {}

                for key, value in d.items():
                    if isinstance(value, dict):
                        result[key] = _convValues(value)
                    else:
                        try:
                            result[key] = UtilMgr.convUnit2Size(
                                value.replace(",", ""), verb=False
                            )
                        except SystemExit:
                            sys.exit(0)
                        except:
                            pass

                return result

            jsonData = _convValues(jsonData)

        return jsonData

    @staticmethod
    def printInfoBuffer():
        SysMgr.printPipe(SysMgr.sysinfoBuffer + "\n")
        SysMgr.clearInfoBuffer()

    @staticmethod
    def parseCustomRecordCmd(cmdList):
        tempList = {"BEFORE": [], "START": [], "AFTER": [], "STOP": []}

        if not cmdList:
            return {}

        cmdList = cmdList.split(",")

        for item in cmdList:
            sitem = item.split(":")
            ltime = sitem[0].strip().upper()

            if len(sitem) not in (2, 3) or ltime not in (
                "BEFORE",
                "START",
                "AFTER",
                "STOP",
            ):
                SysMgr.printErr(
                    "wrong format used, BEFORE|START|AFTER|STOP:file:value"
                )
                sys.exit(-1)
            elif len(sitem) == 2:
                tempList[ltime].append([sitem[1]])
            elif len(sitem) == 3:
                tempList[ltime].append([sitem[1], sitem[2]])

        return tempList

    @staticmethod
    def getOverlayfsInfo(pid, cache=True):
        if cache and pid in SysMgr.overlayfsCache:
            return SysMgr.overlayfsCache[pid]

        data = SysMgr.getMountData(pid)
        mountList = SysMgr.convMountList(data)
        if not mountList:
            return {}

        overlayList = {}
        for point, info in mountList.items():
            try:
                if info["fs"] != "overlay":
                    continue

                overlayList[point] = {}
                items = info["subopt"].split(",")
                for line in items:
                    if line.startswith("lowerdir"):
                        attr = "lowerdir"
                    elif line.startswith("upperdir"):
                        attr = "upperdir"
                    elif line.startswith("mergedir"):
                        continue
                    else:
                        continue

                    dirs = line.lstrip(attr)[1:].split(":")
                    overlayList[point][attr] = dirs
            except SystemExit:
                sys.exit(0)
            except:
                continue

        SysMgr.overlayfsCache[pid] = overlayList

        return overlayList

    @staticmethod
    def convMountList(mountInfo):
        if not mountInfo:
            return {}

        mountList = {}
        for l in mountInfo:
            values = l.split(" - ")
            if len(values) != 2:
                continue
            left = values[0]
            right = values[1]

            left = left.split()
            mountid, parentid, devid, root, path = left[:5]
            major, minor = devid.split(":")
            option = " ".join(left[5:-1])

            # decode octal escapes in mount path (e.g. \040 -> space) #
            path = (
                path.replace("\\040", " ")
                .replace("\\011", "\t")
                .replace("\\012", "\n")
                .replace("\\134", "\\")
            )

            right = right.split()
            fs, dev = right[0:2]
            soption = " ".join(right[2:])

            if "/" not in dev and ":" in dev:
                major, minor = SysMgr.getDevNum(dev)
            else:
                major = minor = -1

            mountList[path] = {
                "major": major,
                "minor": minor,
                "mountid": mountid,
                "fs": fs,
                "opt": option,
                "subopt": soption,
            }

        return mountList

    @staticmethod
    def getMountInfo():
        infoBuf = SysMgr.sysinfoBuffer

        if infoBuf == "":
            return

        mountPosStart = infoBuf.find("Storage Info")
        if mountPosStart == -1:
            return

        mountPosStart = infoBuf.find(twoLine, mountPosStart + 1)
        if mountPosStart == -1:
            return

        mountPosStart = infoBuf.find(twoLine, mountPosStart + 1)
        if mountPosStart == -1:
            return

        mountPosStart = infoBuf.find("\n", mountPosStart)
        if mountPosStart == -1:
            return

        mountPosEnd = infoBuf.find(oneLine, mountPosStart)
        if mountPosEnd == -1:
            return

        try:
            mountTable = []
            tempTable = infoBuf[mountPosStart:mountPosEnd].split("\n")
            for idx, line in enumerate(tempTable):
                nrItem = len(line.split())
                if 1 < nrItem < 4:
                    mountTable.append("%s %s" % (line, tempTable[idx + 1]))
        except:
            pass

        init_mountData = {"dev": " ", "filesystem": " ", "mount": " "}

        for item in mountTable:
            m = re.match(
                (
                    r"(?P<dev>\S+)\s+\((?P<devt>\S+)\)\s+\[(?P<range>\S+)\]\s+"
                    r"(?P<maj>[0-9]+):(?P<min>[0-9]+)\s+(?P<readSize>\S+)\s+"
                    r"(?P<writeSize>\S+)\s+(?P<totalSize>\S+)\s+"
                    r"(?P<freeSize>\S+)\s+(?P<Usage>\S+)\s+(?P<nrFile>\S+)\s+"
                    r"(?P<filesystem>\S+)\s+(?P<mount>.+)"
                ),
                item,
            )
            if not m:
                continue

            d = m.groupdict()
            mid = "%s:%s" % (d["maj"], d["min"])
            SysMgr.savedMountTree[mid] = dict(init_mountData)
            SysMgr.savedMountTree[mid]["dev"] = d["dev"]
            SysMgr.savedMountTree[mid]["filesystem"] = d["filesystem"]
            SysMgr.savedMountTree[mid]["mount"] = d["mount"]

            try:
                start, end = d["range"].split("-")
                SysMgr.savedMountTree[mid]["start"] = long(start)
                SysMgr.savedMountTree[mid]["end"] = long(end)
            except:
                pass

    @staticmethod
    def getProcTreeInfo():
        infoBuf = SysMgr.sysinfoBuffer

        if infoBuf == "":
            return

        magic = "!!!!!"

        treePos = infoBuf.find(magic)
        if treePos == -1:
            return

        newPos = treePos + len(magic)

        commPos = infoBuf[newPos:].find(magic)

        if commPos < 0:
            procTree = infoBuf[newPos:]
            procTree = procTree[: procTree.find("\n")].split(",")
        else:
            procTree = infoBuf[newPos : newPos + commPos].split(",")

        for pair in procTree:
            try:
                ids = pair.split("#")
                tid = ids[0]
                pid = ids[1]

                if not pid.isdigit():
                    group = pid
                    pidPos = group.find("(")
                    pid = group[:pidPos]
                    comm = group[pidPos + 1 :].rstrip(")")
                    SysMgr.savedProcComm[pid] = comm

                SysMgr.savedProcTree[tid] = pid
            except:
                continue

        if commPos < 0:
            SysMgr.sysinfoBuffer = infoBuf[:treePos]
        else:
            commData = infoBuf[newPos + commPos + len(magic) :]
            commData = commData[: commData.find("\n")]
            SysMgr.commCache = UtilMgr.convStr2Dict(commData)
            SysMgr.sysinfoBuffer = infoBuf[: newPos - len(magic)]

    @staticmethod
    def checkVersion(infoBuf):
        try:
            verPosStart = infoBuf.find("Version")
            verPosEnd = infoBuf.find("\n", verPosStart)
            recVer = infoBuf[verPosStart:verPosEnd].split()[1]
            if recVer != __version__:
                SysMgr.printWarn(
                    "data version %s is different from current software %s"
                    % (__version__, recVer),
                    True,
                )
        except:
            pass

    @staticmethod
    def applyLaunchOption():
        infoBuf = SysMgr.sysinfoBuffer

        if infoBuf == "":
            return

        launchPosStart = infoBuf.find("Launch")
        if launchPosStart == -1:
            return

        launchPosEnd = infoBuf.find("\n", launchPosStart)
        if launchPosEnd == -1:
            return

        SysMgr.launchBuffer = infoBuf[launchPosStart:launchPosEnd]

        SysMgr.checkVersion(infoBuf)

        archPosStart = infoBuf.find("CPU")
        archPosEnd = infoBuf.find("\n", archPosStart)

        if not SysMgr.archOption:
            try:
                arch = infoBuf[archPosStart:archPosEnd].split()[1]
                SysMgr.setArch(arch)
            except SystemExit:
                sys.exit(0)
            except:
                pass

        if archPosStart >= 0 and archPosEnd >= 0:
            analOption = "{0:20} {1:<100}".format(
                "Analysis", "# %s" % (" ".join(sys.argv))
            )
            SysMgr.sysinfoBuffer = "%s\n%s\n%s" % (
                infoBuf[:archPosEnd],
                analOption,
                infoBuf[archPosEnd + 1 :],
            )

        if SysMgr.isDrawMode():
            SysMgr.printInfo("<DRAW MODE>")

        if (
            " funcrec " in SysMgr.launchBuffer
            or " funcrecord " in SysMgr.launchBuffer
        ):
            SysMgr.threadEnable = False
            SysMgr.functionEnable = True
            if not SysMgr.isDrawMode():
                SysMgr.printInfo("<FUNCTION MODE>")
        else:
            SysMgr.threadEnable = True
            if not SysMgr.isDrawMode():
                SysMgr.printInfo("<THREAD MODE>")

        filterList = None
        launchPosStart = SysMgr.launchBuffer.find(" -g")
        if SysMgr.isThreadMode() and launchPosStart > -1:
            filterList = SysMgr.launchBuffer[launchPosStart + 3 :]
            filterList = filterList[: filterList.find(" -")].strip()
            filterGroup = filterList.split(",")
            filterGroup = UtilMgr.cleanItem(filterGroup)
            groupProcEnable = SysMgr.launchBuffer.find(" -P") > -1
            if groupProcEnable:
                SysMgr.printInfo(
                    (
                        "only specific threads that involved "
                        "in the process group [ %s ] were recorded"
                    )
                    % ", ".join(filterGroup)
                )
            else:
                SysMgr.printInfo(
                    "only specific threads [ %s ] were recorded"
                    % ", ".join(filterGroup)
                )

        if SysMgr.filterGroup:
            if SysMgr.groupProcEnable:
                SysMgr.printInfo(
                    (
                        "only specific threads that involved "
                        "in the process group [ %s ] are shown"
                    )
                    % ", ".join(SysMgr.filterGroup)
                )
            else:
                SysMgr.printInfo(
                    "only specific threads [ %s ] are shown"
                    % ", ".join(SysMgr.filterGroup)
                )

        if " -D" in SysMgr.launchBuffer:
            SysMgr.depEnable = True

        if " -t" in SysMgr.launchBuffer:
            SysMgr.sysEnable = True

        launchPosStart = SysMgr.launchBuffer.find(" -d")
        if launchPosStart > -1:
            filterList = SysMgr.launchBuffer[launchPosStart + 3 :]
            filterList = filterList[: filterList.find(" -")]
            if "a" in filterList:
                SysMgr.disableAll = True
            if "c" in filterList:
                SysMgr.cpuEnable = False
                SysMgr.latEnable = False
            if "l" in filterList:
                SysMgr.latEnable = False
            if "s" in filterList:
                SysMgr.signalEnable = False

        launchPosStart = SysMgr.launchBuffer.find(" -e")
        if launchPosStart > -1:
            filterList = SysMgr.launchBuffer[launchPosStart + 3 :]
            filterList = filterList[: filterList.find(" -")]
            if "u" in filterList:
                dlist = SysMgr.getOption("d")
                if not dlist or "u" not in dlist:
                    SysMgr.userEnable = True
                    SysMgr.userRecordEnable = True
            if "m" in filterList:
                SysMgr.memEnable = True
            if "b" in filterList:
                SysMgr.blockEnable = True
            if "P" in filterList:
                SysMgr.powerEnable = True
            if "w" in filterList:
                SysMgr.wqEnable = True
            if "M" in filterList:
                SysMgr.moduleEnable = True
            if "B" in filterList:
                SysMgr.binderEnable = True
            if "I" in filterList:
                SysMgr.i2cEnable = True
            if "f" in filterList:
                SysMgr.fsEnable = True
            if "h" in filterList:
                SysMgr.heapEnable = True
            if "L" in filterList:
                SysMgr.lockEnable = True
            if "i" in filterList:
                SysMgr.irqEnable = True
            if "n" in filterList:
                SysMgr.networkEnable = True
            if "s" in filterList:
                SysMgr.syncEnable = True

            disOpt = SysMgr.getOption("d")
            disOpt = disOpt or ""

            if "S" in filterList and "S" not in disOpt:
                SysMgr.pssEnable = True
            elif "u" in filterList and "u" not in disOpt:
                SysMgr.ussEnable = True
            elif not SysMgr.isDrawMode():
                SysMgr.rssEnable = True
        elif not SysMgr.isDrawMode():
            SysMgr.rssEnable = True

        launchPosStart = SysMgr.launchBuffer.find(" -c")
        if launchPosStart > -1:
            filterList = SysMgr.launchBuffer[launchPosStart + 3 :]
            endIdx = filterList.find(" -")
            if endIdx >= 0:
                filterList = filterList[:endIdx]
            filterList = filterList.strip().split(",")
            filterList = UtilMgr.cleanItem(filterList, union=False)
            filterList = list(map(lambda c: c.split(":", 1)[0], filterList))
            for idx, item in enumerate(filterList):
                tempItem = filterList[idx].split("/")
                if len(tempItem) == 2:
                    filterList[idx] = tempItem[1]
                    SysMgr.customEventList.append(tempItem[1])
                elif len(tempItem) == 1:
                    filterList[idx] = tempItem[0]
                    SysMgr.customEventList.append(tempItem[0])
                else:
                    filterList.pop(idx)
            if filterList:
                SysMgr.printInfo(
                    "profiled trace events [ %s ]" % ", ".join(filterList)
                )
                if not SysMgr.customCmd:
                    SysMgr.customCmd = filterList

        launchPosStart = SysMgr.launchBuffer.find(" -U")
        if launchPosStart > -1:
            SysMgr.ueventEnable = True
            filterList = SysMgr.launchBuffer[launchPosStart + 3 :]
            filterList = filterList[: filterList.find(" -")].strip()
            SysMgr.userCmd = str(filterList).split(",")
            SysMgr.userCmd = UtilMgr.cleanItem(SysMgr.userCmd)
            SysMgr.printInfo(
                "profiled user events [ %s ]"
                % ", ".join([cmd.strip() for cmd in SysMgr.userCmd])
            )
            SysMgr.userEventList = [
                cmd.split(":")[0].strip() for cmd in SysMgr.userCmd
            ]

        launchPosStart = SysMgr.launchBuffer.find(" -K")
        if launchPosStart > -1:
            SysMgr.keventEnable = True
            filterList = SysMgr.launchBuffer[launchPosStart + 3 :]
            filterList = filterList[: filterList.find(" -")].strip()
            SysMgr.kernelCmd = str(filterList).split(",")
            SysMgr.kernelCmd = UtilMgr.cleanItem(SysMgr.kernelCmd)
            SysMgr.printInfo(
                "profiled kernel events [ %s ]"
                % ", ".join([cmd.strip() for cmd in SysMgr.kernelCmd])
            )
            SysMgr.kernelEventList = [
                cmd.split(":")[0].strip() for cmd in SysMgr.kernelCmd
            ]

        launchPosStart = SysMgr.launchBuffer.find(" -A")
        if launchPosStart > -1:
            filterList = SysMgr.launchBuffer[launchPosStart + 3 :]
            filterList = filterList[: filterList.find(" -")].strip()

            if SysMgr.arch != filterList:
                SysMgr.printErr(
                    (
                        "arch(%s) of recorded target is different with "
                        "current arch(%s), use -A option with %s"
                    )
                    % (filterList, SysMgr.arch, filterList)
                )
                sys.exit(-1)

    @staticmethod
    def writeEvent(message, show=True):
        if not SysMgr.isLinux:
            return

        if not SysMgr.getTraceEventPath():
            return

        if not SysMgr.eventLogFd:
            if not SysMgr.eventLogPath:
                SysMgr.eventLogPath = "%s/%s" % (
                    SysMgr.traceEventPath,
                    "../trace_marker",
                )

            try:
                SysMgr.eventLogFd = open(SysMgr.eventLogPath, "w")
            except SystemExit:
                sys.exit(0)
            except:
                SysMgr.printOpenWarn(
                    "failed to open %s" % SysMgr.eventLogPath, True, True
                )
                return

        if SysMgr.eventLogFd:
            try:
                SysMgr.eventLogFd.write(message)
                event = message[message.find("_") + 1 :]
                if show:
                    SysMgr.printInfo("wrote '%s' event" % event)

                try:
                    SysMgr.eventLogFd.flush()
                except:
                    pass

                return True
            except SystemExit:
                sys.exit(0)
            except:
                SysMgr.printWarn(
                    "failed to write %s event" % (message), reason=True
                )
                return
        else:
            SysMgr.printErr(
                "failed to write %s event because there is no file\n" % message
            )

    @staticmethod
    def infoBufferPrint(line):
        SysMgr.sysinfoBuffer = "%s%s\n" % (SysMgr.sysinfoBuffer, line)

    @staticmethod
    def clearInfoBuffer():
        SysMgr.sysinfoBuffer = ""

    @staticmethod
    def printPipWarn(name, pkg):
        SysMgr.printWarn(
            "failed to import python package: %s, try to run 'pip%s install %s'"
            % (name, sys.version_info[0], pkg),
            True,
        )

    @staticmethod
    def drawTimeline(
        inputPath=None,
        inputData=None,
        outputPath=None,
        configPath=None,
        configData=None,
        taskList=[],
        start=0,
        annotation=None,
        yval=None,
        begin=0,
        end=0,
    ):
        def _addUserEvent(inputData):
            if not inputData or "EVENT" not in SysMgr.environList:
                return

            for item in SysMgr.environList["EVENT"]:
                try:
                    values = item.split(":")
                    if not (3 <= len(values) <= 5):
                        SysMgr.printErr(
                            (
                                "failed to recognize %s in X:Y:NAME:[CPU|MEM"
                                "|IO]:[BOX|CIRCLE|LARROW|RARROW] format"
                            )
                            % item
                        )
                        sys.exit(-1)

                    x, y, name = values[:3]

                    inputData["segments"].append(
                        {
                            "group": long(y),
                            "text": name,
                            "id": None,
                            "state": "EVENT_USER",
                            "time_start": float(x),
                            "time_end": float(x) + 0.000001,
                        }
                    )

                except SystemExit:
                    sys.exit(0)
                except:
                    SysMgr.printErr(
                        "failed to recognize event for timeline", reason=True
                    )
                    sys.exit(-1)

        svgwrite = SysMgr.getPkg("svgwrite")

        if inputPath:
            inputStr = ' from "%s"' % inputPath
        else:
            inputStr = ""

        SysMgr.printStat("start drawing timeline%s..." % inputStr)

        try:
            dwg = svgwrite.Drawing(
                outputPath, profile="tiny", viewBox="0 0 1700 900", debug=True
            )

            config = Timeline.Config()
            if configPath or configData:
                config = Timeline.Config._load(configPath, configData)

            if "TIMEUNIT" in SysMgr.environList:
                config.TIMEUNIT = SysMgr.environList["TIMEUNIT"][0].lower()
            else:
                config.TIMEUNIT = "us"

            try:
                if "DURATION" not in SysMgr.environList:
                    raise SyntaxWarning()
                duration = long(SysMgr.environList["DURATION"][0])
            except SyntaxWarning:
                duration = 0
            except:
                SysMgr.printErr("failed to set duration", True)
                sys.exit(-1)

            try:
                if "DURATIONMIN" not in SysMgr.environList:
                    raise SyntaxWarning()
                durationMin = long(SysMgr.environList["DURATIONMIN"][0])
            except SyntaxWarning:
                durationMin = 0
            except:
                SysMgr.printErr("failed to set minimum duration", True)
                sys.exit(-1)

            _addUserEvent(inputData)

            Timeline.conv_table = {}
            try:
                for item in SysMgr.environList.get("CONVGROUP", []):
                    src, des = item.split(":", 1)
                    Timeline.conv_table[src.strip()] = des.strip()
            except SystemExit:
                sys.exit(0)
            except:
                SysMgr.printErr("failed to set group conversion table", True)
                sys.exit(-1)

            timeline = Timeline.load(
                inputPath,
                inputData,
                config,
                taskList,
                begin,
                end,
                duration,
                durationMin,
            )
            if not timeline:
                SysMgr.printErr("no time segment on timeline")
                return

            if "STROKE" in SysMgr.environList:
                timeline.stroke_text = SysMgr.environList["STROKE"]
            else:
                timeline.stroke_text = None

            try:
                if "STROKEINTERVAL" not in SysMgr.environList:
                    raise SyntaxWarning()
                stroke_interval = SysMgr.environList["STROKEINTERVAL"][0]
                timeline.stroke_interval = long(stroke_interval)
            except SyntaxWarning:
                timeline.stroke_interval = 0
            except:
                SysMgr.printErr("failed to set interval for stroke", True)
                sys.exit(-1)

            try:
                if "STROKEDURATION" not in SysMgr.environList:
                    raise SyntaxWarning()
                stroke_duration = SysMgr.environList["STROKEDURATION"][0]
                timeline.stroke_duration = long(stroke_duration)
            except SyntaxWarning:
                timeline.stroke_duration = 0
            except:
                SysMgr.printErr("failed to set duration for stroke", True)
                sys.exit(-1)

            timeline.draw(dwg, start=start, annotation=annotation, yval=yval)

            ext = outputPath.rsplit(".", 1)[1]

            if ext == "html":
                svg_path = outputPath.replace(".html", "_temp.svg")
                dwg.filename = svg_path
                dwg.save()

                UtilMgr.convertTimelineSvgToHtml(svg_path, outputPath)

                try:
                    os.remove(svg_path)
                except SystemExit:
                    sys.exit(0)
                except:
                    pass
            elif ext == "svg":
                dwg.save()
            else:
                dwg.save()
                SysMgr.printStat(
                    "start converting '%s' to '%s' format..."
                    % (outputPath, ext)
                )
                cairosvg = SysMgr.getPkg("cairosvg")
                func = getattr(cairosvg, "svg2" + ext)
                func(
                    url=outputPath,
                    write_to=outputPath,
                    dpi=SysMgr.matplotlibDpi,
                )
        except SystemExit:
            sys.exit(0)
        except:
            SysMgr.printErr("failed to draw timeline", reason=True)
            return

    @staticmethod
    def drawText(lines):
        # pylint: disable=import-error

        imageType = None

        textwrap = SysMgr.getPkg("textwrap", False)
        if not textwrap:
            SysMgr.printPipWarn("textwrap", "textwrap3")
            sys.exit(-1)

        PIL = SysMgr.getPkg("PIL", False)
        if not PIL:
            SysMgr.printPipWarn("PIL", "pillow")
            sys.exit(-1)

        from PIL import Image, ImageFont, ImageDraw

        try:
            if not imageType:
                from PIL import JpegImagePlugin

                imageType = "jpg"
        except ImportError:
            err = sys.exc_info()[1]
            SysMgr.printWarn(
                "failed to import python package: %s" % err.args[0]
            )
        except SystemExit:
            sys.exit(0)

        try:
            if not imageType:
                from PIL import BmpImagePlugin

                imageType = "bmp"
        except ImportError:
            err = sys.exc_info()[1]
            SysMgr.printErr(
                "failed to import python package: %s" % err.args[0]
            )
            return
        except SystemExit:
            sys.exit(0)

        if not SysMgr.imagePath:
            SysMgr.printErr("failed to load image path")
            return

        SysMgr.imagePath += ".%s" % imageType

        if SysMgr.fontPath:
            try:
                imageFont = ImageFont.truetype(SysMgr.fontPath, 10)
            except:
                SysMgr.printErr(
                    "failed to load font from %s" % SysMgr.fontPath
                )
                return
        else:
            try:
                imageFont = ImageFont.load_default().font
            except:
                SysMgr.printErr(
                    (
                        "failed to load default font because %s, "
                        "try to use -T option"
                    )
                    % SysMgr.getErrMsg()
                )
                return

        text = textwrap.fill("A", width=150)
        fontSizeX, fontSizeY = imageFont.getsize(text)

        if isinstance(lines, list):
            lines = "".join(lines)

        lines = lines.split("\n")

        imageSizeX = fontSizeX * SysMgr.lineLength
        imageSizeY = fontSizeY * len(lines) + (fontSizeY * 2)
        imagePosY = 1

        if imageType == "jpg":
            pass
        elif imageType == "bmp":
            imageSizeX = 900
        else:
            SysMgr.printErr("no output image type")
            return

        imageObject = Image.new(
            "RGB", (imageSizeX, imageSizeY), (255, 255, 255)
        )

        drawnImage = ImageDraw.Draw(imageObject)

        for line in lines:
            text = textwrap.fill(line, width=170)

            imagePosY += fontSizeY

            try:
                drawnImage.text(
                    (1, imagePosY), text, (0, 0, 0), font=imageFont
                )
            except SystemExit:
                sys.exit(0)
            except:
                try:
                    drawnImage.text((1, imagePosY), text, (0, 0, 0))
                except SystemExit:
                    sys.exit(0)
                except:
                    continue

        try:
            imageObject.save(SysMgr.imagePath)
        except SystemExit:
            sys.exit(0)
        except:
            SysMgr.printErr("failed to save image as %s\n" % SysMgr.imagePath)
            return

        fsize = UtilMgr.getFileSizeStr(SysMgr.imagePath)

        SysMgr.printStat(
            "saved image into %s%s successfully" % (SysMgr.imagePath, fsize)
        )

    @staticmethod
    def clearProcBuffer():
        SysMgr.procBufferSize = 0
        SysMgr.procBuffer = []

    @staticmethod
    def printProcBuffer(suffix="\n"):
        msg = " Detailed Statistics "
        stars = "*" * long((long(SysMgr.lineLength) - len(msg)) / 2)
        SysMgr.printPipe("\n\n%s%s%s\n\n" % (stars, msg, stars))
        if SysMgr.procBuffer:
            SysMgr.printPipe(SysMgr.procBuffer)
        else:
            SysMgr.printPipe("\n" + UtilMgr.NONE_STR + suffix)

    @staticmethod
    def addProcBuffer(data):
        SysMgr.procBuffer.insert(0, data)
        SysMgr.procBufferSize += len(data)

        bufferSize = SysMgr.bufferSize
        convSize = UtilMgr.convSize2Unit

        while 0 < bufferSize < SysMgr.procBufferSize:
            if not SysMgr.bufferLossEnable:
                SysMgr.printInfo(
                    (
                        "start writing interval statistics because "
                        "buffer (%s) exceed %s"
                    )
                    % (
                        convSize(SysMgr.procBufferSize),
                        convSize(bufferSize),
                    )
                )

                pid = SysMgr.createProcess(isDaemon=True, chPgid=True)
                if pid == 0:
                    dtime = UtilMgr.getTime(
                        "UTCTIME" in SysMgr.environList
                    ) or long(SysMgr.getUptime())

                    SysMgr.fileSuffix = "%s_%s" % (dtime, SysMgr.pid)

                    SysMgr.setLowPriority(True)

                    SysMgr.stopHandler()
                elif pid > 0:
                    SysMgr.clearProcBuffer()
                    break
                else:
                    pass

            if not SysMgr.bufferOverflowed:
                SysMgr.printWarn(
                    (
                        "new data is going to be overwritten to the buffer"
                        " because of buffer overflow\n"
                        "\tincrease buffer size (%s) "
                        "if you want to prevent data loss"
                    )
                    % convSize(bufferSize),
                    True,
                )
                SysMgr.bufferOverflowed = True

            if not SysMgr.procBuffer:
                break

            SysMgr.procBufferSize -= len(SysMgr.procBuffer[-1])
            SysMgr.procBuffer.pop(-1)

            for path, data in TaskAnalyzer.fileIntData.items():
                if data and len(SysMgr.procBuffer) < len(data):
                    data.pop(sorted(data, key=lambda e: float(e))[0], None)

    @staticmethod
    def updateSession():
        if not SysMgr.addrListForPrint:
            return

        addrListForPrint = dict(SysMgr.addrListForPrint)
        for addr, cli in addrListForPrint.items():
            if cli.status == "SENT" and cli.ignore > 1:
                SysMgr.printInfo(
                    "unregistered %s:%s for PRINT" % (cli.ip, cli.port)
                )
                del SysMgr.addrListForPrint[addr]

    @staticmethod
    def printTopStats():
        if (
            "LIVEGRAPH" in SysMgr.environList
            or "PSIGRAPH" in SysMgr.environList
            or "CPUGRAPH" in SysMgr.environList
            or SysMgr.liveTaskGraphEnable
        ):
            if not SysMgr.streamEnable:
                SysMgr.clearScreen()
            SysMgr.doPrint()
        elif SysMgr.jsonEnable:
            if SysMgr.reportEnable:
                pass
            else:
                jsonFilter = SysMgr.environList.get("JSONFILTER", [])
                if jsonFilter:
                    for name in list(SysMgr.jsonData):
                        if not UtilMgr.isValidStr(name, jsonFilter):
                            SysMgr.jsonData.pop(name)

                if "ALLJSONSTAT" in SysMgr.environList:
                    _checkItem = lambda x: x.endswith(("Orig", "Fd"))
                else:
                    _checkItem = lambda x: x.startswith(("stat", "io"))

                for pid in list(SysMgr.jsonData.get("process", {})):
                    for k in list(SysMgr.jsonData["process"][pid]):
                        if _checkItem(k):
                            SysMgr.jsonData["process"][pid].pop(k)

                jsonStr = UtilMgr.convDict2Str(SysMgr.jsonData, pretty=False)
                if not jsonStr:
                    SysMgr.printWarn(
                        "failed to convert report data to JSON format"
                    )
                else:
                    SysMgr.printPipe(jsonStr)
        elif not SysMgr.outPath:
            if not SysMgr.streamEnable:
                SysMgr.clearScreen()
            SysMgr.doPrint()
        elif SysMgr.pipeEnable:
            SysMgr.doPrint(addLine=True)
        else:
            bufStr = SysMgr.getPrintBuf()

            SysMgr.addProcBuffer(bufStr + "\n")

            SysMgr.sendOutput2Nodes(bufStr)

        SysMgr.clearPrint()

    @staticmethod
    def printLiveGraph():
        """Print live ASCII line graph for system resource metrics (-q LIVEGRAPH mode)."""
        deque = SysMgr.getPkg("collections").deque

        jsonData = SysMgr.jsonData
        if not jsonData:
            return

        if not SysMgr.graphInfoCache:
            mem = jsonData.get("mem", {}) or {}
            swap = jsonData.get("swap", {}) or {}
            SysMgr.graphInfoCache = {
                "memTotal": mem.get("total", 0),
                "swapTotal": swap.get("total", 0),
            }

        width = max(40, min(SysMgr.ttyCols, SysMgr.lineLength))
        LABEL = 7
        STATS = 30  # "cur:XX,XXX KB  max:XX,XXX KB"
        GRAPH = max(
            10, width - LABEL - STATS - 3
        )  # -3: 2 spaces + trailing '|'
        BLOCKS = "\u2581\u2582\u2583\u2584\u2585\u2586\u2587\u2588"

        def _fmt(val, unit):
            """Format value with thousand-separator commas."""
            if unit == "%":
                return "%.1f%%" % val
            return "%s %s" % (format(int(val), ","), unit)

        metrics = []

        cpu = jsonData.get("cpu", {}) or {}
        if cpu:
            v = float(cpu.get("total", 0) or 0)
            metrics.append(("CPU%", v, 100.0, _fmt(v, "%")))

        mem = jsonData.get("mem", {}) or {}
        if mem:
            v = float(mem.get("available", 0) or 0)
            total = float(SysMgr.graphInfoCache.get("memTotal", 0) or v or 1)
            metrics.append(("MEM", v, total, _fmt(v, "MB")))

        swap = jsonData.get("swap", {}) or {}
        swapTotal = float(SysMgr.graphInfoCache.get("swapTotal", 0) or 0)
        if swap and swapTotal > 0:
            v = float(swap.get("usage", 0) or 0)
            metrics.append(("SWAP", v, swapTotal, _fmt(v, "MB")))

        gpu = jsonData.get("gpu", {}) or {}
        for devname in sorted(gpu.keys()):
            v = float(gpu[devname] or 0)
            label = ("GPU/" + devname.replace("GPU_", ""))[:7]
            metrics.append((label, v, 100.0, _fmt(v, "%")))

        block = jsonData.get("block", {}) or {}
        if block:
            rd = float(block.get("read", 0) or 0) * 1024.0
            wr = float(block.get("write", 0) or 0) * 1024.0
            metrics.append(("BLK_R", rd, None, _fmt(rd, "KB")))
            metrics.append(("BLK_W", wr, None, _fmt(wr, "KB")))

        net = jsonData.get("net", {}) or {}
        if net:
            ni = float(net.get("inbound", 0) or 0) / 1024.0
            no = float(net.get("outbound", 0) or 0) / 1024.0
            metrics.append(("NET_I", ni, None, _fmt(ni, "KB")))
            metrics.append(("NET_O", no, None, _fmt(no, "KB")))

        if not metrics:
            return

        # apply label filter if value(s) provided (skip "SET" = no value given) #
        live_filters = [
            v for v in SysMgr.environList.get("LIVEGRAPH", []) if v != "SET"
        ]
        if live_filters:
            metrics = [
                m
                for m in metrics
                if UtilMgr.isValidStr(m[0], live_filters, ignCap=True)
            ]
            if not metrics:
                return

        for label, val, _maxval, _disp in metrics:
            if label not in SysMgr.graphHistory:
                SysMgr.graphHistory[label] = deque(maxlen=SysMgr.lineLength)
            SysMgr.graphHistory[label].append(val)

        if metrics:
            SysMgr.addPrint("%s\n" % twoLine)

        i = 0
        for label, cur_val, maxval, _disp in metrics:
            i += 1
            hist = SysMgr.graphHistory.get(label)
            if not hist:
                continue

            unit = (
                "%"
                if label in ("CPU%",) or label.startswith("GPU/")
                else ("MB" if label in ("MEM", "SWAP") else "KB")
            )

            # scale: fixed for CPU/MEM/SWAP/GPU, dynamic (hist max) for BLK/NET #
            if maxval is not None:
                scale = float(maxval) or 1.0
            else:
                scale = float(max(hist)) if any(h > 0 for h in hist) else 1.0
            scale = scale or 1.0

            hist_vals = list(hist)
            v_min = min(hist_vals)
            v_max = max(hist_vals)
            v_avg = sum(hist_vals) / len(hist_vals)

            # stats columns: top line = cur + max, bot line = min + avg #
            top_stats = (
                "cur:%-12s max:%s" % (_fmt(cur_val, unit), _fmt(v_max, unit))
            ).ljust(STATS)
            bot_stats = (
                "min:%-12s avg:%s" % (_fmt(v_min, unit), _fmt(v_avg, unit))
            ).ljust(STATS)

            hist_slice = list(hist)[-GRAPH:]

            # render 2 rows: top = upper half of scale, bot = lower half #
            half = scale / 2.0
            top_row = []
            bot_row = []
            for v in hist_slice:
                v = float(v)
                top_ratio = min(1.0, max(0.0, (v - half) / half))
                top_row.append(
                    BLOCKS[int(top_ratio * 7.999)] if v > half else " "
                )
                bot_ratio = min(1.0, max(0.0, v / half))
                bot_row.append(BLOCKS[int(bot_ratio * 7.999)])

            top_str = "".join(top_row).ljust(GRAPH)
            bot_str = "".join(bot_row).ljust(GRAPH)

            SysMgr.addPrint(
                "%-7s %s %s|\n" % (label[:7], top_str[:GRAPH], top_stats)
            )
            SysMgr.addPrint(
                "%-7s %s %s|\n" % (" " * 7, bot_str[:GRAPH], bot_stats)
            )
            if i != len(metrics):
                SysMgr.addPrint("%s\n" % oneLine)

    @staticmethod
    def printPsiGraph():
        """Print live ASCII line graph for PSI metrics (-q PSIGRAPH mode)."""
        deque = SysMgr.getPkg("collections").deque

        jsonData = SysMgr.jsonData
        if not jsonData:
            return

        psi = jsonData.get("psi", {}) or {}
        if not psi:
            return

        width = max(40, min(SysMgr.ttyCols, SysMgr.lineLength))
        LABEL = 7
        STATS = 30  # "cur:XX.XX%  max:XX.XX%"
        GRAPH = max(10, width - LABEL - STATS - 3)  # -3: space×2 + '|'
        BLOCKS = "\u2581\u2582\u2583\u2584\u2585\u2586\u2587\u2588"

        def _fmt(val):
            return "%.4f%%" % val

        metrics = []
        for resource in ("cpu", "memory", "io"):
            rdata = psi.get(resource, {}) or {}
            if not rdata:
                continue
            for kind in ("some", "full"):
                v = float(rdata.get(kind, 0) or 0)
                short = resource[:3] if resource != "memory" else "mem"
                label = "%s_%s" % (short, kind[0])  # e.g. "cpu_s", "mem_f"
                metrics.append((label, v, _fmt(v)))

        if not metrics:
            return

        for label, val, _ in metrics:
            key = "PSI_" + label
            if key not in SysMgr.graphHistory:
                SysMgr.graphHistory[key] = deque(maxlen=SysMgr.lineLength)
            SysMgr.graphHistory[key].append(val)

        SysMgr.addPrint("%s\n" % twoLine)

        i = 0
        for label, cur_val, cur_str in metrics:
            i += 1
            key = "PSI_" + label
            hist = SysMgr.graphHistory.get(key)
            if not hist:
                continue

            # PSI values are percentages: scale to observed max (dynamic) #
            scale = float(max(hist)) if any(h > 0 for h in hist) else 1.0
            scale = scale or 1.0

            hist_vals = list(hist)
            v_min = min(hist_vals)
            v_max = max(hist_vals)
            v_avg = sum(hist_vals) / len(hist_vals)

            top_stats = (
                "cur:%-12s max:%s" % (_fmt(cur_val), _fmt(v_max))
            ).ljust(STATS)
            bot_stats = (
                "min:%-12s avg:%s" % (_fmt(v_min), _fmt(v_avg))
            ).ljust(STATS)

            hist_slice = hist_vals[-GRAPH:]

            # render 2 rows: top = upper half, bot = lower half #
            half = scale / 2.0
            top_row = []
            bot_row = []
            for v in hist_slice:
                v = float(v)
                top_ratio = min(1.0, max(0.0, (v - half) / half))
                top_row.append(
                    BLOCKS[int(top_ratio * 7.999)] if v > half else " "
                )
                bot_ratio = min(1.0, max(0.0, v / half))
                bot_row.append(BLOCKS[int(bot_ratio * 7.999)])

            top_str = "".join(top_row).ljust(GRAPH)
            bot_str = "".join(bot_row).ljust(GRAPH)

            SysMgr.addPrint(
                "%-7s %s %s|\n" % (label[:7], top_str[:GRAPH], top_stats)
            )
            SysMgr.addPrint(
                "%-7s %s %s|\n" % (" " * 7, bot_str[:GRAPH], bot_stats)
            )
            if i != len(metrics):
                SysMgr.addPrint("%s\n" % oneLine)

    @staticmethod
    def printCpuGraph():
        """Print live ASCII line graph for per-core CPU usage (-q CPUGRAPH mode)."""
        deque = SysMgr.getPkg("collections").deque

        jsonData = SysMgr.jsonData
        if not jsonData:
            return

        perCore = (jsonData.get("cpu", {}) or {}).get("perCore", {}) or {}
        if not perCore:
            return

        width = max(40, min(SysMgr.ttyCols, SysMgr.lineLength))
        LABEL = 7
        STATS = 30  # "cur:XX.X%     max:XX.X%"
        GRAPH = max(10, width - LABEL - STATS - 3)  # -3: space×2 + '|'
        BLOCKS = "\u2581\u2582\u2583\u2584\u2585\u2586\u2587\u2588"

        def _fmt(val):
            return "%.1f%%" % val

        metrics = []
        for cid in sorted(perCore.keys(), key=lambda x: int(x)):
            cdata = perCore[cid] or {}
            v = float(cdata.get("total", 0) or 0)
            label = "C%s" % cid  # "C0" .. "C7"
            metrics.append((label, v, _fmt(v)))

        if not metrics:
            return

        for label, val, _ in metrics:
            key = "CPU_" + label
            if key not in SysMgr.graphHistory:
                SysMgr.graphHistory[key] = deque(maxlen=SysMgr.lineLength)
            SysMgr.graphHistory[key].append(val)

        SysMgr.addPrint("%s\n" % twoLine)

        i = 0
        for label, cur_val, cur_str in metrics:
            i += 1
            key = "CPU_" + label
            hist = SysMgr.graphHistory.get(key)
            if not hist:
                continue

            # CPU% is always 0-100 (fixed scale) #
            scale = 100.0

            hist_vals = list(hist)
            v_min = min(hist_vals)
            v_max = max(hist_vals)
            v_avg = sum(hist_vals) / len(hist_vals)

            top_stats = (
                "cur:%-12s max:%s" % (_fmt(cur_val), _fmt(v_max))
            ).ljust(STATS)
            bot_stats = (
                "min:%-12s avg:%s" % (_fmt(v_min), _fmt(v_avg))
            ).ljust(STATS)

            hist_slice = hist_vals[-GRAPH:]

            # render 2 rows: top = upper half of 0-100, bot = lower half #
            half = scale / 2.0
            top_row = []
            bot_row = []
            for v in hist_slice:
                v = float(v)
                top_ratio = min(1.0, max(0.0, (v - half) / half))
                top_row.append(
                    BLOCKS[int(top_ratio * 7.999)] if v > half else " "
                )
                bot_ratio = min(1.0, max(0.0, v / half))
                bot_row.append(BLOCKS[int(bot_ratio * 7.999)])

            top_str = "".join(top_row).ljust(GRAPH)
            bot_str = "".join(bot_row).ljust(GRAPH)

            SysMgr.addPrint(
                "%-7s %s %s|\n" % (label[:7], top_str[:GRAPH], top_stats)
            )
            SysMgr.addPrint(
                "%-7s %s %s|\n" % (" " * 7, bot_str[:GRAPH], bot_stats)
            )
            if i != len(metrics):
                SysMgr.addPrint("%s\n" % oneLine)

    @staticmethod
    def getCutMargin(newline=0):
        return (
            SysMgr.ttyRows
            - SysMgr.ttyRowsMargin
            - (SysMgr.bufferRows + newline)
        )

    @staticmethod
    def checkCutCond(newline=0, more=True):
        if SysMgr.terminalOver:
            return True
        elif (
            not SysMgr.outPath
            and (not SysMgr.jsonEnable or SysMgr.liveGraphEnable)
            and not SysMgr.streamEnable
            and SysMgr.bufferRows + newline
            >= SysMgr.ttyRows - SysMgr.ttyRowsMargin
        ):
            SysMgr.terminalOver = True
            if more:
                SysMgr.addPrint("---more---", force=True)
            return True
        else:
            return False

    @staticmethod
    def updateTimer(interval=None):
        if not SysMgr.isLinux:
            return

        try:
            if interval:
                signal.alarm(long(interval))
            else:
                signal.alarm(SysMgr.intervalEnable)
        except SystemExit:
            sys.exit(0)
        except:
            SysMgr.printErr("failed to set interval timer", reason=True)
            sys.exit(-1)

    @staticmethod
    def setReportPathForm(outPath):
        repFileName = SysMgr.environList.get("REPFILEFORM")
        if not repFileName:
            return False
        elif not os.path.isdir(outPath):
            return False

        SysMgr.updateNrRun(outPath)
        cmd = sys.argv[1] if len(sys.argv) > 1 else None
        repSuffix = repFileName[0] if repFileName[0] != "SET" else None
        SysMgr.setReportPath(outPath, sys.argv[1], repSuffix)

        return True

    @staticmethod
    def makeOutPath(func):
        if not SysMgr.outPath:
            SysMgr.outPath = "."

        ret = SysMgr.setReportPathForm(SysMgr.outPath)
        if not ret:
            SysMgr.updateOutPath()
            SysMgr.outPath = SysMgr.inputFile

        if SysMgr.inputParam:
            return SysMgr.inputParam
        else:
            append = "." + func
            if SysMgr.inputFile.endswith(append):
                return SysMgr.inputFile
            else:
                return SysMgr.inputFile + append

    @staticmethod
    def buildReportFilename(
        nrReport, uptime, event, cmd, timeinfo, nrRun=None
    ):
        """Shared guider_<nrRun>_<nrReport>_<uptime>_<event>_<cmd>_<timeinfo>.out
        naming formula, used by both setReportPath (SAVE-family reports) and
        TaskAnalyzer._writeLLMReport (ASKAI/ASKRUN #SAVE reports) so the two
        report kinds stay structurally identical instead of duplicating the
        format string in two places."""
        return "guider_%05d_%05d_%s_%s_%s_%s.out" % (
            SysMgr.nrRun if nrRun is None else nrRun,
            nrReport,
            uptime,
            event or "CUSTOM",
            cmd,
            timeinfo,
        )

    @staticmethod
    def setReportPath(outPath, cmd, event=None):
        timeinfo = UtilMgr.getTime("UTCTIME" in SysMgr.environList) or long(
            SysMgr.uptime
        )

        if outPath:
            pathList = outPath.split("+")
            outPath = pathList[0].strip()
            if len(pathList) > 1:
                for p in pathList[1:]:
                    SysMgr.addEnvironVar("DUPOUTPATH", p.strip())

        if outPath:
            isdir = os.path.isdir(outPath)
            outPathStr = outPath.rstrip("/") + "/" if isdir else ""
            SysMgr.printInfo("set output path to '%s'" % outPathStr)

            if isdir:
                targetDir = outPath
            else:
                targetDir = "."
                SysMgr.outPath = outPath
                return
        elif not SysMgr.outPath:
            SysMgr.printErr("no output path for report")
            return
        elif SysMgr.outPath == SysMgr.nullPath:
            targetDir = SysMgr.tmpPath
        elif os.path.isdir(SysMgr.outPath):
            targetDir = SysMgr.outPath
        else:
            targetDir = os.path.dirname(SysMgr.outPath)

        SysMgr.outPath = "%s/%s" % (
            targetDir,
            SysMgr.buildReportFilename(
                SysMgr.nrReport,
                SysMgr.getUptime(conv=True).replace(":", ""),
                event,
                cmd.replace(":", ""),
                timeinfo,
            ),
        )

    @staticmethod
    def updateOutPath():
        if SysMgr.outPath and (
            os.path.isdir(SysMgr.outPath)
            or (
                "MKOUTDIR" in SysMgr.environList
                and not os.path.exists(SysMgr.outPath)
            )
        ):
            if "MKOUTDIR" in SysMgr.environList:
                SysMgr.mkdirs(SysMgr.outPath)

            SysMgr.inputFile = os.path.join(SysMgr.outPath, SysMgr.outFilePath)
        else:
            SysMgr.inputFile = SysMgr.outPath

        if not SysMgr.inputFile:
            return

        SysMgr.inputFile = os.path.realpath(SysMgr.inputFile)

        if not FileAnalyzer.isValidFile(SysMgr.inputFile, isAbs=False):
            return

        if SysMgr.fileSuffix:
            dirname, filename = UtilMgr.getPath(SysMgr.inputFile)
            name, ext = os.path.splitext(filename)
            filepath = os.path.join(dirname, name)
            SysMgr.inputFile = "%s_%s%s" % (filepath, SysMgr.fileSuffix, ext)

        if not SysMgr.termFlag:
            SysMgr.inputFile = "%s_%s" % (
                SysMgr.inputFile,
                SysMgr.getRuntime(),
            )

    @staticmethod
    def setDefaultOutPath():
        if (
            SysMgr.inputFile
            and SysMgr.outPath
            and os.path.isdir(SysMgr.outPath)
            and "NOMERGE" not in SysMgr.environList
        ):
            SysMgr.outPath = os.path.join(
                SysMgr.outPath, SysMgr.inputFile + ".out"
            )

    @staticmethod
    def sendOutput2Nodes(line, force=False):
        if not SysMgr.addrListForPrint:
            return
        elif not line:
            return
        else:
            optList = [x[0] for x in SysMgr.optionList if x]
            if not force and "X" in optList and "N" in optList:
                return

        hostname = SysMgr.environList.get("HOSTNAME", ["ANON"])[0]
        line = SysMgr.magicStr + hostname + SysMgr.magicStr + line

        addrListForPrint = dict(SysMgr.addrListForPrint)
        for addr, cli in addrListForPrint.items():
            udpSeg = 65507  # maximum UDP datagram size
            start = 0
            end = udpSeg
            while 1:
                if len(line) >= end:
                    pos = line[start:end].rfind("\n")
                    if pos > 0:
                        end = pos + start

                ret = cli.send(line[start:end])
                if not ret:
                    del SysMgr.addrListForPrint[addr]
                    break
                else:
                    cli.ignore += 1

                if end >= len(line):
                    break

                start = end
                end += udpSeg

    @staticmethod
    def printStr(string):
        print(string)

    @staticmethod
    def printPipe(
        line="",
        newline=True,
        flush=False,
        pager=True,
        trim=True,
        colorCtl=True,
        force=False,
    ):
        if SysMgr.loggingEnable:
            SysMgr.printLog(line)

        SysMgr.sendOutput2Nodes(line)

        if not SysMgr.printEnable:
            return

        if isinstance(line, list):
            if not line:
                line = ""
            elif line[0] and line[0][-1] == "\n":
                line = "".join(line)
            else:
                line = "\n".join(line)

        if (
            not pager
            or SysMgr.pipeForPager
            or SysMgr.outPath
            or SysMgr.streamEnable
            or SysMgr.jsonEnable
            or SysMgr.checkMode("hserver")
        ):
            pass
        elif not SysMgr.isTopMode() or SysMgr.isHelpMode():
            try:
                if SysMgr.isPosixOS():
                    if "LESS" in SysMgr.environList:
                        ecmd = "%s %s %s" % (
                            SysMgr.getExeName(os.getpid()),
                            SysMgr.getPyPath(),
                            "less",
                        )

                        envLogo = os.getenv("LOGO")
                        os.putenv("LOGO", "0")
                        os.putenv("LESSPIPE", "1")

                        SysMgr.pipeForPager = os.popen(ecmd, "w")
                        SysMgr.setPipeSize(SysMgr.pipeForPager)
                        SysMgr.ttyRows = sys.maxsize

                        os.putenv("LOGO", envLogo if envLogo else "")
                        os.putenv("LESSPIPE", "")
                    elif UtilMgr.which("less"):
                        defopt = "-FRXMQi"

                        SysMgr.setSignal(signal.SIGCHLD, signal.SIG_DFL)

                        ret = os.popen(
                            "echo | less %s 2>&1" % defopt, "r"
                        ).read()
                        if len(ret) <= 1:
                            poption = "less %s" % defopt
                        else:
                            poption = "less"

                        SysMgr.pipeForPager = os.popen(poption, "w")

                        SysMgr.setDefaultSignal()
                    elif UtilMgr.which("more"):
                        SysMgr.pipeForPager = os.popen("more", "w")
                elif SysMgr.platform.startswith("win"):
                    try:
                        SysMgr.pipeForPager = os.popen("more", "w")
                    except SystemExit:
                        sys.exit(0)
                    except:
                        pass
                else:
                    SysMgr.pipeForPager = None

                SysMgr.encodeEnable = False

                SysMgr.setPipeHandler()
            except SystemExit:
                sys.exit(0)
            except:
                SysMgr.printWarn("failed to use pager", True, reason=True)

        if SysMgr.pipeForPager and not SysMgr.jsonEnable:
            try:
                if line:
                    SysMgr.pipeForPager.write(line)

                    if newline and line[-1] != "\n":
                        SysMgr.pipeForPager.write("\n")

                return
            except BrokenPipeError:
                try:
                    SysMgr.pipeForPager.close()
                except SystemExit:
                    sys.exit(0)
                except:
                    pass
                SysMgr.pipeForPager = None
                sys.exit(0)
            except SystemExit:
                sys.exit(0)
            except:
                SysMgr.printErr("failed to print to pager\n", True)
                SysMgr.pipeForPager = None

        if SysMgr.outPath and not SysMgr.printFd:
            if SysMgr.isRuntimeMode():
                SysMgr.updateOutPath()
            else:
                if os.path.isdir(SysMgr.outPath) or (
                    "MKOUTDIR" in SysMgr.environList
                    and not os.path.exists(SysMgr.outPath)
                ):
                    if "MKOUTDIR" in SysMgr.environList:
                        SysMgr.mkdirs(SysMgr.outPath)

                    name, ext = os.path.splitext(
                        os.path.basename(SysMgr.inputFile)
                    )
                    if ext != ".out":
                        name = "%s.out" % name
                    SysMgr.inputFile = os.path.join(SysMgr.outPath, name)
                else:
                    SysMgr.inputFile = SysMgr.outPath

            SysMgr.inputFile = os.path.normpath(SysMgr.inputFile)

            if SysMgr.compressEnable:
                if not SysMgr.inputFile.endswith(".gz"):
                    SysMgr.inputFile += ".gz"
                if SysMgr.outPath and not SysMgr.outPath.endswith(".gz"):
                    SysMgr.outPath += ".gz"

            SysMgr.lastReportPath = SysMgr.inputFile

            SysMgr.backupFile(SysMgr.inputFile)

            try:
                try:
                    os.chmod(SysMgr.inputFile, 0o666)
                except SystemExit:
                    sys.exit(0)
                except:
                    pass

                SysMgr.printFd = open(SysMgr.inputFile, "wb")

                try:
                    fmod = SysMgr.environList.get("OUTFILEPERM")
                    if not fmod:
                        raise SyntaxWarning()
                    fmod = long(fmod[0], 8)
                    os.chmod(SysMgr.inputFile, fmod)
                except SyntaxWarning:
                    pass
                except SystemExit:
                    sys.exit(0)
                except:
                    SysMgr.printWarn(
                        "failed to change the perm of '%s' to %s"
                        % (SysMgr.inputFile, fmod),
                        reason=True,
                    )

                try:
                    fusers = SysMgr.environList.get("OUTFILEUSER")
                    if not fusers:
                        raise SyntaxWarning()
                    fusers = fusers[0].split(":", 1)
                    if len(fusers) == 1:
                        fuser = fusers[0]
                        fgroup = None
                    else:
                        fuser, fgroup = fusers

                    if not SysMgr.sysInstance:
                        SysMgr(onlyInstance=True)
                    SysMgr.sysInstance.saveUserInfo()

                    fuser = long(SysMgr.sysInstance.getUserId(fuser))
                    if fgroup:
                        fgroup = long(SysMgr.sysInstance.getUserId(fgroup))

                    os.chown(SysMgr.inputFile, fuser, fgroup)
                except SyntaxWarning:
                    pass
                except SystemExit:
                    sys.exit(0)
                except:
                    SysMgr.printWarn(
                        "failed to change the owner of '%s' to %s"
                        % (SysMgr.inputFile, fusers),
                        reason=True,
                    )

                if SysMgr.compressEnable:
                    compressor = SysMgr.getPkg("gzip", False)
                    if compressor:
                        SysMgr.printFd = compressor.GzipFile(
                            mode="wb", fileobj=SysMgr.printFd
                        )

                if SysMgr.outPath:
                    SysMgr.printInfo(
                        "start writing output to '%s'" % SysMgr.inputFile
                    )
            except SystemExit:
                sys.exit(0)
            except:
                SysMgr.printOpenErr(SysMgr.inputFile)
                sys.exit(-1)

        if SysMgr.printFd:
            try:
                if line:
                    SysMgr.printFd.write(line.encode("utf-8"))

                    if newline and line[-1] != "\n":
                        SysMgr.printFd.write("\n".encode("utf-8"))

                if flush:
                    SysMgr.printFd.flush()
            except SystemExit:
                sys.exit(0)
            except:
                SysMgr.printErr(
                    (
                        "failed to write to %s" % SysMgr.printFd.name
                        if hasattr(SysMgr.printFd, "name")
                        else "N/A"
                    ),
                    True,
                )
        else:
            if trim:
                cols = SysMgr.ttyCols
            else:
                cols = 0

            if SysMgr.colorEnable and not SysMgr.jsonEnable:
                try:
                    line = ConfigMgr.ENDC + line
                except SystemExit:
                    sys.exit(0)
                except:
                    line = "%s%s" % (ConfigMgr.ENDC, line)

            try:
                if cols == 0 or SysMgr.jsonEnable:
                    line = "\n".join([nline for nline in line.split("\n")])
                elif (
                    not SysMgr.absColorEnable
                    and SysMgr.colorEnable
                    and ConfigMgr.ENDC in line
                    and colorCtl
                ):
                    if not SysMgr.ansiObj:
                        UtilMgr.removeColor("")
                    ansiObj = SysMgr.ansiObj

                    def _ansi_trunc(s, maxv, _re=ansiObj):
                        out = []
                        vis = 0
                        i = 0
                        while i < len(s):
                            m = _re.match(s, i)
                            if m:
                                out.append(m.group())
                                i = m.end()
                            elif vis < maxv:
                                out.append(s[i])
                                vis += 1
                                i += 1
                            else:
                                break
                        return "".join(out)

                    line = "\n".join(
                        [
                            (
                                _ansi_trunc(n, cols)
                                if len(ansiObj.sub("", n)) > cols
                                else n
                            )
                            for n in line.split("\n")
                        ]
                    )
                else:
                    line = "\n".join(
                        [nline[: cols - 1] for nline in line.split("\n")]
                    )
            except SystemExit:
                sys.exit(0)
            except:
                SysMgr.printWarn("failed to print to console", reason=True)
                return

            nline = SysMgr.convExtAscii(line)

            try:
                sys.stdout.write(nline)
            except UnicodeEncodeError:
                enc = getattr(sys.stdout, "encoding", None) or "ascii"
                sys.stdout.write(
                    nline.encode(enc, errors="replace").decode(enc)
                )
            except SystemExit:
                sys.exit(0)
            except:
                try:
                    if not SysMgr.encodeEnable:
                        raise Exception()
                    SysMgr.encodeEnable = False
                    sys.stdout.write(line)
                except SystemExit:
                    sys.exit(0)
                except:
                    pass

            if newline:
                try:
                    sys.stdout.write("\n")
                except SystemExit:
                    sys.exit(0)
                except:
                    pass
                SysMgr.newlined = True
            else:
                SysMgr.newlined = False

            if flush or SysMgr.remoteRun:
                try:
                    sys.stdout.flush()
                except SystemExit:
                    sys.exit(0)
                except:
                    pass

    @staticmethod
    def convExtAscii(line, reverse=False):
        # pylint: disable=no-member,undefined-variable
        if not SysMgr.encodeEnable and not reverse:
            return line

        try:
            if not reverse:
                newline = line.replace("-------", "───────")
                newline = newline.replace("=", "═")
                newline = newline.replace("|-", "├─")
                newline = newline.replace("|", "│")
            else:
                newline = line.replace("───────", "-------")
                newline = newline.replace("═", "=")
                newline = newline.replace("├─", "|-")
                newline = newline.replace("│", "|")

            if sys.version_info < (3, 0) and not SysMgr.encoding:
                if not sys.getdefaultencoding().lower().startswith("utf"):
                    try:
                        reload(sys)
                        sys.setdefaultencoding("utf-8")
                        SysMgr.encoding = sys.getdefaultencoding()
                    except:
                        pass

            return newline
        except:
            SysMgr.encodeEnable = False
            return line

    @staticmethod
    def printLog(log, level="INFO"):
        if SysMgr.dltEnable:
            DltAnalyzer.doLogDlt(msg=log, level=level)
        if SysMgr.kmsgEnable:
            LogMgr.doLogKmsg(msg=log)
        if SysMgr.syslogEnable:
            LogMgr.doLogSyslog(msg=log)
        if SysMgr.journalEnable:
            LogMgr.doLogJournal(msg=log)
        if SysMgr.andlogEnable:
            LogMgr.doLogAndroid(msg=log)

    @staticmethod
    def printWarn(line, always=False, reason=False, newline=True, code=False):
        # uncomment to print backtrace for debugging #

        if (
            not line
            or not SysMgr.logEnable
            or (not SysMgr.warnEnable and not always)
        ):
            return

        if reason:
            rstring = " because %s" % SysMgr.getErrMsg()
        elif code:
            rstring = " because %s" % SysMgr.getErrReason()
        else:
            rstring = ""

        proc = SysMgr.getProcInfo()

        log = "%s%s%s%s" % ("[WARN] ", proc, line, rstring)

        if SysMgr.loggingOpsEnable:
            SysMgr.printLog(log, level="WARN")

        log = "\n%s" % (
            UtilMgr.convColor(log, "WARNING", force=not SysMgr.remoteRun)
        )

        if newline:
            log = "%s\n" % log

        if SysMgr.stdlog:
            SysMgr.stdlog.write(log)

        if "REMOTERUN" in os.environ:
            print(log.replace("\n", ""))
        else:
            SysMgr.writeErr(SysMgr.stderr, log)

    @staticmethod
    def printErr(line, reason=False, code=False, newline=True):
        # uncomment to print backtrace for debugging #

        if line:
            SysMgr.errorOccurred = True

        if not SysMgr.logEnable and SysMgr.forceEnable:
            return
        elif not line:
            return

        SysMgr.flushAllForPrint()

        if reason:
            rstring = " because %s" % SysMgr.getErrMsg()
        elif code:
            rstring = " because %s" % SysMgr.getErrReason()
        else:
            rstring = ""

        try:
            line = line.rstrip("\n")
        except SystemExit:
            sys.exit(0)
        except:
            pass

        proc = SysMgr.getProcInfo()

        log = "%s%s%s%s" % ("[ERROR] ", proc, line, rstring)

        if SysMgr.loggingOpsEnable:
            SysMgr.printLog(log, level="ERROR")

        newline = "\n" if newline else ""

        log = "\n%s%s" % (
            UtilMgr.convColor(log, "FAIL", force=not SysMgr.remoteRun),
            newline,
        )

        try:
            SysMgr.stdlog.write(log)
        except SystemExit:
            sys.exit(0)
        except:
            pass

        if SysMgr.remoteRun:
            print(log.replace("\n", ""))
        else:
            SysMgr.writeErr(SysMgr.stderr, log)

    @staticmethod
    def getTaskStr(pid, cache=False, save=False, commCache=True):
        return "%s(%s)" % (
            SysMgr.getComm(pid, cache=cache, save=save, commCache=commCache),
            pid,
        )

    @staticmethod
    def getProcInfo(pid=None):
        if pid:
            return "<%s> " % SysMgr.getTaskStr(pid)
        else:
            if SysMgr.parentPid > 0:
                return "<%s(%s)> " % (SysMgr.comm, SysMgr.pid)
            else:
                return ""

    @staticmethod
    def printInfo(line, prefix=True, suffix=True, title=True, color=True):
        if not SysMgr.logEnable or not line:
            return

        if title:
            title = "[INFO] "
            proc = SysMgr.getProcInfo()
        else:
            title = ""
            proc = ""

        if prefix:
            prefix = "\n"
        else:
            prefix = ""

        if not SysMgr.newlined:
            prefix += "\n"
            SysMgr.newlined = True

        log = "%s%s%s" % (title, proc, line)

        if SysMgr.loggingOpsEnable:
            SysMgr.printLog(log)

        log = UtilMgr.convColor(
            log, "BOLD", force=not bool(SysMgr.remoteRun or not color)
        )
        try:
            log = prefix + log
        except SystemExit:
            sys.exit(0)
        except:
            log = "%s%s" % (prefix, log)

        try:
            SysMgr.stdlog.write(log)
        except SystemExit:
            sys.exit(0)
        except:
            pass

        out = sys.__stderr__ if SysMgr.jsonEnable else sys.stdout
        if suffix:
            try:
                print(log, file=out)
                out.flush()
            except SystemExit:
                sys.exit(0)
            except:
                return
        else:
            try:
                out.write(log)
                out.flush()
            except SystemExit:
                sys.exit(0)
            except:
                SysMgr.printErr("failed to flush stdout", reason=True)

    @staticmethod
    def printGood(line):
        if not SysMgr.logEnable or not line:
            return

        proc = SysMgr.getProcInfo()

        log = "%s%s%s" % ("[INFO] ", proc, line)
        log = "\n%s" % (
            UtilMgr.convColor(log, "OKGREEN", force=not SysMgr.remoteRun)
        )

        if SysMgr.stdlog:
            SysMgr.stdlog.write(log)

        out = sys.__stderr__ if SysMgr.jsonEnable else sys.stdout
        print(log, file=out)
        out.flush()

    @staticmethod
    def printLine(line):
        if not SysMgr.logEnable:
            return

        proc = SysMgr.getProcInfo()

        log = "%s%s" % (proc, line)
        log = "\n%s" % (
            UtilMgr.convColor(log, "UNDERLINE", force=not SysMgr.remoteRun)
        )

        if SysMgr.stdlog:
            SysMgr.stdlog.write(log)

        print(log)

    @staticmethod
    def printStat(line):
        if not SysMgr.logEnable or not line:
            return

        proc = SysMgr.getProcInfo()

        log = "%s%s%s" % ("[STEP] ", proc, line)

        if SysMgr.loggingOpsEnable:
            SysMgr.printLog(log)

        log = "\n%s" % (
            UtilMgr.convColor(log, "SPECIAL", force=not SysMgr.remoteRun)
        )

        if SysMgr.stdlog:
            SysMgr.stdlog.write(log)

        print(log)

    @staticmethod
    def isValidRequest(request):
        try:
            if request.startswith("EVENT_"):
                pass
            elif TaskAnalyzer.requestType.index(request):
                pass
            else:
                raise Exception("wrong request")

            return True
        except SystemExit:
            sys.exit(0)
        except:
            return False

    @staticmethod
    def printOpenErr(path, reason=True):
        SysMgr.printErr("failed to open '%s'" % os.path.realpath(path), reason)

    @staticmethod
    def printOpenWarn(path, always=False, reason=True):
        SysMgr.printWarn(
            "failed to open '%s'" % os.path.realpath(path), always, reason
        )

    @staticmethod
    def addOption(option):
        if not SysMgr.optionList:
            SysMgr.parseOption()

        if not isinstance(SysMgr.optionList, list):
            return

        if option not in SysMgr.optionList:
            SysMgr.optionList.append(option)

    @staticmethod
    def parseOption(option=None, save=True):
        if "ISMAIN" not in os.environ:
            return

        if not option and SysMgr.optionList:
            return

        parsedOpt = []
        prevIdx = 0

        if option:
            optList = [sys.argv[1]] + option
        else:
            optList = sys.argv[1:]

        for idx, opt in enumerate(optList):
            if opt.startswith("-"):
                parsedOpt.append(" ".join(optList[prevIdx:idx])[1:])
                prevIdx = idx
        parsedOpt.append(" ".join(optList[prevIdx:])[1:])

        optionList = parsedOpt[1:]
        if save:
            SysMgr.optionList = optionList

        usedOpt = {}
        for opt in optionList:
            try:
                if opt[0] not in usedOpt or opt[0] == "-":
                    usedOpt[opt[0]] = True
                    continue
            except:
                continue

            SysMgr.printErr(
                "wrong -%s option because of redundant use" % opt[0]
            )
            sys.exit(-1)

        return optionList

    @staticmethod
    def findOption(option):
        if "ISMAIN" not in os.environ:
            return

        if len(sys.argv) <= 2 and not SysMgr.optionList:
            return False

        SysMgr.parseOption()

        option = set(option)
        for item in SysMgr.optionList:
            if item == "":
                pass
            elif set(item[0]) & option:
                return True

        return False

    @staticmethod
    def getOption(option):
        if "ISMAIN" not in os.environ:
            return

        if len(sys.argv) <= 2 and not SysMgr.optionList:
            return None

        SysMgr.parseOption()

        for item in SysMgr.optionList:
            if item and item[0] == option and len(item) > 1:
                return item[1:].strip()

        return None

    @staticmethod
    def parseRuntimeOption(value):
        SysMgr.countEnable = True
        convNum = UtilMgr.convNum
        convTime = UtilMgr.convUnit2Time

        if value:
            repeatParams = UtilMgr.cleanItem(value.split(":"), False)

        if SysMgr.getOption("i"):
            applyInterval = False
        else:
            applyInterval = True

        if not value:
            if applyInterval:
                SysMgr.intervalEnable = 1
            SysMgr.repeatCnt = 1
            repeatParams = None
        elif len(repeatParams) in (2, 3):
            try:
                interval = SysMgr.getOption("i")
                if interval:
                    interval = long(interval)
                else:
                    interval = convTime(repeatParams[0])

                if applyInterval:
                    SysMgr.intervalEnable = interval
                SysMgr.repeatInterval = interval

                cnt = repeatParams[1]
                if not cnt:
                    SysMgr.repeatCnt = sys.maxsize
                elif cnt.isdigit():
                    SysMgr.repeatCnt = long(cnt)
                else:
                    SysMgr.repeatCnt = long(convTime(cnt) / interval)
            except SystemExit:
                sys.exit(0)
            except:
                SysMgr.printErr(
                    (
                        "wrong value for runtime option because %s, "
                        "input integer values"
                    )
                    % SysMgr.getErrMsg()
                )
                sys.exit(-1)
        elif len(repeatParams) == 1:
            try:
                interval = long(convTime(repeatParams[0]))

                if SysMgr.isTopMode():
                    ival = SysMgr.getOption("i")
                    if ival:
                        ival = long(ival)
                        interval = long(interval / ival)
                        SysMgr.repeatCnt = interval
                        SysMgr.repeatInterval = interval
                        if applyInterval:
                            SysMgr.intervalEnable = ival
                    else:
                        SysMgr.repeatCnt = interval
                        SysMgr.repeatInterval = interval
                        if applyInterval:
                            SysMgr.intervalEnable = 1
                else:
                    SysMgr.repeatCnt = 1
                    SysMgr.repeatInterval = interval
                    if applyInterval:
                        SysMgr.intervalEnable = interval
            except SystemExit:
                sys.exit(0)
            except:
                SysMgr.printErr(
                    (
                        "wrong value for runtime option because %s, "
                        "input integer values"
                    )
                    % SysMgr.getErrMsg()
                )
                sys.exit(-1)
        else:
            SysMgr.printErr(
                (
                    "wrong value for runtime option because %s, "
                    "input in the format INTERVAL:REPEAT"
                )
                % SysMgr.getErrMsg()
            )
            sys.exit(-1)

        _i_set = bool(SysMgr.getOption("i"))
        if (
            not _i_set
            and (not SysMgr.intervalEnable or SysMgr.intervalEnable < 1)
        ) or SysMgr.repeatCnt < 1:
            SysMgr.printErr(
                "wrong value for runtime option, input values bigger than 0"
            )
            sys.exit(-1)

        try:
            if SysMgr.intervalEnable == sys.maxsize:
                SysMgr.intervalEnable = SysMgr.maxSize
            if SysMgr.repeatInterval == sys.maxsize:
                SysMgr.repeatInterval = SysMgr.maxSize
        except SystemExit:
            sys.exit(0)
        except:
            SysMgr.printErr(
                (
                    "wrong value for interval option because %s, "
                    "input integer value"
                )
                % SysMgr.getErrMsg()
            )
            sys.exit(-1)

        if SysMgr.checkMode("req"):
            pass
        elif repeatParams and len(repeatParams) == 3:
            SysMgr.termFlag = False
            if not SysMgr.jsonEnable and "-J" not in sys.argv:
                SysMgr.printInfo(
                    "run every %s sec %s time"
                    % (
                        convNum(SysMgr.intervalEnable),
                        convNum(SysMgr.repeatCnt),
                    )
                )
        else:
            if not SysMgr.jsonEnable and "-J" not in sys.argv:
                interval = SysMgr.intervalEnable
                repeat = SysMgr.repeatCnt
                totalSec = convNum(interval)
                totalCnt = convNum(repeat)
                totalTime = convNum(long(interval * repeat))
                SysMgr.printInfo(
                    "run only %s times in %s sec for a total of %s sec"
                    % (totalCnt, totalSec, totalTime)
                )

    @staticmethod
    def reloadFileBuffer(path=None, retFd=False, fd=None):
        # pylint: disable=no-member
        SysMgr.clearProcBuffer()

        try:
            if path or fd:
                pass
            elif SysMgr.printFd:
                path = SysMgr.printFd.name

                try:
                    SysMgr.printFd.close()
                    SysMgr.printFd = None
                except:
                    pass

                SysMgr.outPath = SysMgr.origOutPath

                path = SysMgr.backupFile(path)
            else:
                SysMgr.printErr(
                    "failed to reload monitoring data "
                    "because there is no target file"
                )
                return []

            if not fd:
                fd = SysMgr.getCompFd(path) or open(path, "r")

            if retFd:
                return fd

            buf = fd.read()

            buf = UtilMgr.safeDecode(buf)
        except SystemExit:
            sys.exit(0)
        except:
            SysMgr.printOpenErr(path)
            return None if retFd else []

        # split each interval stats #
        try:
            buf = buf.replace("\n\n", "NEWSTAT\n\n")
            if "CLEANCHAR" in SysMgr.environList:
                buf = buf.replace("[Top Info] ", "NEWSTAT[Top Info] ")

            SysMgr.procBuffer = buf.split("NEWSTAT")

            if not path:
                SysMgr.printFd.seek(0, 0)
                SysMgr.printFd.truncate()
        except SystemExit:
            sys.exit(0)
        except:
            pass

        return SysMgr.procBuffer

    @staticmethod
    def addEnvironVar(names, value="SET"):
        if not isinstance(names, list):
            names = [names]

        for name in names:
            SysMgr.environList.setdefault(name, [])
            if isinstance(value, list):
                SysMgr.environList[name] += value
            elif SysMgr.environList[name] and value == "SET":
                pass
            else:
                SysMgr.environList[name].append(value)

    _reFilterCache = {}

    @staticmethod
    def checkLogCond(log, cond, refilter=False):
        try:
            if not cond:
                return
            elif refilter:
                cache = SysMgr._reFilterCache
                compiled = []
                for c in cond:
                    if c not in cache:
                        try:
                            cache[c] = re.compile(c)
                        except:
                            cache[c] = None
                    compiled.append(cache[c])
                if not all([r and r.match(log) for r in compiled]):
                    return
            elif not UtilMgr.isValidStr(log, cond):
                return
            elif "EVENT_CMD_NOTIFY:log_" in log:
                return

            SysMgr.printWarn(
                "detected '%s' in %s" % (", ".join(cond), [log]), True
            )

            LogMgr.doLogKmsg(msg=UtilMgr.removeColor(log))

            if "WATCHLOGCMD" in SysMgr.environList:
                args = SysMgr.environList["WATCHLOGCMD"]
                SysMgr.executeCommand(args)

            # check exit condition: terminate directly via os._exit() rather
            # than via SIGINT+signal.pause() — SysMgr.stopHandler() (bound
            # to SIGINT in this mode) treats a single SIGINT as an
            # interactive "show a checkpoint, keep running" request and
            # only actually calls os._exit() on a LATER signal, so a lone
            # self-delivered SIGINT here reliably failed to terminate the
            # process at all (device-verified: the watcher kept running and
            # re-firing this same command on every later matching event
            # instead of exiting once, as "oneshot"-style callers of
            # WATCHLOGEXIT expect). Deliberately skip SysMgr.doExit() here:
            # it calls killChildren(), which defaults to SIGKILL-ing every
            # child of this process — including the "GUIDER event ..."
            # notifier just spawned (and already awaited) a few lines above
            # by executeCommand()/os.wait(). That wait() call isn't scoped
            # to the specific notifier pid, so on a system with any other
            # short-lived child in flight it can return as soon as ANY
            # child exits; a subsequent doExit() then has a real chance of
            # SIGKILLing the still-starting notifier before it sends its
            # event, silently dropping the very notification this watcher
            # exists to deliver (device-verified: this raced away the
            # "GUIDER event" UDP send often enough that the parent ctop
            # process never saw the event or ran the configured SAVE
            # command). The OS reclaims this process's fds (including any
            # BPF program/map/perf_event fds) on exit regardless of which
            # exit path is used, so no extra cleanup is needed here #
            if "WATCHLOGEXIT" in SysMgr.environList:
                os._exit(0)
        except SystemExit:
            sys.exit(0)
        except:
            pass

    @staticmethod
    def checkCgroup(manList=()):
        if not manList:
            manList = ("cpu", "cpuacct", "memory", "blkio")
        elif UtilMgr.isString(manList):
            manList = set(
                [
                    manList,
                ]
            )

        cgroupInfo = SysMgr.printCgroupList(json=True, ret=True)
        subList = list(set(manList) - set(list(cgroupInfo)))
        if subList:
            SysMgr.printWarn(
                "no subsystem support for [%s]" % ", ".join(subList), True
            )
            return False

        ret = True
        for sub, values in cgroupInfo.items():
            if sub in subList or sub not in manList:
                continue
            elif not values["mount"]:
                SysMgr.printWarn(
                    "cgroup subsystem [%s] is not mounted, skipping" % sub,
                    True,
                )
                ret = False
        return ret

    @staticmethod
    def applyCgroupVars(varList=[]):
        try:
            if not varList:
                varList = SysMgr.environList

            if "APPLYCG" not in varList:
                return

            cmds = []
            for cmd in varList["APPLYCG"]:
                for item in (
                    "CREATE",
                    "ADD",
                    "MOVE",
                    "REMOVE",
                    "DELETE",
                    "READ",
                    "WRITE",
                    "LIST",
                ):
                    if cmd.upper().startswith(item + ":"):
                        cmds.append(cmd)

            if cmds:
                SysMgr.doCgroup(cmds)
        except SystemExit:
            sys.exit(0)
        except:
            SysMgr.printErr("failed to apply cgroup commands", True)
            sys.exit(-1)

    @staticmethod
    def applyLimitVars(varList=None):
        if varList is None:
            varList = {}
        try:
            if not varList:
                varList = SysMgr.environList

            allPids = []

            for item in (
                "LIMITCPU",
                "LIMITCPUW",
                "LIMITCPUSET",
                "LIMITMEM",
                "LIMITMEMSOFT",
                "LIMITREAD",
                "LIMITWRITE",
                "LIMITPID",
            ):
                if item not in varList:
                    continue

                if item == "LIMITCPU":
                    res = resName = "cpu"
                    default = ["cfs_quota_us", "rt_runtime_us"]
                    mandatory = "cfs_quota_us"
                    func = SysMgr.limitCpu
                elif item == "LIMITCPUW":
                    res = "cpu"
                    resName = "cpu weight"
                    default = ["shares"]
                    mandatory = "shares"
                    func = SysMgr.limitCpuWeight
                elif item == "LIMITCPUSET":
                    res = resName = "cpuset"
                    default = mandatory = "cpus"
                    func = SysMgr.limitCpuset
                elif item in ("LIMITMEM", "LIMITMEMSOFT"):
                    res = resName = "memory"
                    if item == "LIMITMEM":
                        target = "limit_in_bytes"
                    else:
                        target = "soft_limit_in_bytes"
                    default = mandatory = target
                    func = SysMgr.limitMemory
                elif item == "LIMITREAD":
                    res = "blkio"
                    resName = "I/O read"
                    default = "read_bps_device"
                    mandatory = "throttle.read_bps_device"
                    func = SysMgr.limitBlock
                elif item == "LIMITWRITE":
                    res = "blkio"
                    resName = "I/O write"
                    default = "write_bps_device"
                    mandatory = "throttle.write_bps_device"
                    func = SysMgr.limitBlock
                elif item == "LIMITPID":
                    res = resName = "pids"
                    default = "max"
                    mandatory = None
                    func = SysMgr.limitPid
                else:
                    continue

                if not SysMgr.checkCgroup(res):
                    sys.exit(0)

                if mandatory:
                    subPath = SysMgr.getCgroup(res, "/")
                    knobPath = os.path.join(subPath, res + "." + mandatory)
                    knobPath2 = os.path.join(subPath, mandatory)
                    if not os.path.exists(knobPath) and not os.path.exists(
                        knobPath2
                    ):
                        SysMgr.printErr(
                            "no both '%s' and '%s' for %s subsystem"
                            % (knobPath, knobPath2, res)
                        )
                        sys.exit(0)

                for limits in varList[item]:
                    pids = []
                    attrs = []

                    limits = limits.rsplit("@", 1)
                    if len(limits) == 1:
                        limits = limits[0]
                        targets = []
                    else:
                        limits, targets = limits

                    limits = limits.replace("&", ",")

                    for limit in limits.split("+"):
                        values = limit.split(":")
                        if len(values) == 1:
                            name = default
                            val = values[0]
                            if item != "LIMITCPUSET":
                                val = UtilMgr.convUnit2Size(val)
                        elif len(values) == 2:
                            name, val = values
                            if item != "LIMITCPUSET":
                                val = UtilMgr.convUnit2Size(val)
                        else:
                            SysMgr.printErr(
                                "failed to parse '%s' to limit %s"
                                % (item, resName)
                            )
                            sys.exit(-1)

                        if item == "LIMITCPU":
                            # change %-per-sec to ms #
                            if len(values) == 1:
                                unitSize = "%s%%" % val
                                val = long(val) * 10000
                            else:
                                unitSize = UtilMgr.convTime2Unit(val / 1000000)
                        elif item == "LIMITCPUSET":
                            unitSize = val
                        else:
                            unitSize = UtilMgr.convSize2Unit(val)

                        if isinstance(name, list):
                            for subname in name:
                                attrs.append([subname, val])
                        else:
                            attrs.append([name, val])

                        SysMgr.printInfo(
                            "limit %s(%s) to '%s'"
                            % (
                                resName,
                                (
                                    ", ".join(name)
                                    if isinstance(name, list)
                                    else name
                                ),
                                unitSize,
                            )
                        )

                        if targets:
                            pids += SysMgr.getTids(
                                targets,
                                isThread=not SysMgr.processEnable,
                                sibling=SysMgr.groupProcEnable,
                            )
                        else:
                            pids += [str(SysMgr.pid)]

                    pids = list(set(pids))

                    allPids += pids

                    if "EACHTASK" in varList:
                        for pid in pids:
                            func([pid], attrs)
                    else:
                        func(pids, attrs)

            return list(set(allPids))
        except SystemExit:
            sys.exit(0)
        except:
            SysMgr.printErr("failed to apply %s limit values" % resName, True)
            sys.exit(-1)

    @staticmethod
    def runTaskMonitor(pids=[], wait=True, block=False, addOpt=[]):
        if "TASKMON" not in SysMgr.environList:
            return
        elif not pids:
            return

        interval = UtilMgr.getEnvironNum("TASKMON", False, 1, False, True)

        if "TASKFILTER" in SysMgr.environList:
            pids = pids + SysMgr.environList["TASKFILTER"]

        environOption = "-qNOSUMMARY"
        if "TASKMONOPT" in SysMgr.environList:
            monOption = "|".join(SysMgr.environList["TASKMONOPT"]).split("|")
        else:
            monOption = []

            environOption += ",FASTINIT,NOSPECIALTASK"

        enableOption = "-eb"
        startOption = SysMgr.getOption("e")
        if startOption:
            enableOption += startOption
        newMonOption = []
        for m in monOption:
            if m.startswith("-e"):
                enableOption += m[2:]
            else:
                newMonOption.append(m)
        monOption = newMonOption

        if "TASKMONOUT" in SysMgr.environList:
            outPath = SysMgr.environList["TASKMONOUT"][0]
            if outPath == "SET":
                outPath = "."
            outOption = "-o" + outPath
            enableOption += "p"
        else:
            outOption = ""

        SysMgr.environList.pop("TASKMON")

        pid = SysMgr.launchGuider(
            [
                "top",
                "-g%s" % ",".join(pids),
                "-i%s" % interval,
                "-a" if SysMgr.showAll else "",
                "-P" if SysMgr.groupProcEnable else "",
                enableOption,
                environOption,
                "-f",
                "-Q",
                outOption,
            ]
            + addOpt
            + monOption,
            pipe=False,
            stderr=True,
            block=block,
        )

        if wait:
            SysMgr.waitEvent()

        return pid

    @staticmethod
    def applyIgnoreSignals():
        if "IGNORESIGNAL" not in SysMgr.environList:
            return

        if Debugger.ignoreSignals:
            for signum in Debugger.ignoreSignals:
                SysMgr.setSignal(signum, signal.SIG_IGN)
            return

        def _blockSig(signum):
            SysMgr.setSignal(signum, signal.SIG_IGN)

            Debugger.ignoreSignals[signum] = 0

            SysMgr.printInfo("blocked %s" % ConfigMgr.SIG_LIST[signum])

        for sig in SysMgr.environList["IGNORESIGNAL"]:
            try:
                usig = sig.upper()
                if UtilMgr.isNumber(sig):
                    signum = long(sig)
                elif usig in ConfigMgr.SIG_LIST:
                    signum = ConfigMgr.SIG_LIST.index(usig)
                elif "SIG" + usig in ConfigMgr.SIG_LIST:
                    signum = ConfigMgr.SIG_LIST.index("SIG" + usig)
                elif "*" in usig:
                    for i, s in enumerate(ConfigMgr.SIG_LIST):
                        if UtilMgr.isValidStr(s, [usig]):
                            try:
                                _blockSig(i)
                            except SystemExit:
                                sys.exit(0)
                            except:
                                SysMgr.printErr(
                                    "failed to block %s signal" % s, True
                                )
                    continue
                else:
                    raise Exception("no signal")

                _blockSig(signum)
            except SystemExit:
                sys.exit(0)
            except:
                SysMgr.printErr("failed to block %s signal" % sig, True)
                sys.exit(-1)

    @staticmethod
    def checkStartCond():
        exCondList = SysMgr.environList.get("EXSTARTCOND", [])

        while 1:
            successCondList = []
            failCondList = []

            if SysMgr.startCondFile:
                condName = "STARTCONDFILE"
                SysMgr.printStat(
                    "check '%s' files created for start"
                    % ", ".join(SysMgr.startCondFile)
                )
                if any([os.path.exists(f) for f in SysMgr.startCondFile]):
                    successCondList.append(condName)
                else:
                    failCondList.append(condName)

            if SysMgr.startCondNoFile:
                condName = "STARTCONDNOFILE"
                SysMgr.printStat(
                    "check '%s' files removed for start"
                    % ", ".join(SysMgr.startCondNoFile)
                )
                if not any(
                    [os.path.exists(f) for f in SysMgr.startCondNoFile]
                ):
                    successCondList.append(condName)
                else:
                    failCondList.append(condName)

            startCondTask = SysMgr.environList.get("STARTCONDTASK")
            if startCondTask:
                condName = "STARTCONDTASK"
                startCondTask = startCondTask[0]
                SysMgr.printStat(
                    "check '%s' tasks created for start" % startCondTask
                )
                if SysMgr.getTids(startCondTask):
                    successCondList.append(condName)
                else:
                    failCondList.append(condName)

            if SysMgr.startUptime > 0:
                condName = "STARTCONDTIME"
                SysMgr.printStat(
                    "check %s uptime for start"
                    % (UtilMgr.convNum(SysMgr.startUptime))
                )
                if SysMgr.startUptime <= SysMgr.getUptime():
                    successCondList.append(condName)
                else:
                    failCondList.append(condName)

            if not failCondList:
                break
            elif set(successCondList) & set(exCondList):
                return

            time.sleep(1)

        if SysMgr.startCondCpuMore:
            SysMgr.waitForResource(
                cpuRes=SysMgr.startCondCpuMore, cpuCond="MORE"
            )
            if "STARTCONDCPUMORE" in exCondList:
                return

        if SysMgr.startCondCpuLess:
            SysMgr.waitForResource(
                cpuRes=SysMgr.startCondCpuLess, cpuCond="LESS"
            )
            if "STARTCONDCPULESS" in exCondList:
                return

        if SysMgr.startCondMemMore:
            SysMgr.waitForResource(
                memRes=SysMgr.startCondMemMore, memCond="MORE"
            )
            if "STARTCONDMEMMORE" in exCondList:
                return

        if SysMgr.startCondMemLess:
            SysMgr.waitForResource(
                memRes=SysMgr.startCondMemLess, memCond="LESS"
            )
            if "STARTCONDMEMLESS" in exCondList:
                return

        if SysMgr.startCondPsiCpu >= 0:
            SysMgr.printStat(
                "check PSI cpu.some.avg10 > %.1f for start"
                % SysMgr.startCondPsiCpu
            )
            while True:
                try:
                    with open("/proc/pressure/cpu") as _f:
                        for _line in _f:
                            if _line.startswith("some"):
                                _avg10 = float(_line.split()[1].split("=")[1])
                                if _avg10 >= SysMgr.startCondPsiCpu:
                                    break
                        else:
                            time.sleep(1)
                            continue
                    break
                except SystemExit:
                    sys.exit(0)
                except:
                    break
            if "STARTCONDPSICPU" in exCondList:
                return

        if SysMgr.startCondPsiMem >= 0:
            SysMgr.printStat(
                "check PSI memory.some.avg10 > %.1f for start"
                % SysMgr.startCondPsiMem
            )
            while True:
                try:
                    with open("/proc/pressure/memory") as _f:
                        for _line in _f:
                            if _line.startswith("some"):
                                _avg10 = float(_line.split()[1].split("=")[1])
                                if _avg10 >= SysMgr.startCondPsiMem:
                                    break
                        else:
                            time.sleep(1)
                            continue
                    break
                except SystemExit:
                    sys.exit(0)
                except:
                    break
            if "STARTCONDPSIMEM" in exCondList:
                return

        if SysMgr.startCondPsiIO >= 0:
            SysMgr.printStat(
                "check PSI io.some.avg10 > %.1f for start"
                % SysMgr.startCondPsiIO
            )
            while True:
                try:
                    with open("/proc/pressure/io") as _f:
                        for _line in _f:
                            if _line.startswith("some"):
                                _avg10 = float(_line.split()[1].split("=")[1])
                                if _avg10 >= SysMgr.startCondPsiIO:
                                    break
                        else:
                            time.sleep(1)
                            continue
                    break
                except SystemExit:
                    sys.exit(0)
                except:
                    break
            if "STARTCONDPSIIO" in exCondList:
                return

        if SysMgr.startCondLoad1m >= 0:
            SysMgr.printStat(
                "check load1m > %.1f for start" % SysMgr.startCondLoad1m
            )
            while True:
                try:
                    with open("/proc/loadavg") as _lf:
                        load1 = float(_lf.read().split()[0])
                    if load1 >= SysMgr.startCondLoad1m:
                        break
                except SystemExit:
                    sys.exit(0)
                except:
                    break
                time.sleep(1)
            if "STARTCONDLOAD" in exCondList:
                return

        if SysMgr.startCondGpu >= 0:
            SysMgr.printStat(
                "check GPU load > %.1f%% for start" % SysMgr.startCondGpu
            )
            _gpuSysfsPaths = [
                "/sys/class/kgsl/kgsl-3d0/gpu_busy_percentage",
                "/sys/kernel/gpu/gpu_busy_percent",
                "/sys/devices/platform/gpu/utilization",
            ]
            _gpuRetry = 0
            while True:
                try:
                    gpuLoad = -1
                    for _gp in _gpuSysfsPaths:
                        try:
                            with open(_gp) as _gf:
                                gpuLoad = float(_gf.read().strip().rstrip("%"))
                            break
                        except:
                            pass
                    if gpuLoad >= 0 and gpuLoad >= SysMgr.startCondGpu:
                        break
                    if gpuLoad < 0:
                        _gpuRetry += 1
                        if _gpuRetry >= 30:
                            SysMgr.printWarn(
                                "GPU load unavailable, skipping STARTCONDGPU"
                            )
                            break
                except SystemExit:
                    sys.exit(0)
                except:
                    break
                time.sleep(1)
            if "STARTCONDGPU" in exCondList:
                return

    @staticmethod
    def applyEnvironVars():
        def _applyVar(name, tobj, tvar):
            if name not in SysMgr.environList:
                return

            if "FILE" in name:
                setattr(tobj, tvar, SysMgr.environList[name])
                return

            var = SysMgr.environList[name][0]
            if var.strip().isdigit():
                if hasattr(tobj, tvar):
                    setattr(tobj, tvar, long(var))
                else:
                    SysMgr.printErr("no %s in %s" % (tvar, tobj))
                    sys.exit(-1)
            else:
                SysMgr.printErr("wrong value %s for %s" % (var, name))
                sys.exit(-1)

        SysMgr.nrTopRank = UtilMgr.getEnvironNum(
            "NRTOPRANK", False, SysMgr.nrTopRank, False, isInt=True
        )

        SysMgr.nrProcMemReport = UtilMgr.getEnvironNum(
            "NRPROCMEM", False, SysMgr.nrProcMemReport, False, isInt=True
        )

        SysMgr.kmsgLine = UtilMgr.getEnvironNum(
            "NRKLOG", False, SysMgr.kmsgLine, False, isInt=True
        )

        SysMgr.maxErrStrLen = UtilMgr.getEnvironNum(
            "MAXERRLEN", False, SysMgr.maxErrStrLen, False, isInt=True
        )

        if "SAVELMKLOG" in SysMgr.environList and SysMgr.isAndroid:
            maxN = UtilMgr.getEnvironNum(
                "SAVELMKLOG", False, 200, False, isInt=True
            )
            BpfMgr._startLmkLogThread(maxN if maxN and maxN > 0 else 200)

        for item in SysMgr.environList.get("FIXTASK", []):
            SysMgr.fixedTaskList += item.split("|")

        def _setLogger(options):
            SysMgr.dltEnable = "d" in options
            SysMgr.kmsgEnable = "k" in options
            SysMgr.journalEnable = "j" in options
            SysMgr.syslogEnable = "s" in options
            SysMgr.andlogEnable = "a" in options
            if any(
                [
                    SysMgr.dltEnable,
                    SysMgr.kmsgEnable,
                    SysMgr.journalEnable,
                    SysMgr.syslogEnable,
                    SysMgr.andlogEnable,
                ]
            ):
                SysMgr.colorEnable = False
                return True
            else:
                return False

        if "OPSLOG" in SysMgr.environList:
            options = SysMgr.environList["OPSLOG"][0]
            SysMgr.loggingOpsEnable = _setLogger(options)

        if "STDLOG" in SysMgr.environList:
            options = SysMgr.environList["STDLOG"][0]
            SysMgr.loggingEnable = _setLogger(options)

        if "NOCONVSIZE" in SysMgr.environList:
            UtilMgr.convSize2Unit = UtilMgr.convSize2UnitIgn

        if "NOCONVTIME" in SysMgr.environList:
            UtilMgr.convTime2Unit = UtilMgr.convTime2UnitIgn

        if "NOCONVNUM" in SysMgr.environList:
            UtilMgr.convNum = UtilMgr.convNumIgn

        convSize2Unit = UtilMgr.convSize2Unit
        convUnit2Size = UtilMgr.convUnit2Size

        for env, dlist, conv in (
            ("LIMITDIR", SysMgr.limitDirList, convUnit2Size),
            ("LIMITDIRCNT", SysMgr.limitDirCntList, long),
            ("KEEPREPDIRFILECNT", SysMgr.keepRepDirFileList, long),
        ):
            for dirInfo in SysMgr.environList.get(env, []):
                # optional per-target ":RECURSE" suffix - only meaningful
                # for LIMITDIR/LIMITDIRCNT (each keyed by a real directory
                # path); KEEPREPDIRFILECNT's "path" is actually a filename
                # match pattern for freeReportDir(), not a directory, so
                # it never takes this suffix. Stripped from a copy of the
                # original (case-preserved) string before the unchanged
                # path/num split below, so input without the suffix parses
                # byte-for-byte as before #
                recurseTarget = False
                if env in (
                    "LIMITDIR",
                    "LIMITDIRCNT",
                ) and dirInfo.upper().endswith(":RECURSE"):
                    dirInfo = dirInfo[: -len(":RECURSE")]
                    recurseTarget = True

                try:
                    path, num = UtilMgr.cleanItem(
                        dirInfo.split(":", 1), union=False
                    )
                    if not path or not num:
                        continue
                except SystemExit:
                    sys.exit(0)
                except:
                    SysMgr.printErr(
                        "failed to get target dir info to be limited", True
                    )
                    continue

                try:
                    num = conv(num)
                    if not num:
                        continue
                except SystemExit:
                    sys.exit(0)
                except:
                    SysMgr.printErr(
                        "failed to convert number '%s'" % num, True
                    )
                    sys.exit(-1)

                dlist[path] = num

                if recurseTarget:
                    SysMgr.recurseDirSet.add(path)

                if isinstance(num, long):
                    numstr = UtilMgr.convNum(num)
                else:
                    numstr = num

                SysMgr.printInfo(
                    "applied %s of '%s' to [%s]" % (env, path, numstr)
                )

        try:
            if "LIMITREPDIR" not in SysMgr.environList:
                raise SyntaxWarning()
            size = convUnit2Size(SysMgr.environList["LIMITREPDIR"][0])
            SysMgr.limitRepDirSize = size
            SysMgr.printInfo(
                "limit the size of the report directory to [%s]"
                % convSize2Unit(size)
            )
        except SyntaxWarning:
            pass
        except:
            SysMgr.printErr(
                "failed to get the limit size of report directory", True
            )
            sys.exit(-1)

        for env, svar in (("MVREPDIR", "mvRepDir"), ("CPREPDIR", "cpRepDir")):
            try:
                if env not in SysMgr.environList:
                    raise SyntaxWarning()

                val = SysMgr.environList[env][0]
                if not os.path.exists(val):
                    raise Exception("no %s dir '%s'" % (env, val))

                val = os.path.realpath(val)
                setattr(SysMgr, svar, val)

                SysMgr.printInfo(
                    "set %s to '%s' for the report directory" % (env, val)
                )
            except SyntaxWarning:
                pass
            except:
                SysMgr.printErr("failed to set %s" % env, True)
                sys.exit(-1)

        if "LIMITDIRINIT" in SysMgr.environList:
            SysMgr.cleanupDirs()
        elif "LIMITDIREXIT" in SysMgr.environList:
            SysMgr.addExitFunc(SysMgr.cleanupDirs)

        if "EXITCMD" in SysMgr.environList:
            SysMgr.addExitFunc(
                SysMgr.executeCommand, [SysMgr.environList["EXITCMD"]]
            )

            SysMgr.printInfo(
                "registered exit commands '%s'"
                % ", ".join(SysMgr.environList["EXITCMD"])
            )

        for name, env, optList in (
            ("runtime", "DYNRUNTIMEOPT", SysMgr.runtimeOption),
            ("uptime", "DYNUPTIMEOPT", SysMgr.uptimeOption),
        ):
            for opt in SysMgr.environList.get(env, []):
                items = opt.split(":", 1)
                errStr = "failed to recognize dynamic %s option '%s'" % (
                    name,
                    opt,
                )
                if len(items) == 1:
                    SysMgr.printErr(errStr)
                    sys.exit(-1)
                when, opt = items
                when = UtilMgr.convUnit2Time(when)
                if not when:
                    SysMgr.printErr(errStr)
                optList.append([when, opt])

        SysMgr.applyIgnoreSignals()

        SysMgr.applyLimitVars()

        SysMgr.applyCgroupVars()

        varList = [
            ("STARTCONDTIME", "startUptime"),
            ("STARTCONDCPUMORE", "startCondCpuMore"),
            ("STARTCONDCPULESS", "startCondCpuLess"),
            ("STARTCONDMEMMORE", "startCondMemMore"),
            ("STARTCONDMEMLESS", "startCondMemLess"),
            ("STARTCONDFILE", "startCondFile"),
            ("STARTCONDNOFILE", "startCondNoFile"),
            ("EXITCONDTIME", "deadlineUptime"),
            ("EXITCONDCPUMORE", "exitCondCpuMore"),
            ("EXITCONDCPULESS", "exitCondCpuLess"),
            ("EXITCONDMEMMORE", "exitCondMemMore"),
            ("EXITCONDMEMLESS", "exitCondMemLess"),
            ("EXITCONDFILE", "exitCondFile"),
            ("EXITCONDNOFILE", "exitCondNoFile"),
        ]

        for item in varList:
            _applyVar(item[0], SysMgr, item[1])

        # apply float cond items (PSI/Load/GPU) #
        _floatCondMap = [
            ("STARTCONDPSICPU", "startCondPsiCpu"),
            ("STARTCONDPSIMEM", "startCondPsiMem"),
            ("STARTCONDPSIIO", "startCondPsiIO"),
            ("EXITCONDPSICPU", "exitCondPsiCpu"),
            ("EXITCONDPSIMEM", "exitCondPsiMem"),
            ("EXITCONDPSIIO", "exitCondPsiIO"),
            ("STARTCONDLOAD", "startCondLoad1m"),
            ("EXITCONDLOAD", "exitCondLoad1m"),
            ("STARTCONDGPU", "startCondGpu"),
            ("EXITCONDGPU", "exitCondGpu"),
        ]
        for _envKey, _attr in _floatCondMap:
            _val = UtilMgr.getEnvironNum(
                _envKey, False, None, False, isFloat=True
            )
            if _val is not None:
                setattr(SysMgr, _attr, _val)

        SysMgr.checkStartCond()

        SysMgr.printEnv(os.environ, None)

        SysMgr.nsAllEnable = "PRINTNS" in SysMgr.environList

        if "NSTYPE" in SysMgr.environList:
            SysMgr.nsType = SysMgr.environList["NSTYPE"][0].lower()
            if not os.path.exists(
                "%s/self/ns/%s" % (SysMgr.procPath, SysMgr.nsType)
            ):
                SysMgr.printErr(
                    "failed to find '%s' namespace" % SysMgr.nsType
                )
                sys.exit(0)

        if "MOUNTCG" in SysMgr.environList:
            SysMgr.mountCgroups()

        if "UMOUNTCG" in SysMgr.environList:
            SysMgr.umountCgroups()

        if "VMFLAG" in SysMgr.environList:
            flags = SysMgr.environList["VMFLAG"][0].split("+")
            SysMgr.vmflagList = SysMgr.getVmFlags(flags)

        if "SUMMARYFILTER" in SysMgr.environList:
            filters = []
            for item in SysMgr.environList["SUMMARYFILTER"]:
                filters += item.split("+")
            SysMgr.environList["SUMMARYFILTER"] = filters

        if "ADDINTSUMMARY" in SysMgr.environList:
            SysMgr.addEnvironVar("STRPRINTBUF")

        SysMgr.taskStreamEnable = "TASKSTREAM" in SysMgr.environList

        if "PROCPATH" in SysMgr.environList:
            SysMgr.procPath = SysMgr.environList["PROCPATH"][0]

        if "FORCECOLOR" in SysMgr.environList:
            SysMgr.forceColorEnable = True

        if "NOTEMPER" in SysMgr.environList:
            SysMgr.tempEnable = False

        if "OOMADJ" in SysMgr.environList:
            SysMgr.setOOMAdj(pri=SysMgr.environList["OOMADJ"][0])
            SysMgr.addEnvironVar("OOMADJDONE")
            SysMgr.environList.pop("OOMADJ", None)

        SysMgr.dltTimeEnable = "DLTTIME" in SysMgr.environList

        pidPath = SysMgr.environList.get("MKPIDFILE")
        if pidPath and not SysMgr.parentPid:
            pidPath = pidPath[0]
            if pidPath == "SET":
                pidPath = os.path.join(SysMgr.tmpPath, "guider.pid")
            ret = SysMgr.writeFile(pidPath, str(SysMgr.pid), truncate=True)
            if ret:
                SysMgr.printInfo(
                    "wrote PID '%s' to '%s'" % (SysMgr.pid, pidPath)
                )

        def _cmdHandler(signum, frame):
            if not SysMgr.topInstance:
                return

            cmdList = SysMgr.sigCmdList.get(signum, [])
            if not cmdList:
                return

            for cmd in cmdList:
                try:
                    pid = SysMgr.createProcess()
                    if pid > 0:
                        continue

                    SysMgr.topInstance.handleEventCmd(
                        cmd, "SIGNAL", "SIGNAL", False
                    )
                    sys.exit(0)
                except SystemExit:
                    sys.exit(0)
                except:
                    SysMgr.printErr(
                        "failed to handle signal command '%s'" % cmd, True
                    )

        cmdList = SysMgr.environList.get("REGSIGCMD", [])
        for item in cmdList:
            try:
                sig, cmd = item.split(":", 1)
                sig = sig.upper()
                for idx, s in enumerate(ConfigMgr.SIG_LIST):
                    if not UtilMgr.isValidStr(sig, [s]):
                        continue

                    SysMgr.setSignal(idx, _cmdHandler)
                    SysMgr.sigCmdList.setdefault(idx, [])
                    cmds = cmd.split(":", 1)
                    cmds[0] = cmds[0].upper()
                    cmd = ":".join(cmds)
                    SysMgr.sigCmdList[idx].append(cmd)
                    SysMgr.printInfo(
                        "'%s' handler for '%s' command is registered"
                        % (sig, cmd)
                    )
            except SystemExit:
                sys.exit(0)
            except:
                SysMgr.printErr(
                    "failed to register signal command '%s'" % item, True
                )

        regList = SysMgr.environList.get("REGSIGHANDLER", [])
        regList = list(map(str.upper, regList))
        sigList = ConfigMgr.SIG_LIST if regList else []
        for idx, sig in enumerate(sigList):
            if not UtilMgr.isValidStr(sig, regList):
                continue
            try:
                SysMgr.setSignal(idx, SysMgr.printHandler)
                SysMgr.printInfo(
                    "%s handler is registered" % sig, suffix=False
                )
            except SystemExit:
                sys.exit(0)
            except:
                SysMgr.printErr(
                    "failed to register signal handler for '%s'" % sig, True
                )

    @staticmethod
    def checkOptVal(option, value):
        if not value:
            SysMgr.printErr("no input value with -%s option" % option)
            sys.exit(-1)

    @staticmethod
    def applySaveOption(value=None):
        isDefaultPath = not value
        if not value:
            value = "."

        # fall back to a writable dir on Android when cwd is not writable #
        if isDefaultPath and SysMgr.isAndroid and not SysMgr.isWritable(value):
            value = SysMgr.tmpPath

        try:
            if not SysMgr.isWritable(value):
                raise Exception("not writable")

            if os.path.isdir(value):
                SysMgr.outputFile = "%s/guider.dat" % value
            else:
                SysMgr.outputFile = value
        except SystemExit:
            sys.exit(0)
        except:
            SysMgr.printErr("wrong path '%s'" % os.path.realpath(value), True)
            sys.exit(-1)

        SysMgr.outputFile = os.path.normpath(SysMgr.outputFile)

        # support no-report record mode #
        if SysMgr.checkMode(["filerec", "genrec"]):
            if SysMgr.outputFile.endswith(".dat"):
                SysMgr.outPath = (
                    "%s.out" % os.path.splitext(SysMgr.outputFile)[0]
                )
            else:
                SysMgr.outPath = SysMgr.outputFile

    @staticmethod
    def removeOptionArgs():
        if len(sys.argv) < 3:
            return

        firstOptIdx = None
        for idx, item in enumerate(sys.argv):
            if item.startswith("-"):
                firstOptIdx = idx
                break

        if firstOptIdx:
            sys.argv = sys.argv[:firstOptIdx]

    @staticmethod
    def parseAnalOption(option=None):
        if "ISMAIN" not in os.environ:
            return

        if not option and SysMgr.parsedAnalOption:
            return
        else:
            SysMgr.parsedAnalOption = True

        if SysMgr.isTopMode():
            if SysMgr.findOption("a") or SysMgr.isDrawMode():
                SysMgr.cpuEnable = True
                SysMgr.gpuEnable = True
            else:
                SysMgr.cpuEnable = False

        if option:
            optionList = option.split()
            SysMgr.parseOption(optionList)
        elif len(sys.argv) <= 2:
            return
        else:
            optionList = None

        for item in SysMgr.optionList:
            if not item:
                continue

            option = item[0]
            value = item[1:].strip()

            SysMgr.checkValidOption(option)

            if option == "i":
                if not value:
                    SysMgr.intervalEnable = 1
                    continue

                errStr = "wrong value '%s' for interval, " % value

                try:
                    SysMgr.intervalEnable = long(value)

                    if SysMgr.intervalEnable <= 0:
                        SysMgr.printErr(
                            "%sinput number bigger than 0" % errStr
                        )
                        sys.exit(0)
                except SystemExit:
                    sys.exit(0)
                except:
                    SysMgr.printErr(
                        "%sinput number in integer format" % errStr
                    )
                    sys.exit(-1)

            elif SysMgr.isCommonOption(option):
                SysMgr.parseCommonOption(option, value)

            elif option == "I":
                SysMgr.inputParam = value.strip()

            elif option == "w":
                SysMgr.checkOptVal(option, value)
                SysMgr.rcmdList = SysMgr.parseCustomRecordCmd(value)

            elif option == "a":
                SysMgr.printOptionWarn(option, value)
                SysMgr.showAll = True

            elif option == "P":
                SysMgr.printOptionWarn(option, value)
                SysMgr.groupProcEnable = True

            elif option == "p":
                SysMgr.checkOptVal(option, value)

                SysMgr.preemptGroup = UtilMgr.cleanItem(value.split(","))

            elif option == "Y":
                SysMgr.checkOptVal(option, value)
                if SysMgr.prio is None:
                    SysMgr.applyPriority(value)

            elif option == "J":
                SysMgr.printOptionWarn(option, value)
                SysMgr.jsonEnable = True
                if not SysMgr.warnEnable:
                    SysMgr.logEnable = False

            elif option == "k":
                SysMgr.checkOptVal(option, value)
                if not SysMgr.isKillMode():
                    SysMgr.applyKillVal(value)

            elif option == "d":
                SysMgr.checkOptVal(option, value)
                options = value.replace(" ", "")

                optionMap = {
                    "b": ("bufferLossEnable", True),
                    "p": ("printEnable", False),
                    "u": ("userEnable", False),
                    "c": ("cpuEnable", False),
                    "C": ("cloneEnable", False),
                    "B": ("barGraphEnable", False),
                    "O": ("colorEnable", False),
                    "E": ("execEnable", False),
                    "x": ("eventHandleEnable", False),
                    "t": ("truncEnable", False),
                    "T": ("taskEnable", False),
                    "e": ("encodeEnable", False),
                    "a": ("freeMemEnable", True),
                    "G": ("gpuEnable", False),
                    "A": ("cpuAvgEnable", False),
                    "L": ("logEnable", False),
                    "g": ("generalEnable", False),
                    "d": ("demangleEnable", False),
                    "D": ("dwarfEnable", False),
                    "l": ("latEnable", False),
                    "P": ("psiEnable", False),
                    "m": ("gpuMemEnable", False),
                }

                for opt, (attr, value) in optionMap.items():
                    if opt in options:
                        setattr(SysMgr, attr, value)

            elif option == "c":
                itemList = UtilMgr.splitString(value)

                if SysMgr.isTraceMode() or SysMgr.checkMode("cli"):
                    union = False
                else:
                    union = True

                SysMgr.customCmd = UtilMgr.cleanItem(itemList, union=union)

            elif option == "g":
                itemList = UtilMgr.splitString(value)
                SysMgr.filterGroup = UtilMgr.cleanItem(itemList)

            elif "F" in option:
                SysMgr.checkOptVal(option, value)

                SysMgr.drawFormat = value.strip()

            elif option == "e":
                options = value.replace(" ", "")

                if "g" in options:
                    SysMgr.graphEnable = True

                if "D" in options:
                    SysMgr.dwarfEnable = True

                if "l" in options:
                    SysMgr.thresholdEnable = True

                if "t" in options:
                    SysMgr.processEnable = False

                if "H" in options:
                    if not SysMgr.checkMode("ttop"):
                        SysMgr.printErr(
                            "sched option is supported only in thread mode"
                        )
                        sys.exit(-1)
                    SysMgr.schedEnable = True

                if "Y" in options:
                    SysMgr.checkRootPerm()
                    SysMgr.delayEnable = True

                if "P" in options:
                    SysMgr.perfEnable = True
                    if SysMgr.findOption("g"):
                        SysMgr.perfGroupEnable = True

                # below options only for top mode #
                if not SysMgr.isTopMode():
                    continue

                if "T" in options:
                    SysMgr.totalEnable = True

                if "c" in options:
                    SysMgr.cpuEnable = True

                if "p" in options:
                    SysMgr.pipeEnable = True

                if "i" in options:
                    SysMgr.irqEnable = True

                if "b" in options:
                    if SysMgr.checkDiskTopCond():
                        SysMgr.blockEnable = True
                    else:
                        sys.exit(-1)

                if "B" in options:
                    SysMgr.barGraphEnable = True

                if "s" in options:
                    if SysMgr.checkStackTopCond():
                        SysMgr.stackEnable = True
                    else:
                        sys.exit(-1)

                if "S" in options:
                    SysMgr.checkRootPerm()
                    SysMgr.pssEnable = True
                    if not SysMgr.findOption("S"):
                        SysMgr.sort = "m"

                if "u" in options:
                    SysMgr.checkRootPerm()
                    SysMgr.ussEnable = True
                    if not SysMgr.findOption("S"):
                        SysMgr.sort = "m"

                if "L" in options:
                    SysMgr.cmdlineEnable = True

                if "Q" in options:
                    SysMgr.groupInfoEnable = True

                if "X" in options:
                    SysMgr.exeEnable = True

                if "U" in options:
                    SysMgr.dbusUnitEnable = True

                if "O" in options:
                    TaskAnalyzer.setLastField("iosched")
                elif "a" in options:
                    TaskAnalyzer.setLastField("affinity")
                elif "o" in options:
                    TaskAnalyzer.setLastField("oom")
                elif "W" in options:
                    TaskAnalyzer.setLastField("wchan")
                elif "h" in options:
                    TaskAnalyzer.setLastField("signal")
                elif "A" in options:
                    TaskAnalyzer.setLastField("attr")
                elif "K" in options:
                    TaskAnalyzer.setLastField("cgroup")

                if "f" in options:
                    SysMgr.floatEnable = True

                    # set default interval to 3 for accuracy #
                    if not SysMgr.findOption("iR"):
                        SysMgr.intervalEnable = 3

                if "F" in options:
                    SysMgr.wfcEnable = True

                if "R" in options:
                    SysMgr.reportEnable = True
                    SysMgr.reportFileEnable = True

                if "e" in options:
                    SysMgr.encodeEnable = True

                if "k" in options:
                    SysMgr.peakEnable = True

                if "m" in options:
                    if SysMgr.checkMemTopCond():
                        SysMgr.memEnable = True
                    else:
                        sys.exit(-1)

                if "M" in options:
                    SysMgr.minStatEnable = True

                if "w" in options:
                    if SysMgr.checkWssTopCond():
                        SysMgr.memEnable = True
                        SysMgr.wssEnable = True
                        if not SysMgr.findOption("S"):
                            SysMgr.sort = "m"
                    else:
                        sys.exit(-1)

                if "n" in options:
                    SysMgr.networkEnable = True

                if "N" in options:
                    SysMgr.nsEnable = True

                if "P" in options:
                    if SysMgr.checkPerfTopCond():
                        SysMgr.perfEnable = True
                        if SysMgr.findOption("g"):
                            SysMgr.perfGroupEnable = True
                    else:
                        sys.exit(-1)

                if "r" in options:
                    SysMgr.reportEnable = True

                if "I" in options:
                    SysMgr.reportEnable = True
                    SysMgr.elasticEnable = True

                if "d" in options:
                    SysMgr.diskEnable = True

                if "E" in options:
                    SysMgr.execEnable = True

                if "G" in options:
                    SysMgr.cgroupEnable = True

                if "C" in options:
                    SysMgr.compressEnable = True

                if "q" in options:
                    SysMgr.exitFlag = True

                if "x" in options:
                    SysMgr.fixTargetEnable = True

                if "V" in options:
                    SysMgr.lifeAvgEnable = True

                if not SysMgr.isValidEnableOption(options):
                    SysMgr.printErr(
                        "unrecognized option -%s to enable" % options
                    )
                    sys.exit(-1)

            elif option == "O":
                SysMgr.checkOptVal(option, value)

                perCoreList = UtilMgr.cleanItem(value.split(","))
                if not perCoreList:
                    SysMgr.printErr("no input value for filter" % option)
                    sys.exit(-1)

                perCoreList = UtilMgr.convxrange(perCoreList)

                for item in perCoreList:
                    if not item.isdigit():
                        SysMgr.printErr(
                            (
                                "wrong value for core list, "
                                "input number in integer format"
                            )
                            % option
                        )
                        sys.exit(-1)

                SysMgr.printInfo(
                    "only specific cores [ %s ] are shown"
                    % ", ".join(perCoreList)
                )

                SysMgr.perCoreList = list(map(long, perCoreList))

                if SysMgr.isDrawMode():
                    SysMgr.perCoreDrawList = SysMgr.perCoreList
                    SysMgr.perCoreList = []

            # ignore below options for function mode #
            elif SysMgr.isFuncMode():
                SysMgr.functionEnable = True

            elif option == "l":
                if not SysMgr.isDrawMode():
                    options = value
                    SysMgr.dltEnable = "d" in options
                    SysMgr.kmsgEnable = "k" in options
                    SysMgr.journalEnable = "j" in options
                    SysMgr.syslogEnable = "s" in options
                    SysMgr.andlogEnable = "a" in options
                    if any(
                        [
                            SysMgr.dltEnable,
                            SysMgr.kmsgEnable,
                            SysMgr.journalEnable,
                            SysMgr.syslogEnable,
                            SysMgr.andlogEnable,
                        ]
                    ):
                        SysMgr.loggingEnable = True
                        SysMgr.colorEnable = False

            elif option == "r":
                if value.strip():
                    SysMgr.rootPath = value
                else:
                    SysMgr.recursionEnable = True

            elif option == "T":
                SysMgr.checkOptVal(option, value)

                if SysMgr.checkMode("convert"):
                    SysMgr.fontPath = value
                elif SysMgr.isDrawMode():
                    try:
                        SysMgr.nrTop = long(value)
                    except:
                        SysMgr.printErr(
                            (
                                "wrong value for the number of task, "
                                "input number in integer format"
                            )
                            % option
                        )
                        sys.exit(-1)
                # this value will be used in various mode #
                else:
                    try:
                        SysMgr.utilProc = long(value)
                    except:
                        pass

            elif option == "t" and not SysMgr.isRecordMode():
                SysMgr.parseSyscallOption(value)

            elif option == "m":
                try:
                    SysMgr.ttyEnable = True

                    if not value:
                        SysMgr.setTTYAuto()
                    else:
                        rows = cols = 0
                        term = value.split(":")

                        term[0] = term[0].strip()
                        if term[0].isdigit():
                            rows = long(term[0])

                        if len(term) > 1:
                            term[1] = term[1].strip()
                            if term[1].isdigit():
                                cols = long(term[1])

                        if len(term) > 2 and term[2].upper() == "SYSTEM":
                            SysMgr.setTTY(rows, cols)
                        else:
                            if rows > 0:
                                SysMgr.ttyRows = rows
                            if cols > 0:
                                SysMgr.ttyCols = cols
                except SystemExit:
                    sys.exit(0)
                except:
                    SysMgr.printErr(
                        (
                            "wrong value for screen size, "
                            "input number in COLS:ROWS format"
                        )
                        % option,
                        reason=True,
                    )
                    sys.exit(-1)

            elif option == "b" and not SysMgr.isRecordMode():
                SysMgr.checkOptVal(option, value)
                try:
                    if value.isdigit():
                        bsize = long(value) << 10
                    else:
                        bsize = UtilMgr.convUnit2Size(value)

                    if bsize >= 0:
                        SysMgr.bufferSize = bsize
                    else:
                        SysMgr.printErr(
                            (
                                "wrong value %s for buffer size, "
                                "input number bigger than 0"
                            )
                            % option
                        )
                        sys.exit(0)
                except SystemExit:
                    sys.exit(0)
                except:
                    SysMgr.printErr(
                        (
                            "wrong value %s for buffer size, "
                            "input number in integer format"
                        )
                        % option
                    )
                    sys.exit(-1)

            elif option == "N":
                SysMgr.checkOptVal(option, value)
                networkList = UtilMgr.cleanItem(value.split(","))
                for item in networkList:
                    service, ip, port = NetworkMgr.parseAddr(item)
                    NetworkMgr.setRemoteNetwork(service, ip, port)

            elif option == "j":
                if not SysMgr.checkRepTopCond(value):
                    sys.exit(-1)
                SysMgr.jsonEnable = True

            elif option == "x":
                SysMgr.checkOptVal(option, value)
                service, ip, port = NetworkMgr.parseAddr(value)

                if "PUBLICIP" in SysMgr.environList:
                    ip = NetworkMgr.getPublicIp()

                ret = NetworkMgr.setServerNetwork(ip, port, verb=True)
                if not ret:
                    sys.exit(-1)

            elif option == "X":
                if not SysMgr.findOption("x"):
                    service, ip, port = NetworkMgr.parseAddr(value)
                    NetworkMgr.setServerNetwork(None, None)

                NetworkMgr.setRemoteServer(value)

            elif option == "S":
                if not SysMgr.setSortValue(value):
                    sys.exit(-1)

            # Ignore options #
            elif SysMgr.isValidOption(option):
                continue

            else:
                SysMgr.printErr(
                    "unrecognized option -%s for analysis" % option
                )
                sys.exit(-1)

    @staticmethod
    def printOptionWarn(option, value):
        if not value:
            return

        SysMgr.printWarn("the %s option does not require value" % option, True)

    @staticmethod
    def parseCommonOption(option, value):
        if value:
            value = value.strip()

        if option == "f":
            SysMgr.printOptionWarn(option, value)
            SysMgr.forceEnable = True

        elif option == "L":
            if SysMgr.isDrawMode():
                SysMgr.layout = value
            else:
                newPath = None

                if not value:
                    if not os.path.exists(SysMgr.cacheDirPath):
                        SysMgr.mkdirs(SysMgr.cacheDirPath)
                    newPath = os.path.join(SysMgr.cacheDirPath, "guider.log")
                elif not SysMgr.stdlog:
                    if os.path.isdir(value):
                        newPath = os.path.join(value, "guider.log")
                    else:
                        newPath = value

                if newPath:
                    SysMgr.printInfo(
                        "apply '%s'%s to log path from %s"
                        % (
                            newPath,
                            UtilMgr.getFileSizeStr(newPath),
                            UtilMgr.getTime(),
                        )
                    )
                    SysMgr.stdlog = LogMgr(newPath)

        elif option == "o":
            isDefaultPath = value == ""
            if value == "":
                value = "."

            # fall back to a writable dir on Android when cwd is not writable #
            if (
                isDefaultPath
                and SysMgr.isAndroid
                and not SysMgr.isWritable(value)
            ):
                value = SysMgr.tmpPath

            if not SysMgr.isWritable(value):
                SysMgr.printErr(
                    "wrong output path '%s' because of permission" % value
                )
                sys.exit(-1)

            ret = SysMgr.setReportPathForm(value)
            if not ret:
                SysMgr.outPath = os.path.normpath(value)
            SysMgr.origOutPath = os.path.realpath(SysMgr.outPath)

        elif option == "s":
            if not SysMgr.isKillMode():
                SysMgr.applySaveOption(value)

        elif option == "H":
            try:
                if not value:
                    SysMgr.depthLevel = 100
                else:
                    SysMgr.depthLevel = long(value)

                if SysMgr.depthLevel < 0:
                    raise Exception("wrong depth")
            except:
                SysMgr.printErr(
                    "wrong input value for depth, "
                    "input an unsigned integer value"
                )
                sys.exit(-1)

        elif option == "Q":
            SysMgr.printOptionWarn(option, value)
            SysMgr.setStream()

        elif option == "q":
            SysMgr.checkOptVal(option, value)

            # NOTE: variables are already parsed in SysMgr.initEnvironment() #

            SysMgr.applyEnvironVars()

            if "LIVEGRAPH" in SysMgr.environList:
                SysMgr.jsonEnable = True
                SysMgr.liveGraphEnable = True

            if "PSIGRAPH" in SysMgr.environList:
                SysMgr.jsonEnable = True
                SysMgr.psiGraphEnable = True

            if "CPUGRAPH" in SysMgr.environList:
                SysMgr.jsonEnable = True
                SysMgr.cpuGraphEnable = True

            _LIVE_TASK_GRAPH_OPTS = (
                "LIVETASKCPUGRAPH",
                "LIVETASKRSSGRAPH",
                "LIVETASKVSSGRAPH",
                "LIVETASKPSSGRAPH",
                "LIVETASKUSSGRAPH",
                "LIVETASKIOGRAPH",
            )
            if any(k in SysMgr.environList for k in _LIVE_TASK_GRAPH_OPTS):
                SysMgr.liveTaskGraphEnable = True
                # PSS/USS require smaps reading #
                if "LIVETASKPSSGRAPH" in SysMgr.environList:
                    SysMgr.pssEnable = True
                if "LIVETASKUSSGRAPH" in SysMgr.environList:
                    SysMgr.ussEnable = True
                # I/O data requires block collection #
                if "LIVETASKIOGRAPH" in SysMgr.environList:
                    SysMgr.blockEnable = True

        elif option == "R":
            if not value:
                value = str(sys.maxsize)
            SysMgr.parseRuntimeOption(value)

        elif option == "z":
            SysMgr.checkOptVal(option, value)
            SysMgr.parseAffinityOption(
                UtilMgr.cleanItem(value.split(",")), launch=True
            )

        elif option == "A":
            SysMgr.checkOptVal(option, value)
            SysMgr.archOption = value
            SysMgr.setArch(value)

        elif option == "W":
            if value:
                if not SysMgr.waitEnable:
                    SysMgr.waitEnable = UtilMgr.convUnit2Time(value)
                    SysMgr.printStat(
                        "wait %s more seconds"
                        % (UtilMgr.convNum(SysMgr.waitEnable))
                    )
            else:
                SysMgr.waitEnable = True

        elif option == "C":
            if not ConfigMgr.confData:
                SysMgr.confFileName = os.path.realpath(
                    value if value else SysMgr.confFileName
                )

                ret = SysMgr.loadConfig(SysMgr.confFileName)
                if not SysMgr.isDrawMode() and not ret:
                    sys.exit(-1)

                cmdList = SysMgr.getConfigItem("command")
                if cmdList and cmdList.get("apply") == "true":
                    SysMgr.executeCommand(cmdList["list"])

        elif option == "E":
            SysMgr.cacheDirPath = value
            SysMgr.printInfo("use '%s' as the cache directory" % value)

        elif option == "G":
            SysMgr.checkOptVal(option, value)
            itemList = UtilMgr.splitString(value)
            SysMgr.ignoreItemList = UtilMgr.cleanItem(itemList)
            SysMgr.printInfo(
                "applied ignore keyword [ %s ]"
                % ", ".join(SysMgr.ignoreItemList)
            )

        elif option == "u":
            SysMgr.printOptionWarn(option, value)
            SysMgr.runBackgroundMode()

    @staticmethod
    def isCommonOption(option):
        return option in "ACEGHLQRWfoqsuz"

    @staticmethod
    def parseSyscallOption(value, targetList=None, exceptList=None):
        syscallList = UtilMgr.cleanItem(value.split(","))
        enabledSyscall = []
        disabledSyscall = []

        if targetList is None:
            targetList = SysMgr.syscallList
        if exceptList is None:
            exceptList = SysMgr.syscallExceptList

        for val in syscallList:
            try:
                if val.startswith("^"):
                    exceptFlag = True
                    val = val[1:]
                else:
                    exceptFlag = False

                # strip sys_ prefix so wildcard matching below compares bare names #
                if val.lstrip("*").startswith("sys_"):
                    if val.startswith("*"):
                        prefix = "*"
                    else:
                        prefix = ""
                    val = prefix + UtilMgr.lstrip(val.lstrip("*"), "sys_")

                nrList = []
                if "*" in val:
                    for idx, syscall in enumerate(ConfigMgr.sysList):
                        if UtilMgr.isValidStr(
                            UtilMgr.lstrip(syscall, "sys_"), [val]
                        ):
                            nrList.append(idx)
                else:
                    nrList = [SysMgr.getNrSyscall(val)]

                for nrSyscall in nrList:
                    if exceptFlag:
                        disabledSyscall.append(ConfigMgr.sysList[nrSyscall])
                    else:
                        enabledSyscall.append(ConfigMgr.sysList[nrSyscall])

                    if exceptFlag:
                        exceptList.append(nrSyscall)
                    else:
                        targetList.append(nrSyscall)
            except SystemExit:
                sys.exit(0)
            except:
                SysMgr.printErr("no %s syscall in %s ABI" % (val, SysMgr.arch))
                sys.exit(-1)

            if syscallList and not targetList and not exceptList:
                SysMgr.printErr("no %s syscall in %s ABI" % (val, SysMgr.arch))
                sys.exit(-1)

        if not enabledSyscall:
            SysMgr.printInfo("enabled syscall list [ ALL ]")
        else:
            SysMgr.printInfo(
                "enabled syscall list [ %s ]" % ", ".join(enabledSyscall)
            )

        if disabledSyscall:
            SysMgr.printInfo(
                "disabled syscall list [ %s ]" % ", ".join(disabledSyscall)
            )

    @staticmethod
    def getSyscallName(nr):
        """Convert syscall number to human-readable name (strips 'sys_' prefix)"""
        try:
            name = ConfigMgr.sysList[nr]
            return name[4:] if name.startswith("sys_") else name
        except Exception:
            return "syscall_%d" % nr

    @staticmethod
    def parseRecordOption():
        if "ISMAIN" not in os.environ:
            return
        elif len(sys.argv) <= 2:
            return

        SysMgr.parseOption()

        for item in SysMgr.optionList:
            try:
                option = item[0]
                value = item[1:].strip()
            except:
                continue

            SysMgr.checkValidOption(option)

            if option == "b":
                try:
                    if value.isdigit():
                        bsize = long(value)
                        osize = bsize << 10
                    else:
                        osize = UtilMgr.convUnit2Size(value)
                        bsize = osize >> 10

                    if bsize > 0:
                        SysMgr.bufferSize = bsize

                        SysMgr.printInfo(
                            "set buffer size to [%s]"
                            % UtilMgr.convSize2Unit(osize)
                        )
                    else:
                        SysMgr.printErr(
                            "wrong value for buffer size, "
                            "input number bigger than 0"
                        )
                        sys.exit(-1)
                except SystemExit:
                    sys.exit(0)
                except:
                    SysMgr.printErr(
                        "wrong value for buffer size, "
                        "input number in integer format"
                    )
                    sys.exit(-1)

            elif option == "Y":
                SysMgr.applyPriority(value)

            elif option == "e":
                options = value.replace(" ", "")

                optionMap = {
                    "a": "enableAll",
                    "b": "blockEnable",
                    "B": "binderEnable",
                    "c": "cgroupEnable",
                    "d": "diskEnable",
                    "f": "fsEnable",
                    "g": "graphEnable",
                    "h": "heapEnable",
                    "i": "irqEnable",
                    "I": "i2cEnable",
                    "k": "kvmEnable",
                    "L": "lockEnable",
                    "m": "memEnable",
                    "M": "moduleEnable",
                    "n": "networkEnable",
                    "o": "iouringEnable",
                    "p": "pipeEnable",
                    "P": "powerEnable",
                    "r": "resetEnable",
                    "s": "syncEnable",
                    "u": "userEnable",
                    "w": "wqEnable",
                }

                for opt, attr in optionMap.items():
                    if opt in options:
                        setattr(SysMgr, attr, True)

                if not SysMgr.isValidEnableOption(options):
                    SysMgr.printErr(
                        "unrecognized option '%s' to enable" % options
                    )
                    sys.exit(-1)

            elif option == "g":
                itemList = UtilMgr.splitString(value)
                SysMgr.filterGroup = UtilMgr.cleanItem(itemList)
                if not SysMgr.filterGroup:
                    SysMgr.printErr("no input value for filter")
                    sys.exit(-1)

                SysMgr.printInfo(
                    "only specific threads [ %s ] are recorded"
                    % ", ".join(SysMgr.filterGroup)
                )

            elif option == "w":
                SysMgr.rcmdList = SysMgr.parseCustomRecordCmd(value)

            elif option == "U":
                SysMgr.ueventEnable = True
                itemList = UtilMgr.splitString(value)
                SysMgr.userCmd = UtilMgr.cleanItem(itemList)

            elif option == "K":
                SysMgr.keventEnable = True
                itemList = UtilMgr.splitString(value)
                SysMgr.kernelCmd = UtilMgr.cleanItem(itemList)

            elif option == "M":
                SysMgr.objdumpPath = value

                SysMgr.printInfo(
                    "use '%s' as the objdump path" % SysMgr.objdumpPath
                )

            elif option == "F":
                SysMgr.printOptionWarn(option, value)
                SysMgr.fileEnable = True

            elif option == "B":
                if not value:
                    value = SysMgr.cmdFileName

                try:
                    if not SysMgr.isWritable(value):
                        raise Exception("not writable")

                    if os.path.isdir(value):
                        SysMgr.cmdEnable = "%s/%s" % (
                            value,
                            SysMgr.cmdFileName,
                        )
                    else:
                        SysMgr.cmdEnable = value
                except:
                    SysMgr.printErr("wrong command script path '%s'" % value)
                    sys.exit(-1)

                SysMgr.cmdEnable = os.path.normpath(SysMgr.cmdEnable)

            elif option == "t":
                SysMgr.sysEnable = True
                SysMgr.parseSyscallOption(value)

            elif SysMgr.isCommonOption(option):
                SysMgr.parseCommonOption(option, value)

            elif option == "c":
                itemList = UtilMgr.splitString(value)
                SysMgr.customCmd = UtilMgr.cleanItem(itemList)
                if not SysMgr.customCmd:
                    SysMgr.printErr("failed to recognize trace events")
                    sys.exit(-1)

            elif option == "d":
                options = value.replace(" ", "")

                optionMap = {
                    "c": [("cpuEnable", False), ("latEnable", False)],
                    "C": [("compressEnable", False)],
                    "L": [("logEnable", False)],
                    "a": [("disableAll", True)],
                    "b": [("blockEnable", False)],
                    "g": [("generalEnable", False)],
                    "h": [("heapEnable", False)],
                    "l": [("latEnable", False)],
                    "m": [("memEnable", False)],
                    "p": [("printEnable", False)],
                    "s": [("signalEnable", False)],
                }

                for opt, attrs in optionMap.items():
                    if opt in options:
                        for attr, value in attrs:
                            setattr(SysMgr, attr, value)

            elif option == "D":
                SysMgr.printOptionWarn(option, value)
                SysMgr.depEnable = True

            # Ignore options #
            elif SysMgr.isValidOption(option):
                continue

            else:
                SysMgr.printErr(
                    "unrecognized option -%s for recording" % option
                )
                sys.exit(-1)

    @staticmethod
    def makeKerSymTable(symbol=None):
        SysMgr.printInfo("start reading kernel symbols...")

        # disable kptr_restrict so kernel symbol addresses are exposed #
        try:
            restPath = "%s/sys/kernel/kptr_restrict" % SysMgr.procPath
            with open(restPath, "w+") as fd:
                fd.write("0")
        except SystemExit:
            sys.exit(0)
        except:
            pass

        try:
            symPath = "%s/kallsyms" % SysMgr.procPath
            f = open(symPath, "r")
        except IOError:
            SysMgr.printOpenWarn(symPath)
            return None
        except SystemExit:
            sys.exit(0)

        ret = None
        startPos = len(SysMgr.kerSymTable)
        curPos = 0

        while 1:
            line = f.readline()
            curPos += 1

            if startPos > curPos:
                continue

            if not line:
                break

            line = line.split(" ", 2)
            if len(line) < 3:
                continue
            SysMgr.kerSymTable[line[2].strip()] = line[0]

            if line[2] == symbol:
                ret = line[0]
                break

        f.close()
        return ret

    @staticmethod
    def getAddrFromKernel(symbol):
        try:
            return SysMgr.kerSymTable[symbol]
        except:
            return SysMgr.makeKerSymTable(symbol)

    @staticmethod
    def isRecordMode():
        if len(sys.argv) > 1 and sys.argv[1] in (
            "rec",
            "funcrec",
            "iorec",
            "sysrec",
            "filerec",
            "genrec",
        ):
            return True
        else:
            return False

    @staticmethod
    def isHelpMode():
        if len(sys.argv) > 1 and sys.argv[1] == "help":
            return True
        elif {"-help", "--help", "-h"} & set(sys.argv):
            return True
        else:
            return False

    @staticmethod
    def getMode(orig=False):
        if orig:
            target = SysMgr.origArgs
        else:
            target = sys.argv

        if len(target) > 1:
            return target[1]
        else:
            return None

    @staticmethod
    def checkMode(mode, orig=False):
        if orig:
            target = SysMgr.origArgs
        else:
            target = sys.argv

        if not isinstance(mode, list):
            mode = [mode]

        return len(target) > 1 and target[1] in mode

    @staticmethod
    def isKillMode():
        if len(sys.argv) < 2:
            return False
        return sys.argv[1] in ("kill", "tkill")

    @staticmethod
    def isWritable(value):
        if os.access(value, os.F_OK):
            if not os.access(value, os.W_OK):
                return False
        else:
            dirPath = os.path.dirname(value) or "."

            if not os.path.isdir(dirPath):
                return False
            elif not os.access(dirPath, os.W_OK):
                return False

        return True

    @staticmethod
    def isTopMode():
        if len(sys.argv) > 1 and sys.argv[1] in (
            "andtop",
            "atop",
            "attop",
            "bdtop",
            "bgtop",
            "bpfmarktop",
            "btop",
            "cgtop",
            "contop",
            "ctop",
            "dbustop",
            "disktop",
            "dlttop",
            "fetop",
            "ftop",
            "gfxtop",
            "irqtop",
            "ktop",
            "kstop",
            "leaktop",
            "mdtop",
            "mtop",
            "ntop",
            "oomtop",
            "ptop",
            "pytop",
            "rtop",
            "slabtop",
            "stacktop",
            "swaptop",
            "systop",
            "top",
            "tptop",
            "trtop",
            "ttop",
            "utop",
            "vtop",
            "wtop",
        ):
            return True
        else:
            return False

    @staticmethod
    def isTraceMode():
        if len(sys.argv) > 1 and sys.argv[1] in (
            "btrace",
            "leaktrace",
            "mtrace",
            "pytrace",
            "remote",
            "sigtrace",
            "stat",
            "strace",
            "utrace",
        ):
            return True
        else:
            return False

    @staticmethod
    def isRuntimeMode():
        if (
            SysMgr.isRecordMode()
            or SysMgr.isTopMode()
            or SysMgr.isTraceMode()
            or SysMgr.checkMode("req")
        ):
            return True

        return False

    @staticmethod
    def checkCmdMode():
        if SysMgr.isRecordMode():
            return

        if (
            False
            and len(sys.argv) > 1
            and sys.argv[1] not in SysMgr.getCmdSet()
        ):
            SysMgr.printErr("'%s' command is not supported" % sys.argv[1])
            sys.exit(-1)

        SysMgr.parseAnalOption()

        if not SysMgr.ttyEnable:
            SysMgr.setTTYAuto(True, False, False)

        SysMgr.waitUserInput(SysMgr.waitEnable, msg="DEFAULT", force=True)

        if SysMgr.checkMode(["watch", "fetop"]):
            if SysMgr.findOption("l"):
                if SysMgr.hasEnvironVar(["PROCINFO", "INMOUNT", "ALLMOUNT"]):
                    UtilMgr.makeReverseDict(
                        ConfigMgr.FAN_EVENT_TYPE,
                        ConfigMgr.FAN_EVENT_TYPE_REVERSE,
                    )
                    UtilMgr.printList(ConfigMgr.FAN_EVENT_TYPE_REVERSE)
                else:
                    UtilMgr.printList(ConfigMgr.INOTIFY_TYPE)
                sys.exit(0)

            SysMgr.doWatch(top=SysMgr.checkMode("fetop"))

        elif SysMgr.isTopMode():
            return

        elif SysMgr.checkMode("list"):
            SysMgr.setStream(not SysMgr.streamEnable)
            SysMgr.printBgProcs()

        elif SysMgr.checkMode("server"):
            SysMgr.runServerMode()

        elif SysMgr.checkMode("fserver"):
            SysMgr.runFileServerMode()

        elif SysMgr.checkMode("hserver"):
            SysMgr.runHttpServerMode()

        elif SysMgr.checkMode("send"):
            SysMgr.sendMessage()

        elif SysMgr.checkMode("cli"):
            SysMgr.runClientMode()

        elif SysMgr.checkMode(["start", "stop"]):
            if len(sys.argv) > 2:
                argList = sys.argv[2:]
            else:
                argList = None

            SysMgr.sendSignalProcs(signal.SIGINT, argList)

        elif SysMgr.isKillMode():
            SysMgr.doKill()

        elif SysMgr.checkMode("topdiff"):
            SysMgr.removeOptionArgs()

            if SysMgr.hasMainArg():
                argList = SysMgr.getMainArg().split(",")
                argList = UtilMgr.getFileList(argList)
            else:
                argList = None

            SysMgr.printLogo(big=True, onlyFile=True)

            TaskAnalyzer.doDiffReports(argList)

        elif SysMgr.checkMode("topsum"):
            if SysMgr.hasMainArg():
                inputArg = SysMgr.getMainArgs()
            elif SysMgr.inputParam:
                inputArg = str(SysMgr.inputParam).split(",")
                inputArg = UtilMgr.cleanItem(inputArg, True)
            else:
                SysMgr.printErr("no input for PATH")
                sys.exit(-1)

            SysMgr.setDefaultOutPath()

            inputArg = UtilMgr.getFileList(inputArg, sort=True, exceptDir=True)

            TaskAnalyzer.doSumReport(inputArg)

        elif SysMgr.checkMode("pause"):
            ret = SysMgr.selectTaskId()
            if ret:
                targets = [ret]
            elif SysMgr.hasMainArg():
                targets = SysMgr.getMainArgs()
            else:
                targets = SysMgr.filterGroup

            if not targets:
                SysMgr.printErr("no input value for COMM or TID")
                sys.exit(-1)

            targetList = []
            sibling = SysMgr.groupProcEnable

            targetList = SysMgr.convTaskList(
                targets, isThread=True, exceptMe=True, sibling=sibling
            )
            targetList = list(set(targetList))

            if not targetList:
                SysMgr.printErr("no task related to '%s'" % ", ".join(targets))
                sys.exit(-1)

            Debugger.pauseThreads(targetList)

        elif SysMgr.checkMode("readelf"):
            SysMgr.doReadelf()

        elif SysMgr.checkMode("readdex"):
            SysMgr.doReaddex()

        elif SysMgr.checkMode("readapk"):
            SysMgr.doReadapk()

        elif SysMgr.checkMode("leaktrace"):
            SysMgr.doLeaktrace()

        elif SysMgr.checkMode("addr2sym"):
            SysMgr.doAddr2sym()

        elif SysMgr.checkMode("sym2addr"):
            SysMgr.doSym2addr()

        elif SysMgr.checkMode("mkcache"):
            SysMgr.doMkCache()

        elif SysMgr.checkMode("readahead"):
            if SysMgr.hasMainArg():
                path = SysMgr.getMainArg()
            elif SysMgr.inputParam:
                path = SysMgr.inputParam
            else:
                path = "readahead.list"

            SysMgr.doReadahead(path)

        elif SysMgr.checkMode("printext"):
            SysMgr.doPrintExt()

        elif SysMgr.checkMode("printdir"):
            SysMgr.printLogo(big=True, onlyFile=True)

            if SysMgr.hasMainArg():
                rootList = SysMgr.getMainArgs()
            elif SysMgr.inputParam:
                rootList = SysMgr.inputParam.split(",")
                rootList = UtilMgr.cleanItem(rootList, True)
            else:
                rootList = ["."]

            if not SysMgr.depthLevel:
                maxLevel = -1
            else:
                maxLevel = SysMgr.depthLevel

            sizeUnit = "FULLSIZE" not in SysMgr.environList

            if SysMgr.intervalEnable:
                SysMgr.streamEnable = True

            while 1:
                for root in rootList:
                    SysMgr.printDirs(root, maxLevel, sizeUnit=sizeUnit)

                if SysMgr.intervalEnable:
                    time.sleep(SysMgr.intervalEnable)
                else:
                    break

        elif SysMgr.checkMode("dirdiff"):
            SysMgr.printLogo(big=True, onlyFile=True)

            if SysMgr.hasMainArg():
                rootList = SysMgr.getMainArgs(union=False)
            elif SysMgr.inputParam:
                rootList = SysMgr.inputParam.split(",")
                rootList = UtilMgr.cleanItem(rootList, True)
            else:
                rootList = ["."]

            if len(rootList) != 2:
                SysMgr.printErr("wrong input value for path")
                sys.exit(0)

            if not SysMgr.depthLevel:
                maxLevel = -1
            else:
                maxLevel = SysMgr.depthLevel

            sizeUnit = "FULLSIZE" not in SysMgr.environList

            if SysMgr.intervalEnable:
                SysMgr.streamEnable = True

            while 1:
                SysMgr.printDirDiff(
                    rootList, maxLevel=maxLevel, sizeUnit=sizeUnit
                )

                if SysMgr.intervalEnable:
                    time.sleep(SysMgr.intervalEnable)
                else:
                    break

        elif SysMgr.checkMode("printcg"):
            SysMgr.cgroupEnable = True
            SysMgr.printCgroupList(
                json=SysMgr.jsonEnable, ret=SysMgr.jsonEnable
            )
            SysMgr().printCgroupInfo(printTitle=False, progress=True, cmd=True)
            SysMgr.printInfoBuffer()

        elif SysMgr.getMode() in (
            "logjrl",
            "logdlt",
            "logkmsg",
            "logtrace",
            "logsys",
            "logand",
        ):
            _log_map = {
                "logjrl": "journal",
                "logdlt": "dlt",
                "logkmsg": "kmsg",
                "logtrace": "trace",
                "logsys": "syslog",
                "logand": "android",
            }
            SysMgr.doLogMode(_log_map[SysMgr.getMode()])

        elif SysMgr.getMode() in (
            "printdbus",
            "printdbusintro",
            "printdbusstat",
            "printdbussub",
            "printsdinfo",
            "printsdunit",
        ):
            cmd = SysMgr.getMode().replace("dbus", "")

            if cmd == "print":
                SysMgr.setStream()

            SysMgr.printLogo(big=True, onlyFile=True)

            if SysMgr.jsonEnable:
                if cmd == "printsdinfo":
                    cmd = "getunitlist"
                elif cmd == "printsdunit":
                    cmd = "getunitstat"

            ret = DbusMgr.runDbusSnooper(mode=cmd)

            if SysMgr.jsonEnable:
                SysMgr.printPipe(UtilMgr.convDict2Str(ret, gpretty=True))

        elif SysMgr.isPrintLogMode():
            SysMgr.setStream(cut=False)

            console = SysMgr.findOption("Q")

            if SysMgr.intervalEnable > 0:
                SysMgr.setSignal(signal.SIGALRM, SysMgr.onAlarm)
                signal.alarm(SysMgr.intervalEnable)

            SysMgr.printLogo(big=True, onlyFile=True)

            handlers = {
                "printdlt": lambda: DltAnalyzer.runDltReceiver(mode="print"),
                "printjrl": lambda: LogMgr.printJournal(console),
                "printkmsg": lambda: LogMgr.printKmsg(console),
                "printtrace": lambda: LogMgr.printTrace(console),
                "printand": lambda: LogMgr.printAndLog(console),
                "printsyslog": lambda: LogMgr.printSyslog(console),
            }
            handlers[SysMgr.getMode()]()

        elif SysMgr.checkMode("printsig"):
            SysMgr.doPrintSig()

        elif SysMgr.checkMode("printboot"):
            AndroidMgr.doPrintBoot()

        elif SysMgr.checkMode("convlog"):
            AndroidMgr.doConvLog()

        elif SysMgr.checkMode("bugrec"):
            AndroidMgr.doBugRecord(False)

        elif SysMgr.checkMode("bugrep"):
            AndroidMgr.doBugRecord(True)

