    def printHugePageInfo(self):
        if "NOHUGEPAGEINFO" in SysMgr.environList:
            return

        dpath = "/sys/kernel/mm/hugepages"
        if not os.path.exists(dpath):
            return

        lineLen = 69
        SysMgr.infoBufferPrint("\n[HugePage Info]")
