            msgqData["cbytes"] = cbytes
            msgqData["qnum"] = qnum
            msgqData["lspid"] = lspid
            msgqData["lrpid"] = lrpid
            msgqData["uid"] = uid
            msgqData["gid"] = gid
            msgqData["cuid"] = cuid
            msgqData["cgid"] = cgid
            msgqData["stime"] = stime
