                co_names,
                co_exceptiontable,
                co_flags,
                co_argcount,
                co_posonlyargcount,
                co_kwonlyargcount,
                co_stacksize,
                co_firstlineno,
                co_nlocalsplus,
                co_framesize,
                co_nlocals,
                co_ncellvars,
