    def runGfxTop(self):
        if SysMgr.hasMainArg():
            filterGroup = SysMgr.getMainArgs()
        elif SysMgr.filterGroup:
            filterGroup = SysMgr.filterGroup
        else:
            SysMgr.printErr("no input for target info")
            sys.exit(-1)

        if "TARGETCMD" in SysMgr.environList:
            filterGroup = SysMgr.getTids("|".join(filterGroup), isThread=False)

        SysMgr.startRecTime = SysMgr.getUptime()

        if SysMgr.isLinux:
            TaskAnalyzer.dbgObj = Debugger(SysMgr.pid, attach=False)
            TaskAnalyzer.dbgObj.initValues()
            TaskAnalyzer.dbgObj.getCpuUsage(system=True)

        reset = "RESET" in SysMgr.environList

        _samp_cond, _samp_idle, _samp_nr_cores = BpfMgr._initSampCond()

        while 1:
            prevTime = time.time()

            SysMgr.updateUptime()

            stats = AndroidMgr.getGfxStats(filterGroup, reset=reset)
            reset = False
            if not stats:
                SysMgr.printWarn("failed to get gfx stats", True)
            else:
                if SysMgr.gfxData:
                    SysMgr.prevGfxData = SysMgr.gfxData
                SysMgr.gfxData = stats

            if SysMgr.prevGfxData:
                _cond_met, _samp_idle = BpfMgr._checkSampCondOrSkip(
                    _samp_cond,
                    _samp_idle,
                    _samp_nr_cores,
                    SysMgr.intervalEnable,
                )
                if _cond_met:
                    diff = AndroidMgr.diffGfxStats(
                        SysMgr.prevGfxData, SysMgr.gfxData
                    )
                    AndroidMgr.printGfxStat(diff, SysMgr.gfxData)

            SysMgr.checkProgress()

            SysMgr.runProfCmd("AFTER")

            waitTime = max(
                0.000001, SysMgr.intervalEnable - (time.time() - prevTime)
            )
            if not SysMgr.waitUserInput(waitTime):
                time.sleep(waitTime)

    def runOomTop(self):
        """Real-time OOM kill risk monitor."""
        procPath = SysMgr.procPath
        convSize = UtilMgr.convSize2Unit
        convColor = UtilMgr.convColor
        readFile = SysMgr.readFile

        showCmdline = "CMDLINE" in SysMgr.environList
        cmdlineLen = 0
        if showCmdline:
            val = SysMgr.environList["CMDLINE"][0]
            if val != "SET":
                try:
                    cmdlineLen = long(val)
                except:
                    pass
        commHeader = "CMDLINE" if showCmdline else "COMM"

        prevOomKillCnt = -1

        _samp_cond, _samp_idle, _samp_nr_cores = BpfMgr._initSampCond()

        while 1:
            prevTime = time.time()
            SysMgr.updateUptime()

            memData = SysMgr.getMemDict()
            memFree = memData.get("MemFree", 0) << 10
            memAvail = (
                memData.get("MemAvailable", memData.get("MemFree", 0)) << 10
            )

            lmkLevel = "-"
            try:
                lmkBuf = readFile(SysMgr.lmkPath, verb=False)
                if lmkBuf:
                    thresholds = list(map(long, lmkBuf.strip().split(",")))
                    lmkFreeKb = thresholds[0] if thresholds else 0
                    memFreeKb = memData.get("MemFree", 0)
                    if lmkFreeKb and memFreeKb < lmkFreeKb * 2:
                        lmkLevel = "HIGH"
                    elif lmkFreeKb and memFreeKb < lmkFreeKb * 4:
                        lmkLevel = "MED"
                    else:
                        lmkLevel = "LOW"
            except:
                pass
            lmkPressure = (
                convColor(lmkLevel, "RED")
                if lmkLevel == "HIGH"
                else (
                    convColor(lmkLevel, "YELLOW")
                    if lmkLevel == "MED"
                    else (
                        convColor(lmkLevel, "GREEN")
                        if lmkLevel == "LOW"
                        else lmkLevel
                    )
                )
            )

            oomKillCnt = 0
            vmstatBuf = readFile("/proc/vmstat", verb=False)
            if vmstatBuf:
                for line in vmstatBuf.splitlines():
                    if line.startswith("oom_kill "):
                        parts = line.split()
                        if len(parts) >= 2:
                            try:
                                oomKillCnt = long(parts[1])
                            except:
                                pass
                        break
            oomKillDelta = (
                oomKillCnt - prevOomKillCnt if prevOomKillCnt >= 0 else 0
            )
            prevOomKillCnt = oomKillCnt

            procList = []
            try:
                pids = [d for d in os.listdir(procPath) if d.isdigit()]
            except:
                pids = []

            for pid in pids:
                pdir = "%s/%s" % (procPath, pid)
                try:
                    scoreBuf = readFile("%s/oom_score" % pdir, verb=False)
                    if scoreBuf is None:
                        continue
                    oomScore = long(scoreBuf)
                    adjBuf = readFile("%s/oom_score_adj" % pdir, verb=False)
                    if adjBuf is None:
                        continue
                    oomAdj = long(adjBuf)
                    if showCmdline:
                        try:
                            with open("%s/cmdline" % pdir, "rb") as f:
                                buf = f.read()
                            comm = (
                                buf.replace(b"\x00", b" ")
                                .decode("utf-8", errors="replace")
                                .strip()
                            )
                            if cmdlineLen > 0:
                                comm = comm[-cmdlineLen:]
                        except:
                            comm = pid
                    else:
                        commBuf = readFile("%s/comm" % pdir, verb=False)
                        comm = commBuf.strip() if commBuf else pid
                    if SysMgr.filterGroup and not UtilMgr.isValidStr(comm):
                        continue
                    rssMb = 0
                    statusBuf = readFile("%s/status" % pdir, verb=False)
                    if statusBuf:
                        for line in statusBuf.splitlines():
                            if line.startswith("VmRSS:"):
                                parts = line.split()
                                if len(parts) >= 2:
                                    rssMb = long(parts[1]) / 1024.0
                                break
                    if oomAdj >= 900:
                        risk = convColor("HIGH", "RED", size=4)
                        ptype = "Cached"
                    elif oomAdj >= 200:
                        risk = convColor("MED", "YELLOW", size=4)
                        ptype = "Service"
                    elif oomAdj > 0:
                        risk = "%4s" % "LOW"
                        ptype = "App"
                    else:
                        risk = "%4s" % "NONE"
                        ptype = "Critical"
                    procList.append(
                        (oomScore, pid, comm, oomAdj, rssMb, risk, ptype)
                    )
                except (SystemExit, KeyboardInterrupt):
                    raise
                except:
                    continue

            procList.sort(key=lambda x: x[0], reverse=True)

            oomDispList = procList if SysMgr.showAll else procList[:20]
            _cond_met, _samp_idle = BpfMgr._checkSampCondOrSkip(
                _samp_cond, _samp_idle, _samp_nr_cores, SysMgr.intervalEnable
            )
            if not _cond_met:
                SysMgr.checkProgress()
                SysMgr.runProfCmd("AFTER")
                waitTime = max(
                    0.000001, SysMgr.intervalEnable - (time.time() - prevTime)
                )
                if not SysMgr.waitUserInput(waitTime):
                    time.sleep(waitTime)
                continue
            if SysMgr.jsonEnable:
                jsonData = {
                    "time": SysMgr.uptime,
                    "memFree": memFree,
                    "memAvail": memAvail,
                    "lmkPressure": lmkLevel,
                    "oomKill": oomKillCnt,
                    "oomKillDelta": oomKillDelta,
                    "processes": [
                        {
                            "rank": rank,
                            "pid": pid,
                            "comm": comm,
                            "score": score,
                            "oomAdj": adj,
                            "rssMb": round(rssMb, 2),
                            "risk": risk,
                        }
                        for rank, (
                            score,
                            pid,
                            comm,
                            adj,
                            rssMb,
                            risk,
                            ptype,
                        ) in enumerate(oomDispList, 1)
                    ],
                }
                if not SysMgr.outPath and not SysMgr.streamEnable:
                    SysMgr.clearScreen()
                SysMgr.printPipe(UtilMgr.convDict2Str(jsonData, gpretty=True))
            else:
                twoLine = oneLine + "\n"
                SysMgr.clearPrint()
                if not SysMgr.outPath and not SysMgr.streamEnable:
                    SysMgr.clearScreen()
                oomKillStr = (
                    "%d (+%d)" % (oomKillCnt, oomKillDelta)
                    if oomKillDelta > 0
                    else "%d" % oomKillCnt
                )
                SysMgr.addPrint(
                    "[OOM TOP] [Time: %.1f] [MemFree: %s] [MemAvail: %s]"
                    " [LMK: %s] [OOMKill: %s]\n%s"
                    % (
                        SysMgr.uptime,
                        convSize(memFree),
                        convSize(memAvail),
                        lmkPressure,
                        oomKillStr,
                        twoLine,
                    ),
                    newline=2,
                )
                SysMgr.addPrint(
                    "%4s  %7s  %6s  %8s  %9s  %4s  %8s  %-s\n%s"
                    % (
                        "RANK",
                        "PID",
                        "SCORE",
                        "OOM_ADJ",
                        "RSS(MB)",
                        "RISK",
                        "TYPE",
                        commHeader,
                        twoLine,
                    ),
                    newline=2,
                )
                for rank, (
                    score,
                    pid,
                    comm,
                    adj,
                    rssMb,
                    risk,
                    ptype,
                ) in enumerate(oomDispList, 1):
                    ret = SysMgr.addPrint(
                        "%4d  %7s  %6d  %8d  %9.1f  %s  %8s  %s\n"
                        % (rank, pid, score, adj, rssMb, risk, ptype, comm),
                    )
                    if not ret:
                        break
                if not procList:
                    SysMgr.addPrint("  (no processes found)\n")
                SysMgr.addPrint(oneLine + "\n")
                SysMgr.doPrint()
            SysMgr.checkProgress()
            SysMgr.runProfCmd("AFTER")
            waitTime = max(
                0.000001, SysMgr.intervalEnable - (time.time() - prevTime)
            )
            if not SysMgr.waitUserInput(waitTime):
                time.sleep(waitTime)

    def runSwapTop(self):
        """Real-time swap pressure analysis."""
        procPath = SysMgr.procPath
        convSize = UtilMgr.convSize2Unit
        convColor = UtilMgr.convColor
        readFile = SysMgr.readFile

        cmdlineLen = 0
        _cmdval = SysMgr.environList.get("CMDLINE")
        if _cmdval and _cmdval[0] != "SET":
            try:
                cmdlineLen = long(_cmdval[0])
            except:
                pass
        commHeader = "COMM / CMDLINE"

        prevPswpin = 0
        prevPswpout = 0
        prevLoopTime = time.time()
        firstLoop = True

        swapout_target = None
        _so_val = SysMgr.environList.get("SWAPOUT")
        if _so_val and _so_val[0] != "SET":
            swapout_target = _so_val[0]
        elif _so_val:
            # -q SWAPOUT without target: use filterGroup or mainArg #
            if SysMgr.filterGroup:
                swapout_target = SysMgr.filterGroup[0]
            elif SysMgr.hasMainArg():
                swapout_target = SysMgr.getMainArg()

        _samp_cond, _samp_idle, _samp_nr_cores = BpfMgr._initSampCond()

        while 1:
            prevTime = time.time()
            SysMgr.updateUptime()

            if swapout_target:
                _so_tids = SysMgr.getTids(
                    swapout_target,
                    isThread=not SysMgr.processEnable,
                    sibling=SysMgr.groupProcEnable,
                )
                for _so_pid in set(_so_tids) if _so_tids else []:
                    _so_ret = SysMgr.doProcessSwapout(_so_pid, verb=False)
                    _so_comm = SysMgr.getComm(_so_pid) or str(_so_pid)
                    if _so_ret > 0:
                        SysMgr.printInfo(
                            "swapped out %s(%s): %s"
                            % (_so_comm, _so_pid, UtilMgr.convNum(_so_ret))
                        )
                    elif _so_ret == 0:
                        SysMgr.printInfo(
                            "swapped out %s(%s): clear_refs fallback"
                            % (_so_comm, _so_pid)
                        )

            elapsed = (
                prevTime - prevLoopTime
                if not firstLoop
                else SysMgr.intervalEnable
            )
            prevLoopTime = prevTime

            origBytes = 0
            comprBytes = 0
            comprRatioStr = "-"
            savedStr = "-"
            for zidx in xrange(10):
                mmStatBuf = readFile(
                    "/sys/block/zram%d/mm_stat" % zidx, verb=False
                )
                if mmStatBuf is None:
                    break
                try:
                    fields = list(map(long, mmStatBuf.split(None, 8)[:8]))
                    origBytes += fields[0]
                    comprBytes += fields[1]
                except:
                    pass
            if origBytes > 0 and comprBytes > 0:
                comprRatioStr = "%.2fx" % (origBytes / float(comprBytes))
                savedStr = convSize(origBytes - comprBytes)

            memData = SysMgr.getMemDict()
            swapTotal = memData.get("SwapTotal", 0) << 10
            swapFree = memData.get("SwapFree", 0) << 10

            pswpin = 0
            pswpout = 0
            vmstatBuf = readFile("/proc/vmstat", verb=False)
            if vmstatBuf:
                for line in vmstatBuf.splitlines():
                    parts = line.split()
                    if len(parts) >= 2:
                        if parts[0] == "pswpin":
                            pswpin = long(parts[1])
                        elif parts[0] == "pswpout":
                            pswpout = long(parts[1])

            swapInRate = (
                (pswpin - prevPswpin) / elapsed
                if not firstLoop and elapsed > 0
                else 0
            )
            swapOutRate = (
                (pswpout - prevPswpout) / elapsed
                if not firstLoop and elapsed > 0
                else 0
            )
            prevPswpin = pswpin
            prevPswpout = pswpout

            procList = []
            try:
                pids = [d for d in os.listdir(procPath) if d.isdigit()]
            except:
                pids = []

            for pid in pids:
                pdir = "%s/%s" % (procPath, pid)
                try:
                    statusBuf = readFile("%s/status" % pdir, verb=False)
                    if not statusBuf:
                        continue
                    rssMb = 0
                    swapKb = 0
                    for line in statusBuf.splitlines():
                        if line.startswith("VmRSS:"):
                            parts = line.split()
                            if len(parts) >= 2:
                                rssMb = long(parts[1]) / 1024.0
                        elif line.startswith("VmSwap:"):
                            parts = line.split()
                            if len(parts) >= 2:
                                swapKb = long(parts[1])
                    if swapKb == 0 and not SysMgr.showAll:
                        continue
                    oomAdj = 0
                    adjBuf = readFile("%s/oom_score_adj" % pdir, verb=False)
                    if adjBuf:
                        try:
                            oomAdj = long(adjBuf)
                        except:
                            pass
                    commName = SysMgr.getComm(pid) or str(pid)
                    if SysMgr.filterGroup and not UtilMgr.isValidStr(commName):
                        continue
                    cmdline = SysMgr.getCmdline(pid) or ""
                    if cmdlineLen > 0 and cmdline:
                        cmdline = cmdline[-cmdlineLen:]
                    comm = (
                        "%s / %s" % (commName, cmdline)
                        if cmdline
                        else commName
                    )
                    swapMb = swapKb / 1024.0
                    totalMb = rssMb + swapMb
                    swapPer = (swapMb / totalMb * 100) if totalMb > 0 else 0
                    if swapPer > 50:
                        pressure = convColor("HIGH", "RED", size=8)
                    elif swapPer > 20:
                        pressure = convColor("MED", "YELLOW", size=8)
                    elif swapPer > 5:
                        pressure = "%8s" % "LOW"
                    else:
                        pressure = "%8s" % "MIN"
                    procList.append(
                        (
                            swapMb,
                            pid,
                            comm,
                            rssMb,
                            swapMb,
                            swapPer,
                            pressure,
                            oomAdj,
                            totalMb,
                        )
                    )
                except (SystemExit, KeyboardInterrupt):
                    raise
                except:
                    continue

            procList.sort(key=lambda x: x[0], reverse=True)

            dispList = procList if SysMgr.showAll else procList[:20]
            _cond_met, _samp_idle = BpfMgr._checkSampCondOrSkip(
                _samp_cond, _samp_idle, _samp_nr_cores, SysMgr.intervalEnable
            )
            if not _cond_met:
                firstLoop = False
                waitTime = max(
                    0.000001, SysMgr.intervalEnable - (time.time() - prevTime)
                )
                if not SysMgr.waitUserInput(waitTime):
                    time.sleep(waitTime)
                continue
            if SysMgr.jsonEnable:
                jsonData = {
                    "time": SysMgr.uptime,
                    "swapFree": swapFree,
                    "swapTotal": swapTotal,
                    "zram": {
                        "origBytes": origBytes,
                        "comprBytes": comprBytes,
                        "ratio": comprRatioStr,
                        "savedBytes": (
                            origBytes - comprBytes
                            if origBytes > comprBytes
                            else 0
                        ),
                    },
                    "swapInRate": round(swapInRate, 2),
                    "swapOutRate": round(swapOutRate, 2),
                    "processes": [
                        {
                            "rank": rank,
                            "pid": pid,
                            "comm": comm,
                            "oomAdj": oomAdj,
                            "rssMb": round(rssMb, 2),
                            "swapMb": round(swapMb, 2),
                            "totalMb": round(totalMb, 2),
                            "swapPct": round(swapPer, 2),
                            "pressure": (
                                "HIGH"
                                if swapPer > 50
                                else (
                                    "MED"
                                    if swapPer > 20
                                    else "LOW" if swapPer > 5 else "MIN"
                                )
                            ),
                        }
                        for rank, (
                            _,
                            pid,
                            comm,
                            rssMb,
                            swapMb,
                            swapPer,
                            pressure,
                            oomAdj,
                            totalMb,
                        ) in enumerate(dispList, 1)
                    ],
                }
                if not SysMgr.outPath and not SysMgr.streamEnable:
                    SysMgr.clearScreen()
                SysMgr.printPipe(UtilMgr.convDict2Str(jsonData, gpretty=True))
            else:
                twoLine = oneLine + "\n"
                SysMgr.clearPrint()
                if not SysMgr.outPath and not SysMgr.streamEnable:
                    SysMgr.clearScreen()
                SysMgr.addPrint(
                    "[SWAP TOP] [Time: %.1f] [SwapFree: %s / %s]"
                    " [orig: %s] [comp: %s] [ratio: %s] [saved: %s]"
                    " [swapIn: %s/s] [swapOut: %s/s]\n%s"
                    % (
                        SysMgr.uptime,
                        convSize(swapFree),
                        convSize(swapTotal),
                        convSize(origBytes) if origBytes else "-",
                        convSize(comprBytes) if comprBytes else "-",
                        comprRatioStr,
                        savedStr,
                        convSize(int(swapInRate * 4096)),
                        convSize(int(swapOutRate * 4096)),
                        twoLine,
                    ),
                    newline=2,
                )
                SysMgr.addPrint(
                    "%4s  %7s  %8s  %9s  %9s  %9s  %6s  %8s  %-s\n%s"
                    % (
                        "RANK",
                        "PID",
                        "OOM_ADJ",
                        "RSS(MB)",
                        "SWAP(MB)",
                        "TOTAL(MB)",
                        "SWAP%",
                        "PRESSURE",
                        commHeader,
                        twoLine,
                    ),
                    newline=2,
                )
                for rank, (
                    _,
                    pid,
                    comm,
                    rssMb,
                    swapMb,
                    swapPer,
                    pressure,
                    oomAdj,
                    totalMb,
                ) in enumerate(dispList, 1):
                    ret = SysMgr.addPrint(
                        "%4d  %7s  %8d  %9.1f  %9.1f  %9.1f  %5.1f%%  %s  %s\n"
                        % (
                            rank,
                            pid,
                            oomAdj,
                            rssMb,
                            swapMb,
                            totalMb,
                            swapPer,
                            pressure,
                            comm,
                        ),
                    )
                    if not ret:
                        break
                if not procList:
                    SysMgr.addPrint("  (no processes using swap)\n")
                SysMgr.addPrint(oneLine + "\n")
                SysMgr.doPrint()
            SysMgr.checkProgress()
            SysMgr.runProfCmd("AFTER")
            firstLoop = False
            waitTime = max(
                0.000001, SysMgr.intervalEnable - (time.time() - prevTime)
            )
            if not SysMgr.waitUserInput(waitTime):
                time.sleep(waitTime)

    def runLeakTop(self):
        """Memory leak detector - tracks monotonically increasing RSS and swap."""
        from collections import deque

        procPath = SysMgr.procPath
        convColor = UtilMgr.convColor
        readFile = SysMgr.readFile

        showTotal = "TOTAL" in SysMgr.environList
        try:
            window = long(SysMgr.environList.get("WINDOW", ["12"])[0])
        except:
            window = 12

        showPlateau = "PLATEAU" in SysMgr.environList
        try:
            plateauN = long(SysMgr.environList.get("PLATEAU", ["5"])[0])
            if plateauN < 2:
                plateauN = 2
        except:
            plateauN = 5

        showCmdline = "CMDLINE" in SysMgr.environList
        cmdlineLen = 0
        if showCmdline:
            val = SysMgr.environList["CMDLINE"][0]
            if val != "SET":
                try:
                    cmdlineLen = long(val)
                except:
                    pass
        commHeader = "CMDLINE" if showCmdline else "COMM"

        leakHistory = {}
        leakComm = {}

        _samp_cond, _samp_idle, _samp_nr_cores = BpfMgr._initSampCond()

        while 1:
            prevTime = time.time()
            SysMgr.updateUptime()

            curTimestamp = prevTime

            try:
                pids = [d for d in os.listdir(procPath) if d.isdigit()]
            except:
                pids = []

            activePids = set()
            for pid in pids:
                pdir = "%s/%s" % (procPath, pid)
                try:
                    statusBuf = readFile("%s/status" % pdir, verb=False)
                    if not statusBuf:
                        continue
                    rssMb = 0
                    swapMb = 0
                    vssMb = 0
                    for line in statusBuf.splitlines():
                        if line.startswith("VmRSS:"):
                            parts = line.split()
                            if len(parts) >= 2:
                                rssMb = long(parts[1]) / 1024.0
                        elif line.startswith("VmSwap:"):
                            parts = line.split()
                            if len(parts) >= 2:
                                swapMb = long(parts[1]) / 1024.0
                        elif line.startswith("VmSize:"):
                            parts = line.split()
                            if len(parts) >= 2:
                                vssMb = long(parts[1]) / 1024.0
                    if rssMb == 0:
                        continue
                    if showCmdline:
                        try:
                            with open("%s/cmdline" % pdir, "rb") as f:
                                buf = f.read()
                            comm = (
                                buf.replace(b"\x00", b" ")
                                .decode("utf-8", errors="replace")
                                .strip()
                            )
                            if cmdlineLen > 0:
                                comm = comm[-cmdlineLen:]
                        except:
                            comm = pid
                    else:
                        commBuf = readFile("%s/comm" % pdir, verb=False)
                        comm = commBuf.strip() if commBuf else pid
                    if SysMgr.filterGroup and not UtilMgr.isValidStr(comm):
                        continue
                    if pid not in leakHistory:
                        leakHistory[pid] = deque(maxlen=window)
                    leakHistory[pid].append(
                        (rssMb, swapMb, vssMb, curTimestamp)
                    )
                    leakComm[pid] = comm
                    activePids.add(pid)
                except (SystemExit, KeyboardInterrupt):
                    raise
                except:
                    continue

            for pid in list(leakHistory.keys()):
                if pid not in activePids:
                    del leakHistory[pid]
                    leakComm.pop(pid, None)

            leakList = []
            for pid, history in leakHistory.items():
                if len(history) < (2 if showTotal else 3):
                    continue
                samples = [r for r, s, v, t in history]
                n = len(samples)
                mono = sum(
                    1 for i in xrange(1, n) if samples[i] >= samples[i - 1]
                )
                confidence = mono / float(n - 1)
                if not SysMgr.showAll and confidence < 0.7:
                    continue
                firstRss, firstSwap, firstVss, firstTime = history[0]
                lastRss, lastSwap, lastVss, lastTime = history[-1]
                elapsed = lastTime - firstTime
                if elapsed <= 0:
                    continue
                growthPerMin = (lastRss - firstRss) / elapsed * 60.0
                totalGrowth = lastRss - firstRss
                vssGrowthPerMin = (lastVss - firstVss) / elapsed * 60.0
                vssTotalGrowth = lastVss - firstVss
                if showTotal:
                    sortKey = abs(totalGrowth)
                else:
                    if not SysMgr.showAll and growthPerMin <= 0:
                        continue
                    sortKey = growthPerMin
                confStr = "%d/%d" % (mono, n - 1)
                if confidence >= 0.9:
                    confLevelStr = "HIGH"
                    confLevel = convColor("HIGH", "RED")
                elif confidence >= 0.75:
                    confLevelStr = "MED"
                    confLevel = convColor("MED ", "YELLOW")
                else:
                    confLevelStr = "LOW"
                    confLevel = "LOW "
                leakList.append(
                    (
                        sortKey,
                        pid,
                        leakComm.get(pid, pid),
                        growthPerMin,
                        totalGrowth,
                        vssGrowthPerMin,
                        vssTotalGrowth,
                        confStr,
                        confLevel,
                        confLevelStr,
                        lastRss,
                        lastSwap,
                        lastVss,
                    )
                )

            leakList.sort(key=lambda x: x[0], reverse=True)

            plateauList = []
            if showPlateau:
                for pid, history in leakHistory.items():
                    if len(history) < plateauN + 1:
                        continue
                    recent = [r for r, s, v, t in list(history)[-plateauN:]]
                    rng = max(recent) - min(recent)
                    meanRss = sum(recent) / len(recent)
                    if meanRss <= 0 or rng / meanRss >= 0.02:
                        continue  # still varying, not plateau
                    firstRss = history[0][0]
                    totalGrowth = meanRss - firstRss
                    if totalGrowth < 5.0:
                        continue  # never grew significantly
                    lastRss, lastSwap, lastVss, _ = history[-1]
                    plateauList.append(
                        (
                            totalGrowth,
                            pid,
                            leakComm.get(pid, pid),
                            lastRss,
                            lastSwap,
                            lastVss,
                            plateauN,
                        )
                    )
                plateauList.sort(key=lambda x: x[0], reverse=True)

            growthHeader = "GROWTH/tot" if showTotal else "GROWTH/min"
            dispList = leakList if SysMgr.showAll else leakList[:20]
            _cond_met, _samp_idle = BpfMgr._checkSampCondOrSkip(
                _samp_cond, _samp_idle, _samp_nr_cores, SysMgr.intervalEnable
            )
            if not _cond_met:
                waitTime = max(
                    0.000001, SysMgr.intervalEnable - (time.time() - prevTime)
                )
                if not SysMgr.waitUserInput(waitTime):
                    time.sleep(waitTime)
                continue
            if SysMgr.jsonEnable:
                jsonData = {
                    "time": SysMgr.uptime,
                    "interval": float(SysMgr.intervalEnable),
                    "window": window,
                    "mode": "total" if showTotal else "perMin",
                    "processes": [
                        {
                            "rank": rank,
                            "pid": pid,
                            "comm": comm,
                            "growthPerMin": round(growthPerMin, 3),
                            "totalGrowth": round(totalGrowth, 3),
                            "vssGrowthPerMin": round(vssGpm, 3),
                            "vssTotalGrowth": round(vssTg, 3),
                            "confidence": confStr,
                            "confidenceLevel": confLevelStr,
                            "vssMb": round(vss, 2),
                            "rssMb": round(rss, 2),
                            "swapMb": round(swap, 2),
                        }
                        for rank, (
                            _,
                            pid,
                            comm,
                            growthPerMin,
                            totalGrowth,
                            vssGpm,
                            vssTg,
                            confStr,
                            confLevel,
                            confLevelStr,
                            rss,
                            swap,
                            vss,
                        ) in enumerate(dispList, 1)
                    ],
                }
                if showPlateau and plateauList:
                    jsonData["plateauProcesses"] = [
                        {
                            "rank": rank,
                            "pid": pid,
                            "comm": comm,
                            "totalGrowthMb": round(tg, 2),
                            "rssMb": round(rss, 2),
                            "swapMb": round(swap, 2),
                            "vssMb": round(vss, 2),
                            "stableIntervals": pn,
                        }
                        for rank, (
                            tg,
                            pid,
                            comm,
                            rss,
                            swap,
                            vss,
                            pn,
                        ) in enumerate(plateauList, 1)
                    ]
                if not SysMgr.outPath and not SysMgr.streamEnable:
                    SysMgr.clearScreen()
                SysMgr.printPipe(UtilMgr.convDict2Str(jsonData, gpretty=True))
            else:
                twoLine = oneLine + "\n"
                SysMgr.clearPrint()
                if not SysMgr.outPath and not SysMgr.streamEnable:
                    SysMgr.clearScreen()
                SysMgr.addPrint(
                    "[LEAK TOP] [Time: %.1f] [interval: %.1fs] [window: %d]\n%s"
                    % (
                        SysMgr.uptime,
                        float(SysMgr.intervalEnable),
                        window,
                        twoLine,
                    ),
                    newline=2,
                )
                SysMgr.addPrint(
                    "%4s  %7s  %12s  %10s  %9s  %9s  %9s  %-s\n%s"
                    % (
                        "RANK",
                        "PID",
                        growthHeader,
                        "CONFIDENCE",
                        "VSS(MB)",
                        "RSS(MB)",
                        "SWAP(MB)",
                        commHeader,
                        twoLine,
                    ),
                    newline=2,
                )
                for rank, (
                    _,
                    pid,
                    comm,
                    growthPerMin,
                    totalGrowth,
                    vssGpm,
                    vssTg,
                    confStr,
                    confLevel,
                    confLevelStr,
                    rss,
                    swap,
                    vss,
                ) in enumerate(dispList, 1):
                    growthVal = "%+9.2f MB" % (
                        totalGrowth if showTotal else growthPerMin
                    )
                    confDisplay = "%5s %s" % (confStr, confLevel)
                    ret = SysMgr.addPrint(
                        "%4d  %7s  %s  %s  %9.1f  %9.1f  %9.1f  %s\n"
                        % (
                            rank,
                            pid,
                            growthVal,
                            confDisplay,
                            vss,
                            rss,
                            swap,
                            comm,
                        ),
                    )
                    if not ret:
                        break
                if not leakList:
                    minSamples = 2 if showTotal else 3
                    SysMgr.addPrint(
                        "  (collecting samples... need at least %d intervals)\n"
                        % minSamples
                    )
                if showPlateau and plateauList:
                    SysMgr.addPrint(
                        "\n[PLATEAU] (stable ≥%d intervals, grew >5MB total)\n%s"
                        % (plateauN, twoLine),
                        newline=2,
                    )
                    SysMgr.addPrint(
                        "%4s  %7s  %10s  %9s  %9s  %9s  %-s\n%s"
                        % (
                            "RANK",
                            "PID",
                            "GREW(MB)",
                            "VSS(MB)",
                            "RSS(MB)",
                            "SWAP(MB)",
                            commHeader,
                            twoLine,
                        ),
                        newline=2,
                    )
                    for rank, (tg, pid, comm, rss, swap, vss, pn) in enumerate(
                        plateauList[:20], 1
                    ):
                        ret = SysMgr.addPrint(
                            "%4d  %7s  %+10.2f  %9.1f  %9.1f  %9.1f  %s\n"
                            % (rank, pid, tg, vss, rss, swap, comm)
                        )
                        if not ret:
                            break
                    SysMgr.addPrint(oneLine + "\n")
                else:
                    SysMgr.addPrint(oneLine + "\n")
                SysMgr.doPrint()
            SysMgr.checkProgress()
            SysMgr.runProfCmd("AFTER")
            waitTime = max(
                0.000001, SysMgr.intervalEnable - (time.time() - prevTime)
            )
            if not SysMgr.waitUserInput(waitTime):
                time.sleep(waitTime)

    def runCgTop(self):
        cgroupPath = SysMgr.sysInstance.getCgroupPath()
        if not cgroupPath:
            cgroupPath = SysMgr.sysInstance.getCgroupPath(
                "cgroup2", force=True, save=True
            )
            if not cgroupPath:
                SysMgr.printCgroupList()
                SysMgr.printErr("failed to access cgroup filesystem")
                sys.exit(-1)
            SysMgr.printWarn("no cgroup v1 filesystem, using cgroup v2", True)

        disOpt = SysMgr.getOption("d") or ""
        targetGroup = []
        if "c" not in disOpt:
            targetGroup += ["cpu", "cpuacct"]
        if "m" not in disOpt:
            targetGroup.append("memory")
        if "b" not in disOpt:
            targetGroup.append("blkio")

        for item in list(targetGroup):
            if not SysMgr.checkCgroup(item):
                targetGroup.remove(item)
        if not targetGroup:
            if SysMgr.sysInstance.getCgroupPath(
                "cgroup2", force=True, save=False
            ):
                SysMgr.printWarn("no mounted cgroup v1 subsystem", True)
            else:
                SysMgr.printErr("no mounted cgroup subsystem")
                sys.exit(-1)

        targetGroup.sort()

        SysMgr.printInfo(
            "enabled cgroup subsystems [ %s ]"
            % (", ".join(targetGroup) if targetGroup else "cgroup2")
        )

        _samp_cond, _samp_idle, _samp_nr_cores = BpfMgr._initSampCond()

        while 1:
            self.saveSystemStat(saveProc=False)

            self.saveCgroupStat(targetGroup)

            prevTime = time.time()

            if self.prevCpuData:
                _cond_met, _samp_idle = BpfMgr._checkSampCondOrSkip(
                    _samp_cond,
                    _samp_idle,
                    _samp_nr_cores,
                    SysMgr.intervalEnable,
                )
                if _cond_met:
                    self.printSystemStat(idIndex=True, targetList=["cgroup"])

            SysMgr.checkProgress()

            self.reinitStats()

            SysMgr.runProfCmd("AFTER")

            waitTime = max(
                0.000001, SysMgr.intervalEnable - (time.time() - prevTime)
            )
            if not SysMgr.waitUserInput(waitTime):
                time.sleep(waitTime)

    def runFileTop(self):
        def _getFilter(init=False):
            procFilter = []
            fileFilter = []

            if not SysMgr.filterGroup:
                return [procFilter, fileFilter]

            newFilter = ",".join(SysMgr.filterGroup)
            newFilter = newFilter.split(":", 1)

            for pval in newFilter[0].split(","):
                if pval != "":
                    procFilter.append(pval)

            if len(newFilter) > 1:
                for fval in newFilter[1].split(","):
                    if fval != "":
                        fileFilter.append(fval)

            if init and len(procFilter) > 0:
                SysMgr.printInfo(
                    "only specific processes including [ %s ] are shown"
                    % ", ".join(procFilter)
                )

            if init and len(fileFilter) > 0:
                SysMgr.printInfo(
                    "only specific files including [ %s ] are shown"
                    % ", ".join(fileFilter)
                )

            return [procFilter, fileFilter]

        if SysMgr.isLinux:
            SysMgr.checkRootPerm()

            if not os.path.isdir(SysMgr.procPath):
                SysMgr.printErr("failed to access to procfs")
                sys.exit(-1)

            TaskAnalyzer.dbgObj = Debugger(SysMgr.pid, attach=False)
            TaskAnalyzer.dbgObj.initValues()
            TaskAnalyzer.dbgObj.getCpuUsage(system=True)

            if SysMgr.inputParam:
                SysMgr.filterGroup = SysMgr.createWatchList()

        if not SysMgr.outPath:
            SysMgr.getPkg("select", False)

        prevFilter = []

        SysMgr.progressCnt = 1

        printFlag = "PRINTDELAY" in SysMgr.environList

        _samp_cond, _samp_idle, _samp_nr_cores = BpfMgr._initSampCond()

        while 1:
            prevTime = time.time()

            if prevFilter != SysMgr.filterGroup:
                nowFilter = _getFilter(True)
                prevFilter = SysMgr.filterGroup
            else:
                nowFilter = _getFilter()

            if printFlag:
                UtilMgr.saveTime()
            self.saveFileStat(nowFilter)
            if printFlag:
                UtilMgr.printTime("saveFileStat")

            _cond_met, _samp_idle = BpfMgr._checkSampCondOrSkip(
                _samp_cond, _samp_idle, _samp_nr_cores, SysMgr.intervalEnable
            )

            if printFlag and _cond_met:
                UtilMgr.saveTime()
            if _cond_met:
                self.printFileStat(nowFilter)
                if printFlag:
                    UtilMgr.printTime("printFileStat")

            SysMgr.udpListCache = {}
            SysMgr.tcpListCache = {}
            SysMgr.udsListCache = {}

            SysMgr.checkProgress()

            if printFlag:
                UtilMgr.saveTime()
            self.saveProcInstance()
            if printFlag:
                UtilMgr.printTime("saveProcInstance")

            self.reinitStats()

            SysMgr.runProfCmd("AFTER")

            waitTime = max(
                0.000001, SysMgr.intervalEnable - (time.time() - prevTime)
            )
            if not SysMgr.waitUserInput(waitTime, msg="DEFAULT"):
                time.sleep(waitTime)

    def runTaskTopGen(self):
        if not SysMgr.outPath:
            SysMgr.getPkg("select", False)

        printFlag = "PRINTDELAY" in SysMgr.environList

        _samp_cond, _samp_idle, _samp_nr_cores = BpfMgr._initSampCond()

        while 1:
            if printFlag:
                UtilMgr.saveTime()
            self.saveSystemStatGen()
            if printFlag:
                UtilMgr.printTime("saveSystemStatGen")

            prevTime = time.time()

            if SysMgr.totalEnable and not self.prevCpuData:
                SysMgr.progressCnt += 1
                self.reinitStats()
                self.saveSystemStatGen()

            if self.prevCpuData:
                _cond_met, _samp_idle = BpfMgr._checkSampCondOrSkip(
                    _samp_cond,
                    _samp_idle,
                    _samp_nr_cores,
                    SysMgr.intervalEnable,
                )
                if _cond_met:
                    if printFlag:
                        UtilMgr.saveTime()

                    self.printSystemStatGen(idIndex=True)

                    self.checkTermCond()

                    if SysMgr.elasticEnable:
                        self.reportSystemStatElastic()
                    elif SysMgr.reportEnable:
                        self.reportSystemStat()

                    if printFlag:
                        UtilMgr.printTime("printSystemStatGen")

            SysMgr.checkProgress()

            self.reinitStats()

            waitTime = max(
                0.000001, SysMgr.intervalEnable - (time.time() - prevTime)
            )
            if not SysMgr.waitUserInput(waitTime):
                time.sleep(waitTime)

    def runTaskTop(self):
        if not os.path.isdir(SysMgr.procPath):
            SysMgr.printErr("failed to access procfs")
            sys.exit(-1)

        if not SysMgr.outPath:
            SysMgr.getPkg("select", False)

        SysMgr.initSystemPerfEvents()

        if SysMgr.inputParam:
            watchList = SysMgr.createWatchList()

            SysMgr.filterGroup = watchList
            if not SysMgr.processEnable:
                SysMgr.groupProcEnable = True

            SysMgr.addEnvironVar("EXITCONDTERM", watchList)

        printFlag = "PRINTDELAY" in SysMgr.environList

        self.checkStartMonCond()

        if "PRINTCG" in SysMgr.environList:
            cgroupPath = SysMgr.sysInstance.getCgroupPath()
            if not cgroupPath:
                SysMgr.printCgroupList()
                SysMgr.printErr("failed to access cgroup filesystem")
                sys.exit(-1)

            SysMgr.checkCgroup()

            targetGroup = SysMgr.environList["PRINTCG"][0]
            if targetGroup == "SET":
                targetGroup = ["cpu", "cpuacct"]
            elif targetGroup.upper() == "ALL":
                targetGroup = []
            else:
                targetGroup = UtilMgr.cleanItem(targetGroup.split("+"))
                if "cpu" in targetGroup:
                    targetGroup += ["cpuacct"]
                targetGroup = list(set(targetGroup))

            if not SysMgr.sort and "cpu" not in targetGroup:
                SysMgr.sort = False

            targetList = ["task", "cgroup"]

            printCg = True
        else:
            targetList = ["task"]

            printCg = False

        if SysMgr.dbusUnitEnable:
            DbusMgr.pidUnitList = DbusMgr.runDbusSnooper(mode="getpidlist")

        NetworkMgr.execReceiverTask()

        if "DROPFILECACHE" in SysMgr.environList:
            SysMgr.dropFileCaches(SysMgr.pid)

        SysMgr.startRecTime = SysMgr.getUptime()

        # parse SWAPOUT option once before the loop #
        swapout_target = None
        _so_val = SysMgr.environList.get("SWAPOUT")
        if _so_val and _so_val[0] != "SET":
            swapout_target = _so_val[0]
        elif _so_val:
            if SysMgr.filterGroup:
                swapout_target = SysMgr.filterGroup[0]
            elif SysMgr.hasMainArg():
                swapout_target = SysMgr.getMainArg()

        # parse sampling condition options once #
        _samp_cond, _samp_idle, _samp_nr_cores = BpfMgr._initSampCond()

        while 1:
            if SysMgr.remoteServObj:
                ret = SysMgr.localServObj.recvfrom()

                self.handleServerResponse(ret)

                continue

            if SysMgr.skipCnt:
                SysMgr.skipCnt -= 1
                self.reinitStats()
                time.sleep(SysMgr.intervalEnable)
                SysMgr.updateUptime()
                continue

            if swapout_target:
                _so_tids = SysMgr.getTids(
                    swapout_target,
                    isThread=not SysMgr.processEnable,
                    sibling=SysMgr.groupProcEnable,
                )
                for _so_pid in set(_so_tids) if _so_tids else []:
                    _so_ret = SysMgr.doProcessSwapout(_so_pid, verb=False)
                    _so_comm = SysMgr.getComm(_so_pid) or str(_so_pid)
                    if _so_ret > 0:
                        SysMgr.printInfo(
                            "swapped out %s(%s): %s"
                            % (_so_comm, _so_pid, UtilMgr.convNum(_so_ret))
                        )
                    elif _so_ret == 0:
                        SysMgr.printInfo(
                            "swapped out %s(%s): clear_refs fallback"
                            % (_so_comm, _so_pid)
                        )

            if printFlag:
                UtilMgr.saveTime()
            self.saveSystemStat()
            if printFlag:
                UtilMgr.printTime("saveSystemStat")

            if printCg:
                self.saveCgroupStat(targetGroup)
                if printFlag:
                    UtilMgr.printTime("saveCgroupStat")

            prevTime = time.time()

            if SysMgr.totalEnable and not self.prevCpuData:
                SysMgr.progressCnt += 1
                self.reinitStats()
                self.saveSystemStat()

            if self.prevCpuData:
                _cond_met, _samp_idle = BpfMgr._checkSampCondOrSkip(
                    _samp_cond,
                    _samp_idle,
                    _samp_nr_cores,
                    SysMgr.intervalEnable,
                )
                if _cond_met:
                    if printFlag:
                        UtilMgr.saveTime()

                    self.printSystemStat(idIndex=True, targetList=targetList)

                    self.checkTermCond()

                    if SysMgr.elasticEnable:
                        self.reportSystemStatElastic()
                    elif SysMgr.reportEnable:
                        self.reportSystemStat()

                    if printFlag:
                        UtilMgr.printTime("printSystemStat")

            SysMgr.checkProgress()

            self.reinitStats()

            SysMgr.runProfCmd("AFTER")

            waitTime = max(
                0.000001, SysMgr.intervalEnable - (time.time() - prevTime)
            )
            if SysMgr.stackEnable and self.stackTable:
                self.sampleStack(waitTime)
                SysMgr.waitUserInput(0.000001)
            elif not SysMgr.waitUserInput(waitTime):
                time.sleep(waitTime)

            self.checkServer()

    def saveCgroupInstance(self):
        del self.prevCgroupData
        self.prevCgroupData = self.cgroupData
        self.cgroupData = {}
        SysMgr.topInstance = self
        SysMgr.procInstance = self.procData

    def saveProcInstance(self):
        for pid in set(self.prevProcData) - set(self.procData):
            try:
                os.close(self.procFdData.pop(pid, None))
            except SystemExit:
                sys.exit(0)
            except:
                pass

        self.prevProcData = self.procData
        self.procData = {}
        self.fixedProcData = {}
        SysMgr.topInstance = self
        SysMgr.procInstance = self.procData

    def reinitStats(self):
        self.oldCpuData = self.prevCpuData
        self.prevCpuData = self.cpuData
        self.cpuData = {}
        self.fileData = {}
        self.abnormalTasks = {}
        self.nsData = {}
        self.nsProcData = {}
        self.binderData = {}
        self.windowData = {}
        self.nrPrevThread = self.nrThread
        self.nrPrevProcess = self.nrProcess
        self.nrThread = 0
        self.nrProcess = 0
        self.nrFd = 0
        SysMgr.jsonData = {}

    @staticmethod
    def applyPrintCond():
        _floatCondKeys = frozenset(
            ("PSICPUCOND", "LOADCOND", "GPUCOND", "UPTIMEDIFFCOND", "TEMPCOND")
        )
        for env in list(SysMgr.printCond):
            if env not in SysMgr.environList:
                continue

            if env in _floatCondKeys:
                SysMgr.printCond[env] = UtilMgr.getEnvironNum(
                    env, False, None, False, isFloat=True
                )
            else:
                SysMgr.printCond[env] = UtilMgr.getEnvironNum(env)
            if SysMgr.printCond[env]:
                SysMgr.reportEnable = True

    @staticmethod
    def getStatsFile(
        logFile, handle=None, applyOpt=True, onlyStart=False, verb=False
    ):
        path = None
        infoBuf = None
        chartStats = {}
        timeline = []
        eventList = []
        eventData = []

        cpuUsage = []
        nrCore = []
        stealUsage = []
        nrTask = []
        memFree = []
        memAnon = []
        memCache = []
        memKernel = []
        swapUsage = []
        reclaimBg = []
        reclaimDr = []
        blkWait = []
        blkRead = []
        blkWrite = []
        netRead = []
        netWrite = []
        gpuUsage = {}
        psiUsage = {}
        mdUsage = {}
        coreUsage = {}
        cpuProcUsage = {}
        cpuProcDelay = {}
        cpuProcPrio = {}
        memProcUsage = {}
        blkProcUsage = {}
        storageUsage = {}
        networkUsage = {}
        newStats = {}
        termStats = {}

        try:
            if handle:
                fd = handle
            else:
                fd = UtilMgr.getTextLines(logFile, verb=verb, retfd=True)
        except SystemExit:
            sys.exit(0)
        except:
            SysMgr.printErr("failed to read '%s'\n" % logFile)
            sys.exit(-1)

        if "TOPSUM" in SysMgr.environList:
            SysMgr.reloadFileBuffer(path=fd.name, fd=fd if handle else None)

            idx = 0
            for idx, item in enumerate(SysMgr.procBuffer):
                if item.lstrip("\n ").startswith("[Top Info]"):
                    break
            metaData = SysMgr.procBuffer[:idx]
            SysMgr.procBuffer = SysMgr.procBuffer[idx:]

            try:
                metaData = "\n".join(metaData).split("\n")
            except SystemExit:
                sys.exit(0)
            except:
                SysMgr.printErr("failed to split meta data", True)

            for line in metaData:
                try:
                    if not line:
                        continue
                    elif not SysMgr.sysinfoBuffer and line.startswith(
                        "[System General Info]"
                    ):
                        infoBuf = ""
                    elif infoBuf is not None:
                        if line.startswith("["):
                            SysMgr.sysinfoBuffer = infoBuf
                            if applyOpt:
                                SysMgr.applyLaunchOption()
                            infoBuf = None
                            continue
                        elif line[0] in ("=", " "):
                            continue
                        else:
                            if not line.endswith("\n"):
                                line += "\n"
                            infoBuf += line
                            continue
                except SystemExit:
                    sys.exit(0)
                except:
                    SysMgr.printErr(
                        "failed to read system info from '%s'" % line, True
                    )

            origFd = SysMgr.printFd

            SysMgr.printFd = MemoryFile(name="buf")

            TaskAnalyzer.printIntervalUsage(current=False)

            fd = SysMgr.printFd
            fd.seek(0)

            SysMgr.printFd = origFd

        totalSize = 0
        if not handle:
            fsize = UtilMgr.getFileSizeStr(logFile)
            SysMgr.printStat(r"start processing '%s'%s..." % (logFile, fsize))

        context = None
        totalRam = None
        totalSwap = None
        startTime = 0
        blkTotal = 0

        envList = SysMgr.environList
        nocgcpu = "NOCGCPU" in envList
        nocgthrottle = "NOCGTHROTTLE" in envList
        nocgmem = "NOCGMEM" in envList
        nocgblk = "NOCGBLK" in envList
        norecfile = "NORECFILE" in envList
        recfileFilter = envList.get("RECFILEFILTER")
        lifeEvent = "LIFEEVENT" in SysMgr.environList
        nolifestat = "LIFESTAT" not in SysMgr.environList
        cleanChar = "CLEANCHAR" in SysMgr.environList

        convSize = UtilMgr.convUnit2Size

        def _parseNetUnit(s):
            unit = s[-1]
            val = long(s[:-1])
            if unit == "T":
                return val << 30
            elif unit == "G":
                return val << 20
            elif unit == "M":
                return val << 10
            elif unit == "K":
                return val
            return 0

        commLen = SysMgr.environList.get("COMMLEN", [None])[0]
        if commLen:
            commLen = long(commLen)

        try:
            isCompressed = UtilMgr.isCompressed(fd.name)
        except SystemExit:
            sys.exit(0)
        except:
            isCompressed = False

        curSize = 0
        for idx, line in enumerate(fd):
            if not line and fd.size <= curSize:
                break

            if isCompressed:
                try:
                    line = line.decode()
                except SystemExit:
                    sys.exit(0)
                except:
                    pass

            curSize += len(line) + 1
            UtilMgr.printProgress(curSize, totalSize)

            if cleanChar:
                line = UtilMgr.removeColor(line)
                line = SysMgr.convExtAscii(line, True)

            try:
                if not SysMgr.sysinfoBuffer and line.startswith(
                    "[System General Info]"
                ):
                    infoBuf = ""
                elif infoBuf is not None:
                    if line.startswith("["):
                        SysMgr.sysinfoBuffer = infoBuf
                        if applyOpt:
                            SysMgr.applyLaunchOption()
                        infoBuf = None
                        continue
                    elif line[0] in ("=", " "):
                        continue
                    else:
                        if not line.endswith("\n"):
                            line += "\n"
                        infoBuf += line
                        continue
            except SystemExit:
                sys.exit(0)
            except:
                SysMgr.printErr(
                    "failed to read system info from '%s'" % fd.name, True
                )
                break

            sline = line.split("|")
            slen = len(sline)

            if line.startswith("[Top "):
                pid = 0
                maxVss = 0
                maxRss = 0
                pname = None
                gname = None
                mpath = None
                intervalList = None

                contextList = line.split()
                context = contextList[1]

                if len(contextList) > 10 and context not in ("MemDump",):
                    strPos = line.find("[RAM")
                    sline = line[strPos:].split()

                    try:
                        totalRam = convSize(sline[1].rstrip(" ]"))
                    except:
                        pass

                    try:
                        totalSwap = convSize(sline[3].rstrip(" ]"))
                    except:
                        totalSwap = None

                    break

            if context == "Summary":
                nrStatistics = 15

                if slen < nrStatistics:
                    continue

                try:
                    idx = long(sline[0])
                except:
                    continue

                try:
                    tick = long(float(sline[1].split("-")[1]))
                    timeline.append(tick)
                    if not startTime and tick:
                        startTime = tick
                        if onlyStart:
                            return {"start": tick}, {}
                except:
                    timeline.append(0)

                eventList.append(list())

                try:
                    cpuUsage.append(long(sline[2]))
                except:
                    cpuUsage.append(0)

                try:
                    memStat = sline[3].split("/", 4)

                    if len(memStat) > 4:
                        raise Exception()

                    memFree.append(long(memStat[0]))
                    memAnon.append(long(memStat[1]))
                    memCache.append(long(memStat[2]))
                    try:
                        memKernel.append(long(memStat[3]))
                    except:
                        memKernel.append(0)
                except:
                    # for backward compatibility #
                    try:
                        memFree.append(long(sline[3]))
                    except:
                        memFree.append(0)
                    memAnon.append(0)
                    memCache.append(0)
                    memKernel.append(0)

                try:
                    blkWait.append(long(sline[5]))
                except:
                    blkWait.append(0)

                try:
                    swapUsage.append(long(sline[6]))
                except:
                    swapUsage.append(0)

                try:
                    reclaim = sline[7].strip().split("/", 1)
                    reclaimBg.append(long(reclaim[0]) << 2)
                    reclaimDr.append(long(reclaim[1]) << 2)
                except:
                    reclaimBg.append(0)
                    reclaimDr.append(0)

                try:
                    blkUsage = sline[4].split("/", 1)
                    blkRead.append(long(blkUsage[0]) << 10)
                    blkWrite.append(long(blkUsage[1]) << 10)
                except:
                    blkRead.append(0)
                    blkWrite.append(0)

                try:
                    nrTask.append(sline[11])
                except:
                    nrTask.append("")

                try:
                    nrCore.append(long(sline[12]))
                except:
                    nrCore.append(0)

                try:
                    netstat = sline[13].strip().split("/", 1)

                    if netstat[0] == "-":
                        raise Exception()

                    netRead.append(_parseNetUnit(netstat[0]))
                    netWrite.append(_parseNetUnit(netstat[1]))
                except:
                    netRead.append(0)
                    netWrite.append(0)

            elif context in ("CPU", "Delay", "Prio"):
                if slen == 3:
                    m = re.match(r"\s*(?P<comm>.+?)\(\s*(?P<pid>[0-9]+)", line)
                    if not m:
                        continue

                    d = m.groupdict()
                    comm = d["comm"].strip()[:commLen]

                    if SysMgr.filterGroup:
                        if not TaskAnalyzer.checkFilter(comm, d["pid"]):
                            intervalList = None
                        else:
                            pid = d["pid"]
                            pname = "%s(%s)" % (comm, pid)

                            intervalList = sline[2]
                    else:
                        pid = d["pid"]
                        pname = "%s(%s)" % (comm, pid)

                        intervalList = sline[2]
                elif slen == 2:
                    if intervalList:
                        intervalList += sline[1]
                elif intervalList:
                    if context == "CPU":
                        statList = cpuProcUsage
                        convFunc = long
                        hasTotal = True
                    elif context == "Delay":
                        statList = cpuProcDelay
                        convFunc = long
                        hasTotal = True
                    else:
                        statList = cpuProcPrio
                        convFunc = lambda e: e
                        hasTotal = False

                    statList[pname] = {}
                    statList[pname]["pid"] = pid

                    start = -1
                    finish = -1
                    zombie = -1
                    intervalList = intervalList.split()
                    for cidx, item in enumerate(list(intervalList)):
                        if item.startswith("+"):
                            start = cidx
                        elif item.startswith("-"):
                            finish = cidx
                        elif item.startswith("z"):
                            zombie = cidx
                        else:
                            continue
                        intervalList[cidx] = item[1:]

                    cpuList = list(map(convFunc, intervalList))
                    intervalList = " ".join(intervalList)

                    statList[pname]["usage"] = intervalList
                    intervalList = None

                    if start > -1:
                        statList[pname]["start"] = start
                    if finish > -1:
                        statList[pname]["finish"] = finish
                    if zombie > -1:
                        statList[pname]["zombie"] = zombie

                    if not hasTotal:
                        statList[pname]["usage"] = cpuList
                        continue

                    if TaskAnalyzer.checkFilter(comm, pid):
                        tname = "[ TOTAL ]"

                        if tname not in statList:
                            statList[tname] = {
                                "count": 0,
                                "usage": "0 " * len(cpuList),
                            }

                        pstats = statList[tname]["usage"].split()
                        ftotal = list(map(long, pstats))

                        for cidx in xrange(len(cpuList)):
                            ftotal[cidx] += cpuList[cidx]

                        statList[tname]["count"] += 1
                        usageList = " ".join(list(map(str, ftotal)))
                        statList[tname]["usage"] = usageList
                        statList[tname]["minimum"] = min(ftotal)
                        statList[tname]["average"] = UtilMgr.getAvg(ftotal)
                        statList[tname]["maximum"] = max(ftotal)

                    if not cpuList:
                        statList[pname]["minimum"] = 0
                        statList[pname]["average"] = 0
                        statList[pname]["maximum"] = 0
                    else:
                        statList[pname]["minimum"] = min(cpuList)
                        statList[pname]["average"] = UtilMgr.getAvg(cpuList)
                        statList[pname]["maximum"] = max(cpuList)

            elif context == "GPU":
                if slen == 3:
                    gname = sline[0].strip()
                    intervalList = sline[2]
                elif slen == 2:
                    if intervalList:
                        intervalList += sline[1]
                elif intervalList and gname != "GPU":
                    gpuUsage[gname] = intervalList
                    intervalList = None

                    """
                    gpuUsage[gname] = {}

                    gpuUsage[gname]['usage'] = intervalList
                    gpuList = list(map(long, intervalList.split()))

                    if not gpuList:
                        gpuUsage[gname]['minimum'] = 0
                        gpuUsage[gname]['average'] = 0
                        gpuUsage[gname]['maximum'] = 0
                    else:
                        gpuUsage[pname]['minimum'] = min(gpuList)
                        gpuUsage[pname]['average'] = \
                            sum(gpuList) / len(gpuList)
                        gpuUsage[pname]['maximum'] = max(gpuList)
                    """

            elif context == "VSS":
                if slen == 3:
                    m = re.match(r"\s*(?P<comm>.+?)\(\s*(?P<pid>[0-9]+)", line)
                    if not m:
                        continue

                    d = m.groupdict()
                    comm = d["comm"].strip("^ ")[:commLen]

                    if not SysMgr.filterGroup:
                        pid = d["pid"]
                        pname = "%s(%s)" % (comm, pid)
                        maxVss = long(sline[1])
                        intervalList = sline[2]
                        continue

                    if not TaskAnalyzer.checkFilter(comm, d["pid"]):
                        intervalList = None
                    else:
                        pid = d["pid"]
                        pname = "%s(%s)" % (comm, pid)
                        maxVss = long(sline[1])
                        intervalList = sline[2]
                elif slen == 2:
                    if intervalList:
                        intervalList += sline[1]
                elif intervalList:
                    try:
                        memProcUsage[pname]
                    except:
                        memProcUsage[pname] = {}
                        memProcUsage[pname]["pid"] = pid

                    memProcUsage[pname]["maxVss"] = maxVss
                    memProcUsage[pname]["vssUsage"] = intervalList
                    intervalList = None

            elif (
                SysMgr.rssEnable or SysMgr.pssEnable or SysMgr.ussEnable
            ) and context in ("RSS", "PSS", "USS"):
                if slen == 3:
                    m = re.match(r"\s*(?P<comm>.+?)\(\s*(?P<pid>[0-9]+)", line)
                    if not m:
                        continue

                    d = m.groupdict()
                    comm = d["comm"].strip("^ ")[:commLen]

                    if not SysMgr.filterGroup:
                        pid = d["pid"]
                        pname = "%s(%s)" % (comm, pid)
                        maxRss = long(sline[1])
                        intervalList = sline[2]
                        continue

                    if not TaskAnalyzer.checkFilter(comm, d["pid"]):
                        intervalList = None
                    else:
                        pid = d["pid"]
                        pname = "%s(%s)" % (comm, pid)
                        maxRss = long(sline[1])
                        intervalList = sline[2]
                elif slen == 2:
                    if intervalList:
                        intervalList += sline[1]
                elif intervalList:
                    try:
                        memProcUsage[pname]
                    except:
                        memProcUsage[pname] = {}
                        memProcUsage[pname]["pid"] = pid

                    memProcUsage[pname]["maxRss"] = maxRss
                    memProcUsage[pname]["rssUsage"] = intervalList
                    intervalList = None

            elif context == "PSI":
                if slen == 3:
                    gname = sline[0].strip()
                    if gname == "RES":
                        continue
                    intervalList = sline[2]
                elif slen == 2:
                    if intervalList:
                        intervalList += sline[1]
                elif intervalList:
                    psiUsage[gname] = intervalList
                    intervalList = None

            elif context == "Block":
                if slen == 3:
                    m = re.match(r"\s*(?P<comm>.+?)\(\s*(?P<pid>[0-9]+)", line)
                    if not m:
                        continue

                    d = m.groupdict()
                    comm = d["comm"].strip()[:commLen]

                    if not SysMgr.filterGroup:
                        pid = d["pid"]
                        pname = "%s(%s)" % (comm, pid)

                        try:
                            blkTotal = long(sline[1])
                        except:
                            blkTotal = sline[1]

                        intervalList = sline[2]
                        continue

                    if not TaskAnalyzer.checkFilter(comm, d["pid"]):
                        intervalList = None
                    else:
                        pid = d["pid"]
                        pname = "%s(%s)" % (comm, pid)

                        try:
                            blkTotal = long(sline[1])
                        except:
                            blkTotal = sline[1]

                        intervalList = sline[2]
                elif slen == 2:
                    if intervalList:
                        intervalList += sline[1]
                elif intervalList:
                    blkProcUsage[pname] = {}
                    blkProcUsage[pname]["pid"] = pid
                    blkProcUsage[pname]["total"] = blkTotal
                    blkProcUsage[pname]["usage"] = intervalList
                    intervalList = None

            elif context == "Storage":
                if slen == 3:
                    gname = sline[0].strip()
                    intervalList = sline[2]
                elif slen == 2:
                    if intervalList:
                        intervalList += sline[1]
                elif intervalList and gname not in ("Device", "Storage"):
                    storageUsage.setdefault(gname, {})
                    busyList = []
                    readList = []
                    writeList = []
                    freeList = []

                    for item in intervalList.split():
                        if item == "0":
                            busy = read = write = free = 0
                        else:
                            busy, read, write, free = item.split("/", 3)
                        busyList.append(long(busy))
                        readList.append(convSize(read) >> 10)
                        writeList.append(convSize(write) >> 10)
                        freeList.append(convSize(free) >> 10)

                    storageUsage[gname]["busy"] = busyList
                    storageUsage[gname]["read"] = readList
                    storageUsage[gname]["write"] = writeList
                    storageUsage[gname]["free"] = freeList
                    intervalList = None

            elif context == "Network":
                if slen == 3:
                    gname = sline[0].strip()
                    intervalList = sline[2]
                elif slen == 2:
                    if intervalList:
                        intervalList += sline[1]
                elif intervalList and gname not in ("Device", "Network"):
                    networkUsage.setdefault(gname, {})
                    recvList = []
                    tranList = []

                    for item in intervalList.split():
                        if item == "0":
                            recv = tran = 0
                        else:
                            recv, tran = item.split("/", 1)
                        recvList.append(convSize(recv) >> 10)
                        tranList.append(convSize(tran) >> 10)

                    networkUsage[gname]["recv"] = recvList
                    networkUsage[gname]["tran"] = tranList
                    intervalList = None

            elif context == "Memory":
                if slen != 13:
                    continue

                m = re.match(r"\s*(?P<comm>.+?)\(\s*(?P<pid>[0-9]+)", sline[0])
                if m:
                    d = m.groupdict()
                    pid = d["pid"]
                    comm = d["comm"].strip()[:commLen]
                    pname = "%s(%s)" % (comm, pid)
                    chartStats[pname] = {}

                try:
                    chartStats[pname][sline[1].strip()] = list(
                        map(lambda x: long(x.replace(",", "")), sline[2:-1])
                    )
                except:
                    pass

            elif context in (
                "Cgroup.CPU",
                "Cgroup.Throttle",
                "Cgroup.Mem",
                "Cgroup.Blk",
            ):
                if context == "Cgroup.CPU":
                    if nocgcpu:
                        continue
                    targetDict = cpuProcUsage
                elif context == "Cgroup.Throttle":
                    if nocgthrottle:
                        continue
                    targetDict = cpuProcDelay
                elif context == "Cgroup.Mem":
                    if nocgmem:
                        continue
                    targetDict = memProcUsage
                else:
                    if nocgblk:
                        continue
                    targetDict = blkProcUsage

                pid = 0

                if slen == 3:
                    if not sline[0].startswith("Cgroup"):
                        comm = sline[0].strip()[:commLen]

                        if SysMgr.filterGroup:
                            if not TaskAnalyzer.checkFilter(comm, pid):
                                intervalList = None
                            else:
                                pname = "%s" % comm

                                intervalList = sline[2]
                        else:
                            pname = "%s" % comm

                            intervalList = sline[2]
                elif slen == 2:
                    if intervalList:
                        intervalList += sline[1]
                elif intervalList:
                    targetDict[pname] = {}
                    targetDict[pname]["pid"] = pid

                    intervalList = intervalList.split()

                    statNames = {
                        "min": "minimum",
                        "avg": "average",
                        "max": "maximum",
                        "usage": "usage",
                    }

                    if context in ("Cgroup.CPU", "Cgroup.Throttle"):
                        rlist = list(map(float, intervalList))
                        rlist = list(map(long, rlist))
                    elif context == "Cgroup.Blk":
                        for cidx in range(len(intervalList)):
                            rd, wr = intervalList[cidx].split("/", 1)
                            rd = convSize(rd) >> 20
                            wr = convSize(wr) >> 20
                            intervalList[cidx] = "%s/%s" % (rd, wr)
                        rlist = intervalList
                    elif context == "Cgroup.Mem":
                        rlist = list(map(convSize, intervalList))
                        rlist = list(map(lambda v: long(v) >> 20, rlist))

                        statNames = {
                            "min": "minRss",
                            "avg": "avgRss",
                            "max": "maxRss",
                            "usage": "rssUsage",
                        }

                    intervalList = list(map(str, rlist))
                    intervalList = " ".join(intervalList)
                    targetDict[pname][statNames["usage"]] = intervalList
                    intervalList = None

                    if context == "Cgroup.Blk":
                        continue

                    tdict = targetDict[pname]
                    if not rlist:
                        tdict[statNames["min"]] = 0
                        tdict[statNames["avg"]] = 0
                        tdict[statNames["max"]] = 0
                    else:
                        tdict[statNames["min"]] = min(rlist)
                        tdict[statNames["avg"]] = UtilMgr.getAvg(rlist)
                        tdict[statNames["max"]] = max(rlist)

            elif context == "Steal":
                if slen == 3:
                    if not sline[0].lstrip().startswith("Core"):
                        intervalList = sline[2]
                elif slen == 2:
                    if intervalList:
                        intervalList += sline[1]
                elif intervalList:
                    stealUsage = list(map(long, intervalList.split()))
                    intervalList = None

            elif context == "Core":
                if slen == 3:
                    if not sline[0].startswith("Core"):
                        gname = sline[0].strip()
                        intervalList = sline[2]
                elif slen == 2:
                    if intervalList:
                        intervalList += sline[1]
                elif intervalList:
                    coreUsage[gname] = intervalList
                    intervalList = None

            elif context == "Event":
                if slen != 4:
                    continue

                try:
                    ltime, utime, dtime = list(map(str.strip, sline[:3]))
                    ltime = long(float(ltime)) if ltime else 0
                    utime = float(utime) if utime else 0
                    dtime = float(dtime) if dtime else 0
                    event = sline[3].strip()
                    eventData.append([ltime, utime, dtime, event])
                except:
                    pass

            elif context == "File":
                if norecfile:
                    continue
                elif slen != 2:
                    if line.startswith("[Top File"):
                        for item in line.strip().split("("):
                            if not item.startswith("Path:"):
                                continue
                            path = UtilMgr.lstrip(item, "Path: ").strip(")")
                    continue
                elif recfileFilter and not UtilMgr.isValidStr(
                    path, recfileFilter
                ):
                    continue

                try:
                    utime = float(sline[0])
                    uidx = timeline.index(long(utime))
                    dtime = 0

                    if path not in TaskAnalyzer.fileNameTable:
                        TaskAnalyzer.fileNameTable[path] = "#%s" % len(
                            TaskAnalyzer.fileNameTable
                        )
                    name = TaskAnalyzer.fileNameTable[path]

                    event = "%s> %s" % (name, sline[1].strip())

                    eventList[uidx].insert(0, event)
                except:
                    pass

            elif context == "Life":
                if slen not in (7, 8):
                    continue
                elif not lifeEvent and nolifestat:
                    continue

                try:
                    task = sline[0].strip()
                    if task == "Process":
                        continue
                    start = sline[1].strip()
                    end = sline[2].strip()
                    prio = sline[6].strip()

                    if not nolifestat:
                        for lt, ll in ((start, newStats), (end, termStats)):
                            if lt == "-":
                                continue
                            ll.setdefault(
                                task, {"usage": [], "start": start, "end": end}
                            )
                            ll[task]["usage"].append(1)

                    if not lifeEvent:
                        raise Exception()

                    for s, char in ((start, "+"), (end, "-")):
                        try:
                            st = UtilMgr.convTime2Sec(s)
                            if not st:
                                raise Exception("no time")

                            stidx = UtilMgr.bisect_left(timeline, st)
                            eventList[stidx].append(
                                "[%s] %s [%s] <%s>"
                                % (char, task, s, prio if prio else "?")
                            )
                        except SystemExit:
                            sys.exit(0)
                        except:
                            pass
                except SystemExit:
                    sys.exit(0)
                except:
                    pass

            elif context == "MemDump":
                if line.startswith("[Top "):
                    for l in reversed(line.strip().split("(", 5)[1:]):
                        t, v = list(map(str.strip, l.split(":", 1)))
                        v = v[:-1]

                        if t == "Target":
                            mdUsage.setdefault(v, {})
                            mpath = mdUsage[v]
                        elif t == "Type":
                            mpath.setdefault(v, {})
                            # pylint: disable-next=unsubscriptable-object
                            mpath = mpath[v]
                        elif t == "RAM":
                            totalRam = convSize(v.split("/", 2)[1])
                        elif t == "Swap":
                            totalSwap = convSize(v.split("/", 2)[1])
                elif slen == 3:
                    gname = sline[0].strip()
                    intervalList = sline[2].rstrip()
                elif slen == 2:
                    if intervalList:
                        intervalList += sline[1].rstrip()
                elif intervalList:
                    if gname == "UPTIME":
                        if not timeline:
                            timeline = list(map(long, intervalList.split()))
                    elif mpath is not None:
                        mpath[gname] = intervalList
                    intervalList = None

        try:
            for evt in eventData:
                ltime, utime, dtime, event = evt
                idx = timeline.index(ltime)
                eventList[idx].append(
                    "%s [%.3f / +%.2fs]" % (event, utime, dtime)
                )
        except:
            pass

        if curSize:
            UtilMgr.deleteProgress()

        if mdUsage:
            pass
        elif not totalRam:
            SysMgr.printErr("failed to find statistics data in '%s'" % logFile)
            return {}, {}
        elif not timeline:
            SysMgr.printErr("failed to find interval data in '%s'" % logFile)
            return {}, {}

        try:
            sysinfo = {}
            for item in SysMgr.sysinfoBuffer.split("\n"):
                item = item.split(" ", 1)
                if len(item) != 2:
                    continue
                sysinfo[item[0]] = item[1].strip()
        except SystemExit:
            sys.exit(0)
        except:
            SysMgr.printWarn("failed to parse sysinfo", True, True)

        if "TIMELINERANGE" in SysMgr.environList:
            vals = SysMgr.environList["TIMELINERANGE"][0].split(":", 1)
            try:
                vals = list(map(long, vals))
                if not (2 <= len(vals) <= 3):
                    raise Exception("wrong input number")
            except SystemExit:
                sys.exit(0)
            except:
                SysMgr.printErr(
                    "wrong TIMELINERANGE %s" % ":".join(vals), True
                )
                sys.exit(-1)

            start, end = vals[:2]
            if len(vals) == 3:
                num = vals[2]
            else:
                num = 1

            newTimeline = list(xrange(start, end, num))
            if len(timeline) < len(newTimeline):
                SysMgr.printErr(
                    "failed to change timeline because original(%s) and new(%s) are different"
                    % (len(timeline), len(newTimeline))
                )
                sys.exit(-1)
            timeline = newTimeline

        if {"TRIM", "TRIMIDX"} & set(envList):
            vals = SysMgr.getTrimVals(timeline)
            if not vals:
                SysMgr.printErr("no item in timeline")
                sys.exit(0)

            imin = timeline.index(vals[0])
            imax = timeline.index(vals[-1])

            for resUsage in (cpuProcUsage, blkProcUsage):
                for name, value in resUsage.items():
                    value["usage"] = value["usage"].split()[imin:imax]
                    value["usage"] = " ".join(value["usage"])

            for name, value in memProcUsage.items():
                for nmUsage in ("vssUsage", "rssUsage"):
                    if nmUsage not in value:
                        continue
                    value[nmUsage] = value[nmUsage].split()[imin:imax]
                    value[nmUsage] = " ".join(value[nmUsage])

            for resUsage in (gpuUsage, psiUsage, coreUsage):
                for name, value in resUsage.items():
                    value = value.split()[imin:imax]
                    resUsage[name] = " ".join(value)

            for resUsage in (storageUsage, networkUsage):
                for name, dev in resUsage.items():
                    for item, value in dev.items():
                        resUsage[name][item] = value[imin:imax]

            for resUsage in (mdUsage,):
                for mtype, value in resUsage.items():
                    for proc, attrs in value.items():
                        for attr, val in attrs.items():
                            val = val.split()[imin:imax]
                            resUsage[mtype][proc][attr] = " ".join(val)
        else:
            imin = 0
            imax = len(timeline)

        if not timeline[imin:imax]:
            SysMgr.printErr("no data in the range %s:%s" % (imin, imax))
            return {}, {}

        systemdList = []
        systemdParsing = False
        for line in fd:
            if not line:
                break

            if isCompressed:
                try:
                    line = line.decode()
                except SystemExit:
                    sys.exit(0)
                except:
                    pass

            if systemdParsing:
                if line.startswith("*") and "Kernel Message" in line:
                    break
                else:
                    systemdList.append(line)
            else:
                if line.startswith("*") and "Systemd Info" in line:
                    systemdParsing = True
        try:
            systemdInfo = {}
            if systemdList:
                systemdInfo = UtilMgr.convStr2Dict("".join(systemdList))
        except SystemExit:
            sys.exit(0)
        except:
            SysMgr.printErr("failed to get systemd info", True)

        for lifeStats in (newStats, termStats):
            for n, v in lifeStats.items():
                systemdInfo.setdefault("all", {})
                start = UtilMgr.convTime2Sec(v["start"], True) * 1000000.0
                end = v["end"]
                if end != "-":
                    end = UtilMgr.convTime2Sec(v["end"], True) * 1000000.0
                else:
                    end = 0
                systemdInfo["all"][n.strip("*")] = {
                    "Boot": {
                        "activating": start,
                        "activated": start,
                        "deactivated": end,
                    }
                }

        if "MEMDUMP" in SysMgr.environList:
            fd.seek(0)
            memdumpList = []
            memdumpParsing = False
            for line in fd:
                if not line:
                    break

                if isCompressed:
                    line = line.decode()

                if memdumpParsing:
                    if line.startswith("*") and "File Data" in line:
                        break
                    else:
                        memdumpList.append(line)
                else:
                    if line.startswith("*") and "MemDump Data" in line:
                        memdumpParsing = True
            if memdumpList:
                token = "Applications Memory Usage"
                memdumpData = "".join(memdumpList)
                memdumpList = UtilMgr.cleanItem(
                    memdumpData.strip().split(token), False
                )
                memdumpIntData = {}
                for i in xrange(len(memdumpList)):
                    memdumpList[i] = token + memdumpList[i]
                    ret = AndroidMgr.parseMemDump(memdumpList[i])
                    if ret:
                        comm = ret.get("appMemoryUsage", {}).get("comm")
                        pid = ret.get("appMemoryUsage", {}).get("pid")
                        proc = "%s(%s)" % (comm, pid)
                        memdumpIntData[proc] = memdumpList[i]
                SysMgr.memDumpIntData = [memdumpIntData]
                mdUsage = TaskAnalyzer.printMemDumpInterval(True)[0]

        graphStats = {
            "graphTitle": "Guider Perf Graph",
            "blkProcUsage": blkProcUsage,
            "blkRead": blkRead[imin:imax],
            "blkWait": blkWait[imin:imax],
            "blkWrite": blkWrite[imin:imax],
            "coreUsage": coreUsage,
            "cpuProcDelay": cpuProcDelay,
            "cpuProcPrio": cpuProcPrio,
            "cpuProcUsage": cpuProcUsage,
            "cpuUsage": cpuUsage[imin:imax],
            "eventList": eventList[imin:imax],
            "gpuUsage": gpuUsage,
            "mdUsage": mdUsage,
            "memAnon": memAnon[imin:imax],
            "memCache": memCache[imin:imax],
            "memFree": memFree[imin:imax],
            "memKernel": memKernel[imin:imax],
            "memProcUsage": memProcUsage,
            "netRead": netRead[imin:imax],
            "netWrite": netWrite[imin:imax],
            "networkUsage": networkUsage,
            "newStats": newStats,
            "nrCore": nrCore[imin:imax],
            "nrTask": list(map(lambda x: x.strip(), nrTask[imin:imax])),
            "psiUsage": psiUsage,
            "reclaimBg": reclaimBg[imin:imax],
            "reclaimDr": reclaimDr[imin:imax],
            "start": startTime,
            "stealUsage": stealUsage[imin:imax],
            "storageUsage": storageUsage,
            "swapUsage": swapUsage[imin:imax],
            "sysinfo": sysinfo,
            "systemdInfo": systemdInfo,
            "termStats": termStats,
            "timeline": timeline[imin:imax],
            "totalRam": totalRam,
            "totalSwap": totalSwap,
        }

        return graphStats, chartStats

    def getAvgStats(self, flist, stats):
        # pylint: disable=undefined-variable

        fileIdxList = {}
        for idx, fname in enumerate(flist):
            fileIdxList[fname] = idx

        avgList = {}

        for name, value in stats.items():
            if name == "graphTitle":
                avgList.setdefault(name, "Guider Average Graph")
                continue
            elif name.endswith("sysinfo"):
                continue

            try:
                fname, sname = name.split(":", 1)
            except:
                SysMgr.printErr(
                    "failed to get file name from '%s" % name, True
                )
                sys.exit(-1)

            if sname.endswith("List"):
                continue
            elif sname.endswith("ProcUsage"):
                avgList.setdefault(sname, {})

                for proc, pvalue in value.items():
                    pname = proc.split("(", 1)[0].lstrip("*")
                    avgList[sname].setdefault(pname, [0] * len(flist))
                    if sname == "cpuProcUsage":
                        usage = pvalue["average"]
                    elif sname == "memProcUsage":
                        if "rssUsage" in pvalue:
                            mname = "rssUsage"
                        else:
                            mname = "vssUsage"
                        mlist = list(map(long, pvalue[mname].split()))
                        usage = max(mlist)
                    else:
                        continue

                    avgList[sname][pname][fileIdxList[fname]] += usage
            elif isinstance(value, list):
                if not value:
                    usage = 0
                elif isinstance(value[0], (int, long)):
                    usage = round(sum(value) / len(value), 1)
                else:
                    continue

                avgList.setdefault(sname, [0] * len(flist))
                avgList[sname][fileIdxList[fname]] = usage
            elif isinstance(value, dict):
                avgList.setdefault(sname, {})

                for item, val in value.items():
                    if UtilMgr.isString(val):
                        # tokens are usually plain integers, but PSI usage
                        # strings (e.g. psiUsage) use "some/full" (e.g. "1/0")
                        # per interval — split those into both numbers
                        numList = []
                        for tok in val.split():
                            if "/" in tok:
                                numList += list(map(long, tok.split("/", 1)))
                            else:
                                numList.append(long(tok))
                        if not numList:
                            continue
                        usage = round(sum(numList) / len(numList), 1)
                    else:
                        continue

                    avgList[sname].setdefault(item, [0] * len(flist))
                    avgList[sname][item][fileIdxList[fname]] = usage
            else:
                avgList.setdefault(sname, value)

        return avgList

    @staticmethod
    def mergeDrawStats(inputList):
        totalStat = {}

        if "TARGETDRAW" in SysMgr.environList:
            targetList = ",".join(SysMgr.environList["TARGETDRAW"]).split(",")
        else:
            targetList = ["*"]

        for fname in inputList:
            graphStats, chartStats = TaskAnalyzer.getStatsFile(
                logFile=fname,
                applyOpt=True,
            )

            for n, v in graphStats.items():
                if not UtilMgr.isValidStr(n, targetList) or not v:
                    continue

                if n in ("storageUsage", "networkUsage"):
                    slist = {
                        "read": [],
                        "write": [],
                        "recv": [],
                        "tran": [],
                    }
                    for val in v.values():
                        for key, sv in val.items():
                            if key not in slist:
                                continue

                            if not slist[key]:
                                slist[key] = sv
                                continue

                            slist[key] = [sum(x) for x in zip(slist[key], sv)]

                    if slist["read"]:
                        name = "storageUsage"
                    else:
                        name = "networkUsage"

                    for key, sv in slist.items():
                        if not sv:
                            continue

                        key = name + key[0].upper() + key[1:]

                        if "EACHFILE" in SysMgr.environList:
                            totalStat["%s@%s" % (key, name)] = sv
                            continue

                        if key not in totalStat:
                            totalStat[key] = []

                        totalStat[key] += sv

                    continue
                elif n == "gpuUsage":
                    nv = []
                    for val in v.values():
                        nv += list(map(long, val.strip().split()))
                    v = nv

                # TODO: handle process stats with -g filter option #

                if not isinstance(v, list):
                    continue

                if "EACHFILE" in SysMgr.environList:
                    totalStat["%s@%s" % (n, fname)] = v
                    continue

                if n not in totalStat:
                    totalStat[n] = []

                totalStat[n] += v

        return totalStat

    @staticmethod
    def drawHist(
        inputFile=[],
        statList=[],
        nameList=[],
        outFile=None,
        posInfo=[],
        subNameList=[],
        gname=None,
        yper=True,
        msg=None,
        yunit="",
        inLabel=False,
        xrangeList=[],
        addLabel=False,
        cumulative=False,
        diff=False,
    ):
        # pylint: disable=undefined-variable

        """
        function call example:
        - statList: value list
        - nameList: plot name list
        - posInfo: position info list (grid, pos, rowspan, colspan)

        drawHist(
            statList = [       # bar data #
                [
                    range(1, 10),
                    range(5, 10),
                    range(9, 20),
                    range(10, 20),
                ],
                [
                    range(1, 10),
                    range(5, 10),
                    range(9, 20),
                    range(10, 20),
                ],
            ],
            nameList = [       # bar name #
                [
                    "test1",
                    "test2",
                    "test3",
                    "test4",
                ],
                [
                    "test1",
                    "test2",
                    "test3",
                    "test4",
                ],
            ],
            subNameList = [    # box name #
                "group1",
                "group2",
                "group3",
            ],
            posInfo = [        # box position of stat #
                (
                    [(3, 3), (0, 0), 1, 1],
                    [(3, 3), (1, 1), 1, 1],
                    [(3, 3), (2, 2), 1, 1],
                    [(3, 3), (0, 0), 1, 1],
                ),
                (
                    [(3, 3), (0, 0), 1, 1],
                    [(3, 3), (1, 1), 1, 1],
                    [(3, 3), (2, 2), 1, 1],
                    [(3, 3), (0, 0), 1, 1],
                ),
            ],
            xrangeList = [     # set xrange list #
                "10:100:10",
                "",
                ":200",
                "::50",
            ],
        )
        """

        if not inputFile and not statList:
            SysMgr.printErr("no input for histogram")
            sys.exit(-1)

        if not posInfo:
            posInfo = []
        if not nameList:
            nameList = []
        if not subNameList:
            subNameList = []
        if not statList:
            statList = []

        fileName, inputName, inputList = UtilMgr.getInputNames(inputFile)

        TaskAnalyzer.initDrawEnv()

        figObj = TaskAnalyzer.drawFigure()
        renderer = figObj.canvas.get_renderer()

        if inputFile:
            totalStat = TaskAnalyzer.mergeDrawStats(inputList)

            for n, v in totalStat.items():
                if n.startswith("cpuUsage"):
                    if sum(v) == 0:
                        continue

                    posInfo.append([(2, 2), (0, 0), 1, 1])
                elif n.startswith("memFree"):
                    if sum(v) == 0:
                        continue

                    posInfo.append([(2, 2), (0, 1), 1, 1])
                elif n.startswith("blkRead"):
                    if sum(v) == 0:
                        continue

                    posInfo.append([(2, 2), (1, 0), 1, 2])
                elif n.startswith("storageUsage"):
                    if sum(v) == 0:
                        continue

                    posInfo.append([(2, 2), (1, 1), 1, 2])
                else:
                    continue

                name = "System" + n[0].upper() + n[1:]
                nameList.append(name)
                subNameList.append(name)
                statList.append(v)

        if not statList:
            SysMgr.printErr("no stat for histogram")
            sys.exit(-1)

        fig, ax = subplots()

        if msg:
            fig.text(
                0,
                0.99,
                msg,
                color="b",
                fontsize=2,
            )

        if not gname:
            gname = "Guider Histogram"

        ax.xaxis.set_major_locator(MaxNLocator(integer=True))
        suptitle(gname, fontsize=8)

        convNum = UtilMgr.convNum
        posList = {}
        nrBins = 20
        newSubNameList = []
        addLabel = addLabel or "ADDLABEL" in SysMgr.environList

        def convLong(arr):
            if isinstance(arr, list) or isinstance(arr, range):
                return [convLong(item) for item in arr]
            else:
                return long(arr)

        statList = convLong(list(statList))

        if not isinstance(statList[0][0], list):
            statList = [statList]
        if not isinstance(nameList[0], list):
            nameList = [nameList]
        try:
            posInfo[0][0][0][0]
        except SystemExit:
            sys.exit(0)
        except:
            posInfo = [posInfo]

        try:
            if not posInfo:
                posList = [0]
                raise ValueError("no pos info")

            for pidx, posSet in enumerate(posInfo):
                for idx, pos in enumerate(posSet):
                    posStr = str(pos)
                    if posStr in posList:
                        posList[posStr][1].append(list(statList[pidx][idx]))
                        posList[posStr][2].append(nameList[pidx][idx])
                    else:
                        posList[posStr] = [
                            pos,
                            [list(statList[pidx][idx])],
                            [nameList[pidx][idx]],
                        ]
        except ValueError:
            pass
        except SystemExit:
            sys.exit(0)
        except:
            SysMgr.printErr("failed to parse pos info", True)
            return

        try:
            for idx in range(len(posList)):
                newSubNameList.append(subNameList[idx])
        except SystemExit:
            sys.exit(0)
        except:
            SysMgr.printWarn("wrong index of subNameList used", True)

        if len(newSubNameList) != len(posList):
            SysMgr.printWarn(
                "counts of posInfo(%s) and subNameList(%s) are different"
                % (convNum(len(posList)), convNum(len(newSubNameList))),
                True,
            )

        def _getColor():
            try:
                random = SysMgr.getPkg("random", False)
                return (random.random(), random.random(), random.random())
            except SystemExit:
                sys.exit(0)
            except:
                return None

        def _getStat(a, m, f):
            try:
                l = 0 if f == max else sys.maxsize
                for n in a:
                    l = f(m, l, _getStat(n, m, f))
                return l
            except SystemExit:
                sys.exit(0)
            except:
                return f(m, l, a)

        def _applyTickLabel(items, ax, maxVal):
            try:
                xticks(items, fontsize=TaskAnalyzer.xfsize)
                rmax = max(items)

                newList = []
                for idx, name in enumerate(items):
                    name = UtilMgr.convNum(long(name))
                    if idx & 1:
                        name = "\n%s" % name
                    newList.append(name)
                items = newList

                nitems = items[:]
                last = UtilMgr.convNum(max(maxVal, rmax) + 1)
                last = "\n" + last if nitems[-1].startswith("\n") else last
                nitems[-1] = last
                ax.set_xticklabels(nitems)

                ax.xaxis.grid(
                    True, linestyle="-", linewidth="0.01", color="black"
                )
                ax.yaxis.grid(True, linestyle="-", linewidth="0.1", color="w")

                gca().xaxis.set_ticks_position("both")
                tick_params(
                    axis="x",
                    which="both",
                    direction="in",
                    width=0.2,
                    pad=1,
                    color="black",
                )
            except:
                SysMgr.printWarn("failed to apply xticks", True, True)

            try:
                ytickLabel = ax.get_yticks().tolist()
                ytickLabel = list(map(long, ytickLabel))
                ax.set_yticks(ytickLabel)
                ytickLabel = [convNum(val) for val in ytickLabel]
                ax.set_yticklabels(ytickLabel)
            except:
                pass

        histDataList = []

        for index, pos in enumerate(posList):
            if not posInfo:
                continue

            posData, statData, nameList = posList[pos]

            try:
                ax.remove()
            except SystemExit:
                sys.exit(0)
            except:
                pass

            ax = subplot2grid(
                posData[0],
                posData[1],
                rowspan=posData[2],
                colspan=posData[3],
            )
            ax.xaxis.set_major_locator(MaxNLocator(integer=True))
            subplots_adjust(
                top=0.90,
                bottom=0.05,
                left=0.05,
                right=0.95,
                hspace=0.4,
                wspace=0.3,
            )
            wbox = ax.get_window_extent(renderer=renderer)

            ax.xaxis.set_major_locator(MaxNLocator(integer=True))
            name = (
                newSubNameList[index] if len(newSubNameList) > index else " "
            )
            ax.set_title(name, fontsize=5)

            [x.set_linewidth(0.2) for x in ax.spines.values()]
            tick_params(direction="in", length=2, width=0.5)

            minVal = _getStat(statData, sys.maxsize, min)
            maxVal = _getStat(statData, 0, max)

            diff = long(maxVal - minVal)
            diff = 1 if diff == 0 else diff
            nrBins = min(diff, nrBins)
            nrBins = 1 if nrBins == 0 else nrBins
            nrTicks = long(diff / nrBins)
            bins = range(minVal, maxVal + 1 + nrTicks, nrTicks)

            h, b, p = hist(
                statData,
                bins=bins,
                density=False,
                color=[_getColor() for _ in range(len(statData))],
                alpha=0.7,
                cumulative=cumulative,
                histtype="bar",
                stacked=False,
            )
            """
            histtype = "bar" | "barstacked" | "step" | "stepfilled"
            """

            if SysMgr.drawFormat == "html":
                histDataList.append(
                    {
                        "axis_index": index,
                        "pos": pos,
                        "posData": posData,
                        "statData": statData,
                        "nameList": nameList,
                        "h": h,  # heights
                        "b": b,  # bin edges
                        "p": p,  # BarContainer(s)
                        "bins": bins,
                        "yper": yper,
                        "xmin": None,  # will be set later
                        "xmax": None,
                    }
                )

            TaskAnalyzer.drawLabel(
                [
                    "%s(%s)" % (nameList[i], convNum(len(s)))
                    for i, s in enumerate(statData)
                ],
                draw=True,
                anchor=(1, 1) if inLabel else (1.1, 1.1),
                fontsize=2,
                handlelength=None if len(statData) > 1 else 0,
            )

            try:
                minTick = 0
                maxTick = 0

                totalVal = 0
                for i, subp in enumerate(p):
                    try:
                        height = subp.get_height()
                        if totalVal == 0:
                            totalVal = sum([x.get_height() for x in p])
                        if yper:
                            per = height / totalVal * 100
                            subp.set_height(per)
                            t = per
                        else:
                            t = height
                        maxTick = max(maxTick, t)
                    except SystemExit:
                        sys.exit(0)
                    except:
                        totalVal = 0
                        for si, bar in enumerate(subp):
                            height = bar.get_height()
                            if totalVal == 0:
                                totalVal = sum([x.get_height() for x in subp])
                            if yper:
                                per = height / totalVal * 100
                                bar.set_height(per)
                                t = per
                            else:
                                t = height
                            maxTick = max(maxTick, t)
            except SystemExit:
                sys.exit(0)
            except:
                pass

            items = list(map(long, b))
            try:
                long(h[0])
                h = [h]
            except SystemExit:
                sys.exit(0)
            except:
                pass

            try:
                if len(xrangeList) > index:
                    xrangeval = xrangeList[index]
                    xvals = xrangeval.split(":")
                elif "XRANGE" in SysMgr.environList:
                    xvals = SysMgr.environList["XRANGE"][0].split(":")
                else:
                    raise ValueError()

                minidx = -1
                xmin = (
                    long(xvals[0])
                    if len(xvals) > 0 and xvals[0].isdigit()
                    else min(items)
                )
                for mi, ms in enumerate(items):
                    if ms >= xmin:
                        minidx = 0 if mi == 0 else mi - 1
                        break
                minidx = len(items) - 1 if minidx == -1 else minidx

                maxidx = -1
                xmax = (
                    long(xvals[1])
                    if len(xvals) > 1 and xvals[1].isdigit()
                    else max(items)
                )
                for mi, ms in enumerate(items):
                    if ms >= xmax:
                        maxidx = 0 if mi == 0 else mi
                        break
                maxidx = len(items) - 1 if maxidx == -1 else maxidx

                if len(xvals) > 2 and xvals[2].isdigit():
                    xint = long(xvals[2])
                else:
                    xint = 0

                if xint:
                    items = list(range(xmin, xmax + xint, xint))
                else:
                    items = items[minidx : maxidx + 1]
            except ValueError:
                pass
            except SystemExit:
                sys.exit(0)
            except:
                SysMgr.printErr("failed to apply custom xrange", True)
            finally:
                xmin = min(items)
                xmax = max(items)

                xlim(xmin, xmax)

                if SysMgr.drawFormat == "html" and histDataList:
                    histDataList[-1]["xmin"] = xmin
                    histDataList[-1]["xmax"] = xmax

            _applyTickLabel(items, ax, maxVal if maxVal <= xmax else xmax)

            vmaxTick = 0
            for c, v in enumerate(h):
                for i in range(len(b) - 1):
                    if not (xmin <= b[i] < xmax):
                        continue

                    try:
                        num = long(v[i])
                    except SystemExit:
                        sys.exit(0)
                    except:
                        num = long(v)

                    if num == 0:
                        continue

                    try:
                        width = p[c][i].get_width()
                        if yper:
                            per = p[c][i].get_height()
                    except SystemExit:
                        sys.exit(0)
                    except:
                        width = p[i].get_width()
                        if yper:
                            per = p[i].get_height()

                    if yper:
                        vmaxTick = max(vmaxTick, per)
                    else:
                        per = num / float(totalVal) * 100
                        vmaxTick = max(vmaxTick, num)

            for c, v in enumerate(h):
                for i in range(len(b) - 1):
                    if not (xmin <= b[i] < xmax):
                        continue

                    try:
                        num = long(v[i])
                    except SystemExit:
                        sys.exit(0)
                    except:
                        num = long(v)

                    if num == 0:
                        continue

                    try:
                        width = p[c][i].get_width()
                        if yper:
                            per = p[c][i].get_height()
                    except SystemExit:
                        sys.exit(0)
                    except:
                        width = p[i].get_width()
                        if yper:
                            per = p[i].get_height()

                    cn = convNum(num)
                    cp = convNum(per, True)
                    if cp == "0.0":
                        cp = "0"
                    if yper:
                        t = "%s%% (%s)" % (cp, cn)
                    else:
                        t = "%s (%s%%)" % (cn, cp)
                    if addLabel:
                        t += " [%s]" % nameList[c]

                    fontsize = min(width / (xmax - xmin) * 140, 3)

                    y = per if yper else num
                    if y > (vmaxTick / 2):
                        va = "top"
                    else:
                        va = "bottom"

                    tobj = text(
                        b[i] + ((c + 0.5) * width),
                        y,
                        t,
                        ha="left",
                        va=va,
                        color="black",
                        fontsize=fontsize,
                        rotation=-90,
                        rotation_mode=None,
                    )
                    bbox = tobj.get_window_extent(renderer=renderer)
                    if bbox.height > wbox.height / 2:
                        tobj.remove()

                        tobj = text(
                            b[i] + ((c + 0.5) * width),
                            y,
                            t,
                            ha="left",
                            va=va,
                            color="black",
                            fontsize=fontsize / 2,
                            rotation=-90,
                            rotation_mode=None,
                        )

            if not yunit and yper:
                yunit = "%"

            TaskAnalyzer.drawYticks(
                ax, vmaxTick, adjust=True, ymin=minTick, yunit=yunit
            )

        return TaskAnalyzer.saveImage(
            fileName,
            "hist",
            outFile=outFile,
            histData=histDataList if SysMgr.drawFormat == "html" else None,
        )

    @staticmethod
    def drawBitmap(inputFile, unit=4096, diff=False):
        # pylint: disable=undefined-variable

        if isinstance(inputFile, list):
            if len(inputFile) > 1:
                SysMgr.printErr("no support multiple files")
                sys.exit(0)
            inputFile = inputFile[0]

        try:
            with open(inputFile, "rb") as fd:
                table = list(fd.read())
        except SystemExit:
            sys.exit(0)
        except:
            SysMgr.printErr(
                "failed to read bitmap from '%s'" % inputFile, True
            )
            sys.exit(0)

        TaskAnalyzer.initDrawEnv()

        _, ax = subplots()

        suptitle("Guider Bitmap", fontsize=8)

        num = long(len(table) ** (1 / 2))

        table = [3 if not val else val for val in table]

        nrTotal = len(table)
        nrExist = table.count(1)
        nrEmpty = table.count(3)
        convNum = UtilMgr.convNum
        info = (
            "- Unit: %s\n" "- Total: %s\n" "- Used: %s\n" "- Unused: %s\n"
        ) % (
            convNum(unit),
            convNum(nrTotal * unit),
            convNum(nrExist * unit),
            convNum(nrEmpty * unit),
        )

        bitmap = []
        prevPos = 0
        for pos in xrange(num, len(table), num):
            bitmap.append(table[prevPos:pos])
            prevPos = pos

        if prevPos < len(table) - 1:
            last = table[prevPos : len(table)]
            last += [2] * (num - len(last))
            bitmap.append(last)

        figObj = TaskAnalyzer.drawFigure()

        ax.imshow(
            bitmap,
            cmap="RdGy",
            aspect="auto",
            interpolation="nearest",
            extent=[0, num, num, 0],
        )

        fontsize = UtilMgr.getEnvironNum(
            "FONTSIZE", False, 3, False, isInt=True
        )

        ax.set_xticks(xrange(0, num, 1))
        ax.set_yticks(xrange(0, num, 1))
        ax.grid(color="w", linewidth=0.1)

        xticks(fontsize=fontsize)
        yticks(fontsize=fontsize)

        figObj.text(0, 1, info, va="top", ha="left", size=3)

        return TaskAnalyzer.saveImage(inputFile, "bitmap")

