        for idx in xrange(len(TA.procIntData)):
            statList.append(TA.procIntData[idx]["total"]["steal"])

        stats = "%s/%.1f/%s/%s" % (
            min(statList),
            totalStat / float(len(statList)),
            max(statList),
            totalStat,
        )

