    @staticmethod
    def printMemDumpInterval(ret=False):
        if not SysMgr.memDumpIntData:
            return

        if "NOMDSUMMARY" in SysMgr.environList:
            return
        elif not TaskAnalyzer.checkSummaryFilter("MD"):
            return

        procList = {}
        uptimeIntData = []
        procIntData = []
        convSize = UtilMgr.convSize2Unit

        for idx, d in enumerate(SysMgr.memDumpIntData):
            procIntData.append(dict())

            if not d:
                continue

            for proc, v in d.items():
                procList[proc] = {}

                if not v:
                    continue

                jsonObj = AndroidMgr.parseMemDump(v)

                info = jsonObj.get("appMemoryUsage", {})
                uptime = info.get("uptime")
                minfo = info.get("memoryInfo")
                plist = {
                    item: v.get("pssTotal", 0) for item, v in minfo.items()
                }
                rlist = {
                    item: v.get("rssTotal", 0) for item, v in minfo.items()
                }
                procList[proc]["pss"] = plist
                procList[proc]["rss"] = rlist

                if len(uptimeIntData) <= idx:
                    uptimeIntData.append(uptime)

                procIntData[idx][proc] = {"rss": rlist, "pss": plist}

        if ret:
            return procIntData

        if SysMgr.jsonEnable:
            _printer = lambda x: x
        else:
            _printer = SysMgr.printPipe

        margin = 5

        uptimeIntData = list(map(lambda x: long(x / 1000), uptimeIntData))

        memData = SysMgr.getMemDict()
        memTotal = convSize(memData.get("MemTotal", 0) << 10)
        memAvail = convSize(memData.get("MemAvailable", 0) << 10)
        swapTotal = convSize(memData.get("SwapTotal", 0) << 10)
        swapFree = convSize(memData.get("SwapFree", 0) << 10)

        for proc, items in procList.items():
            comm = SysMgr.getComm(proc)
            if comm:
                pname = "%s(%s)" % (comm, proc)
            else:
                pname = proc

            for mtype in ("rss", "pss"):
                _printer(
                    (
                        "\n[Top MemDump Info] (Unit: KB) (RAM: %s/%s) "
                        "(Swap: %s/%s) (Type: %s) (Target: %s)\n%s\n"
                    )
                    % (
                        memAvail,
                        memTotal,
                        swapFree,
                        swapTotal,
                        mtype.upper(),
                        pname,
                        twoLine,
                    )
                )

                memInfo = "{0:>16} | {1:>6} / {2:>6} |".format(
                    "UPTIME", "MIN", "MAX"
                )
                TaskAnalyzer.printTimelineInterval(
                    margin,
                    len(memInfo),
                    memInfo,
                    1,
                    timeList=uptimeIntData,
                    index=False,
                )

                for attr, _ in sorted(
                    items[mtype].items(), key=lambda x: x[1], reverse=True
                ):
                    stats = [
                        v.get(proc, {}).get(mtype, {}).get(attr, 0)
                        for v in procIntData
                    ]
                    validStatList = [x for x in stats if x != 0]
                    if not validStatList:
                        validStatList = [0]

                    attrInfo = "{0:>16} | {1:>6} / {2:>6} |".format(
                        attr, min(validStatList), max(stats)
                    )
                    attrInfoLen = len(attrInfo)
                    maxLineLen = SysMgr.lineLength
                    timeLine = ""
                    lineLen = len(attrInfo)
                    prev = 0

                    for i, stat in enumerate(stats):
                        if stat == 0 and prev != 0 and len(stats) >= i:
                            stat = prev

                        if lineLen + margin > maxLineLen:
                            timeLine += "\n" + (" " * (attrInfoLen - 1)) + "| "
                            lineLen = len(attrInfo)
                        timeLine += "{0:>6} ".format(stat)
                        lineLen += 7

                        prev = stat

                    _printer(
                        "{0:1} {1:1}\n{2:1}\n".format(
                            attrInfo, timeLine, oneLine
                        )
                    )

    @staticmethod
    def printMemInterval(mtype):
        if mtype == "VSS":
            sumFilter = "NOVSSSUMMARY"
        else:
            sumFilter = "NORSSSUMMARY"

        if sumFilter in SysMgr.environList:
            return
        elif not TaskAnalyzer.checkSummaryFilter(mtype):
            return

        TA = TaskAnalyzer
        printList = []
        jname = "vssUsage" if mtype == "VSS" else "rssUsage"
        if SysMgr.jsonEnable:
            _printer = lambda x: x
            jsonData = SysMgr.jsonData[jname] = {}
        else:
            _printer = lambda x: printList.append(x)
            jsonData = {}

        pd = SysMgr.getMaxPidLen(TA.procTotData)
        cl = 26 - (pd * 2)

        if mtype == "VSS":
            maxStr = "maxVss"
            memStr = "vss"
        else:
            maxStr = "maxMem"
            memStr = "mem"

            mtype = TaskAnalyzer.getMemStatStr()

        _printer(
            "\n[Top %s Info] (Unit: MB) (Change: ^)\n%s\n" % (mtype, twoLine)
        )

        if SysMgr.processEnable:
            idName = "PID"
            pidName = "PPID"
        else:
            idName = "TID"
            pidName = "PID"

        procInfo = (
            "{0:>{cl}} ({1:>{pd}}/{2:>{pd}}/{3:>4}/{4:>4})|{5:^6} |".format(
                "COMM", idName, pidName, "Nr", "Pri", " Max", cl=cl, pd=pd
            )
        )
        procInfoLen = len(procInfo)
        maxLineLen = SysMgr.lineLength
        margin = 5

        TA.printTimelineInterval(
            margin, procInfoLen, procInfo, 1, printer=_printer
        )

        value = TA.procTotData["total"]
        procInfo = (
            "{0:>{cl}} ({1:>{pd}}/{2:>{pd}}/{3:>4}/{4:>4})|{5:>6} |".format(
                "[FREE/MIN]", "-", "-", "-", "-", value["minMem"], cl=cl, pd=pd
            )
        )
        procInfoLen = len(procInfo)
        maxLineLen = SysMgr.lineLength

        timeLine = ""
        lineLen = len(procInfo)
        for idx in xrange(len(TA.procIntData)):
            if lineLen + margin > maxLineLen:
                timeLine += "\n" + (" " * (procInfoLen - 1)) + "| "
                lineLen = len(procInfo)

            if "total" in TA.procIntData[idx]:
                usage = TA.procIntData[idx]["total"]["mem"]
            else:
                usage = 0

            timeLine += "{0:>6} ".format(usage)
            lineLen += 7

        _printer(("{0:1} {1:1}\n{2:1}\n").format(procInfo, timeLine, oneLine))

        for pid, value in sorted(
            TA.procTotData.items(),
            key=lambda e: 0 if maxStr not in e[1] else e[1][maxStr],
            reverse=True,
        ):
            if pid == "total" or value[maxStr] == 0:
                continue

            procInfo = (
                "{0:>{cl}} ({1:>{pd}}/{2:>{pd}}/" "{3:>4}/{4:>4})|{5:>6} |"
            ).format(
                value["comm"][:cl],
                pid,
                value["ppid"],
                value["nrThreads"],
                value["pri"],
                value[maxStr],
                cl=cl,
                pd=pd,
            )
            procInfoLen = len(procInfo)
            maxLineLen = SysMgr.lineLength

            prev = 0
            timeLine = ""
            minVal = maxVal = 0
            lineLen = len(procInfo)
            intData = TA.procIntData
            usageList = []
            for idx in xrange(len(intData)):
                if lineLen + margin > maxLineLen:
                    timeLine += "\n" + (" " * (procInfoLen - 1)) + "| "
                    lineLen = len(procInfo)

                # process is shown #
                if pid in intData[idx]:
                    if intData[idx][pid]["die"]:
                        try:
                            usage = intData[idx][pid][memStr]
                        except:
                            prev = usage = 0
                    else:
                        usage = intData[idx][pid][memStr]
                        if usage == 0 and prev > 0:
                            usage = prev
                        else:
                            prev = usage
                # process was shown previously #
                elif prev > 0:
                    try:
                        # process was terminated #
                        if intData[idx - 1][pid]["die"]:
                            prev = usage = 0
                        # process is alive #
                        else:
                            usage = prev
                    except:
                        usage = prev
                else:
                    prev = usage = 0

                if usage == 0:
                    pass
                else:
                    if minVal == 0 or minVal > usage:
                        minVal = usage
                    if maxVal == 0 or maxVal < usage:
                        maxVal = usage

                usageList.append(usage)
                timeLine += "{0:>6} ".format(usage)
                lineLen += 7

            if maxVal - minVal > 0:
                try:
                    procInfo = procInfo.replace(" (", "^(", 1)
                except:
                    pass

            _printer(
                "{0:1} {1:1}\n{2:1}\n".format(procInfo, timeLine, oneLine)
            )

            try:
                if not SysMgr.jsonEnable:
                    raise Exception()

                jsonData[pid] = {
                    "comm": value["comm"],
                    "usage": usageList,
                    "minimum": minVal,
                    "maximum": maxVal,
                    "peak": value[maxStr],
                }
            except SystemExit:
                sys.exit(0)
            except:
                pass

        if printList:
            SysMgr.printPipe("".join(printList))

