    @staticmethod
    def printLifeHistory():
        if "NOLIFESUMMARY" in SysMgr.environList:
            return
        elif not TaskAnalyzer.checkSummaryFilter("LIFE"):
            return

        TA = TaskAnalyzer
        printList = []
        if SysMgr.jsonEnable:
            _printer = lambda x: x
            jsonData = SysMgr.jsonData["procLife"] = {}
        else:
            _printer = lambda x: printList.append(x)
            jsonData = {}

        _printer("\n[Top Life Info]\n%s" % twoLine)

        if SysMgr.processEnable:
            target = "Process"
            parent = "Parent"
        else:
            target = "Thread"
            parent = "Process"

        _printer(
            (
                "{0:^32} | {1:^16} | {2:^16} | {3:^16} | "
                "{4:^32} | {5:^18} | {6:^4} |\n{7:1}"
            ).format(
                target,
                "START",
                "END (BEFORE)",
                "DURATION",
                parent,
                "USER",
                "PRIO",
                oneLine,
            )
        )

        isPrinted = False
        procIntData = TaskAnalyzer.procIntData

        for pid, value in sorted(
            TA.lifeProcData.items(), key=lambda x: long(x[0])
        ):
            if SysMgr.filterGroup and (
                not UtilMgr.isValidStr(pid)
                and not UtilMgr.isValidStr(value["comm"])
            ):
                continue

            name = "%s(%s)" % (value["comm"], pid)

            try:
                start = value["START"]
                if start == -2:
                    start = "<-"
                else:
                    start = float(start)
            except SystemExit:
                sys.exit(0)
            except:
                start = "x"

            try:
                end = value["FINISH"]
                if end == -2:
                    end = "-"
                elif end == -1:
                    startTime = float(procIntData[0]["time"])
                    end = float(startTime - SysMgr.intervalEnable)
                else:
                    end = float(end)
            except:
                end = "x"

            try:
                duration = end - start
                durations = str(duration).split(".")
                duration = UtilMgr.convTime(long(durations[0]))
            except:
                duration = " "

            try:
                start = UtilMgr.convTime(float(start), True, 1)
            except:
                pass

            try:
                end = UtilMgr.convTime(float(end), True, 1)
            except:
                pass

            _printer(
                (
                    "{0:>32} | {1:>16} | {2:>16} | {3:>16} | "
                    "{4:>32} | {5:>18} | {6:>4} |"
                ).format(
                    name,
                    start,
                    end,
                    duration,
                    value["parent"],
                    value["user"],
                    value["prio"],
                )
            )

            if SysMgr.jsonEnable:
                jsonData[name] = {
                    "start": start,
                    "end": end,
                    "duration": duration,
                    "parent": value["parent"],
                    "user": value["user"],
                    "prio": value["prio"],
                }

            isPrinted = True

        if not isPrinted:
            _printer(UtilMgr.NONE_STR)

        _printer("%s\n" % oneLine)

        if printList:
            SysMgr.printPipe("\n".join(printList))

    @staticmethod
    def printLmkLog():
        """Print buffered LMK kill events collected via _startLmkLogThread."""
        log = SysMgr.lmkEventLog
        if not log:  # None or empty — hide section entirely
            return
        conv = UtilMgr.convSize2Unit
        convN = UtilMgr.convNum
        twoLine = "=" * SysMgr.lineLength
        oneLine = "-" * SysMgr.lineLength
        n = len(log)
        if SysMgr.jsonEnable:
            jsonEvents = SysMgr.jsonData["lmkEvents"] = []
        else:
            jsonEvents = None
            SysMgr.printPipe(
                "\n[LMK Event Log] (%d events, max=%d)" % (n, log.maxlen)
            )
            SysMgr.printPipe(twoLine)
            SysMgr.printPipe(
                "%-15s  %4s  %-22s  %6s  %6s  %6s  %6s  %6s  %6s  %9s  %9s  %s %s"
                % (
                    "TIME",
                    "ADJ",
                    "REASON",
                    "FREE",
                    "FILE",
                    "AVAIL",
                    "RSS",
                    "CACHE",
                    "SWAP",
                    "MINPF",
                    "MAJPF",
                    "USER(UID)",
                    "PROC(PID)",
                )
            )
            SysMgr.printPipe(oneLine)
        for ev in list(log):
            uid = ev.get("uid", 0)
            pid = ev.get("pid", 0)
            if SysMgr.sysInstance:
                uname = SysMgr.sysInstance.getUserName(str(uid), str(uid))
            else:
                uname = str(uid)
            ts = ev.get("timestamp", 0)
            try:
                ts_str = UtilMgr.convEpoch2Clock(ts)
            except Exception:
                ts_str = "-"
            if jsonEvents is not None:
                jsonEvents.append(
                    {
                        "time": ts_str,
                        "adj": ev.get("oom", 0),
                        "reason": ev.get("reason", "?"),
                        "memFreeKB": ev.get("mem_free_kb", 0),
                        "memCachedKB": ev.get("mem_cached_kb", 0),
                        "memAvailKB": ev.get("mem_avail_kb", 0),
                        "rss": ev.get("rss", 0),
                        "cache": ev.get("cache", 0),
                        "swap": ev.get("swap", 0),
                        "pgfault": ev.get("pgfault", 0),
                        "pgmajflt": ev.get("pgmajflt", 0),
                        "uid": uid,
                        "user": uname,
                        "pid": pid,
                        "name": ev.get("name", "?"),
                    }
                )
            else:
                line = (
                    "%-15s  %4d  %-22s  %6s  %6s  %6s  %6s  %6s  %6s  %9s  %9s  %s %s"
                    % (
                        ts_str,
                        ev.get("oom", 0),
                        ev.get("reason", "?")[:22],
                        conv(ev.get("mem_free_kb", 0) * 1024),
                        conv(ev.get("mem_cached_kb", 0) * 1024),
                        conv(ev.get("mem_avail_kb", 0) * 1024),
                        conv(ev.get("rss", 0)),
                        conv(ev.get("cache", 0)),
                        conv(ev.get("swap", 0)),
                        convN(ev.get("pgfault", 0)),
                        convN(ev.get("pgmajflt", 0)),
                        "%s(%d)" % (uname, uid),
                        (
                            "%s(%d)" % (ev.get("name", "?"), pid)
                            if pid
                            else ev.get("name", "?")
                        ),
                    )
                )
                SysMgr.printPipe(line, trim=False)
        if jsonEvents is None:
            SysMgr.printPipe(oneLine)

    @staticmethod
    def printCgBlkInterval():
        if "NOCGBLKSUMMARY" in SysMgr.environList:
            return
        elif not TaskAnalyzer.checkSummaryFilter("CGBLOCK"):
            return

        convSize2Unit = UtilMgr.convSize2Unit

        TA = TaskAnalyzer
        printList = []
        if SysMgr.jsonEnable:
            _printer = lambda x: x
            jsonData = SysMgr.jsonData["blkCgroupUsage"] = {}
        else:
            _printer = lambda x: printList.append(x)
            jsonData = {}

        _printer("\n[Top Cgroup.Blk Info] (Unit: Byte)\n%s\n" % twoLine)

        blkInfo = "{0:<48} | {1:^15} |".format("Cgroup", "Read/Write")
        blkInfoLen = len(blkInfo)
        margin = 14

        TA.printTimelineInterval(
            margin, blkInfoLen, blkInfo, 1, printer=_printer
        )

        totalData = TA.procTotData["total"]

        if "cgroup.read" not in totalData:
            _printer(UtilMgr.NONE_STR + "\n" + oneLine)
            if printList:
                SysMgr.printPipe("".join(printList))
            return

        isPrinted = False
        for group, val in sorted(
            totalData["cgroup.read"].items(),
            key=lambda e: e[1]["max"],
            reverse=True,
        ):
            rdTotal = val["usage"]
            wrTotal = totalData["cgroup.write"][group]["usage"]
            if rdTotal == wrTotal == 0:
                continue

            rdTotal = convSize2Unit(rdTotal)
            wrTotal = convSize2Unit(wrTotal)
            usagestr = "%s/%s" % (rdTotal, wrTotal)

            cgroupInfo = "{0:<48} | {1:^15} |".format(group, usagestr)
            cgroupInfoLen = len(cgroupInfo)
            maxLineLen = SysMgr.lineLength

            timeLine = ""
            lineLen = len(cgroupInfo)
            usageList = []
            for idx in xrange(len(TA.procIntData)):
                if lineLen + margin > maxLineLen:
                    timeLine += "\n" + (" " * (cgroupInfoLen - 1)) + "| "
                    lineLen = len(cgroupInfo)

                try:
                    rd = TA.procIntData[idx]["total"]["cgroup.read"][group]
                    rd = convSize2Unit(rd)
                    wr = TA.procIntData[idx]["total"]["cgroup.write"][group]
                    wr = convSize2Unit(wr)
                    usage = "%s/%s" % (rd, wr)
                except:
                    usage = "0/0"

                usageList.append(usage)
                timeLine += "{0:>15} ".format(usage)
                lineLen += margin + 2

            _printer(
                ("{0:1} {1:1}\n{2:1}\n").format(cgroupInfo, timeLine, oneLine)
            )

            try:
                if not SysMgr.jsonEnable:
                    raise Exception()

                jsonData[group] = {
                    "usage": usageList,
                    "rdTotal": rdTotal,
                    "wrTotal": wrTotal,
                }
            except SystemExit:
                sys.exit(0)
            except:
                pass

            isPrinted = True

        if not isPrinted:
            _printer(UtilMgr.NONE_STR + "\n" + oneLine)

        if printList:
            SysMgr.printPipe("".join(printList))

